// Schlange (nur Spiel-API, keine Importe). Steuerung: Pfeiltasten, Steuerkreuz oder Wischen.
// Hinweis zur Optik: Originalgrafik und Originalname des alten Handyspiels sind nicht uebernommen.
// Es gibt nur Formen in den Farben yellow, cream, ink, red und Emojis, daher eine eigene schlichte Optik.
const CELL = 20, COLS = 18, ROWS = 29, Y0 = 56;

export default {
  title: "Schlange",
  controls: ["up", "down", "left", "right"],
  lives: 3,

  init(g) {
    const s = { body: [], dir: { x: 1, y: 0 }, next: { x: 1, y: 0 }, apple: { x: 0, y: 0 }, wait: 0, eaten: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    const want = input.up ? { x: 0, y: -1 } : input.down ? { x: 0, y: 1 } : input.left ? { x: -1, y: 0 } : input.right ? { x: 1, y: 0 } : null;
    if (want && !(want.x === -s.dir.x && want.y === -s.dir.y)) s.next = want;
    s.wait += 1;
    if (s.wait < Math.max(4, 9 - g.level)) return;
    s.wait = 0;
    s.dir = { x: s.next.x, y: s.next.y };
    const head = { x: s.body[0].x + s.dir.x, y: s.body[0].y + s.dir.y };
    const crash = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS || s.body.some((p) => p.x === head.x && p.y === head.y);
    if (crash) { g.sound("hurt"); g.loseLife(); reset(s, g); return; }
    s.body.unshift(head);
    if (head.x === s.apple.x && head.y === s.apple.y) {
      g.addScore(10); g.sound("coin"); s.eaten += 1;
      if (s.eaten % 5 === 0) { g.nextLevel(); g.sound("level"); }
      placeApple(s, g);
    } else {
      s.body.pop();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    s.body.forEach((p, i) => d.rect(p.x * CELL + 1, Y0 + p.y * CELL + 1, CELL - 2, CELL - 2, i === 0 ? "red" : "ink", { round: 6 }));
  }
};

function reset(s, g) {
  s.body = [{ x: 6, y: 14 }, { x: 5, y: 14 }, { x: 4, y: 14 }];
  s.dir = { x: 1, y: 0 }; s.next = { x: 1, y: 0 }; s.wait = 0;
  placeApple(s, g);
}

function placeApple(s, g) {
  for (let tries = 0; tries < 200; tries++) {
    const a = { x: g.randInt(0, COLS - 1), y: g.randInt(0, ROWS - 1) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = { x: a.x, y: a.y }; return; }
  }
  // Rueckfall: erstes freies Feld im Raster suchen
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      if (!s.body.some((p) => p.x === x && p.y === y)) { s.apple = { x: x, y: y }; return; }
    }
  }
}

