// Pizza-Ziegel (nur Spiel-API, keine Importe): Paddle unten, die Pizza prallt an den Ziegeln ab.
// Ersatz fuer Lego-Steine: bunte Ziegel-Rechtecke in yellow, red und ink.
export default {
  title: "Pizza-Ziegel",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return {
      paddle: { x: 150, y: 600, w: 60, h: 12 },
      ball: { x: 180, y: 588, vx: 0, vy: 0, r: 9, wait: 60 },
      bricks: wall(g)
    };
  },

  update(s, input, g) {
    const p = s.paddle;
    if (input.left) p.x -= 5;
    if (input.right) p.x += 5;
    p.x = g.clamp(p.x, 4, g.W - p.w - 4);

    const b = s.ball;

    // Ball sitzt auf dem Paddle und startet nach 60 Frames automatisch
    if (b.wait > 0) {
      b.wait -= 1;
      b.x = p.x + p.w / 2;
      b.y = 588;
      b.vx = 0;
      b.vy = 0;
      if (b.wait === 0) { b.vx = 0; b.vy = -speed(g); }
      return;
    }

    for (const k of s.bricks) k.wait += 1;

    b.x += b.vx;
    b.y += b.vy;

    // Waende und Decke
    if (b.x - b.r < 0) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x + b.r > g.W) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y - b.r < g.TOP) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Steine: hoechstens ein Stein pro Frame
    for (let i = 0; i < s.bricks.length; i++) {
      const k = s.bricks[i];
      if (g.hit(b, k)) {
        s.bricks.splice(i, 1);
        b.vy = -b.vy;
        g.addScore(10 * g.level);
        g.sound("pop");
        break;
      }
    }

    // Level geschafft: neue Mauer, Ball zurueck aufs Paddle
    if (s.bricks.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.bricks = wall(g);
      resetBall(s);
      return;
    }

    // Paddle von oben: Richtung haengt von der Trefferstelle ab, Geschwindigkeit bleibt gleich
    if (b.vy > 0 && g.hit(b, p)) {
      b.y = p.y - b.r;
      const sp = speed(g);
      const vx = (b.x - (p.x + p.w / 2)) * 0.08;
      const len = Math.sqrt(vx * vx + 1);
      b.vx = (vx / len) * sp;
      b.vy = -(1 / len) * sp;
    }

    // Ball unten vorbei: Leben weg, Neustart mit Wartezeit
    if (b.y > g.H) {
      g.sound("hurt");
      g.loseLife();
      resetBall(s);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const k of s.bricks) d.rect(k.x, k.y, k.w, k.h, k.color, { round: 4, line: true });
    d.rect(s.paddle.x, s.paddle.y, s.paddle.w, s.paddle.h, "red", { round: 6, shadow: true });
    d.emoji("🍕", s.ball.x, s.ball.y, 22);
  }
};

// Grundgeschwindigkeit: 4 auf Level 1, plus 0.5 je weiterem Level, hoechstens 9
function speed(g) {
  return Math.min(9, 4 + 0.5 * (g.level - 1));
}

// Mauer: 8 Spalten mal 5 Reihen, Farben nach Reihe yellow, red, ink
function wall(g) {
  const colors = ["yellow", "red", "ink"];
  const out = [];
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 8; col++) {
      out.push({
        x: 20 + col * 42,
        y: g.TOP + 30 + row * 24,
        w: 40,
        h: 18,
        color: colors[row % 3],
        wait: 0
      });
    }
  }
  return out;
}

// Ball zurueck aufs Paddle, 60 Frames Wartezeit
function resetBall(s) {
  const b = s.ball;
  b.x = s.paddle.x + s.paddle.w / 2;
  b.y = 588;
  b.vx = 0;
  b.vy = 0;
  b.r = 9;
  b.wait = 60;
}

