    for (const k of s.bricks) d.rect(k.x, k.y, k.w, k.h, k.color, { round: 4, line: true });
    d.rect(s.paddle.x, s.paddle.y, s.paddle.w, s.paddle.h, "red", { round: 6, shadow: true });
    d.emoji("🍕", s.ball.x, s.ball.y, 22);
  }
};

// Grundgeschwindigkeit: 4 auf Level 1, plus 0.5 je weiterem Level, hoechstens 9
function speed(g) {
  return Math.min(9, 4 + 0.5 * (g.level - 1));
}

// Mauer: 8 Spalten mal 5 Reihen, Farben nach Reihe yellow, red, ink
function wall(g) {
  const colors = ["yellow", "red", "ink"];
  const out = [];
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 8; col++) {
      out.push({
        x: 20 + col * 42,
        y: g.TOP + 30 + row * 24,
        w: 40,
        h: 18,
        color: colors[row % 3],
        wait: 0
      });
    }
  }
  return out;
}

// Ball zurueck aufs Paddle, 60 Frames Wartezeit
function resetBall(s) {
  const b = s.ball;
  b.x = s.paddle.x + s.paddle.w / 2;
  b.y = 588;
  b.vx = 0;
  b.vy = 0;
  b.r = 9;
  b.wait = 60;
}

