// Grosse Felsen zerbrechen in kleine. Das Schiff fliegt am Rand um. Die Figur ist das Emoji 🚀; die Blickrichtung
// zeigt ein roter Strich vor dem Schiff, weil ein Emoji nicht gedreht werden kann.

function wrapX(v, g) {
  if (v < 0) return v + g.W;
  if (v >= g.W) return v - g.W;
  return v;
}

function wrapY(v, g) {
  const h = g.H - g.TOP;
  if (v < g.TOP) return v + h;
  if (v >= g.H) return v - h;
  return v;
}

function spawnRocks(s, g) {
  s.rocks = [];
  const n = 4 + g.level;
  for (let i = 0; i < n; i++) {
    let p = null;
    for (let t = 0; t < 30; t++) {
      const side = g.randInt(0, 3);
      let q;
      if (side === 0) q = { x: g.random() * g.W, y: g.TOP };
      else if (side === 1) q = { x: g.random() * g.W, y: g.H };
      else if (side === 2) q = { x: 0, y: g.TOP + g.random() * (g.H - g.TOP) };
      else q = { x: g.W, y: g.TOP + g.random() * (g.H - g.TOP) };
      p = q;
      const dx = q.x - s.ship.x;
      const dy = q.y - s.ship.y;
      if (Math.sqrt(dx * dx + dy * dy) >= 120) break;
    }
    s.rocks.push({ x: p.x, y: p.y, vx: g.random() * 2.4 - 1.2, vy: g.random() * 2.4 - 1.2, r: 36, gone: false });
  }
}

function resetShip(s) {
  s.ship.x = 170;
  s.ship.y = 320;
  s.ship.vx = 0;
  s.ship.vy = 0;
}

export default {
  title: "Felsen-Jäger",
  controls: ["left", "right", "up", "fire"],
  lives: 3,

  init(g) {
    const s = {
      ship: { x: 170, y: 560, vx: 0, vy: 0, ang: -90, cool: 0, safe: 0 },
      shots: [],
      rocks: []
    };
    spawnRocks(s, g);
    return s;
  },

  update(s, input, g) {
    const sh = s.ship;

    // Drehen
    if (input.left) sh.ang -= 4;
    if (input.right) sh.ang += 4;
    if (sh.ang < -180) sh.ang += 360;
    if (sh.ang > 180) sh.ang -= 360;

    // Schub oder Reibung
    if (input.up) {
      sh.vx += g.cos(sh.ang) * 0.12;
      sh.vy += g.sin(sh.ang) * 0.12;
      const sp = Math.sqrt(sh.vx * sh.vx + sh.vy * sh.vy);
      if (sp > 4) {
        sh.vx = sh.vx * 4 / sp;
        sh.vy = sh.vy * 4 / sp;
      }
    } else {
      sh.vx *= 0.99;
      sh.vy *= 0.99;
    }
    sh.x = wrapX(sh.x + sh.vx, g);
    sh.y = wrapY(sh.y + sh.vy, g);

    if (sh.cool > 0) sh.cool -= 1;
    if (sh.safe > 0) sh.safe -= 1;

    // Schiessen
    if ((input.fire || input.firePressed) && sh.cool === 0 && s.shots.length < 5) {
      const dx = g.cos(sh.ang);
      const dy = g.sin(sh.ang);
      s.shots.push({ x: sh.x + dx * 14, y: sh.y + dy * 14, vx: dx * 7, vy: dy * 7, life: 60, r: 3 });
      sh.cool = 12;
      g.sound("shoot");
    }

    // Schuesse bewegen
    for (const shot of s.shots) {
      shot.x = wrapX(shot.x + shot.vx, g);
      shot.y = wrapY(shot.y + shot.vy, g);
      shot.life -= 1;
    }

    // Felsen bewegen
    for (const rock of s.rocks) {
      rock.x = wrapX(rock.x + rock.vx, g);
      rock.y = wrapY(rock.y + rock.vy, g);
    }

    // Schuss trifft Fels
    const fresh = [];
    for (const shot of s.shots) {
      if (shot.life <= 0) continue;
      for (const rock of s.rocks) {
        if (rock.gone) continue;
        if (g.hit(shot, rock)) {
          shot.life = 0;
          rock.gone = true;
          if (rock.r === 36) {
            g.addScore(20);
            for (let i = 0; i < 2; i++) {
              fresh.push({ x: rock.x, y: rock.y, vx: g.random() * 3 - 1.5, vy: g.random() * 3 - 1.5, r: 18, gone: false });
            }
          } else {
            g.addScore(50);
          }
          g.sound("pop");
          break;
        }
      }
    }
    s.shots = s.shots.filter((x) => x.life > 0);
    s.rocks = s.rocks.filter((r) => !r.gone);
    for (const f of fresh) s.rocks.push(f);

    // Schiff trifft Fels
    if (sh.safe === 0) {
      const body = { x: sh.x, y: sh.y, r: 12 };
      let crashed = false;
      for (const rock of s.rocks) {
        if (g.hit(body, rock)) { crashed = true; break; }
      }
      if (crashed) {
        s.rocks = s.rocks.filter((r) => {
          const dx = r.x - sh.x;
          const dy = r.y - sh.y;
          return Math.sqrt(dx * dx + dy * dy) >= 100;
        });
        g.sound("hurt");
        g.loseLife();
        resetShip(s);
        sh.safe = 90;
      }
    }

    // Naechste Welle
    if (s.rocks.length === 0) {
      g.nextLevel();
      g.sound("level");
      spawnRocks(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const rock of s.rocks) {
      d.circle(rock.x, rock.y, rock.r, "yellow");
      d.circle(rock.x, rock.y, rock.r - 4, "ink");
    }
    for (const shot of s.shots) d.circle(shot.x, shot.y, shot.r, "red");

    const sh = s.ship;
    if (sh.safe === 0 || (sh.safe >> 2) % 2 === 0) {
      d.line(sh.x, sh.y, sh.x + g.cos(sh.ang) * 22, sh.y + g.sin(sh.ang) * 22, "red", 3);
      d.emoji("🚀", sh.x, sh.y, 28);
    }
  }
};

