// Autobahn-Ueberholer (nur Spiel-API, keine Importe): Spieler-Auto wechselt die Spur und regelt das Tempo.
// Ueberholte Autos bringen Punkte, Zusammenstoesse kosten ein Leben.
const TOP = 48;
const FIELD_H = 640;
const LANES = [58, 158, 258];
const CAR_W = 44;
const CAR_H = 70;
const PY = 520;
const PW = 44;
const PH = 60;
const PASS_Y = 570;
const WIN_PASSED = 40;

export default {
  title: "Autobahn-Ueberholer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return { px: 158, speed: 4, cars: [], passed: 0, inv: 0 };
  },

  update(s, input, g) {
    // Spur und Tempo
    if (input.left) s.px -= 4;
    if (input.right) s.px += 4;
    s.px = g.clamp(s.px, 50, 266);
    if (input.up) s.speed = Math.min(9, s.speed + 0.1);
    if (input.down) s.speed = Math.max(3, s.speed - 0.1);

    if (s.inv > 0) s.inv -= 1;

    // Neue Autos
    const spawnChance = 0.02 + 0.005 * g.level;
    if (g.random() < spawnChance) {
      const lane = g.randInt(0, 2);
      const busy = s.cars.some((c) => c.lane === lane && c.y < TOP + 120);
      if (!busy) {
        s.cars.push({ lane: lane, x: LANES[lane], y: TOP - 60, v: g.randInt(0, 2), counted: false });
      }
    }

    // Bewegung
    for (const c of s.cars) c.y += s.speed - c.v;

    // Ueberholen
    for (const c of s.cars) {
      if (!c.counted && c.y > PASS_Y) {
        c.counted = true;
        s.passed += 1;
        g.addScore(10 * g.level);
        g.sound("coin");
        if (s.passed >= WIN_PASSED) {
          g.win();
          return;
        }
        if (s.passed % 10 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }

    // Zusammenstoss
    if (s.inv === 0) {
      const me = { x: s.px, y: PY, w: PW, h: PH };
      let hitCar = null;
      for (const c of s.cars) {
        if (g.hit(me, { x: c.x, y: c.y, w: CAR_W, h: CAR_H })) { hitCar = c; break; }
      }
      if (hitCar) {
        s.cars = s.cars.filter((c) => c !== hitCar);
        s.inv = 60;
        g.sound("hurt");
        g.loseLife();
      }
    }

    // Aufraeumen
    s.cars = s.cars.filter((c) => c.y <= g.H + 10);
  },

  draw(s, d) {
    d.clear("cream");
    // Strasse
    d.rect(40, TOP, 280, FIELD_H - TOP, "ink");
    // Gestrichelte Spurlinien
    for (let y = TOP; y < FIELD_H; y += 40) {
      d.line(140, y, 140, y + 20, "yellow", 3);
      d.line(240, y, 240, y + 20, "yellow", 3);
    }
    // Andere Autos
    for (const c of s.cars) d.emoji("🚙", c.x + CAR_W / 2, c.y + CAR_H / 2, 40);
    // Spieler-Auto mit rotem Rahmen, blinkt in der Unverwundbarkeit
    if (s.inv === 0 || (s.inv >> 2) % 2 === 0) {
      d.rect(s.px, PY, PW, PH, "red", { round: 8 });
      d.rect(s.px + 3, PY + 3, PW - 6, PH - 6, "cream", { round: 6 });
      d.emoji("🏎️", s.px + PW / 2, PY + PH / 2, 34);
    }
  }
};

