// Wasserballon-Duell (nur Spiel-API, keine Importe).
// Zwei Tiere stehen sich gegenueber: 🐸 unten, 🐧 oben. Zug fuer Zug am selben Geraet:
// Nur die aktive Figur reagiert auf left/right/fire. Ein Schuss wirft einen Wasserballon
// zur Gegenseite und beendet den Zug. Nass werden ist die einzige Folge, kein Blut, keine Gewalt.
// Wer 3-mal nass wird (unten: g.gameOver), verliert; wer die Gegenseite 3-mal nass macht (g.win), gewinnt.
// Zeitlimit: 3600 Frames, danach g.gameOver().
const FIG_W = 40, FIG_H = 30;
const FIG_Y = [580, 70];
const EMO = ["🐸", "🐧"];
const LIMIT = 3600;
const WIN_WET = 3;
const MAX_BALLS = 2;

export default {
  title: "Wasserballon-Duell",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return {
      active: 0,
      xs: [160, 160],
      balls: [],
      wet: [0, 0],
      hits: 0,
      turnShot: 0
    };
  },

  update(s, input, g) {
    if (g.frame >= LIMIT) { g.gameOver(); return; }

    const me = s.active;
    const other = 1 - me;

    // Bewegung nur der aktiven Figur
    if (input.left) s.xs[me] -= 4;
    if (input.right) s.xs[me] += 4;
    s.xs[me] = g.clamp(s.xs[me], 4, g.W - FIG_W - 4);

    // Ballons fliegen, treffen oder verschwinden
    const keep = [];
    for (const b of s.balls) {
      b.x += b.dx;
      b.y += b.dy;
      const opp = 1 - b.owner;
      const rect = { x: s.xs[opp], y: FIG_Y[opp], w: FIG_W, h: FIG_H };
      if (g.hit(b, rect)) {
        s.wet[opp] += 1;
        s.hits += 1;
        g.addScore(10);
        g.sound("pop");
        if (s.hits % 5 === 0) { g.nextLevel(); g.sound("level"); }
        if (s.wet[0] >= WIN_WET) { g.gameOver(); return; }
        if (s.wet[1] >= WIN_WET) { g.win(); return; }
        continue;
      }
      if (b.y < g.TOP - 20 || b.y > g.H + 20 || b.x < -20 || b.x > g.W + 20) continue;
      keep.push(b);
    }
    s.balls = keep;

    // Schuss der aktiven Figur (ein Schuss pro Zug, hoechstens 2 Ballons je Seite)
    if (input.firePressed) {
      let mine = 0;
      for (const b of s.balls) if (b.owner === me) mine += 1;
      if (mine < MAX_BALLS) {
        const speed = 6 + 0.3 * g.level;
        const up = me === 0;
        s.balls.push({
          x: s.xs[me] + FIG_W / 2,
          y: up ? FIG_Y[me] - 10 : FIG_Y[me] + FIG_H + 10,
          dx: 0,
          dy: up ? -speed : speed,
          r: 7,
          owner: me
        });
        s.turnShot += 1;
        s.active = other;
        g.sound("shoot");
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.line(0, 330, g.W, 330, "yellow", 3);

    d.emoji(EMO[0], s.xs[0] + FIG_W / 2, FIG_Y[0] + FIG_H / 2, 36);
    d.emoji(EMO[1], s.xs[1] + FIG_W / 2, FIG_Y[1] + FIG_H / 2, 36);

    // Markierung der aktiven Figur
    const a = s.active;
    d.rect(s.xs[a], FIG_Y[a] + FIG_H + 2, FIG_W, 5, "red", { round: 2 });

    for (const b of s.balls) d.emoji("💧", b.x, b.y, 18);

    // Anzeigeleiste: Nass-Zaehler und Zug
    d.text(`Unten ${s.wet[0]}/3  Oben ${s.wet[1]}/3`, 10, 30, { size: 15, color: "ink", align: "left" });
    d.text(s.active === 0 ? "Zug: unten" : "Zug: oben", 350, 30, { size: 14, color: "ink", align: "right" });
  }
};

