// Dachhuepfer-Katze (nur Spiel-API, keine Importe)
// Die Katze huepft ueber Daecher und sammelt Fische 🐟. Moewen 🐦 (ab Level 2) kosten ein Leben,
// ebenso das Fallen in eine Luecke. Ein Level hat 10 Daecher mit je einem Fisch.
// Hinweis: Fischgraeten gibt es als Emoji nicht; der Fisch 🐟 ist das Sammelobjekt.
const FLOOR_Y = 600;
const ROW_GAP = 92;
const ROWS = 5;
const CAT_W = 22;
const CAT_H = 30;

export default {
  title: "Dachhuepfer-Katze",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = {
      cat: { x: 0, y: 0, w: CAT_W, h: CAT_H, vx: 0, vy: 0, ground: true },
      roofs: [],
      fish: [],
      birds: [],
      caught: 0,
      safe: 0
    };
    build(s, g);
    respawn(s);
    return s;
  },

  update(s, input, g) {
    if (g.frame > 3600) { g.gameOver(); return; }
    const c = s.cat;

    // Bewegung und Schwerkraft
    c.vx = input.left ? -3 : input.right ? 3 : 0;
    if (input.up && c.ground) { c.vy = -10.5; c.ground = false; g.sound("jump"); }
    c.vy = Math.min(c.vy + 0.5, 12);
    const oldBottom = c.y + c.h;
    c.x = g.clamp(c.x + c.vx, 0, g.W - c.w);
    c.y += c.vy;
    c.ground = false;

    // Landung nur beim Fallen von oben
    if (c.vy >= 0) {
      for (const r of s.roofs) {
        const over = c.x + c.w > r.x && c.x < r.x + r.w;
        if (over && oldBottom <= r.y && c.y + c.h >= r.y) {
          c.y = r.y - c.h;
          c.vy = 0;
          c.ground = true;
        }
      }
    }

    if (s.safe > 0) s.safe -= 1;

    // Moewen fliegen waagerecht hin und her
    for (const b of s.birds) {
      b.x += b.dir * (0.8 + 0.2 * g.level);
      if (b.x < 0) { b.x = 0; b.dir = 1; }
      if (b.x + b.w > g.W) { b.x = g.W - b.w; b.dir = -1; }
    }
    if (s.safe === 0 && s.birds.some((b) => g.hit(c, b))) {
      g.sound("hurt");
      g.loseLife();
      respawn(s);
      return;
    }

    // Fische einsammeln
    for (const f of s.fish) {
      if (!f.got && g.hit(c, f)) {
        f.got = true;
        s.caught += 1;
        g.addScore(10);
        g.sound("coin");
      }
    }
    s.fish = s.fish.filter((f) => !f.got);

    // Level geschafft: 10 Fische
    if (s.caught >= 10) {
      g.addScore(50);
      if (g.level >= 3) {
        g.sound("win");
        g.win();
        return;
      }
      g.nextLevel();
      g.sound("level");
      build(s, g);
      respawn(s);
      return;
    }

    // Sturz unter den Bildschirm
    if (c.y > g.H) {
      g.sound("hurt");
      g.loseLife();
      respawn(s);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.roofs) d.rect(r.x, r.y, r.w, r.h, "yellow", { round: 8, shadow: true, line: true });
    for (const f of s.fish) d.emoji("🐟", f.x + f.w / 2, f.y + f.h / 2, 18);
    for (const b of s.birds) d.emoji("🐦", b.x + b.w / 2, b.y + b.h / 2, 26);
    const c = s.cat;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) d.emoji("🐱", c.x + c.w / 2, c.y + c.h / 2, 32);
  }
};

// Baut Daecher, Fische und Moewen fuer das aktuelle Level neu.
// Jede Reihe hat zwei Daecher; ueberlappende Daecher zur Reihe darunter erlauben das Hochspringen.
function build(s, g) {
  s.roofs = [];
  s.fish = [];
  s.birds = [];
  s.caught = 0;

  for (let k = 0; k < ROWS; k++) {
    const y = FLOOR_Y - k * ROW_GAP;
    const w1 = g.randInt(90, 110);
    const x1 = g.randInt(4, 40);
    const w2 = g.randInt(90, 110);
    const x2 = x1 + w1 + g.randInt(20, 50);
    addRoof(s, x1, y, w1);
    addRoof(s, x2, y, w2);
  }

  for (const r of s.roofs) {
    s.fish.push({ x: r.x + r.w / 2 - 8, y: r.y - 22, w: 16, h: 16, got: false });
  }

  if (g.level >= 2) {
    const k = g.randInt(1, ROWS - 1);
    s.birds.push({
      x: g.randInt(0, 200),
      y: FLOOR_Y - k * ROW_GAP - 44,
      w: 26,
      h: 22,
