// Ball-Duell (nur Spiel-API, keine Importe): Du spielst unten mit dem Schlaeger, der Computer oben.
// Der Ball prallt von Schlaegern und Seitenwaenden ab. Verfehlst du ihn, verlierst du ein Leben.
// Verfehlt der Computer ihn, gibt es Punkte. Ab 50 Punkten hast du gewonnen.
const PAD_W = 80, PAD_H = 12, PAD_Y = 590, CPU_Y = 70, WIN_POINTS = 50;

export default {
  title: "Ball-Duell",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return {
      paddleX: 140,
      cpuX: 140,
      ball: { x: 180, y: 320, vx: 0, vy: 0, r: 8 },
      serve: 60,
      misses: 0
    };
  },

  update(s, input, g) {
    // Mein Schlaeger
    if (input.left) s.paddleX -= 5;
    if (input.right) s.paddleX += 5;
    s.paddleX = g.clamp(s.paddleX, 0, g.W - PAD_W);

    // Computer-Schlaeger folgt dem Ball
    const target = s.ball.x - 40;
    const step = 2.2 + 0.4 * g.level;
    const diff = target - s.cpuX;
    if (Math.abs(diff) <= step) s.cpuX = target;
    else s.cpuX += Math.sign(diff) * step;
    s.cpuX = g.clamp(s.cpuX, 0, g.W - PAD_W);

    // Aufschlag-Pause
    if (s.serve > 0) { s.serve -= 1; return; }

    const b = s.ball;
    b.x += b.vx;
    b.y += b.vy;

    // Seitenwaende
    if (b.x <= 8) { b.x = 8; b.vx = Math.abs(b.vx); }
    if (b.x >= g.W - 8) { b.x = g.W - 8; b.vx = -Math.abs(b.vx); }

    // Treffer mein Schlaeger (Ball kommt von oben)
    if (b.vy > 0 && g.hit(b, { x: s.paddleX, y: PAD_Y, w: PAD_W, h: PAD_H })) {
      b.vy = -Math.abs(b.vy);
      b.vx = g.clamp(b.vx + (b.x - (s.paddleX + PAD_W / 2)) * 0.06, -6, 6);
      b.y = PAD_Y - 12;
      g.sound("hit");
    }

    // Treffer Computer-Schlaeger (Ball kommt von unten)
    if (b.vy < 0 && g.hit(b, { x: s.cpuX, y: CPU_Y, w: PAD_W, h: PAD_H })) {
      b.vy = Math.abs(b.vy);
      b.vx = g.clamp(b.vx + (b.x - (s.cpuX + PAD_W / 2)) * 0.06, -6, 6);
      b.y = CPU_Y + PAD_H + 12;
      g.sound("hit");
    }

    // Ball an mir vorbei: ein Leben weg
    if (b.y > g.H) {
      g.sound("hurt");
      g.loseLife();
      launch(s, g, true);
      return;
    }

    // Ball am Computer vorbei: Punkte
    if (b.y < g.TOP) {
      g.addScore(10);
      s.misses += 1;
      if (g.score >= WIN_POINTS) { g.win(); return; }
      if (s.misses % 5 === 0) { g.nextLevel(); g.sound("level"); }
      launch(s, g, true);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    // Mittellinie gestrichelt
    for (let x = 6; x < g.W; x += 24) d.rect(x, 322, 12, 4, "yellow");
    // Schlaeger
    d.rect(s.cpuX, CPU_Y, PAD_W, PAD_H, "ink", { round: 4 });
    d.rect(s.paddleX, PAD_Y, PAD_W, PAD_H, "ink", { round: 4 });
