// Kuchen-Stapler (nur Spiel-API, keine Importe): Kuchenstuecke fallen von oben, bei voller Reihe verschwindet sie.
// Stapeln bis nach oben kostet ein Leben. Steuerung: links/rechts bewegen, unten schneller, Feuer dreht.
const W = 9, H = 14, CELL = 40, Y0 = 56;

// Tetromino-Formen als Offsets; die erste Zelle ist der Drehpunkt.
const SHAPES = [
  [[0, 0], [1, 0], [2, 0], [3, 0]],   // Gerade
  [[0, 0], [1, 0], [0, 1], [1, 1]],   // Quadrat
  [[0, 0], [0, 1], [0, 2], [1, 2]],   // L
  [[0, 0], [-1, 0], [1, 0], [0, 1]],  // T
  [[0, 0], [1, 0], [-1, 1], [0, 1]],  // S
  [[0, 0], [-1, 0], [0, 1], [1, 1]]   // Z
];
const EMOJI = ["🍰", "🎂", "🧁", "🍩", "🥧", "🍪"];

export default {
  title: "Kuchen-Stapler",
  controls: ["left", "right", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      board: emptyBoard(),
      piece: { cells: [] },
      next: g.randInt(0, SHAPES.length - 1),
      fallTimer: 0,
      moveCool: 0,
      lines: 0
    };
    spawn(s, g);
    return s;
  },

  update(s, input, g) {
    if (input.firePressed) rotate(s, g);

    if (input.left || input.right) {
      if (s.moveCool === 0) {
        const dx = input.left ? -1 : 1;
        if (fits(s.board, s.piece.cells, dx, 0)) shift(s.piece.cells, dx, 0);
        s.moveCool = 6;
      } else {
        s.moveCool -= 1;
      }
    } else {
      s.moveCool = 0;
    }

    s.fallTimer += 1;
    const interval = input.down ? 3 : Math.max(6, 30 - 3 * g.level);
    if (s.fallTimer >= interval) {
      s.fallTimer = 0;
      if (fits(s.board, s.piece.cells, 0, 1)) {
        shift(s.piece.cells, 0, 1);
      } else {
        if (land(s, g)) return;
        spawn(s, g);
      }
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, W * CELL, H * CELL, "yellow", { round: 6, line: true });
    for (let i = 0; i < s.board.length; i++) {
      const v = s.board[i];
      if (v === null) continue;
      const x = i % W, y = Math.floor(i / W);
      d.emoji(v, x * CELL + CELL / 2, Y0 + y * CELL + CELL / 2, 34);
    }
    for (const c of s.piece.cells) {
      d.emoji(c.e, c.x * CELL + CELL / 2, Y0 + c.y * CELL + CELL / 2, 34);
    }
  }
};

function emptyBoard() {
  const b = [];
  for (let i = 0; i < W * H; i++) b.push(null);
  return b;
}

function spawn(s, g) {
  const t = s.next;
  s.next = g.randInt(0, SHAPES.length - 1);
  const cells = SHAPES[t].map((o) => ({ x: 3 + o[0], y: o[1], e: EMOJI[t] }));
  s.piece = { cells: cells };
  s.fallTimer = 0;
  if (!fits(s.board, cells, 0, 0)) {
    // Spawn blockiert: Stapel bis oben, Leben weg, Feld leeren, neues Teil
    g.loseLife();
    s.board = emptyBoard();
  }
}

function fits(board, cells, dx, dy) {
  for (const c of cells) {
    const nx = c.x + dx, ny = c.y + dy;
    if (nx < 0 || nx >= W || ny < 0 || ny >= H) return false;
    if (board[ny * W + nx] !== null) return false;
  }
  return true;
}

function shift(cells, dx, dy) {
  for (const c of cells) { c.x += dx; c.y += dy; }
}

function rotate(s, g) {
  const cells = s.piece.cells;
  const p = cells[0];
  const turned = cells.map((c) => {
    const rx = c.x - p.x, ry = c.y - p.y;
    return { x: p.x - ry, y: p.y + rx, e: c.e };
  });
  if (fits(s.board, turned, 0, 0)) {
    s.piece.cells = turned;
    g.sound("jump");
  }
}

// Gibt true zurueck, wenn das Spiel durch Sieg beendet wurde.
function land(s, g) {
  for (const c of s.piece.cells) {
    s.board[c.y * W + c.x] = c.e;
    g.addScore(1);
  }

  const rows = [];
  for (let y = 0; y < H; y++) {
    let full = true;
    for (let x = 0; x < W; x++) if (s.board[y * W + x] === null) { full = false; break; }
    if (!full) rows.push(s.board.slice(y * W, y * W + W));
  }
  const cleared = H - rows.length;

  if (cleared > 0) {
    const nb = [];
    for (let i = 0; i < cleared; i++) for (let x = 0; x < W; x++) nb.push(null);
    for (const r of rows) for (const v of r) nb.push(v);
    s.board = nb;
    // je geloeschter Reihe 100 * Anzahl * Level Punkte
    g.addScore(100 * cleared * cleared * g.level);
    g.sound("pop");
    s.lines += cleared;
    while (s.lines >= 5) {
      s.lines -= 5;
      g.nextLevel();
      g.sound("level");
    }
    if (g.level >= 5) {
      g.win();
      return true;
    }
  } else {
    g.sound("hit");
  }
  return false;
}

