export default {
  title: "Donut im Labyrinth",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    const s = { mz: 0, streusel: [], dn: { c: START.c, r: START.r, dx: 0, dy: 0 }, wx: 0, wy: 0, moewen: [], safe: 0 };
    build(s, g);
    return s;
  },

  update(s, input, g) {
    if (input.left) { s.wx = -1; s.wy = 0; }
    else if (input.right) { s.wx = 1; s.wy = 0; }
    else if (input.up) { s.wx = 0; s.wy = -1; }
    else if (input.down) { s.wx = 0; s.wy = 1; }

    const dn = s.dn;
    if (g.frame % 8 === 0) {
      if ((s.wx !== 0 || s.wy !== 0) && isOpen(s, dn.c + s.wx, dn.r + s.wy)) { dn.dx = s.wx; dn.dy = s.wy; }
      if (isOpen(s, dn.c + dn.dx, dn.r + dn.dy)) { dn.c += dn.dx; dn.r += dn.dy; }
      else { dn.dx = 0; dn.dy = 0; }
    }

    const before = s.streusel.length;
    s.streusel = s.streusel.filter((p) => !(p.c === dn.c && p.r === dn.r));
    const got = before - s.streusel.length;
    if (got > 0) { g.addScore(10 * got); g.sound("coin"); }

    if (s.streusel.length === 0) {
      if (g.level >= 3) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      build(s, g);
      return;
    }

    if (g.frame % 10 === 0) {
      for (const m of s.moewen) stepBird(s, m, dn, g);
    }

    if (s.safe > 0) s.safe -= 1;
    if (s.safe === 0) {
      const dnCircle = cellCircle(dn);
      if (s.moewen.some((m) => g.hit(cellCircle(m), dnCircle))) {
        g.sound("hurt");
        g.loseLife();
        resetPositions(s);
        s.safe = 60;
        return;
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    const grid = MAZES[s.mz];
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (grid[r].charAt(c) === "#") d.rect(c * CELL, Y0 + r * CELL, CELL, CELL, "ink", {});
      }
    }
    for (const p of s.streusel) d.circle(p.c * CELL + CELL / 2, Y0 + p.r * CELL + CELL / 2, 4, "yellow", {});
    for (const m of s.moewen) d.emoji("🐦", m.c * CELL + CELL / 2, Y0 + m.r * CELL + CELL / 2, 20);
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      const x = s.dn.c * CELL + CELL / 2, y = Y0 + s.dn.r * CELL + CELL / 2;
      d.circle(x, y, 10, "red", {});
      d.emoji("🍩", x, y, 18);
    }
  }
};

function build(s, g) {
  s.mz = (g.level - 1) % 2;
  const grid = MAZES[s.mz];
  s.streusel = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (grid[r].charAt(c) === ".") s.streusel.push({ c: c, r: r });
    }
  }
  s.dn = { c: START.c, r: START.r, dx: 0, dy: 0 };
  s.wx = 0;
  s.wy = 0;
  s.safe = 0;
  let n = g.level + 1;
  if (n > 4) n = 4;
  s.moewen = [];
  for (let i = 0; i < n; i++) {
    s.moewen.push({ c: CORNERS[i].c, r: CORNERS[i].r, dx: 0, dy: 0 });
  }
}

function resetPositions(s) {
  s.dn.c = START.c;
  s.dn.r = START.r;
  s.dn.dx = 0;
  s.dn.dy = 0;
  s.wx = 0;
  s.wy = 0;
  for (let i = 0; i < s.moewen.length; i++) {
    const m = s.moewen[i];
    m.c = CORNERS[i].c;
    m.r = CORNERS[i].r;
    m.dx = 0;
    m.dy = 0;
  }
}

function isOpen(s, c, r) {
  if (c < 0 || r < 0 || c >= COLS || r >= ROWS) return false;
  return MAZES[s.mz][r].charAt(c) !== "#";
}

function cellCircle(p) {
  return { x: p.c * CELL + CELL / 2, y: Y0 + p.r * CELL + CELL / 2, r: 10 };
}

function stepBird(s, m, dn, g) {
  const cand = [];
  for (const d of DIRS) {
    const back = (m.dx !== 0 || m.dy !== 0) && d.x === -m.dx && d.y === -m.dy;
    if (!back && isOpen(s, m.c + d.x, m.r + d.y)) cand.push(d);
  }
  if (cand.length === 0) {
    if (isOpen(s, m.c - m.dx, m.r - m.dy)) cand.push({ x: -m.dx, y: -m.dy });
    else return;
  }
  let pick = cand[0];
  if (cand.length > 1) {
    if (g.random() < 0.6) {
      let bestD = 99999;
      for (const d of cand) {
        const nc = m.c + d.x - dn.c, nr = m.r + d.y - dn.r;
        const dd = nc * nc + nr * nr;
        if (dd < bestD) { bestD = dd; pick = d; }
      }
    } else {
      pick = cand[g.randInt(0, cand.length - 1)];
    }
  }
  m.dx = pick.x;
  m.dy = pick.y;
  m.c += pick.x;
  m.r += pick.y;
}

