// Alle Streusel eines Labyrinths gesammelt = gewonnen.
const CELL = 24, COLS = 15, ROWS = 24, Y0 = 48;
const START = { c: 7, r: 21 };
const CORNERS = [{ c: 1, r: 1 }, { c: 13, r: 1 }, { c: 1, r: 21 }, { c: 13, r: 21 }];
const DIRS = [{ x: 1, y: 0 }, { x: -1, y: 0 }, { x: 0, y: 1 }, { x: 0, y: -1 }];

// Labyrinth 1 (Level ungerade) und Labyrinth 2 (Level gerade). Jede Zeile hat 15 Zeichen, # = Wand.
const MAZES = [
  [
    "###############",
    "#.............#",
    "#############.#",
    "#.............#",
    "#.#############",
    "#.............#",
    "#############.#",
    "#.............#",
    "#.#############",
    "#.............#",
    "#############.#",
    "#.............#",
    "#.#############",
    "#.............#",
    "#############.#",
    "#.............#",
    "#.#############",
    "#.............#",
    "#############.#",
    "#.............#",
    "#.#############",
    "#.............#",
    "###############",
    "###############"
  ],
  [
    "###############",
    "#.............#",
    "#######.#######",
    "#.............#",
    "###.###########",
    "#.............#",
    "###########.###",
    "#.............#",
    "#####.#########",
    "#.............#",
    "#########.#####",
    "#.............#",
    "##.############",
    "#.............#",
    "############.##",
    "#.............#",
    "######.########",
    "#.............#",
    "##########.####",
    "#.............#",
    "####.##########",
    "#.............#",
    "###############",
    "###############"
  ]
];

export default {
  title: "Donut im Labyrinth",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    const s = { mz: 0, streusel: [], dn: { c: START.c, r: START.r, dx: 0, dy: 0 }, wx: 0, wy: 0, moewen: [], safe: 0 };
    build(s, g);
    return s;
  },

  update(s, input, g) {
    if (input.left) { s.wx = -1; s.wy = 0; }
    else if (input.right) { s.wx = 1; s.wy = 0; }
    else if (input.up) { s.wx = 0; s.wy = -1; }
    else if (input.down) { s.wx = 0; s.wy = 1; }

    const dn = s.dn;
    if (g.frame % 8 === 0) {
      if ((s.wx !== 0 || s.wy !== 0) && isOpen(s, dn.c + s.wx, dn.r + s.wy)) { dn.dx = s.wx; dn.dy = s.wy; }
      if (isOpen(s, dn.c + dn.dx, dn.r + dn.dy)) { dn.c += dn.dx; dn.r += dn.dy; }
      else { dn.dx = 0; dn.dy = 0; }
    }

    const before = s.streusel.length;
    s.streusel = s.streusel.filter((p) => !(p.c === dn.c && p.r === dn.r));
    const got = before - s.streusel.length;
    if (got > 0) { g.addScore(10 * got); g.sound("coin"); }

    // Gewonnen, sobald alle Streusel des Labyrinths gesammelt sind
    if (s.streusel.length === 0) {
      g.sound("win");
      g.win();
      return;
    }

    if (g.frame % 10 === 0) {
      for (const m of s.moewen) stepMoewe(s, m, dn, g);
    }

    if (s.safe > 0) s.safe -= 1;
    if (s.safe === 0) {
      const dnCircle = cellCircle(dn);
      if (s.moewen.some((m) => g.hit(cellCircle(m), dnCircle))) {
        g.sound("hurt");
        g.loseLife();
        resetPositions(s);
        s.safe = 60;
        return;
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    const grid = MAZES[s.mz];
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (grid[r].charAt(c) === "#") d.rect(c * CELL, Y0 + r * CELL, CELL, CELL, "ink", {});
      }
    }
    for (const p of s.streusel) d.circle(p.c * CELL + CELL / 2, Y0 + p.r * CELL + CELL / 2, 4, "yellow", {});
    for (const m of s.moewen) drawMoewe(m, d, g);
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      const x = s.dn.c * CELL + CELL / 2, y = Y0 + s.dn.r * CELL + CELL / 2;
      d.circle(x, y, 10, "red", {});
      d.emoji("🍩", x, y, 18);
    }
  }
};

function build(s, g) {
  s.mz = (g.level - 1) % 2;
  const grid = MAZES[s.mz];
  s.streusel = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (grid[r].charAt(c) === ".") s.streusel.push({ c: c, r: r });
    }
  }
  s.dn = { c: START.c, r: START.r, dx: 0, dy: 0 };
  s.wx = 0;
  s.wy = 0;
  s.safe = 0;
  let n = g.level + 1;
  if (n > 4) n = 4;
  s.moewen = [];
  for (let i = 0; i < n; i++) {
    s.moewen.push({ c: CORNERS[i].c, r: CORNERS[i].r, dx: 0, dy: 0 });
  }
}

function resetPositions(s) {
  s.dn.c = START.c;
  s.dn.r = START.r;
  s.dn.dx = 0;
  s.dn.dy = 0;
  s.wx = 0;
  s.wy = 0;
  for (let i = 0; i < s.moewen.length; i++) {
    const m = s.moewen[i];
    m.c = CORNERS[i].c;
    m.r = CORNERS[i].r;
    m.dx = 0;
    m.dy = 0;
  }
}

function isOpen(s, c, r) {
  if (c < 0 || r < 0 || c >= COLS || r >= ROWS) return false;
  return MAZES[s.mz][r].charAt(c) !== "#";
}

function cellCircle(p) {
  return { x: p.c * CELL + CELL / 2, y: Y0 + p.r * CELL + CELL / 2, r: 10 };
}

// Moewe aus Formen: Koerper, Schnabel und zwei schlagende Fluegel (ink)
function drawMoewe(m, d, g) {
  const x = m.c * CELL + CELL / 2, y = Y0 + m.r * CELL + CELL / 2;
  const flap = (g.frame >> 3) % 2 === 0 ? -5 : 1;
  d.line(x - 10, y + flap, x, y, "ink", 3);
  d.line(x, y, x + 10, y + flap, "ink", 3);
  d.circle(x, y, 5, "ink", {});
  d.circle(x + 6, y - 1, 2, "yellow", {});
}

function stepMoewe(s, m, dn, g) {
  const cand = [];
  for (const d of DIRS) {
    const back = (m.dx !== 0 || m.dy !== 0) && d.x === -m.dx && d.y === -m.dy;
    if (!back && isOpen(s, m.c + d.x, m.r + d.y)) cand.push(d);
  }
  if (cand.length === 0) {
    if (isOpen(s, m.c - m.dx, m.r - m.dy)) cand.push({ x: -m.dx, y: -m.dy });
    else return;
  }
  let pick = cand[0];
  if (cand.length > 1) {
    if (g.random() < 0.6) {
      let bestD = 99999;
      for (const d of cand) {
        const nc = m.c + d.x - dn.c, nr = m.r + d.y - dn.r;
        const dd = nc * nc + nr * nr;
        if (dd < bestD) { bestD = dd; pick = d; }
      }
    } else {
      pick = cand[g.randInt(0, cand.length - 1)];
    }
  }
  m.dx = pick.x;
  m.dy = pick.y;
  m.c += pick.x;
  m.r += pick.y;
}

// Memory Tierpaare (nur Spiel-API, keine Importe). Tier-Emojis als Motive, keine Fotos.
const SYMS = ["🐶", "🐱", "🐰", "🐻", "🐼", "🦊"];
const CW = 72, CH = 88;

export default {
  title: "Memory Tierpaare",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 5,

  init(g) {
    const cards = [];
    for (let k = 0; k < SYMS.length; k++) {
      cards.push({ sym: SYMS[k], up: false, done: false });
      cards.push({ sym: SYMS[k], up: false, done: false });
    }
    // Fisher-Yates mit g.random
    for (let i = cards.length - 1; i > 0; i--) {
      const j = g.randInt(0, i);
      const tmp = cards[i];
      cards[i] = cards[j];
      cards[j] = tmp;
    }
    return { cards: cards, cur: 0, open: [], wait: 0, cool: 0, found: 0 };
  },

  update(s, input, g) {
    if (g.frame >= 5400) { g.gameOver(); return; }

    if (s.cool > 0) s.cool -= 1;

    // Fehlpaar oder Treffer nach kurzer Wartezeit auswerten
    if (s.open.length === 2) {
      s.wait += 1;
      if (s.wait >= 40) {
        const a = s.cards[s.open[0]];
        const b = s.cards[s.open[1]];
        if (a.sym === b.sym) {
          a.done = true;
          b.done = true;
          s.found += 1;
          s.open = [];
          s.wait = 0;
          g.addScore(20);
          g.sound("coin");
          if (s.found >= 6) { g.win(); return; }
        } else {
          a.up = false;
          b.up = false;
          s.open = [];
          s.wait = 0;
          g.sound("hurt");
          g.loseLife();
          if (g.lives <= 0) return;
        }
      }
    }

    // Cursor bewegen (innerhalb der Zeile bzw. Spalte, nicht umbrechen)
    if (s.cool === 0) {
      const col = s.cur % 4;
      const row = Math.floor(s.cur / 4);
      let nc = s.cur;
      if (input.left && col > 0) nc = s.cur - 1;
      else if (input.right && col < 3) nc = s.cur + 1;
      else if (input.up && row > 0) nc = s.cur - 4;
      else if (input.down && row < 2) nc = s.cur + 4;
      if (nc !== s.cur) { s.cur = nc; s.cool = 8; }
    }

    // Karte umdrehen
    if (input.firePressed) {
      const c = s.cards[s.cur];
      if (!c.up && !c.done && s.open.length < 2) {
        c.up = true;
        s.open.push(s.cur);
        g.sound("pop");
      }
    }
  },

  draw(s, d) {
    d.clear("cream");
    for (let i = 0; i < s.cards.length; i++) {
      const c = s.cards[i];
      const x = 24 + (i % 4) * 84;
      const y = 110 + Math.floor(i / 4) * 104;
      if (c.done) {
        d.rect(x, y, CW, CH, "red", { round: 10, line: true });
        d.emoji(c.sym, x + 36, y + 44, 48);
      } else if (c.up) {
        d.rect(x, y, CW, CH, "yellow", { round: 10, line: true });
        d.emoji(c.sym, x + 36, y + 44, 48);
      } else {
        d.rect(x, y, CW, CH, "ink", { round: 10, shadow: true });
        d.text("?", x + 36, y + 54, { size: 40, color: "cream", align: "center" });
      }
    }
    // Cursor als Umriss um die aktuelle Karte
    const cx = 24 + (s.cur % 4) * 84 - 4;
    const cy = 110 + Math.floor(s.cur / 4) * 104 - 4;
    const w = CW + 8, h = CH + 8;
    d.line(cx, cy, cx + w, cy, "ink", 3);
    d.line(cx, cy + h, cx + w, cy + h, "ink", 3);
    d.line(cx, cy, cx, cy + h, "ink", 3);
    d.line(cx + w, cy, cx + w, cy + h, "ink", 3);
  }
};

