// Wuerfel bis 100 (nur Spiel-API, keine Importe). Vier Personen wuerfeln abwechselnd am selben Geraet.
// Fire wuerfelt, down sichert die Zug-Punkte. Eine 1 verfaellt den Zug. Wer zuerst 100 hat, gewinnt.
// Haekchen h6 (Wuerfel mit echten Augen) ist nicht machbar: stattdessen Zahl im Wuerfel-Rechteck und 🎲.
const ROW_Y = 56, ROW_H = 62;

export default {
  title: "Wuerfel bis 100",
  controls: ["fire", "down"],
  lives: 3,

  init(g) {
    return {
      players: [0, 0, 0, 0],
      cur: 0,
      turn: 0,
      die: 0,
      cool: 0,
      prevDown: false,
      winner: -1,
      msg: "Spieler 1 ist dran"
    };
  },

  update(s, input, g) {
    if (s.winner >= 0) return;
    if (s.cool > 0) s.cool -= 1;

    if (input.firePressed && s.cool === 0) {
      s.die = g.randInt(1, 6);
      s.cool = 12;
      g.sound("pop");
      if (s.die === 1) {
        s.turn = 0;
        s.msg = "Eine 1, Zug vorbei";
        s.cur = (s.cur + 1) % 4;
        g.sound("hurt");
      } else {
        s.turn += s.die;
        s.msg = "Gewuerfelt: " + s.die;
      }
    }

    if (input.down && !s.prevDown) {
      const prev = s.cur;
      s.players[prev] += s.turn;
      g.addScore(s.turn);
      s.turn = 0;
      s.cur = (prev + 1) % 4;
      s.msg = "Gesichert";
      g.sound("coin");
      if (s.players[prev] >= 100) {
        s.winner = prev;
        g.sound("win");
        g.win();
        return;
      }
    }

    s.prevDown = input.down === true;
  },

  draw(s, d) {
    d.clear("cream");

    for (let i = 0; i < 4; i++) {
      const x = 16, y = ROW_Y + i * ROW_H, w = 328, h = 52;
      const active = i === s.cur && s.winner < 0;
      if (active) {
        d.rect(x - 4, y - 4, w + 8, h + 8, "red", { round: 14 });
        d.rect(x, y, w, h, "yellow", { round: 12 });
      } else {
        d.rect(x, y, w, h, "cream", { round: 12, line: true });
      }
      d.text("Spieler " + (i + 1), x + 14, y + 16, { size: 20, color: "ink", align: "left" });
      d.text("Konto " + s.players[i], x + 180, y + 16, { size: 20, color: "ink", align: "left" });
      if (active) {
        d.text("Zug " + s.turn, x + 180, y + 36, { size: 16, color: "red", align: "left" });
      }
    }

    d.rect(110, 430, 140, 140, "yellow", { round: 20, shadow: true, line: true });
    d.text(s.die > 0 ? String(s.die) : "?", 180, 460, { size: 64, color: "ink", align: "center" });
    d.emoji("🎲", 70, 500, 56);

    if (s.winner >= 0) {
      d.text("Spieler " + (s.winner + 1) + " gewinnt", 180, 340, { size: 28, color: "red", align: "center" });
    }

    d.text(s.msg, 180, 600, { size: 18, color: "ink", align: "center" });
    d.text("Feuer: wuerfeln | Runter: sichern", 180, 624, { size: 14, color: "ink", align: "center" });
  }
};

