// Gummibaer-Schaetzen (nur Spiel-API, keine Importe).
// Ein Glas voller Baeren, die Anzahl wird geschaetzt. Der Computer schaetzt in jeder Runde mit.
const GLASS = { x: 50, y: 130, w: 260, h: 380 };
const REVEAL_FRAMES = 180;
const COUNT_FRAMES = 120;
const LOCK_FRAMES = 240;
const ROUNDS = 5;

export default {
  title: "Gummibaer-Schaetzen",
  controls: ["up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      phase: "guess", t: 0, round: 1, n: 0, guess: 30, cg: 0, tick: 0, idle: 0,
      bears: [], pp: 0, cp: 0, msg: ""
    };
    newRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "guess") {
      const dir = input.up ? 1 : input.down ? -1 : 0;
      if (dir === 0) {
        s.tick = 0;
      } else {
        if (s.tick === 0) s.guess = g.clamp(s.guess + dir, 0, 99);
        s.tick = (s.tick + 1) % 3;
      }
      s.idle += 1;
      if (input.firePressed || s.idle >= LOCK_FRAMES) {
        s.phase = "reveal";
        s.t = 0;
        evaluate(s, g);
      }
      return;
    }

    // Phase "reveal": Anzeige, danach naechste Runde oder Spielende
    s.t += 1;
    if (s.t < REVEAL_FRAMES) return;

    if (s.round >= ROUNDS) {
      if (s.pp > s.cp) g.win();
      else g.gameOver();
      return;
    }
    if (s.round % 2 === 0) { g.nextLevel(); g.sound("level"); }
    s.round += 1;
    newRound(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(GLASS.x, GLASS.y, GLASS.w, GLASS.h, "yellow", { round: 24, line: true });

    const total = s.bears.length;
    const shown = s.phase === "guess" ? total : Math.min(total, Math.floor(s.t * total / COUNT_FRAMES));
    for (let i = 0; i < shown; i++) {
      const b = s.bears[i];
      d.emoji("🐻", b.x, b.y, 22);
    }

    if (s.phase === "guess") {
      d.text("Runde " + s.round + " von " + ROUNDS, 180, 530, { size: 16, color: "ink", align: "center" });
      d.text("Deine Schaetzung: " + s.guess, 180, 570, { size: 26, color: "ink", align: "center" });
      d.text("Hoch/Runter aendern, Feuer = sperren", 180, 610, { size: 14, color: "ink", align: "center" });
    } else {
      if (s.t < COUNT_FRAMES) {
        d.text("Die Baeren werden gezaehlt ...", 180, 570, { size: 20, color: "ink", align: "center" });
      } else {
        d.text("Anzahl: " + s.n, 180, 560, { size: 26, color: "ink", align: "center" });
        d.text("Du " + s.guess + " / Computer " + s.cg, 180, 595, { size: 20, color: "ink", align: "center" });
        d.text(s.msg, 180, 625, { size: 16, color: "red", align: "center" });
      }
    }
  }
};

function newRound(s, g) {
  s.phase = "guess";
  s.t = 0;
  s.idle = 0;
  s.tick = 0;
  s.guess = 30;
  s.msg = "";
  s.n = g.randInt(12, 60);
  const err = Math.max(2, 16 - 3 * g.level);
  s.cg = g.clamp(s.n + Math.round((g.random() * 2 - 1) * err), 0, 99);
  s.bears = [];
  for (let i = 0; i < s.n; i++) {
    s.bears.push({
      x: Math.round(GLASS.x + 20 + g.random() * (GLASS.w - 40)),
      y: Math.round(GLASS.y + 20 + g.random() * (GLASS.h - 40))
    });
  }
}

function evaluate(s, g) {
  const dp = Math.abs(s.guess - s.n);
  const dc = Math.abs(s.cg - s.n);
  if (dp < dc) {
    const pts = dp === 0 ? 25 : 10;
    s.pp += pts;
    g.addScore(pts);
    g.sound("coin");
    s.msg = dp === 0 ? "Genau getroffen! +25 Punkte" : "Du liegst naeher dran! +10 Punkte";
  } else if (dc < dp) {
    const pts = dc === 0 ? 25 : 10;
    s.cp += pts;
    g.sound("hurt");
    s.msg = dc === 0 ? "Computer trifft genau: Leben weg" : "Computer liegt naeher dran: Leben weg";
    g.loseLife();
  } else {
    g.sound("pop");
    s.msg = "Gleichstand: keine Punkte";
  }
}

