// Segel-Armada (nur Spiel-API, keine Importe): Segelboote fliegen in Reihen heran und werfen Kanonenkugeln aufs Floss.
// Das Floss wirft Wasserbomben nach oben. Keine Gewalt gegen Menschen, keine Menschen im Spiel.
export default {
  title: "Segel-Armada",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    return {
      raft: { x: 160, y: 580, w: 40, h: 28 },
      bombs: [],
      balls: [],
      boats: fleet(g, 1),
      dir: 1,
      cool: 0,
      safe: 0
    };
  },

  update(s, input, g) {
    const raft = s.raft;
    if (input.left) raft.x -= 4;
    if (input.right) raft.x += 4;
    raft.x = g.clamp(raft.x, 4, g.W - raft.w - 4);

    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;

    // Wasserbomben nach oben
    if ((input.firePressed || input.fire) && s.cool === 0 && s.bombs.length < 3) {
      s.bombs.push({ x: raft.x + raft.w / 2, y: raft.y, r: 7 });
      s.cool = 14;
      g.sound("shoot");
    }
    for (const b of s.bombs) b.y -= 8;
    s.bombs = s.bombs.filter((b) => b.y > g.TOP);

    // Flotte: seitwaerts, am Rand eine Reihe tiefer und Richtungswechsel
    const speed = 0.5 + 0.2 * g.level + (24 - s.boats.length) * 0.04;
    let edge = false;
    for (const b of s.boats) {
      b.x += s.dir * speed;
      if (b.x < 6 || b.x + b.w > g.W - 6) edge = true;
    }
    if (edge) {
      s.dir = -s.dir;
      for (const b of s.boats) {
        b.x += s.dir * speed;
        b.y += 14;
      }
    }

    // Treffer: Boot versinkt, Punkte
    for (const bomb of s.bombs) {
      for (const boat of s.boats) {
        if (!boat.sunk && g.hit(bomb, boat)) {
          boat.sunk = true;
          bomb.y = -100;
          g.addScore(10 * g.level);
          g.sound("pop");
          break;
        }
      }
    }
    s.boats = s.boats.filter((b) => !b.sunk);
    s.bombs = s.bombs.filter((b) => b.y > g.TOP);

    // Gegenfeuer aus einem zufaelligen Boot
    if (s.boats.length > 0 && g.random() < 0.012 + 0.006 * g.level) {
      const b = s.boats[g.randInt(0, s.boats.length - 1)];
      s.balls.push({ x: b.x + b.w / 2, y: b.y + b.h, r: 5 });
    }
    for (const c of s.balls) c.y += 2.5 + 0.4 * g.level;
    s.balls = s.balls.filter((c) => c.y < g.H + 10);

    // Treffer aufs Floss: Leben weg, kurzer Schutz
    if (s.safe === 0 && s.balls.some((c) => g.hit(c, raft))) {
      s.balls = [];
      s.safe = 60;
      g.sound("hurt");
      g.loseLife();
    }

    // Ende: Flotte erreicht das Floss
    if (s.boats.some((b) => b.y + b.h >= raft.y)) {
      g.gameOver();
      return;
    }

    // Flotte geschafft: naechste Stufe
    if (s.boats.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.boats = fleet(g, g.level);
      s.balls = [];
      s.bombs = [];
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    // Wellenlinien des Meeres
    for (let y = 120; y < g.H; y += 60) {
      const wave = (g.frame >> 3) % 6;
      d.line(0, y + wave, g.W, y + wave, "yellow", 2);
    }

    // Boote fliegen: Schwebehoehe 0 bis 18 px. Der Schatten liegt fest auf dem Meer
    // und wird schmaler, je hoeher das Boot fliegt. Eine Haltelinie zeigt die Flughoehe.
