    const tmp = deck[i];
    deck[i] = deck[j];
    deck[j] = tmp;
  }
  s.hand = [];
  s.cpu = [];
  for (let k = 0; k < 5; k++) {
    s.hand.push(deck.pop());
    s.cpu.push(deck.pop());
  }
  s.pile = [deck.pop()];
  s.deck = deck;
  s.cursor = 0;
  s.cpuWait = 0;
  s.t = 0;
  s.mv = 0;
  s.prevUp = false;
  s.msg = "";
  s.msgT = 0;
}

function playerWins(s, g) {
  g.addScore(50);
  s.won += 1;
  if (s.won >= WINS_TO_WIN) {
    g.sound("win");
    g.win();
    return;
  }
  g.nextLevel();
  g.sound("level");
  newRound(s, g);
}

function computerWins(s, g) {
  if (g.lives <= 1) {
    g.sound("lose");
    g.gameOver();
    return;
  }
  g.sound("hurt");
  g.loseLife();
  newRound(s, g);
}

function resolveByCount(s, g) {
  const p = s.hand.length;
  const c = s.cpu.length;
  if (p < c) playerWins(s, g);
  else computerWins(s, g);
}

function fits(card, top) {
  return card.suit === top.suit || card.rank === top.rank;
}

function anyFits(list, top) {
  return list.some((c) => fits(c, top));
}

function firstFit(list, top) {
  for (let i = 0; i < list.length; i++) {
    if (fits(list[i], top)) return i;
  }
  return -1;
}

function say(s, text) {
  s.msg = text;
  s.msgT = MSG_TIME;
}

function txtColor(suit) {
  return suit === 2 ? "cream" : "ink";
}

