        s.pile.push(s.cpu.splice(i, 1)[0]);
        g.sound("pop");
        if (s.cpu.length === 0) { computerWins(s, g); return; }
      } else if (s.deck.length > 0) {
        s.cpu.push(s.deck.pop());
      }
    }

    // Festgefahren: Stapel leer und niemand kann legen
    const top2 = s.pile[s.pile.length - 1];
    if (s.deck.length === 0 && !anyFits(s.hand, top2) && !anyFits(s.cpu, top2)) {
      resolveByCount(s, g);
      return;
    }

    // Zeitlimit pro Runde
    if (s.t >= TIME_LIMIT) {
      resolveByCount(s, g);
      return;
    }
  },

  draw(s, d) {
    d.clear("cream");

    // Computerhand (verdeckt, nur Anzahl)
    const n = s.cpu.length;
    const sp = Math.min(14, Math.floor(300 / Math.max(1, n)));
    d.text("Computer: " + n, 20, 100, { size: 14, color: "ink", align: "left" });
    for (let i = 0; i < n; i++) d.rect(20 + i * sp, 70, 10, 14, "ink", { round: 2 });

    // Ablagestapel
    const top = s.pile[s.pile.length - 1];
    d.rect(145, 300, 70, 100, SUIT_COLORS[top.suit], { round: 8, line: true, shadow: true });
    d.text(String(top.rank), 180, 350, { size: 40, color: txtColor(top.suit), align: "center" });
    d.text("Stapel: " + s.deck.length, 180, 420, { size: 14, color: "ink", align: "center" });
    if (s.msg) d.text(s.msg, 180, 280, { size: 14, color: "red", align: "center" });

    // Eigene Hand
    const m = s.hand.length;
    const step = m > 1 ? Math.min(56, Math.floor(300 / (m - 1))) : 56;
    d.text("Du: " + m, 20, 486, { size: 14, color: "ink", align: "left" });
    if (m > 0) {
      const cur = Math.min(s.cursor, m - 1);
      d.rect(20 + cur * step - 4, 496, 58, 84, "red", { round: 8 });
    }
    for (let i = 0; i < m; i++) {
      const c = s.hand[i];
      const x = 20 + i * step;
      d.rect(x, 500, 50, 76, SUIT_COLORS[c.suit], { round: 6, line: true });
      d.text(String(c.rank), x + 25, 538, { size: 24, color: txtColor(c.suit), align: "center" });
    }

    d.text("Wahl: links/rechts  Ablegen: Feuer  Ziehen: oben", 180, 620, { size: 10, color: "ink", align: "center" });
  }
};

function newRound(s, g) {
  const deck = [];
  for (let suit = 0; suit < 4; suit++) {
    for (let rank = 1; rank <= 10; rank++) deck.push({ suit, rank });
  }
  for (let i = deck.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const tmp = deck[i];
    deck[i] = deck[j];
    deck[j] = tmp;
  }
  s.hand = [];
  s.cpu = [];
  for (let k = 0; k < 5; k++) {
    s.hand.push(deck.pop());
    s.cpu.push(deck.pop());
  }
  s.pile = [deck.pop()];
  s.deck = deck;
  s.cursor = 0;
  s.cpuWait = 0;
  s.t = 0;
  s.mv = 0;
  s.prevUp = false;
  s.msg = "";
  s.msgT = 0;
}

function playerWins(s, g) {
  g.addScore(50);
  s.won += 1;
  if (s.won >= WINS_TO_WIN) {
    g.sound("win");
    g.win();
    return;
  }
  g.nextLevel();
  g.sound("level");
  newRound(s, g);
}

function computerWins(s, g) {
  if (g.lives <= 1) {
    g.sound("lose");
    g.gameOver();
    return;
  }
  g.sound("hurt");
  g.loseLife();
  newRound(s, g);
}

function resolveByCount(s, g) {
  const p = s.hand.length;
  const c = s.cpu.length;
  if (p < c) playerWins(s, g);
  else computerWins(s, g);
}

function fits(card, top) {
  return card.suit === top.suit || card.rank === top.rank;
}

function anyFits(list, top) {
  return list.some((c) => fits(c, top));
}

function firstFit(list, top) {
  for (let i = 0; i < list.length; i++) {
    if (fits(list[i], top)) return i;
  }
  return -1;
}

function say(s, text) {
  s.msg = text;
  s.msgT = MSG_TIME;
}

function txtColor(suit) {
  return suit === 2 ? "cream" : "ink";
}

