const R = 11;
const PAD_Y = 600;
const PAD_W = 70;
const PAD_H = 14;

export default {
  title: "Pizza-Ziegelbrecher",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    const s = {
      pad: { x: 145, y: PAD_Y, w: PAD_W, h: PAD_H },
      ball: { x: 180, y: PAD_Y - R, vx: 0, vy: 0, live: false },
      bricks: makeBricks(g.level)
    };
    return s;
  },

  update(s, input, g) {
    const p = s.pad;
    const b = s.ball;

    // Schlaeger
    if (input.left) p.x -= 4;
    if (input.right) p.x += 4;
    p.x = g.clamp(p.x, 4, g.W - 4 - p.w);

    // Ball liegt auf dem Schlaeger, bis gestartet wird
    if (!b.live) {
      b.x = p.x + p.w / 2;
      b.y = p.y - R;
      if (input.firePressed) {
        b.live = true;
        b.vx = 2.5;
        b.vy = -(3 + 0.5 * g.level);
        g.sound("shoot");
      }
      return;
    }

    // Bewegung
    b.x += b.vx;
    b.y += b.vy;

    // Wand links und rechts
    if (b.x < R) { b.x = R; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - R) { b.x = g.W - R; b.vx = -Math.abs(b.vx); }

    // Decke (unterhalb der Anzeigeleiste)
    if (b.y - R <= g.TOP) { b.y = g.TOP + R; b.vy = Math.abs(b.vy); }

    const c = { x: b.x, y: b.y, r: R };

