    if (b.vy > 0 && g.hit(c, p)) {
      b.vy = -Math.abs(b.vy);
      b.vx = g.clamp((b.x - (p.x + p.w / 2)) / 35 * 3, -3, 3);
      if (b.vx === 0) b.vx = 1;
      b.y = p.y - R;
    }

