      g.addScore(10 * g.level);
      g.sound("pop");
      b.vy = -b.vy;
    }

    // Unten vorbei: Leben weg, Ball zurueck auf den Schlaeger
    if (b.y - R > g.H) {
      g.sound("hurt");
      g.loseLife();
