      return;
    }

    // Alle Steine weg
    if (s.bricks.length === 0) {
      if (g.level >= 3) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      s.bricks = makeBricks(g.level);
      resetBall(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const br of s.bricks) {
      d.rect(br.x, br.y, br.w, br.h, br.c, { round: 4, line: true });
      d.circle(br.x + 10, br.y + 5, 2.5, "cream");
      d.circle(br.x + 28, br.y + 5, 2.5, "cream");
    }
    d.rect(s.pad.x, s.pad.y, s.pad.w, s.pad.h, "yellow", { round: 6, line: true });
    d.emoji("🍕", s.ball.x, s.ball.y, 24);
  }
};

function makeBricks(level) {
  const out = [];
  const rows = Math.min(2 + level, 6);
  const colors = ["red", "ink", "yellow"];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 8; c++) {
      out.push({ x: 12 + c * 44, y: 88 + r * 22, w: 38, h: 16, c: colors[(r + c) % 3] });
    }
  }
  return out;
}

function resetBall(s, g) {
  s.ball.live = false;
  s.ball.vx = 0;
  s.ball.vy = 0;
  s.ball.x = s.pad.x + s.pad.w / 2;
  s.ball.y = s.pad.y - R;
}

