// Schlange (nur Spiel-API, keine Importe): Die Schlange laeuft auf einem Raster, Aepfel machen sie laenger.
// Wand oder eigener Koerper kostet ein Leben. Steuerung: Pfeile, Steuerkreuz oder Wischen.
// Das Spielende ("Neues Spiel") liegt bei der Laufzeit: g.gameOver() wird bei 0 Leben ausgeloest.
const CELL = 20, COLS = 18, ROWS = 29, Y0 = 56;

export default {
  title: "Schlange",
  controls: ["up", "down", "left", "right"],
  lives: 3,

  init(g) {
    const s = { body: [], dir: { x: 1, y: 0 }, next: { x: 1, y: 0 }, apple: { x: 0, y: 0 }, wait: 0, eaten: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    const want = input.up ? { x: 0, y: -1 } : input.down ? { x: 0, y: 1 } : input.left ? { x: -1, y: 0 } : input.right ? { x: 1, y: 0 } : null;
    // Umkehr auf der Stelle ist verboten: Wunsch gegen die aktuelle Richtung pruefen
    if (want && !(want.x === -s.dir.x && want.y === -s.dir.y)) s.next = want;
    s.wait += 1;
    if (s.wait < Math.max(4, 9 - g.level)) return;
    s.wait = 0;
    s.dir = { x: s.next.x, y: s.next.y };
    const head = { x: s.body[0].x + s.dir.x, y: s.body[0].y + s.dir.y };
    const crash = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS || s.body.some((p) => p.x === head.x && p.y === head.y);
    if (crash) { g.sound("hurt"); g.loseLife(); reset(s, g); return; }
    s.body.unshift(head);
    if (head.x === s.apple.x && head.y === s.apple.y) {
      g.addScore(10); g.sound("coin"); s.eaten += 1;
      if (s.eaten % 5 === 0) { g.nextLevel(); g.sound("level"); }
      placeApple(s, g);
    } else {
      s.body.pop();
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    s.body.forEach((p, i) => d.rect(p.x * CELL + 1, Y0 + p.y * CELL + 1, CELL - 2, CELL - 2, i === 0 ? "red" : "ink", { round: 6 }));
    // Sichtbares Spielende: ohne Leben steht die Meldung mit Punkten im Feld
    if (g.lives <= 0) {
      d.rect(20, Y0 + 200, COLS * CELL - 40, 130, "cream", { round: 12, line: true, shadow: true });
      d.text("Spiel vorbei", (COLS * CELL) / 2, Y0 + 245, { size: 28, color: "red", align: "center" });
      d.text("Punkte: " + g.score, (COLS * CELL) / 2, Y0 + 290, { size: 18, color: "ink", align: "center" });
    }
  }
};

function reset(s, g) {
  s.body = [{ x: 6, y: 14 }, { x: 5, y: 14 }, { x: 4, y: 14 }];
  s.dir = { x: 1, y: 0 };
  s.next = { x: 1, y: 0 };
  s.wait = 0;
  placeApple(s, g);
}

function placeApple(s, g) {
  for (let tries = 0; tries < 200; tries++) {
    const a = { x: g.randInt(0, COLS - 1), y: g.randInt(0, ROWS - 1) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = a; return; }
  }
}

// Autobahn-Ueberholer (nur Spiel-API, keine Importe).
// Roter Sportwagen auf drei Spuren. Wer fremden Autos ueberholt, bekommt Punkte.
// Ein Zusammenstoss kostet ein Leben. Mit jedem Level wird der Verkehr dichter und schneller.
const ROAD_X = 60, ROAD_W = 240, ME_Y = 560, CAR_W = 30, CAR_H = 50, PASS_Y = 610;

export default {
  title: "Autobahn-Ueberholer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return { me: 180, speed: 3, cars: [], count: 0 };
  },

  update(s, input, g) {
    // Lenken: 3 px pro Frame, auf die drei Spuren begrenzt
    if (input.left) s.me -= 3;
    if (input.right) s.me += 3;
    s.me = g.clamp(s.me, 75, 285);

    // Geschwindigkeit des Sportwagens, jeden Frame neu berechnet
    const p = g.clamp(3 + 0.5 * g.level + (input.up ? 4 : 0) - (input.down ? 2 : 0), 1, 12);
    s.speed = p;

    // Neue fremde Autos oben in zufaelliger Spur
    if (s.cars.length < 30 && g.random() < 0.02 + 0.01 * g.level) {
      const lane = [100, 180, 260][g.randInt(0, 2)];
      s.cars.push({
        x: lane,
        y: -60,
        vc: g.randInt(1, 3) + 0.3 * g.level,
        passed: false,
        e: g.random() < 0.5 ? "🚙" : "🚕",
        gone: false
      });
    }

    const me = { x: s.me - 15, y: ME_Y, w: CAR_W, h: CAR_H };

    for (const c of s.cars) {
      // Relative Bewegung zum Sportwagen
      c.y += p - c.vc;

      // Zusammenstoss: Leben weg, Auto verschwindet
      if (!c.passed && !c.gone && g.hit(me, { x: c.x - 15, y: c.y, w: CAR_W, h: CAR_H })) {
        c.gone = true;
        g.sound("hurt");
        g.loseLife();
        continue;
      }

      // Ueberholt: unten am Sportwagen vorbei
      if (!c.passed && c.y > PASS_Y) {
        c.passed = true;
        g.addScore(10 * g.level);
        g.sound("pop");
        s.count += 1;
        if (s.count >= 10) {
          s.count = 0;
          g.nextLevel();
          g.sound("level");
        }
      }
    }

    // Aufraeumen: verschwundene Autos, Autos ganz unten oder ganz oben weg
    s.cars = s.cars.filter((c) => !c.gone && c.y > -100 && c.y < g.H + 60);
  },

  draw(s, d, g) {
    d.clear("cream");
    // Strasse
    d.rect(ROAD_X, 0, ROAD_W, g.H, "ink");
    // Wandernde gelbe Spurstriche auf den zwei Trennlinien (x 140 und 220)
    const off = (g.frame * 4) % 60;
    for (let y = -60 + off; y < g.H; y += 60) {
      d.rect(138, y, 4, 30, "yellow");
      d.rect(218, y, 4, 30, "yellow");
    }
    // Fremde Autos
    for (const c of s.cars) d.emoji(c.e, c.x, c.y + 25, 40);
    // Sportwagen
    d.rect(s.me - 15, ME_Y, CAR_W, CAR_H, "red", { round: 6, line: true });
    d.emoji("🏎️", s.me, ME_Y + 25, 36);
  }
};

