// Felsen-Jaeger im All (nur Spiel-API, keine Importe). Raumschiff dreht sich mit links/rechts, fliegt mit oben
// und schiesst mit fire. Grosse Felsen zerbrechen in kleinere. Beruehrung mit einem Fels kostet ein Leben.
const SHIP_X = 180, SHIP_Y = 340;
const RADIUS = { 1: 12, 2: 22, 3: 36 };
const PTS = { 1: 100, 2: 50, 3: 20 };

export default {
  title: "Felsen-Jäger im All",
  controls: ["left", "right", "up", "fire"],
  lives: 3,

  init(g) {
    return {
      ship: { x: SHIP_X, y: SHIP_Y, a: 0, vx: 0, vy: 0 },
      shots: [],
      rocks: makeRocks(g),
      cool: 0,
      inv: 0
    };
  },

  update(s, input, g) {
    const sh = s.ship;

    // Drehen, Schub, Reibung, Geschwindigkeitsgrenze
    if (input.left) sh.a -= 4;
    if (input.right) sh.a += 4;
    sh.a = ((sh.a % 360) + 360) % 360;
    if (input.up) {
      sh.vx += g.sin(sh.a) * 0.15;
      sh.vy -= g.cos(sh.a) * 0.15;
    }
    const sp = Math.sqrt(sh.vx * sh.vx + sh.vy * sh.vy);
    if (sp > 5) { sh.vx *= 5 / sp; sh.vy *= 5 / sp; }
    sh.vx *= 0.99;
    sh.vy *= 0.99;
    sh.x += sh.vx;
    sh.y += sh.vy;
    wrap(sh, g);

    // Timer
    if (s.cool > 0) s.cool -= 1;
    if (s.inv > 0) s.inv -= 1;

    // Schuss
    const want = input.firePressed || input.fire;
    if (want && s.cool === 0 && s.shots.length < 4) {
      const a = sh.a;
      s.shots.push({ x: sh.x + g.sin(a) * 14, y: sh.y - g.cos(a) * 14, vx: g.sin(a) * 7, vy: -g.cos(a) * 7, r: 3, t: 50 });
      s.cool = 12;
      g.sound("shoot");
    }
    for (const shot of s.shots) { shot.x += shot.vx; shot.y += shot.vy; shot.t -= 1; }
    s.shots = s.shots.filter((p) => p.t > 0 && p.x >= 0 && p.x <= g.W && p.y >= g.TOP && p.y <= g.H);

    // Felsen bewegen
    for (const rk of s.rocks) { rk.x += rk.vx; rk.y += rk.vy; wrap(rk, g); }

    // Schuss trifft Fels: Fels zerbricht in zwei kleinere (nicht bei Groesse 1)
    const fresh = [];
    for (const shot of s.shots) {
      for (const rk of s.rocks) {
        if (!rk.dead && g.hit(shot, rk)) {
          shot.t = 0;
          rk.dead = true;
          g.addScore(PTS[rk.size] * g.level);
          g.sound("pop");
          if (rk.size > 1) {
            for (const k of [25, -25]) {
              const cs = g.cos(k), sn = g.sin(k);
              const nvx = rk.vx * cs - rk.vy * sn;
              const nvy = rk.vx * sn + rk.vy * cs;
              fresh.push(rock(rk.size - 1, rk.x, rk.y, nvx, nvy));
            }
          }
          break;
        }
      }
    }
    s.rocks = s.rocks.filter((rk) => !rk.dead).concat(fresh);
    s.shots = s.shots.filter((p) => p.t > 0);

    // Schiff trifft Fels
    if (s.inv === 0) {
      const body = { x: sh.x, y: sh.y, r: 12 };
      if (s.rocks.some((rk) => g.hit(body, rk))) {
        g.sound("hurt");
        g.loseLife();
        respawn(s, g);
        return;
      }
    }

    // Level geschafft
    if (s.rocks.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.rocks = makeRocks(g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const rk of s.rocks) {
      if (rk.size === 3) d.circle(rk.x, rk.y, rk.r, "ink");
      else d.circle(rk.x, rk.y, rk.r, "yellow", { line: true });
    }
    for (const shot of s.shots) d.circle(shot.x, shot.y, shot.r, "yellow");

    if (s.inv === 0 || (g.frame >> 3) % 2 === 0) {
      const sh = s.ship;
      const a = sh.a;
      const nx = sh.x + g.sin(a) * 14, ny = sh.y - g.cos(a) * 14;
      const lx = sh.x + g.sin(a + 150) * 12, ly = sh.y - g.cos(a + 150) * 12;
      const rx = sh.x + g.sin(a - 150) * 12, ry = sh.y - g.cos(a - 150) * 12;
      d.line(nx, ny, lx, ly, "ink", 3);
      d.line(nx, ny, rx, ry, "ink", 3);
      d.line(lx, ly, rx, ry, "ink", 3);
      d.circle(nx, ny, 4, "red");
    }
  }
};

function rock(size, x, y, vx, vy) {
  return { x, y, r: RADIUS[size], size, vx, vy, dead: false };
}

function makeRocks(g) {
  const out = [];
  const n = g.level + 2;
  const base = 0.6 + 0.2 * g.level;
  for (let i = 0; i < n; i++) {
    const side = g.randInt(0, 3);
    let x = 0, y = 0;
    if (side === 0) { x = g.random() * g.W; y = g.TOP + 1; }
    else if (side === 1) { x = g.random() * g.W; y = g.H - 1; }
    else if (side === 2) { x = 1; y = g.TOP + g.random() * (g.H - g.TOP); }
    else { x = g.W - 1; y = g.TOP + g.random() * (g.H - g.TOP); }
    const ang = g.random() * 360;
    const sp = base * (0.8 + 0.4 * g.random());
    out.push(rock(3, x, y, g.sin(ang) * sp, -g.cos(ang) * sp));
  }
  return out;
}

function wrap(p, g) {
  if (p.x < 0) p.x += g.W;
  else if (p.x >= g.W) p.x -= g.W;
  if (p.y < g.TOP) p.y += g.H - g.TOP;
  else if (p.y >= g.H) p.y -= g.H - g.TOP;
}

function respawn(s, g) {
  const sh = s.ship;
  sh.x = SHIP_X; sh.y = SHIP_Y; sh.a = 0; sh.vx = 0; sh.vy = 0;
  s.inv = 90;
  const center = { x: SHIP_X, y: SHIP_Y };
  s.rocks = s.rocks.filter((rk) => g.dist({ x: rk.x, y: rk.y }, center) >= 100);
}

