  sh.x = SHIP_X; sh.y = SHIP_Y; sh.a = 0; sh.vx = 0; sh.vy = 0;
  s.inv = 90;
  const center = { x: SHIP_X, y: SHIP_Y };
  s.rocks = s.rocks.filter((rk) => g.dist({ x: rk.x, y: rk.y }, center) >= 100);
