      if (input.firePressed) {
        const a = s.aim[me];
        if (me === 0) {
          s.ball = { x: 180, y: 580, vx: g.sin(a) * BALL_SPEED, vy: -g.cos(a) * BALL_SPEED, r: 7 };
        } else {
          s.ball = { x: 180, y: 118, vx: -g.sin(a) * BALL_SPEED, vy: g.cos(a) * BALL_SPEED, r: 7 };
        }
        g.sound("shoot");
      }
      return;
    }

    // Ball fliegt weiter
    const b = s.ball;
    b.x += b.vx;
    b.y += b.vy;

    // Treffer auf den Gegner
    if (g.hit(b, box(opp))) {
      s.wet[opp] += 1;
      s.ball = null;
      s.turn = opp;
      g.addScore(10);
      g.sound("pop");
      g.loseLife();
      return;
    }

    // Ball verlaesst das Feld: Zugwechsel ohne Punkte
    if (b.x < -b.r || b.x > g.W + b.r || b.y < -b.r || b.y > g.H + b.r) {
      s.ball = null;
      s.turn = opp;
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    // Wasserlinie in der Mitte
    d.line(0, 340, g.W, 340, "yellow", 2);

    // Trefferboxen und Figuren
    d.rect(160, 590, 40, 30, "yellow", { round: 8, line: true });
    d.rect(160, 88, 40, 30, "yellow", { round: 8, line: true });
    d.emoji("🐸", 180, 605, 30);
    d.emoji("🦆", 180, 103, 30);

    // Zielhilfe, solange kein Ball fliegt
    if (s.ball === null) {
      const a = s.aim[s.turn];
      if (s.turn === 0) {
        d.line(180, 590, 180 + g.sin(a) * 60, 590 - g.cos(a) * 60, "ink", 2);
      } else {
