    const over = s.wet[0] + s.wet[1] >= MAX_HITS || g.frame >= MAX_TIME;
    if (over) {
      let result = "Unentschieden";
      if (s.wet[0] < s.wet[1]) result = "Frosch ist weniger nass: gewinnt";
      else if (s.wet[1] < s.wet[0]) result = "Ente ist weniger nass: gewinnt";
      d.text(result, 180, 380, { size: 20, color: "red", align: "center" });
    }
  }
};

