function free(x, y) {
  if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return false;
  return MAP[y].charAt(x) !== "#";
}

function md(ax, ay, s) {
  return Math.abs(ax - s.dx) + Math.abs(ay - s.dy);
}

function setWant(s, x, y) {
  s.want = { x: x, y: y };
}

function remaining(s) {
  let n = 0;
  for (const st of s.streusel) if (!st.got) n += 1;
  return n;
}

function buildBoard(s) {
  s.streusel = [];
  s.stars = [];
  s.gulls = [];
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      const c = MAP[y].charAt(x);
      if (c === ".") s.streusel.push({ x: x, y: y, got: false });
      else if (c === "*") s.stars.push({ x: x, y: y, got: false });
      else if (c === "D") { s.sx = x; s.sy = y; }
      else if (c === "G") s.gulls.push({ x: x, y: y, sx: x, sy: y, mode: "normal" });
    }
  }
}

function resetActors(s) {
  s.dx = s.sx;
  s.dy = s.sy;
  s.dir = { x: 0, y: 0 };
  s.want = { x: 0, y: 0 };
  s.dtick = 0;
  s.gtick = 0;
  s.scare = 0;
  s.safe = 60;
  for (const gl of s.gulls) {
    gl.x = gl.sx;
    gl.y = gl.sy;
    gl.mode = "normal";
  }
}

function eatItems(s, g) {
  for (const st of s.streusel) {
    if (!st.got && st.x === s.dx && st.y === s.dy) {
      st.got = true;
      g.addScore(10);
      g.sound("coin");
    }
  }
  for (const st of s.stars) {
    if (!st.got && st.x === s.dx && st.y === s.dy) {
      st.got = true;
      s.scare = 360;
      for (const gl of s.gulls) gl.mode = "verjagt";
      g.sound("pop");
    }
  }
}

function stepGull(s, gl, g) {
  const fleeing = gl.mode === "verjagt";
  const opts = [];
  for (const dd of DIRS) {
    const nx = gl.x + dd.x, ny = gl.y + dd.y;
    if (free(nx, ny)) {
      const dist = md(nx, ny, s);
      opts.push({ x: nx, y: ny, v: fleeing ? -dist : dist });
    }
  }
  if (opts.length === 0) return;
  let min = opts[0].v;
  for (const o of opts) if (o.v < min) min = o.v;
  const ties = [];
  for (const o of opts) if (o.v === min) ties.push(o);
  const pick = ties[g.randInt(0, ties.length - 1)];
  gl.x = pick.x;
  gl.y = pick.y;
}

function touchGulls(s, g) {
  for (const gl of s.gulls) {
    if (gl.x === s.dx && gl.y === s.dy) {
      if (gl.mode === "verjagt") {
        g.addScore(100);
        g.sound("pop");
        gl.x = gl.sx;
        gl.y = gl.sy;
      } else if (s.safe === 0) {
        g.sound("hurt");
        g.loseLife();
        resetActors(s);
        return true;
      }
    }
  }
  return false;
}

