// Huhn im Flug (nur Spiel-API, keine Importe). Eigener Titel und eigene Mechanik mit Huhn und Saeulen.
// Hinweis: Der Name "Flappy Bird" ist ein geschuetzter Markenname und wird hier nicht verwendet.
const BIRD_X = 64, BIRD_W = 32, BIRD_H = 28, BIRD_START_Y = 300;
const GROUND = 610, PIPE_W = 56, GAP_H = 170, SPAWN_EVERY = 110;

export default {
  title: "Huhn im Flug",
  controls: ["up"],
  lives: 3,

  init(g) {
    return {
      bird: { x: BIRD_X, y: BIRD_START_Y, w: BIRD_W, h: BIRD_H, vy: 0 },
      pipes: [],
      timer: 0,
      count: 0,
      prevUp: false
    };
  },

  update(s, input, g) {
    const bird = s.bird;

    // Flattern: neuer Druck auf up gibt einen Impuls nach oben
    if (input.up && !s.prevUp) {
      bird.vy = -6.5;
      g.sound("jump");
    }
    s.prevUp = input.up === true;

    // Physik
    bird.vy += 0.35;
    if (bird.vy > 8) bird.vy = 8;
    bird.y += bird.vy;

    // Decke: kein Leben-Verlust, nur anhalten
    if (bird.y < g.TOP) {
      bird.y = g.TOP;
      bird.vy = 0;
    }

    // Saeulen erzeugen
    s.timer += 1;
    if (s.timer % SPAWN_EVERY === 0) {
      const gapY = g.randInt(g.TOP + 80, 480);
      s.pipes.push({ x: g.W + 10, gapY: gapY, passed: false });
    }

    // Saeulen bewegen, Passieren zaehlen, Kollision pruefen
    const speed = 2 + 0.3 * g.level;
    for (const p of s.pipes) {
      p.x -= speed;
    }

    for (const p of s.pipes) {
      const top = { x: p.x, y: g.TOP, w: PIPE_W, h: p.gapY - g.TOP };
      const bottom = { x: p.x, y: p.gapY + GAP_H, w: PIPE_W, h: g.H - (p.gapY + GAP_H) };
      const bird2 = { x: bird.x, y: bird.y, w: bird.w, h: bird.h };
      if (g.hit(bird2, top) || g.hit(bird2, bottom)) {
        g.sound("hurt");
        g.loseLife();
