      pause: 0,
      goals: 0,
      cpuSpeed: 3.2
    };
    serve(s, g);
    return s;
  },

  update(s, input, g) {
    // Spieler-Schlaeger
    const me = s.me;
    if (input.up) me.y -= 5;
    if (input.down) me.y += 5;
    me.y = g.clamp(me.y, g.TOP, g.H - me.h);

    // Computer-Schlaeger folgt dem Ball (begrenzte Geschwindigkeit)
    const cpu = s.cpu;
    const diff = s.ball.y - (cpu.y + cpu.h / 2);
    cpu.y += g.clamp(diff, -s.cpuSpeed, s.cpuSpeed);
    cpu.y = g.clamp(cpu.y, g.TOP, g.H - cpu.h);

    // Zeitlimit als Sicherheit
    if (g.frame >= 3600) { g.gameOver(); return; }

    // Pause nach jedem Ballwechsel
    if (s.pause > 0) { s.pause -= 1; return; }

    const b = s.ball;
    b.x += b.vx;
    b.y += b.vy;

    // Obere und untere Wand
    if (b.y - b.r < g.TOP) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }
    if (b.y + b.r > g.H) { b.y = g.H - b.r; b.vy = -Math.abs(b.vy); }

    // Treffer Spieler-Schlaeger (Ball fliegt nach links)
    if (b.vx < 0 && g.hit({ x: b.x, y: b.y, r: b.r }, me)) {
      rally(b, me, true);
    }
    // Treffer Computer-Schlaeger (Ball fliegt nach rechts)
    if (b.vx > 0 && g.hit({ x: b.x, y: b.y, r: b.r }, cpu)) {
      rally(b, cpu, false);
    }

    // Ball an meiner Seite vorbei: Leben weg
    if (b.x + b.r < 0) {
      g.loseLife();
      serve(s, g);
      return;
    }

    // Ball an der Seite des Computers vorbei: Punkte
