// Kuchen-Stapler (nur Spiel-API, keine Importe).
// Kuchenstuecke aus 7 Formen (je 4 Quadrate) fallen in ein Feld aus 10 x 20 Zellen.
// Volle Reihen verschwinden. Hinweis: Die Plattform hat nur die Farben yellow, red, ink, cream.
// Deshalb hat jedes Stueck eine dieser vier Farben plus ein Kuchen-Emoji als Dekor (nicht bunt).
const X0 = 40, Y0 = 60, CELL = 28, COLS = 10, ROWS = 20;
const NAMES = ["", "yellow", "red", "ink", "cream"];

// Formen als Quadrat-Koordinaten [spalte, zeile]
const SHAPES = [
  [[0, 0], [1, 0], [2, 0], [3, 0]],  // I
  [[0, 0], [1, 0], [0, 1], [1, 1]],  // O
  [[0, 0], [1, 0], [2, 0], [1, 1]],  // T
  [[1, 0], [2, 0], [0, 1], [1, 1]],  // S
  [[0, 0], [1, 0], [1, 1], [2, 1]],  // Z
  [[0, 0], [0, 1], [1, 1], [2, 1]],  // J
  [[2, 0], [0, 1], [1, 1], [2, 1]]   // L
];

function emptyGrid() {
  const g = [];
  for (let r = 0; r < ROWS; r++) {
    const row = [];
    for (let c = 0; c < COLS; c++) row.push(0);
    g.push(row);
  }
  return g;
}

function newRow() {
  const row = [];
  for (let c = 0; c < COLS; c++) row.push(0);
  return row;
}

function makePiece(f) {
  const cells = SHAPES[f].map((q) => ({ x: q[0], y: q[1] }));
  return { f: f, rot: 0, col: 3, row: 0, cells: cells };
}

function rotate(cells) {
  const rc = cells.map((c) => ({ x: -c.y, y: c.x }));
  let minX = rc[0].x, minY = rc[0].y;
  for (const c of rc) {
    if (c.x < minX) minX = c.x;
    if (c.y < minY) minY = c.y;
  }
  return rc.map((c) => ({ x: c.x - minX, y: c.y - minY }));
}

function fits(grid, cells, col, row) {
  for (const c of cells) {
    const gx = col + c.x, gy = row + c.y;
    if (gx < 0 || gx >= COLS || gy >= ROWS) return false;
    if (gy >= 0 && grid[gy][gx] !== 0) return false;
  }
  return true;
}

function spawn(s, g) {
  s.piece = makePiece(s.next);
  s.next = g.randInt(0, 6);
  s.cool = 0;
  const p = s.piece;
  if (!fits(s.grid, p.cells, p.col, p.row)) {
    g.sound("hurt");
    g.loseLife();
    s.grid = emptyGrid();
    s.piece = makePiece(s.next);
    s.next = g.randInt(0, 6);
  }
}

function lockPiece(s, g) {
  const p = s.piece;
  const code = (p.f % 4) + 1;
  for (const c of p.cells) {
    const gx = p.col + c.x, gy = p.row + c.y;
    if (gx >= 0 && gx < COLS && gy >= 0 && gy < ROWS) s.grid[gy][gx] = code;
  }
  // volle Reihen entfernen (von unten nach oben)
  let n = 0;
  for (let r = ROWS - 1; r >= 0; r--) {
    if (s.grid[r].every((v) => v !== 0)) {
      s.grid.splice(r, 1);
      n += 1;
    }
  }
  for (let i = 0; i < n; i++) s.grid.unshift(newRow());
  if (n > 0) {
    g.addScore(100 * n * g.level);
    g.sound("pop");
    const before = s.cleared;
    s.cleared += n;
    if (Math.floor(s.cleared / 5) > Math.floor(before / 5)) {
      g.nextLevel();
      g.sound("level");
    }
  }
  spawn(s, g);
}

export default {
  title: "Kuchen-Stapler",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    const s = {
      grid: emptyGrid(),
      piece: makePiece(g.randInt(0, 6)),
      next: 0,
      cool: 0,
      mvCool: 0,
      lPrev: false,
      rPrev: false,
      upPrev: false,
