// Wuerfel-Hundert (nur Spiel-API, keine Importe). Vier Personen am selben Geraet, Zug fuer Zug.
// Haken h6 (echte Wuerfel mit Augen als Bild) ist nicht machbar: Ersatz ist ein Wuerfel-Emoji
// mit der Augenzahl als Text daneben. Das wird unten im Spiel angezeigt.
export default {
  title: "Wuerfel-Hundert",
  controls: ["fire"],
  lives: 1,

  init(g) {
    return {
      cur: 0,
      dice: [1, 1],
      last: "",
      note: "",
      turnPts: 0,
      wait: 0,
      lastWho: 0,
      lastValue: 0,
      totals: [0, 0, 0, 0]
    };
  },

  update(s, input, g) {
    if (s.wait > 0) s.wait -= 1;
    if (!input.firePressed || s.wait > 0) return;

    const a = g.randInt(1, 6);
    const b = g.randInt(1, 6);
    const who = s.cur;
    s.dice = [a, b];
    s.lastWho = who;
    s.wait = 20;

    if (a === 1 || b === 1) {
      s.lastValue = 0;
      s.turnPts = 0;
      s.note = "Eine 1: keine Punkte";
      s.last = "Spieler " + (who + 1) + ": " + a + " + " + b;
      g.sound("pop");
    } else {
      const sum = a + b;
      s.lastValue = sum;
      s.turnPts = sum;
      s.totals[who] += sum;
      g.addScore(sum);
      s.note = "";
      s.last = "Spieler " + (who + 1) + ": " + a + " + " + b + " = " + sum;
      g.sound("shoot");
    }

    if (s.totals[who] >= 100) {
      g.sound("win");
      g.win();
      return;
    }
    s.cur = (s.cur + 1) % 4;
  },

  draw(s, d) {
    d.clear("cream");

    for (let i = 0; i < 4; i++) {
      const y = 70 + i * 100;
      if (i === s.cur) d.rect(12, y - 4, 336, 98, "red", { round: 14 });
      d.rect(16, y, 328, 90, "yellow", { round: 12 });
      d.text("Spieler " + (i + 1), 36, y + 30, { size: 22, color: "ink" });
      d.text(String(s.totals[i]), 36, y + 66, { size: 30, color: "ink" });
      d.text("Ziel 100", 326, y + 66, { size: 16, color: "ink", align: "right" });
    }

    d.text("Am Zug: Spieler " + (s.cur + 1) + " (Tippen oder Taste)", 180, 478, { size: 18, color: "ink", align: "center" });
    d.emoji("🎲", 180, 530, 64);
    d.text(s.last || "Noch kein Wurf", 180, 586, { size: 28, color: "ink", align: "center" });
    if (s.note) d.text(s.note, 180, 614, { size: 18, color: "red", align: "center" });
    d.text("Wuerfel als Emoji, Augen als Text", 180, 634, { size: 12, color: "ink", align: "center" });
  }
};

