// Gummibär-Schätzen (nur Spiel-API, keine Importe): Wie viele Gummibärchen sind im Glas?
// Tipp mit hoch/runter einstellen, fire bestätigt. Der Computer tippt gegen dich, wer näher dran ist, gewinnt die Runde.
// Gegner ist der Computer, da es keinen Mehrspieler-Modus gibt.
const GLASS = { x: 110, y: 170, w: 140, h: 220 };

export default {
  title: "Gummibär-Schätzen",
  controls: ["up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      phase: "tipp", round: 1, real: 0, bears: [], tipp: 30, timer: 0, rep: 0,
      cGuess: 0, pd: 0, cd: 0, won: false, wait: 0, msg: ""
    };
    startRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "tipp") {
      const dir = (input.up ? 1 : 0) - (input.down ? 1 : 0);
      if (dir !== 0) {
        if (s.rep <= 0) {
          s.tipp = g.clamp(s.tipp + dir, 0, 99);
          s.rep = 4;
        } else {
          s.rep -= 1;
        }
      } else {
        s.rep = 0;
      }
      s.timer += 1;
      if (input.firePressed || s.timer >= 600) reveal(s, g);
      return;
    }

    // Anzeige-Phase (150 Frames), dann naechste Runde oder Ende
    s.wait += 1;
    if (s.wait >= 150) {
      if (s.round >= 10) { g.win(); return; }
      s.round += 1;
      startRound(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Wie viele Gummibärchen?", 180, 80, { size: 22, color: "ink", align: "center" });
    d.text("Runde " + s.round + " von 10", 180, 106, { size: 18, color: "ink", align: "center" });
    d.text("Gegner: der Computer (kein Mehrspieler-Modus)", 180, 134, { size: 13, color: "ink", align: "center" });
    d.rect(GLASS.x, GLASS.y, GLASS.w, GLASS.h, "yellow", { round: 16, line: true });

    if (s.phase === "tipp") {
      d.text("?", 180, 300, { size: 64, color: "ink", align: "center" });
      d.rect(GLASS.x, 410, Math.max(1, GLASS.w * (1 - s.timer / 600)), 8, "red", { round: 4 });
      d.text("Dein Tipp: " + s.tipp, 180, 450, { size: 28, color: "ink", align: "center" });
