// Pizza-Ausbruch (nur Spiel-API, keine Importe): Eine Pizza prallt von der Platte und den Waenden ab
// und zerstoert Bausteine. Faellt sie unten raus, verliert man ein Leben.
const R = 9;

export default {
  title: "Pizza-Ausbruch",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    const s = {
      paddle: { x: 140, y: 600, w: 80, h: 14 },
      bricks: buildBricks(g),
      ball: { x: 180, y: 591, vx: 0, vy: 0, r: R },
      hold: 60
    };
    return s;
  },

  update(s, input, g) {
    const p = s.paddle;
    const b = s.ball;

    // Platte bewegen und im Feld halten
    if (input.left) p.x -= 5;
    if (input.right) p.x += 5;
    p.x = g.clamp(p.x, 4, g.W - 84);

    // Ball haengt auf der Platte, bis der Startzaehler abgelaufen ist
    if (s.hold > 0) {
      s.hold -= 1;
      b.x = p.x + p.w / 2;
      b.y = p.y - b.r;
      if (s.hold === 0) {
        b.vx = 2;
