// Autobahn-Ueberholer (nur Spiel-API, keine Importe).
// Roter Sportwagen auf drei Spuren. Gegner-Autos ziehen vorbei; wer ein langsameres Auto ueberholt, bekommt Punkte.
// Kollision kostet ein Leben. Gas (up) und Bremse (down) veraendern das Tempo.
// Hinweis: Der Foto-Look der Autobahn (Schilder, Asphalt) fehlt. Es gibt nur einfache farbige Formen.
const LANES = [70, 160, 250];
const CAR_W = 40, CAR_H = 70;

export default {
  title: "Autobahn-Ueberholer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return {
      me: { x: 160, y: 530, w: CAR_W, h: CAR_H },
      speed: 4,
      off: 0,
      cars: [],
      overtakes: 0,
      safe: 0
    };
  },

  update(s, input, g) {
    const me = s.me;

    // Steuerung: Spur wechseln, Tempo aendern
    if (input.left) me.x -= 4;
    if (input.right) me.x += 4;
    me.x = g.clamp(me.x, 20, 280);
    if (input.up) s.speed = Math.min(9, s.speed + 0.1);
    if (input.down) s.speed = Math.max(1.5, s.speed - 0.1);

    // Fahrbahnstreifen bewegen sich nach unten
    s.off = (s.off + s.speed) % 40;
    if (s.safe > 0) s.safe -= 1;

    // Gegner-Autos bewegen sich relativ zu unserem Tempo
    for (const c of s.cars) {
      c.y += s.speed - c.v;
      if (!c.passed && c.y > me.y + me.h) {
        c.passed = true;
        g.addScore(10 * g.level);
        g.sound("coin");
        s.overtakes += 1;
        if (s.overtakes % 10 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }

    // Kollision: ein Auto kostet ein Leben, danach kurze Schonzeit
    if (s.safe === 0) {
      for (let i = 0; i < s.cars.length; i++) {
        if (g.hit(me, s.cars[i])) {
          s.cars.splice(i, 1);
          s.safe = 60;
          g.sound("hurt");
          g.loseLife();
          break;
        }
      }
    }

    // Aufraeumen: Autos ausserhalb des Feldes entfernen
    s.cars = s.cars.filter((c) => c.y <= g.H + 10 && c.y >= -100);

    // Neue Autos: Haeufigkeit steigt mit dem Level
    if (g.random() < 0.02 + 0.006 * g.level) {
      s.cars.push({
        x: LANES[g.randInt(0, 2)],
        y: -80,
        w: CAR_W,
        h: CAR_H,
        v: g.randInt(1, 3),
        passed: false
      });
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    // Mittellinien zwischen den drei Spuren, wandern nach unten
    for (let y = g.TOP + s.off - 40; y < g.H; y += 40) {
      d.rect(133, y, 4, 22, "yellow");
      d.rect(223, y, 4, 22, "yellow");
    }

    // Gegner-Autos
    for (const c of s.cars) {
      d.rect(c.x, c.y, c.w, c.h, c.passed ? "ink" : "red", { round: 8 });
      d.emoji("🚙", c.x + c.w / 2, c.y + c.h / 2, 30);
    }

    // Sportwagen des Spielers (blinkt in der Schonzeit)
    const me = s.me;
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.rect(me.x, me.y, me.w, me.h, "red", { round: 10, shadow: true });
      d.rect(me.x + 17, me.y + 6, 6, 58, "ink", { round: 3 });
    }

    // Ehrlicher Hinweis: Foto-Look fehlt
    d.text("Foto-Look fehlt: einfache Formen", 180, 628, { size: 12, color: "ink", align: "center" });
  }
};

