      sh.vy -= 0.15 * cs;
    }
    sh.vx *= 0.99;
    sh.vy *= 0.99;
    const sp = Math.sqrt(sh.vx * sh.vx + sh.vy * sh.vy);
    if (sp > 5) {
      sh.vx = sh.vx * 5 / sp;
      sh.vy = sh.vy * 5 / sp;
    }
    sh.x = wrapX(sh.x + sh.vx, g);
    sh.y = wrapY(sh.y + sh.vy, g);

    // Schuss abfeuern
    if (input.firePressed && s.shots.length < MAX_SHOTS) {
      s.shots.push({
        x: sh.x + sn * 14,
        y: sh.y - cs * 14,
        vx: sn * SHOT_SPEED,
        vy: -cs * SHOT_SPEED,
        life: SHOT_LIFE,
        r: 3,
        dead: false
      });
      g.sound("shoot");
    }

    // Schuesse bewegen, ablaufen lassen, am Rand entfernen (ohne Umlauf)
    for (const sj of s.shots) {
      sj.x += sj.vx;
      sj.y += sj.vy;
      sj.life -= 1;
    }
    s.shots = s.shots.filter((sj) => sj.life > 0 && sj.x >= 0 && sj.x <= g.W && sj.y >= g.TOP && sj.y <= g.H);

    // Brocken bewegen (umlaufend)
    for (const rk of s.rocks) {
      rk.x = wrapX(rk.x + rk.vx, g);
      rk.y = wrapY(rk.y + rk.vy, g);
    }

    // Schuss gegen Brocken
    const kids = [];
    for (const sj of s.shots) {
      for (const rk of s.rocks) {
        if (sj.dead || rk.dead) continue;
        if (g.dist(sj, rk) < sj.r + rk.r) {
          sj.dead = true;
          rk.dead = true;
          g.addScore(rk.big ? 20 : 50);
          g.sound("pop");
          if (rk.big) {
            for (let k = 0; k < 2; k++) {
              const a = g.random() * 360;
              const v = 0.9 + g.random() * 0.8;
              kids.push({ x: rk.x, y: rk.y, vx: v * g.sin(a), vy: v * g.cos(a), r: 14, big: false, dead: false });
            }
          }
          break;
        }
      }
    }
    s.shots = s.shots.filter((sj) => !sj.dead);
    s.rocks = s.rocks.filter((rk) => !rk.dead);
    for (const k of kids) {
      if (s.rocks.length >= MAX_ROCKS) break;
      s.rocks.push(k);
    }

    // Schutzzeit
    if (s.safe > 0) s.safe -= 1;

    // Brocken gegen Schiff
    if (s.safe === 0) {
      const hitRock = s.rocks.some((rk) => g.dist(sh, rk) < SHIP_R + rk.r);
      if (hitRock) {
        g.sound("hurt");
        g.loseLife();
        sh.x = CX;
        sh.y = CY;
        sh.vx = 0;
        sh.vy = 0;
        s.safe = SAFE_FRAMES;
        s.shots = [];
        clearNear(s, g);
        return;
      }
    }

    // Level geschafft
    if (s.rocks.length === 0) {
      g.nextLevel();
      g.sound("level");
      spawnLevel(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    const sh = s.ship;
    const sn = g.sin(sh.winkel);
    const cs = g.cos(sh.winkel);

    for (const rk of s.rocks) {
      d.emoji("🪨", rk.x, rk.y, rk.big ? 56 : 28);
    }
    for (const sj of s.shots) {
      d.circle(sj.x, sj.y, sj.r, "ink");
    }
    if (sh.thr) {
      const jit = (g.frame >> 2) % 2 === 0 ? 2 : 0;
      d.circle(sh.x - sn * 18, sh.y + cs * 18, 4 + jit, "yellow");
      d.circle(sh.x - sn * 24, sh.y + cs * 24, 3, "yellow");
    }
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🚀", sh.x, sh.y, 36);
      d.line(sh.x + sn * 10, sh.y - cs * 10, sh.x + sn * 26, sh.y - cs * 26, "red", 4);
    }
  }
};

function wrapX(x, g) {
  if (x < 0) return x + g.W;
  if (x >= g.W) return x - g.W;
  return x;
}

function wrapY(y, g) {
  const h = g.H - g.TOP;
  if (y < g.TOP) return y + h;
  if (y >= g.H) return y - h;
  return y;
}

function spawnLevel(s, g) {
  const count = Math.min(8, 2 + g.level);
  for (let i = 0; i < count; i++) {
    let pos = null;
    for (let tries = 0; tries < 60; tries++) {
      const side = g.randInt(0, 3);
      const t = g.random();
      let x, y;
      if (side === 0) { x = 0; y = g.TOP + t * (g.H - g.TOP); }
      else if (side === 1) { x = g.W - 1; y = g.TOP + t * (g.H - g.TOP); }
      else if (side === 2) { x = t * g.W; y = g.TOP + 1; }
      else { x = t * g.W; y = g.H - 1; }
      if (g.dist({ x: x, y: y }, { x: CX, y: CY }) >= 150) { pos = { x: x, y: y }; break; }
    }
    if (!pos) pos = { x: 10 + i * 30, y: g.TOP + 10 };
    const a = g.random() * 360;
    const v = 0.6 + g.random() * 0.8;
    s.rocks.push({ x: pos.x, y: pos.y, vx: v * g.sin(a), vy: v * g.cos(a), r: 28, big: true, dead: false });
  }
}

function clearNear(s, g) {
  for (const rk of s.rocks) {
    let tries = 0;
    while (rk.big && tries < 4 && g.dist(rk, { x: CX, y: CY }) < 110) {
      rk.x = wrapX(rk.x + 150, g);
      tries += 1;
    }
  }
}

