// Keine Schriften oder Bilder.
const SYMS = ["❤️", "💎", "⭐", "🌿"];
const VALS = ["7", "8", "9", "10", "Bube", "Dame", "König", "As"];
const CW = 56, CH = 84, WAIT = 30, ROUND_LIMIT = 3600;

export default {
  title: "Mau-Mau gegen den Computer",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    const s = {
      hand: [], cpu: [], pile: [], used: [], top: { sym: "⭐", val: "7" },
      cursor: 0, delay: 0, turn: "player", wait: 0, rf: 0, wins: 0, msg: ""
    };
    newRound(s, g);
    return s;
  },

  update(s, input, g) {
    s.rf += 1;
    if (s.cursor > s.hand.length) s.cursor = s.hand.length;

    // Cursor: Hand-Karten 0..n-1, Position n = Stapel. Verzoegerung 10 Frames beim Halten.
    if (input.left || input.right) {
      if (s.delay === 0) {
        const n = s.hand.length + 1;
        s.cursor = (s.cursor + (input.right ? 1 : n - 1)) % n;
        s.delay = 10;
      } else {
        s.delay -= 1;
      }
    } else {
      s.delay = 0;
    }

    // Spielerzug: passende Karte legen, sonst vom Stapel ziehen.
    if (s.turn === "player" && input.firePressed) {
      if (s.cursor < s.hand.length && fits(s.hand[s.cursor], s.top)) {
        const c = s.hand.splice(s.cursor, 1)[0];
        playCard(s, c);
        if (s.cursor > s.hand.length) s.cursor = s.hand.length;
        g.addScore(5);
        g.sound("pop");
        s.msg = "Gelegt: +5 Punkte";
      } else {
        const c = drawCard(s, g);
        if (c) {
          s.hand.push({ sym: c.sym, val: c.val });
          g.sound("coin");
          s.msg = "Karte vom Stapel gezogen";
        } else {
          s.msg = "Stapel ist leer";
        }
      }
      s.turn = "cpu";
      s.wait = 0;
    }

    // Computerzug nach wartezeit.
    if (s.turn === "cpu") {
      s.wait += 1;
      if (s.wait >= WAIT) {
        s.wait = 0;
        const idx = s.cpu.findIndex((c) => fits(c, s.top));
        if (idx >= 0) {
          const c = s.cpu.splice(idx, 1)[0];
          playCard(s, c);
          g.sound("hit");
          s.msg = "Computer legt eine Karte.";
        } else {
          const c = drawCard(s, g);
          if (c) s.cpu.push({ sym: c.sym, val: c.val });
          s.msg = "Computer zieht eine Karte.";
        }
        s.turn = "player";
      }
    }

    // Rundenende: Spieler leer gewinnt, Computer leer verliert ein Leben.
    if (s.hand.length === 0) {
      g.addScore(50);
      g.sound("level");
      g.nextLevel();
      s.wins += 1;
      if (s.wins >= 3) { g.win(); return; }
      newRound(s, g);
      return;
    }
    if (s.cpu.length === 0) {
      g.sound("lose");
      g.loseLife();
      newRound(s, g);
      return;
    }

    // Zeitlimit: Runde ohne Ende zaehlt als verloren.
    if (s.rf >= ROUND_LIMIT) {
      g.sound("lose");
      g.loseLife();
      newRound(s, g);
      return;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Computer: " + s.cpu.length + " Karten", 16, 70, { size: 16, color: "ink", align: "left" });
    const spc = spacing(s.cpu.length);
    for (let i = 0; i < s.cpu.length; i++) d.rect(16 + i * spc, 80, CW, CH, "ink", { round: 8 });

    cardFace(d, s.top, 110, 220);
    d.rect(210, 220, CW, CH, "ink", { round: 8 });
    d.text(String(s.pile.length), 238, 262, { size: 18, color: "cream", align: "center" });
    if (s.cursor === s.hand.length) d.line(210, 314, 266, 314, "red", 4);

    d.text(s.msg, 180, 340, { size: 14, color: "ink", align: "center" });
    d.text(s.turn === "player" ? "Dein Zug" : "Computer ist am Zug", 180, 372, { size: 16, color: "red", align: "center" });
    d.text("Du: " + s.hand.length + " Karten", 16, 404, { size: 16, color: "ink", align: "left" });

    const sp = spacing(s.hand.length);
    for (let i = 0; i < s.hand.length; i++) {
      const x = 16 + i * sp;
      cardFace(d, s.hand[i], x, 420);
      if (s.cursor === i) d.line(x, 514, x + CW, 514, "red", 4);
    }
  }
};

function newRound(s, g) {
  const deck = shuffle(makeDeck(), g);
  s.hand = deck.splice(0, 5);
  s.cpu = deck.splice(0, 5);
  s.top = deck.pop();
  s.pile = deck;
  s.used = [];
  s.cursor = 0;
  s.delay = 0;
  s.turn = "player";
  s.wait = 0;
  s.rf = 0;
  s.msg = "Neue Runde";
}

function makeDeck() {
  const out = [];
  for (const sym of SYMS) for (const val of VALS) out.push({ sym: sym, val: val });
  return out;
}

function shuffle(arr, g) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = arr[i];
    arr[i] = arr[j];
    arr[j] = t;
  }
  return arr;
}

function fits(c, top) {
  return c.sym === top.sym || c.val === top.val;
}

function playCard(s, c) {
  s.used.push(s.top);
  s.top = c;
}

function drawCard(s, g) {
  if (s.pile.length === 0 && s.used.length > 0) {
    s.pile = shuffle(s.used, g);
    s.used = [];
  }
  if (s.pile.length === 0) return null;
  return s.pile.pop();
}

function spacing(n) {
  return n <= 1 ? 0 : Math.min(56, Math.floor(300 / (n - 1)));
}

function cardFace(d, c, x, y) {
  d.rect(x, y, CW, CH, "cream", { round: 8, line: true });
  d.emoji(c.sym, x + CW / 2, y + 28, 26);
  d.text(c.val, x + CW / 2, y + 70, { size: 12, color: "ink", align: "center" });
}

