// Wasserballon-Duell (nur Spiel-API, keine Importe): Ente unten, Schwein oben.
// Beide werfen Wasserballons ueber die Mittellinie. Treffer machen nass, nichts Blutiges.
export default {
  title: "Wasserballon-Duell",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    return {
      me: { x: 160, y: 580, w: 40, h: 30 },
      foe: { x: 160, y: 90, w: 40, h: 30, dir: 1 },
      mine: [],
      theirs: [],
      cool: 0,
      et: 0,
      gap: 75 + g.randInt(0, 30),
      safe: 0,
      wet: 0,
      fwet: 0,
      hits: 0,
      taken: 0,
      splash: []
    };
  },

  update(s, input, g) {
    if (g.frame >= 3600) { g.gameOver(); return; }

    // Ente bewegen
    if (input.left) s.me.x -= 4;
    if (input.right) s.me.x += 4;
    s.me.x = g.clamp(s.me.x, 4, 316);

    // Timer
    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;
    if (s.wet > 0) s.wet -= 1;
    if (s.fwet > 0) s.fwet -= 1;

    // Eigener Wurf: nur ein Ballon gleichzeitig, mit Abkuehlung
    if (input.firePressed && s.cool === 0 && s.mine.length === 0) {
      const sx = s.me.x + 20;
      s.mine.push({ bx: sx, x: sx, y: s.me.y, r: 8, t: 0, gone: false });
      s.cool = 30;
      g.sound("shoot");
    }

    // Eigene Ballons: steigen als Bogen (Seitwaerts-Schwingung)
    for (const b of s.mine) {
      b.t += 1;
      b.y -= 6;
      b.x = b.bx + g.sin(b.t * 4) * 10;
      if (!b.gone && g.hit(b, s.foe)) {
        b.gone = true;
        s.hits += 1;
        s.fwet = 90;
        g.addScore(10);
        g.sound("pop");
        if (s.splash.length < 10) s.splash.push({ x: s.foe.x + 20, y: s.foe.y + 15, t: 0 });
        if (s.hits % 2 === 0) { g.nextLevel(); g.sound("level"); }
      }
    }
    s.mine = s.mine.filter((b) => !b.gone && b.y > g.TOP - 20);

    if (s.hits >= 5) { g.sound("win"); g.win(); return; }

    // Gegner: hin und her, Tempo steigt mit dem Level
    s.foe.x += s.foe.dir * (2 + 0.5 * (g.level - 1));
    if (s.foe.x < 20) { s.foe.x = 20; s.foe.dir = 1; }
    if (s.foe.x > 300) { s.foe.x = 300; s.foe.dir = -1; }

    // Gegnerwurf: alle 75 Frames plus Zufall, mit Zielabweichung
    s.et += 1;
    if (s.et >= s.gap) {
      s.et = 0;
      s.gap = 75 + g.randInt(0, 30);
      const sx = s.foe.x + 20;
      const sy = s.foe.y + 30;
      const vy = 4.5 + 0.3 * g.level;
      const tx = s.me.x + 20 + g.randInt(-30, 30);
      const steps = (s.me.y - sy) / vy;
      const vx = (tx - sx) / steps;
      s.theirs.push({ x: sx, y: sy, vx: vx, vy: vy, r: 8, gone: false });
    }

    // Gegnerische Ballons: fallen und koennen die Ente treffen
    for (const b of s.theirs) {
      b.x += b.vx;
      b.y += b.vy;
      if (!b.gone && s.safe === 0 && g.hit(b, s.me)) {
        b.gone = true;
        s.taken += 1;
        s.safe = 60;
        s.wet = 120;
        g.sound("hurt");
        if (s.splash.length < 10) s.splash.push({ x: s.me.x + 20, y: s.me.y + 15, t: 0 });
        if (s.taken >= 5) { g.sound("lose"); g.gameOver(); return; }
        g.loseLife();
        return;
      }
    }
    s.theirs = s.theirs.filter((b) => !b.gone && b.y < g.H + 20);

    // Spritzer ausklingen lassen
    for (const p of s.splash) p.t += 1;
    s.splash = s.splash.filter((p) => p.t < 20);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.line(0, 340, 360, 340, "yellow", 3);

    // Gegner (Schwein), nass mit Wasserspuren
    d.emoji("🐷", s.foe.x + 20, s.foe.y + 15, 36);
    if (s.fwet > 0) {
      d.circle(s.foe.x + 6, s.foe.y + 34, 3, "yellow", { line: true });
      d.circle(s.foe.x + 20, s.foe.y + 38, 3, "yellow", { line: true });
      d.circle(s.foe.x + 34, s.foe.y + 34, 3, "yellow", { line: true });
    }

    // Spieler (Ente): blinkt rot, wenn geschuetzt
    if (s.safe > 0 && (g.frame >> 2) % 2 === 0) {
      d.rect(s.me.x - 4, s.me.y - 4, s.me.w + 8, s.me.h + 8, "red", { round: 10 });
    }
    d.emoji("🦆", s.me.x + 20, s.me.y + 15, 36);
    if (s.wet > 0) {
      d.circle(s.me.x + 6, s.me.y + 2, 3, "yellow", { line: true });
      d.circle(s.me.x + 20, s.me.y - 2, 3, "yellow", { line: true });
      d.circle(s.me.x + 34, s.me.y + 2, 3, "yellow", { line: true });
    }

    // Ballons
    for (const b of s.mine) d.circle(b.x, b.y, b.r, "yellow", { line: true });
    for (const b of s.theirs) d.circle(b.x, b.y, b.r, "yellow", { line: true });

    // Platz-Spritzer
    for (const p of s.splash) d.circle(p.x, p.y, 4 + p.t * 0.5, "yellow", { line: true });

