    for (const b of s.mine) {
      b.t += 1;
      b.y -= 6;
      b.x = b.bx + g.sin(b.t * 4) * 10;
      if (!b.gone && g.hit(b, s.foe)) {
        b.gone = true;
        s.hits += 1;
        s.fwet = 90;
        g.addScore(10);
        g.sound("pop");
