// Dach-Katze (nur Spiel-API, keine Importe). Die Katze huepft ueber Daecher und sammelt Fischgraeten.
// Ende: Jeder Absturz und jeder Vogel-Treffer kostet ein Leben und startet die Katze auf dem Startdach
// mit Schutz. Die Runde ist vorbei, wenn die Leben aufgebraucht sind (Laufzeit ruft g.gameOver auf).
const GRAV = 0.5, JUMP = -10.5, FLOOR = 610, ROOF_H = 16;

export default {
  title: "Dach-Katze",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 30, y: FLOOR - 30, w: 22, h: 30, vx: 0, vy: 0, ground: true },
      roofs: [], fish: [], birds: [], safe: 0
    };
    build(s, g);
    respawn(s);
    return s;
  },

  update(s, input, g) {
    const me = s.me;

    // Katze: Laufen, Springen, Schwerkraft
    me.vx = input.left ? -3 : input.right ? 3 : 0;
    if (input.up && me.ground) { me.vy = JUMP; me.ground = false; g.sound("jump"); }
    me.vy = Math.min(me.vy + GRAV, 12);
    const oldBottom = me.y + me.h;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);
    me.y += me.vy;
    me.ground = false;
    if (me.vy >= 0) {
      for (const r of s.roofs) {
        const over = me.x + me.w > r.x && me.x < r.x + r.w;
        if (over && oldBottom <= r.y && me.y + me.h >= r.y) {
          me.y = r.y - me.h; me.vy = 0; me.ground = true;
        }
      }
    }

    if (s.safe > 0) s.safe -= 1;

    // Voegel laufen auf ihrem Dach hin und her
    for (const b of s.birds) {
      b.x += b.vx;
      if (b.x < b.min || b.x + b.w > b.max) {
        b.vx = -b.vx;
        b.x = g.clamp(b.x, b.min, b.max - b.w);
      }
      if (s.safe === 0 && g.hit(me, b)) {
        g.sound("hurt"); g.loseLife(); respawn(s); return;
      }
    }

    // Fischgraeten einsammeln
    s.fish = s.fish.filter((f) => {
      if (g.hit(me, f)) { g.addScore(10); g.sound("coin"); return false; }
      return true;
    });

    // Alle Graeten da: naechstes Level mit einer Graete mehr
    if (s.fish.length === 0) {
      g.addScore(50); g.nextLevel(); g.sound("level");
      build(s, g);
      respawn(s);
      return;
    }

    // Abgrund
    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); respawn(s); }
  },

  draw(s, d) {
    d.clear("cream");
    for (const r of s.roofs) d.rect(r.x, r.y, r.w, r.h, "yellow", { round: 8, shadow: true, line: true });
    for (const f of s.fish) drawFish(d, f);
