    // Abgrund: Absturz beendet die Runde
    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); g.gameOver(); return; }
  },

  draw(s, d) {
    d.clear("cream");
    for (const r of s.roofs) d.rect(r.x, r.y, r.w, r.h, "yellow", { round: 8, shadow: true, line: true });
    for (const f of s.fish) drawFish(d, f);
    for (const b of s.birds) d.emoji("🐦", b.x + b.w / 2, b.y + b.h / 2, 22);
    const m = s.me;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) d.emoji("🐈", m.x + m.w / 2, m.y + m.h / 2, 30);
  }
};

// Fischgraete: Mittelgraete plus 5 Rippenpaare, Box 16x16
function drawFish(d, f) {
  const cx = f.x + 8;
  d.line(cx, f.y + 1, cx, f.y + 15, "ink", 2);
  for (let i = 0; i < 5; i++) {
    const yy = f.y + 3 + i * 3;
    d.line(cx, yy, cx - 6, yy - 3, "ink", 2);
    d.line(cx, yy, cx + 6, yy - 3, "ink", 2);
  }
}

// Layout: Startdach unten links, dann 4 bis 6 Daecher, jeweils erreichbar (Sprunghoehe ca. 110, Reichweite ca. 120)
function build(s, g) {
  const start = { x: 0, y: FLOOR, w: 140, h: ROOF_H };
  s.roofs = [start];
  let prev = start;
  const n = g.randInt(4, 6);
  for (let i = 0; i < n; i++) {
    const w = g.randInt(90, 140);
    const y = g.clamp(prev.y + g.randInt(-90, 60), 120, 580);
    const gap = g.randInt(20, 80);
    let x = prev.x + prev.w + gap;
    if (x + w > g.W - 4) x = prev.x - gap - w;
    x = g.clamp(x, 4, g.W - w - 4);
    const r = { x, y, w, h: ROOF_H };
    s.roofs.push(r);
    prev = r;
  }

  // Graeten: eine je Dach, dazu level-1 Extra-Graeten
  // Voegel: immer einer auf dem Startdach (sichert das Spielende), ab Level 2 zusaetzlich zufaellig auf Daechern
  s.fish = [];
  s.birds = [];
  for (let i = 0; i < s.roofs.length; i++) {
    const r = s.roofs[i];
    s.fish.push({ x: r.x + r.w / 2 - 8, y: r.y - 20, w: 16, h: 16 });
    if (i === 0 || (g.level >= 2 && g.random() < 0.5)) {
      s.birds.push({ x: r.x, y: r.y - 20, w: 20, h: 18, vx: 0.6 + 0.2 * g.level, min: r.x, max: r.x + r.w });
    }
  }
  for (let k = 1; k < g.level; k++) {
    const r = s.roofs[g.randInt(0, s.roofs.length - 1)];
    s.fish.push({ x: r.x + g.randInt(0, r.w - 16), y: r.y - 20, w: 16, h: 16 });
  }
}

function respawn(s) {
  const m = s.me;
  m.x = 30; m.y = FLOOR - m.h; m.vx = 0; m.vy = 0; m.ground = true;
  s.safe = 60;
}

// Tennis-Duell (nur Spiel-API, keine Importe). Links steuert die Spielerin bzw. der Spieler den Schläger,
// rechts spielt der Computer. Der Ball ist ein Tennisball. Kein Gegner wird verletzt: es geht nur um den Ball.
const PAD_SPEED = 6;
const BALL_MAX = 9;
const CPU_BASE = 3;
const CPU_MAX = 5;

export default {
  title: "Tennis-Duell",
  controls: ["up", "down"],
  lives: 3,

  init(g) {
    const s = {
      ball: { x: 180, y: 344, r: 8, vx: 3, vy: 0 },
      me: { x: 20, y: 300, w: 10, h: 90 },
      cpu: { x: 330, y: 300, w: 10, h: 90 },
      hits: 0,
      serve: 1
    };
    serve(s, g);
    return s;
  },

  update(s, input, g) {
    const ball = s.ball;
    const me = s.me;
    const cpu = s.cpu;

    // Eigener Schläger (links)
    const dy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    me.y = g.clamp(me.y + dy * PAD_SPEED, g.TOP, g.H - me.h);

    // Computer-Schläger (rechts) folgt dem Ball
    const cpuSpeed = Math.min(CPU_MAX, CPU_BASE + 0.4 * (g.level - 1));
    const target = ball.y - cpu.h / 2;
    const diff = target - cpu.y;
    const step = Math.min(cpuSpeed, Math.abs(diff));
    cpu.y = g.clamp(cpu.y + (diff > 0 ? step : -step), g.TOP, g.H - cpu.h);

    // Ball bewegen
    ball.x += ball.vx;
    ball.y += ball.vy;

    // Obere und untere Wand
    if (ball.y - ball.r < g.TOP) { ball.y = g.TOP + ball.r; ball.vy = Math.abs(ball.vy); }
    if (ball.y + ball.r > g.H) { ball.y = g.H - ball.r; ball.vy = -Math.abs(ball.vy); }

    // Treffer des eigenen Schlägers (links), nur wenn der Ball auf ihn zufliegt
    if (ball.vx < 0 && touches(ball, me)) {
      const sp = Math.min(BALL_MAX, Math.abs(ball.vx) + 0.3);
      ball.vx = sp;
      ball.vy = clampV(ball.vy + (ball.y - (me.y + me.h / 2)) * 0.08);
      g.addScore(10);
      g.sound("hit");
      s.hits += 1;
      if (s.hits >= 5) {
        s.hits = 0;
        g.nextLevel();
        g.sound("level");
      }
    }

    // Treffer des Computer-Schlägers (rechts)
    if (ball.vx > 0 && touches(ball, cpu)) {
      const sp = Math.min(BALL_MAX, Math.abs(ball.vx) + 0.3);
      ball.vx = -sp;
      ball.vy = clampV(ball.vy + (ball.y - (cpu.y + cpu.h / 2)) * 0.08);
      g.sound("hit");
    }

    // Ball geht links vorbei: Leben weg
    if (ball.x < 0) {
      g.sound("hurt");
      g.loseLife();
      serve(s, g);
      return;
    }

    // Ball geht rechts vorbei: Punkte für den Spieler
    if (ball.x > g.W) {
      g.addScore(50);
      g.sound("pop");
      serve(s, g);
    }

    if (g.score >= 500) {
      g.sound("win");
      g.win();
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    // Spielbereich mit Rahmen
    d.rect(4, g.TOP + 4, g.W - 8, g.H - g.TOP - 8, "cream", { round: 12, line: true });
    // Netzlinie aus kleinen Rechtecken in der Mitte
    for (let y = g.TOP + 12; y < g.H - 12; y += 24) d.rect(178, y, 4, 12, "ink");
    // Schläger
    d.rect(s.me.x, s.me.y, s.me.w, s.me.h, "red", { round: 4 });
    d.rect(s.cpu.x, s.cpu.y, s.cpu.w, s.cpu.h, "ink", { round: 4 });
    // Tennisball
    d.emoji("🎾", s.ball.x, s.ball.y, 22);
  }
};

// Ball (Kreis, x/y Mitte) trifft Rechteck {x,y,w,h}?
function touches(b, p) {
  const nx = Math.max(p.x, Math.min(b.x, p.x + p.w));
  const ny = Math.max(p.y, Math.min(b.y, p.y + p.h));
  const dx = b.x - nx;
  const dy = b.y - ny;
  return dx * dx + dy * dy <= b.r * b.r;
}

function clampV(v) {
  return Math.max(-6, Math.min(6, v));
}

function serve(s, g) {
  s.ball.x = 180;
  s.ball.y = (g.TOP + g.H) / 2;
  s.ball.vx = 3 * s.serve;
  s.serve = -s.serve;
  s.ball.vy = g.random() * 4 - 2;
}

