// Huhn-Flatter (nur Spiel-API, keine Importe): Ein Huhn fliegt durch Rohre mit Luecken.
// Nichts tun = das Huhn sinkt. Hoch-Taste = Flattern. Alle Zustandsdaten liegen in s.
const BIRD_X = 64, BIRD_W = 32, BIRD_H = 28, START_Y = 300;
const PIPE_W = 52, GAP = 150, GRAVITY = 0.45, MAX_FALL = 9, FLAP = -7.5, FLAP_COOL = 12;
const SPAWN_EVERY = 150, PROTECT = 90;

export default {
  title: "Huhn-Flatter",
  controls: ["up"],
  lives: 3,

  init(g) {
    return {
      y: START_Y,
      vy: 0,
      cool: 0,
      safe: 0,
      timer: 0,
      pipes: [],
      passedCount: 0
    };
  },

  update(s, input, g) {
    // Flattern mit Sperre
    if (s.cool > 0) s.cool -= 1;
    if (input.up && s.cool === 0) {
      s.vy = FLAP;
      s.cool = FLAP_COOL;
    }

    // Schwerkraft und Bewegung
    s.vy = Math.min(s.vy + GRAVITY, MAX_FALL);
    s.y += s.vy;
    if (s.y < g.TOP) {
      s.y = g.TOP;
      s.vy = 0;
    }

    if (s.safe > 0) s.safe -= 1;

    // Rohre spawnen
    s.timer += 1;
    if (s.timer >= SPAWN_EVERY) {
      s.timer = 0;
      s.pipes.push({
        x: g.W,
        gapY: g.randInt(g.TOP + 80, g.H - 230),
        passed: false
      });
    }

    // Rohre bewegen
    const speed = 2.5 + 0.3 * g.level;
    for (const p of s.pipes) p.x -= speed;

    // Punkte fuer passierte Rohre
    for (const p of s.pipes) {
      if (!p.passed && p.x + PIPE_W < BIRD_X) {
        p.passed = true;
        s.passedCount += 1;
        g.addScore(10);
        if (s.passedCount % 5 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }
    s.pipes = s.pipes.filter((p) => p.x + PIPE_W >= 0);

    // Kollision: Rohre oder Boden
    if (s.safe === 0) {
      const b = bird(s);
      let hurt = b.y + b.h >= g.H;
      if (!hurt) {
        for (const p of s.pipes) {
          const top = { x: p.x, y: g.TOP, w: PIPE_W, h: p.gapY - g.TOP };
          const bottom = { x: p.x, y: p.gapY + GAP, w: PIPE_W, h: g.H - (p.gapY + GAP) };
          if (g.hit(b, top) || g.hit(b, bottom)) { hurt = true; break; }
        }
      }
      if (hurt) {
        g.sound("hurt");
        g.loseLife();
        s.y = START_Y;
        s.vy = 0;
        s.pipes = [];
        s.timer = 0;
        s.safe = PROTECT;
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const p of s.pipes) {
      d.rect(p.x, g.TOP, PIPE_W, p.gapY - g.TOP, "ink");
      d.rect(p.x, p.gapY + GAP, PIPE_W, g.H - (p.gapY + GAP), "ink");
    }
    d.rect(0, g.H - 24, g.W, 24, "yellow");
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🐔", BIRD_X + BIRD_W / 2, s.y + BIRD_H / 2, 30);
    }
  }
};

function bird(s) {
  return { x: BIRD_X, y: s.y, w: BIRD_W, h: BIRD_H };
}

