// Enkel-Memory (nur Spiel-API, keine Importe): 12 verdeckte Karten, 6 Tier-Paare, Zeitlimit 60 s.
// Fotos sind nicht moeglich; als Ersatz dienen Tier-Emojis. Der Hinweis steht im Spielfeld.
export default {
  title: "Enkel-Memory",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    const motifs = ["🐶", "🐱", "🐰", "🐻", "🦊", "🐸"];
    const cards = [];
    for (let k = 0; k < motifs.length; k++) {
      cards.push({ pair: k, emo: motifs[k], open: false, found: false });
      cards.push({ pair: k, emo: motifs[k], open: false, found: false });
    }
    // Fisher-Yates mit g.randInt
    for (let i = cards.length - 1; i > 0; i--) {
      const j = g.randInt(0, i);
      const t = cards[i];
      cards[i] = cards[j];
      cards[j] = t;
    }
    return { cards: cards, col: 0, row: 0, open: [], wait: 0, hold: 0, found: 0 };
  },

  update(s, input, g) {
    if (g.frame >= 3600) { g.gameOver(); return; }

    // Cursor: bei Halten alle 10 Frames einen Schritt, beim ersten Druck sofort
    const dir = input.left || input.right || input.up || input.down;
    if (dir) {
      if (s.hold <= 0) {
        if (input.left && s.col > 0) s.col -= 1;
        else if (input.right && s.col < 2) s.col += 1;
        else if (input.up && s.row > 0) s.row -= 1;
        else if (input.down && s.row < 3) s.row += 1;
        s.hold = 10;
      } else {
        s.hold -= 1;
      }
    } else {
      s.hold = 0;
    }

    // Warte-Phase nach Fehlpaar oder Paar
    if (s.wait > 0) {
      s.wait -= 1;
      if (s.wait === 0) resolve(s, g);
      return;
    }

    if (input.firePressed) {
      const i = s.row * 3 + s.col;
      const c = s.cards[i];
      if (!c.open && !c.found && s.open.length < 2) {
        c.open = true;
        s.open.push(i);
        if (s.open.length === 2) s.wait = 60;
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    const cur = s.row * 3 + s.col;
    for (let i = 0; i < 12; i++) {
      const c = s.cards[i];
      const x = 48 + (i % 3) * 92;
      const y = 140 + Math.floor(i / 3) * 92;
      if (i === cur) d.rect(x - 4, y - 4, 88, 88, "ink", { round: 12 });
      if (c.found) {
        d.rect(x, y, 80, 80, "red", { round: 10, line: true });
        d.emoji(c.emo, x + 40, y + 40, 40);
      } else if (c.open) {
        d.rect(x, y, 80, 80, "cream", { round: 10, line: true });
        d.emoji(c.emo, x + 40, y + 40, 40);
      } else {
        d.rect(x, y, 80, 80, "yellow", { round: 10, line: true });
      }
    }
    d.text("Fotos fehlen: Tier-Motive statt Fotos", g.W / 2, 600, { size: 12, color: "ink", align: "center" });
  }
};

function resolve(s, g) {
  const a = s.cards[s.open[0]];
  const b = s.cards[s.open[1]];
  if (a.pair === b.pair) {
    a.found = true;
    b.found = true;
    s.found += 1;
    g.addScore(20);
    g.sound("pop");
  } else {
    a.open = false;
    b.open = false;
    g.sound("hit");
  }
  s.open = [];
  if (s.found === 6) {
    g.sound("win");
    g.win();
  }
}

