      } else if (input.right && fits(s, p.cells, p.ax + 1, p.ay)) {
        p.ax += 1; s.cool = 5;
      } else if (input.up) {
        const nc = p.cells.map((c) => [0 - c[1], c[0]]);
        if (fits(s, nc, p.ax, p.ay)) { p.cells = nc; s.cool = 8; }
      }
    }

    // Hartes Fallen: sofort ans Ende, dann aufsetzen
    if (input.firePressed) {
      while (fits(s, p.cells, p.ax, p.ay + 1)) p.ay += 1;
      land(s, g);
      return;
    }

    // Weiches Fallen: ein zusaetzlicher Schritt
