versuche.code:
// Wuerfel-Rennen 100 (nur Spiel-API, keine Importe): Vier Personen wuerfeln abwechselnd.
// fire wuerfelt, up sichert die Zugpunkte. Eine 1 verliert den Zug. Wer zuerst 100 hat, gewinnt.
export default {
  title: "Wuerfel-Rennen 100",
  controls: ["up", "fire"],
  lives: 1,

  init(g) {
    return {
      players: [
        { name: "Spieler 1", total: 0 },
        { name: "Spieler 2", total: 0 },
        { name: "Spieler 3", total: 0 },
        { name: "Spieler 4", total: 0 }
      ],
      turn: 0,
      zug: 0,
      dice: 0,
      msg: "",
      over: false,
      winner: -1,
      prevUp: false
    };
  },

  update(s, input, g) {
    if (s.over) return;

    const upNew = !!input.up && !s.prevUp;
    s.prevUp = !!input.up;

    // Sicherheitsende, falls niemand mehr 100 erreicht (nach langer Zeit)
    if (g.frame > 36000) {
      s.over = true;
      g.gameOver();
      return;
    }

    if (input.firePressed) {
      const d = g.randInt(1, 6);
      s.dice = d;
      if (d === 1) {
        s.zug = 0;
        s.msg = "Pech! Eine 1 - Zug verloren";
        g.sound("hurt");
        nextTurn(s);
      } else {
        s.zug += d;
        s.msg = "";
        g.sound("pop");
      }
    } else if (upNew && s.dice > 0) {
      const p = s.players[s.turn];
      const gain = s.zug;
      p.total += gain;
      g.addScore(gain);
      g.sound("coin");
      if (p.total >= 100) {
        s.winner = s.turn;
        s.over = true;
        s.msg = p.name + " gewinnt!";
        g.sound("win");
        g.win();
        return;
      }
      s.msg = p.name + " sichert " + gain + " Punkte";
      nextTurn(s);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Ziel 100", 180, 26, { size: 28, color: "ink", align: "center" });

    for (let i = 0; i < 4; i++) {
      const p = s.players[i];
      const y = 80 + i * 76;
      if (i === s.turn && !s.over) {
        d.rect(8, y - 6, 344, 62, "red", { round: 10 });
        d.rect(12, y - 2, 336, 54, "cream", { round: 8 });
      }
      d.text(p.name, 22, y + 14, { size: 20, color: "ink", align: "left" });
      d.text("Gesamt " + p.total, 180, y + 14, { size: 18, color: "ink", align: "center" });
      d.text("Zug " + (i === s.turn ? s.zug : 0), 340, y + 14, { size: 18, color: "red", align: "right" });
    }

    d.emoji("🎲", 180, 380, 100);
    d.text(s.dice > 0 ? "Augenzahl: " + s.dice : "Noch nicht gewuerfelt", 180, 440, { size: 22, color: "ink", align: "center" });
    d.text(s.msg, 180, 480, { size: 16, color: "red", align: "center" });
    d.text("fire wuerfelt, up sichert", 180, 540, { size: 18, color: "ink", align: "center" });
    d.text("Am Zug: " + s.players[s.turn].name, 180, 572, { size: 16, color: "ink", align: "center" });
  }
};

function nextTurn(s) {
  s.turn = (s.turn + 1) % 4;
  s.zug = 0;
  s.dice = 0;
}

