// Wer naeher dran ist, gewinnt die Runde. Keine Figuren mit Menschen, keine Gewalt.
const GLAS = { x: 80, y: 150, w: 200, h: 300 };
const MAX_WAIT = 600;
const REVEAL_FRAMES = 180;

export default {
  title: "Gummibaerchen-Schaetzen",
  controls: ["up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      count: 0,
      bears: [],
      guess: 50,
      phase: "guess",
      timer: 0,
      playerScore: 0,
      compScore: 0,
      compGuess: 0,
      round: 1,
      maxRounds: 5,
      stepCool: 0,
      lastWinner: ""
    };
    startRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "guess") {
      s.timer += 1;
      if (s.stepCool > 0) s.stepCool -= 1;

      if ((input.up || input.down) && s.stepCool === 0) {
        const step = input.fire ? 5 : 1;
        const delta = input.up ? step : -step;
        s.guess = g.clamp(s.guess + delta, 0, 200);
        s.stepCool = 6;
      }

      if (input.firePressed || s.timer >= MAX_WAIT) {
        confirm(s, g);
      }
    } else {
      s.timer += 1;
      if (s.timer >= REVEAL_FRAMES) {
        if (s.round >= s.maxRounds) {
          finish(s, g);
        } else {
          s.round += 1;
          startRound(s, g);
        }
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(GLAS.x, GLAS.y, GLAS.w, GLAS.h, "yellow", { round: 16, line: true });
    for (const b of s.bears) d.emoji("🐻", b.x, b.y, 16);

    d.text("Runde " + s.round + " von " + s.maxRounds, 180, 80, { size: 18, color: "ink", align: "center" });
    d.text("Du " + s.playerScore + " : " + s.compScore + " Gegner", 180, 106, { size: 16, color: "ink", align: "center" });

    if (s.phase === "guess") {
      d.text("Deine Schaetzung: " + s.guess, 180, 472, { size: 24, color: "red", align: "center" });
      d.text("Gegner schaetzt verdeckt", 180, 500, { size: 14, color: "ink", align: "center" });
      d.text("oben/unten aendern, fire bestaetigen", 180, 524, { size: 12, color: "ink", align: "center" });
    } else {
      d.text("Echte Zahl: " + s.count, 180, 472, { size: 24, color: "red", align: "center" });
      d.text("Du: " + s.guess + "   Gegner: " + s.compGuess, 180, 500, { size: 16, color: "ink", align: "center" });
      const info = s.lastWinner === "player" ? "Du gewinnst diese Runde" : "Gegner gewinnt diese Runde";
      d.text(info, 180, 526, { size: 14, color: "ink", align: "center" });
    }
  }
};

function startRound(s, g) {
  s.count = g.randInt(20, 120);
  s.bears = [];
  for (let i = 0; i < s.count; i++) {
    s.bears.push({ x: GLAS.x + 12 + g.randInt(0, GLAS.w - 24), y: GLAS.y + 14 + g.randInt(0, GLAS.h - 28) });
  }
  s.guess = 50;
  s.phase = "guess";
  s.timer = 0;
  s.stepCool = 0;
  s.compGuess = 0;
  s.lastWinner = "";
}

function confirm(s, g) {
  s.compGuess = Math.max(0, Math.round(s.count * (0.7 + 0.6 * g.random())));
  const dp = Math.abs(s.guess - s.count);
  const dc = Math.abs(s.compGuess - s.count);
  if (dp <= dc) {
    s.playerScore += 1;
    s.lastWinner = "player";
    g.addScore(10 + 5 * s.round);
    g.sound("coin");
  } else {
    s.compScore += 1;
    s.lastWinner = "comp";
    g.sound("hurt");
    g.loseLife();
  }
  s.phase = "reveal";
  s.timer = 0;
}

function finish(s, g) {
  if (s.playerScore > s.compScore) {
    g.sound("win");
    g.win();
  } else {
    g.sound("lose");
    g.gameOver();
  }
}

