// Apfel-Schlange (nur Spiel-API, keine Importe). Schlange auf einem Raster, Aepfel machen sie laenger.
// Wand oder eigener Koerper kostet ein Leben. Steuerung: Pfeile, Steuerkreuz oder Wischen.
// Hinweis: Die Nokia-Optik (gruenes Display, Pixel-Look) ist nicht umsetzbar, weil nur die Farben
// yellow, cream, ink, red erlaubt sind. Ersatz: gelbes Spielfeld mit dunkler Schlange in Blockoptik.
const CELL = 20, COLS = 18, ROWS = 29, Y0 = 56;

export default {
  title: "Apfel-Schlange",
  controls: ["up", "down", "left", "right"],
  lives: 3,

  init(g) {
    const s = { body: [], dir: { x: 1, y: 0 }, next: { x: 1, y: 0 }, apple: { x: 0, y: 0 }, wait: 0, eaten: 0, idle: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    const want = input.up ? { x: 0, y: -1 }
      : input.down ? { x: 0, y: 1 }
      : input.left ? { x: -1, y: 0 }
      : input.right ? { x: 1, y: 0 }
      : null;
    if (want && !(want.x === -s.dir.x && want.y === -s.dir.y)) {
      s.next = want;
      s.idle = 0;
    } else {
      s.idle += 1;
    }

    s.wait += 1;
    if (s.wait < Math.max(4, 9 - g.level)) return;
    s.wait = 0;

    s.dir = { x: s.next.x, y: s.next.y };
    const head = { x: s.body[0].x + s.dir.x, y: s.body[0].y + s.dir.y };
    const crash = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS
      || s.body.some((p) => p.x === head.x && p.y === head.y);
    if (crash) {
      g.sound("hurt");
      g.loseLife();
      reset(s, g);
      return;
    }

    s.body.unshift(head);
    if (head.x === s.apple.x && head.y === s.apple.y) {
      g.addScore(10);
      g.sound("coin");
      s.eaten += 1;
      if (s.eaten % 5 === 0) {
        g.nextLevel();
        g.sound("level");
      }
      placeApple(s, g);
    } else {
      s.body.pop();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    s.body.forEach((p, i) => {
      d.rect(p.x * CELL + 1, Y0 + p.y * CELL + 1, CELL - 2, CELL - 2, i === 0 ? "red" : "ink", { round: 6 });
    });
  }
};

function reset(s, g) {
