// Mau-Mau gegen den Computer (nur Spiel-API, keine Importe).
// Textkarten mit Wert und Farbzeichen (keine Bildkarten, keine Dateien).
// Links/rechts waehlen den Cursor (Stapel links, dann eigene Karten), Feuer spielt oder zieht.
const SUITS = ["♥", "♦", "♣", "♠"];
const RANKS = ["7", "8", "9", "10", "U", "O", "K", "A"];

export default {
  title: "Mau-Mau gegen den Computer",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    const s = { hand: [], cpu: [], disc: [], stock: [], turn: "p", wait: 0, cur: 1, mv: 0, wins: 0, note: "" };
    deal(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.mv > 0) s.mv -= 1;
    const n = s.hand.length;
    if (s.cur > n) s.cur = n;

    // Cursor: 0 = Stapel, 1..n = eigene Karten; wrap-around, mit kurzer Pause zwischen Schritten
    if (s.mv === 0) {
      if (input.right) { s.cur = (s.cur + 1) % (n + 1); s.mv = 10; }
      else if (input.left) { s.cur = (s.cur + n) % (n + 1); s.mv = 10; }
    }

    if (s.turn === "p") {
      if (input.firePressed) {
        if (s.cur === 0) {
          playerDraw(s, g);
        } else {
          const card = s.hand[s.cur - 1];
          if (fits(card, topCard(s))) {
            s.hand.splice(s.cur - 1, 1);
            s.disc.push(card);
            g.addScore(10);
            g.sound("pop");
            if (s.hand.length === 0) { wonRound(s, g); return; }
            s.turn = "c";
            s.wait = 30;
            s.note = "Computer ist dran";
          } else {
            playerDraw(s, g);
          }
        }
      }
    } else {
      s.wait -= 1;
      if (s.wait <= 0) cpuTurn(s, g);
    }
    if (s.cur > s.hand.length) s.cur = s.hand.length;
  },

  draw(s, d, g) {
    d.clear("cream");

    // Computer-Hand oben als Rueckseiten
    const cn = s.cpu.length, csp = spacingFor(cn), cx0 = startX(cn, g);
    for (let i = 0; i < cn; i++) d.rect(cx0 + i * csp, 60, 40, 60, "ink", { round: 6, line: true });

    // Ablage Mitte
    if (s.disc.length > 0) drawCard(d, 160, 250, topCard(s));

    // Stapel links
    if (s.turn === "p" && s.cur === 0) d.rect(16, 246, 48, 68, "yellow", { round: 8 });
    if (s.stock.length > 0) d.rect(20, 250, 40, 60, "ink", { round: 6, line: true });
    else d.rect(20, 250, 40, 60, "cream", { round: 6, line: true });
    d.text(String(s.stock.length), 40, 320, { size: 12, color: "ink", align: "center" });

    // Eigene Hand unten
    const pn = s.hand.length, psp = spacingFor(pn), px0 = startX(pn, g);
    for (let i = 0; i < pn; i++) {
      const x = px0 + i * psp;
      if (s.turn === "p" && s.cur === i + 1) d.rect(x - 3, 497, 46, 66, "yellow", { round: 8 });
      drawCard(d, x, 500, s.hand[i]);
    }

    // Statuszeilen
    d.text("Runden gewonnen: " + s.wins + " von 3", 180, 150, { size: 14, color: "ink", align: "center" });
    d.text(s.note, 180, 200, { size: 13, color: "ink", align: "center" });
    d.text(s.turn === "p" ? "Du bist dran" : "Computer denkt nach", 180, 222, { size: 13, color: "red", align: "center" });
    d.text("Textkarten: Wert und Farbzeichen", 180, 585, { size: 12, color: "ink", align: "center" });
    d.text("Links/rechts waehlen, Feuer spielt oder zieht", 180, 605, { size: 12, color: "ink", align: "center" });
  }
};

function shuffle(list, g) {
  for (let i = list.length - 1; i >= 1; i--) {
    const j = g.randInt(0, i);
    const t = list[i];
    list[i] = list[j];
    list[j] = t;
  }
}

function deal(s, g) {
  const deck = [];
  for (let c = 0; c < 4; c++) for (let r = 0; r < 8; r++) deck.push({ r: r, c: c });
  shuffle(deck, g);
  s.hand = [];
  s.cpu = [];
  for (let i = 0; i < 5; i++) {
    s.hand.push(deck.pop());
    s.cpu.push(deck.pop());
  }
  s.disc = [deck.pop()];
  s.stock = deck;
  s.turn = "p";
  s.wait = 0;
  s.cur = 1;
  s.mv = 0;
  s.note = "Passende Farbe oder gleicher Wert ablegen";
}

function redeal(s, g) {
  deal(s, g);
  s.note = "Kein Zug moeglich - neu gemischt ohne Leben-Verlust";
}

function topCard(s) {
  return s.disc[s.disc.length - 1];
}

function fits(card, top) {
  return card.r === top.r || card.c === top.c;
}

// Holt eine Karte vom Stapel; ist er leer, wird die Ablage ausser der obersten neu gemischt.
// Gibt null zurueck, wenn nichts mehr zu ziehen ist.
function takeStock(s, g) {
  if (s.stock.length === 0) {
    if (s.disc.length <= 1) return null;
    const top = s.disc.pop();
    s.stock = s.disc;
    s.disc = [top];
    shuffle(s.stock, g);
  }
  return s.stock.pop();
}

function playerDraw(s, g) {
  const card = takeStock(s, g);
  if (card === null) { redeal(s, g); return; }
  s.hand.push(card);
  s.turn = "c";
  s.wait = 30;
  s.note = "Du hast eine Karte gezogen";
}

function cpuTurn(s, g) {
  const top = topCard(s);
  const idx = [];
  for (let i = 0; i < s.cpu.length; i++) if (fits(s.cpu[i], top)) idx.push(i);
  if (idx.length > 0) {
    const i = idx[g.randInt(0, idx.length - 1)];
    const card = s.cpu.splice(i, 1)[0];
    s.disc.push(card);
    g.sound("pop");
    s.note = "Computer legt eine Karte ab";
    if (s.cpu.length === 0) { lostRound(s, g); return; }
  } else {
    const card = takeStock(s, g);
    if (card === null) { redeal(s, g); return; }
    s.cpu.push(card);
    s.note = "Computer zieht eine Karte";
  }
  s.turn = "p";
  s.wait = 0;
}

function wonRound(s, g) {
  g.addScore(50);
  s.wins += 1;
  if (s.wins >= 3) { g.sound("win"); g.win(); return; }
  g.sound("level");
  g.nextLevel();
  deal(s, g);
  s.note = "Runde gewonnen - neue Runde";
}

function lostRound(s, g) {
  g.sound("hurt");
  g.loseLife();
  deal(s, g);
  s.note = "Computer war zuerst - neue Runde";
}

function spacingFor(n) {
  return n > 1 ? Math.min(44, Math.floor(300 / (n - 1))) : 0;
}

function startX(n, g) {
  return (g.W - (40 + Math.max(0, n - 1) * spacingFor(n))) / 2;
}

function drawCard(d, x, y, card) {
  d.rect(x, y, 40, 60, "cream", { round: 6, line: true });
  const col = card.c < 2 ? "red" : "ink";
  d.text(RANKS[card.r] + SUITS[card.c], x + 20, y + 30, { size: 13, color: col, align: "center" });
}

