      else if (input.left) { s.cur = (s.cur + n) % (n + 1); s.mv = 10; }
    }

    if (s.turn === "p") {
      s.idle += 1;
      if (s.idle > IDLE_LIMIT) {
        // Zeitlimit: der Spieler hat nicht gehandelt, er muss ziehen
        playerDraw(s, g);
      } else if (input.firePressed) {
        s.idle = 0;
        if (s.cur === 0) {
          playerDraw(s, g);
        } else {
          const card = s.hand[s.cur - 1];
          if (fits(card, topCard(s))) {
            s.hand.splice(s.cur - 1, 1);
            s.disc.push(card);
            g.addScore(10);
            g.sound("pop");
            if (s.hand.length === 0) { wonRound(s, g); return; }
            s.turn = "c";
            s.wait = 30;
            s.note = "Computer ist dran";
          } else {
            playerDraw(s, g);
          }
        }
      }
    } else {
      s.wait -= 1;
      if (s.wait <= 0) cpuTurn(s, g);
    }
    if (s.cur > s.hand.length) s.cur = s.hand.length;
  },

  draw(s, d, g) {
    d.clear("cream");

    // Computer-Hand oben als Rueckseiten
    const cn = s.cpu.length, csp = spacingFor(cn), cx0 = startX(cn, g);
    for (let i = 0; i < cn; i++) d.rect(cx0 + i * csp, 60, 40, 60, "ink", { round: 6, line: true });

    // Ablage Mitte
    if (s.disc.length > 0) drawCard(d, 160, 250, topCard(s));

    // Stapel links
    if (s.turn === "p" && s.cur === 0) d.rect(16, 246, 48, 68, "yellow", { round: 8 });
    if (s.stock.length > 0) d.rect(20, 250, 40, 60, "ink", { round: 6, line: true });
    else d.rect(20, 250, 40, 60, "cream", { round: 6, line: true });
    d.text(String(s.stock.length), 40, 320, { size: 12, color: "ink", align: "center" });

    // Eigene Hand unten
    const pn = s.hand.length, psp = spacingFor(pn), px0 = startX(pn, g);
    for (let i = 0; i < pn; i++) {
      const x = px0 + i * psp;
      if (s.turn === "p" && s.cur === i + 1) d.rect(x - 3, 497, 46, 66, "yellow", { round: 8 });
      drawCard(d, x, 500, s.hand[i]);
    }

    // Statuszeilen
    d.text("Runden gewonnen: " + s.wins + " von 3", 180, 150, { size: 14, color: "ink", align: "center" });
    d.text(s.note, 180, 200, { size: 13, color: "ink", align: "center" });
    d.text(s.turn === "p" ? "Du bist dran" : "Computer denkt nach", 180, 222, { size: 13, color: "red", align: "center" });
    d.text("Textkarten: Wert und Farbzeichen", 180, 585, { size: 12, color: "ink", align: "center" });
    d.text("Links/rechts waehlen, Feuer spielt oder zieht", 180, 605, { size: 12, color: "ink", align: "center" });
  }
};

function shuffle(list, g) {
  for (let i = list.length - 1; i >= 1; i--) {
    const j = g.randInt(0, i);
    const t = list[i];
    list[i] = list[j];
    list[j] = t;
  }
}

function deal(s, g) {
  const deck = [];
  for (let c = 0; c < 4; c++) for (let r = 0; r < 8; r++) deck.push({ r: r, c: c });
  shuffle(deck, g);
  s.hand = [];
  s.cpu = [];
  for (let i = 0; i < 5; i++) {
    s.hand.push(deck.pop());
    s.cpu.push(deck.pop());
  }
  s.disc = [deck.pop()];
  s.stock = deck;
  s.turn = "p";
  s.wait = 0;
  s.cur = 1;
  s.mv = 0;
  s.idle = 0;
  s.note = "Passende Farbe oder gleicher Wert ablegen";
}

function redeal(s, g) {
  deal(s, g);
  s.note = "Kein Zug moeglich - neu gemischt ohne Leben-Verlust";
}

function topCard(s) {
  return s.disc[s.disc.length - 1];
}

function fits(card, top) {
  return card.r === top.r || card.c === top.c;
}

// Holt eine Karte vom Stapel; ist er leer, wird die Ablage ausser der obersten neu gemischt.
// Gibt null zurueck, wenn nichts mehr zu ziehen ist.
function takeStock(s, g) {
  if (s.stock.length === 0) {
    if (s.disc.length <= 1) return null;
    const top = s.disc.pop();
    s.stock = s.disc;
    s.disc = [top];
    shuffle(s.stock, g);
  }
  return s.stock.pop();
}

function playerDraw(s, g) {
  const card = takeStock(s, g);
  if (card === null) { redeal(s, g); return; }
  s.hand.push(card);
  if (s.hand.length >= HAND_LIMIT) {
    // Zu viele Karten auf der Hand: Leben weg, neue Runde ohne Rundensieg
    g.sound("hurt");
    g.loseLife();
    deal(s, g);
    s.note = "Zu viele Karten - Leben verloren, neue Runde";
    return;
  }
  s.turn = "c";
  s.wait = 30;
  s.idle = 0;
  s.note = "Du hast eine Karte gezogen";
}

function cpuTurn(s, g) {
  const top = topCard(s);
  const idx = [];
  for (let i = 0; i < s.cpu.length; i++) if (fits(s.cpu[i], top)) idx.push(i);
  if (idx.length > 0) {
    const i = idx[g.randInt(0, idx.length - 1)];
    const card = s.cpu.splice(i, 1)[0];
    s.disc.push(card);
    g.sound("pop");
    s.note = "Computer legt eine Karte ab";
    if (s.cpu.length === 0) { lostRound(s, g); return; }
  } else {
    const card = takeStock(s, g);
    if (card === null) { redeal(s, g); return; }
    s.cpu.push(card);
    s.note = "Computer zieht eine Karte";
  }
  s.turn = "p";
  s.wait = 0;
  s.idle = 0;
}

// Du bist zuerst ohne Karten: Rundensieg, +50 Punkte, naechstes Level.
function wonRound(s, g) {
  g.addScore(50);
  s.wins += 1;
  if (s.wins >= 3) { g.sound("win"); g.win(); return; }
  g.sound("level");
  g.nextLevel();
  deal(s, g);
  s.note = "Runde gewonnen! Naechstes Level - neue Runde";
}

// Der Computer ist zuerst ohne Karten: du verlierst ein Leben, neue Runde.
function lostRound(s, g) {
  g.sound("hurt");
  g.loseLife();
  deal(s, g);
  s.note = "Computer war zuerst fertig - du verlierst ein Leben";
}

function spacingFor(n) {
  return n > 1 ? Math.min(44, Math.floor(300 / (n - 1))) : 0;
}

function startX(n, g) {
  return (g.W - (40 + Math.max(0, n - 1) * spacingFor(n))) / 2;
}

function drawCard(d, x, y, card) {
  d.rect(x, y, 40, 60, "cream", { round: 6, line: true });
  const col = card.c < 2 ? "red" : "ink";
  d.text(RANKS[card.r] + SUITS[card.c], x + 20, y + 30, { size: 13, color: col, align: "center" });
}

// Pizza-Ausbruch (nur Spiel-API, keine Importe).
// Haken h4 (Lego-Steine) ist nicht umgesetzt: Markenname nicht erlaubt. Ersatz: eigene Bausteine mit Noppen.
const COLORS = ["yellow", "red", "ink", "cream"];

export default {
  title: "Pizza-Ausbruch",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return {
      paddle: { x: 140, y: 600, w: 80, h: 14 },
      ball: { x: 180, y: 590, r: 10, vx: 0, vy: 0, stuck: true },
      bricks: makeBricks(g),
      safe: 0,
      wait: 0
    };
  },

  update(s, input, g) {
    const p = s.paddle;
    if (input.left) p.x -= 5;
    if (input.right) p.x += 5;
    p.x = g.clamp(p.x, 0, g.W - p.w);
    if (s.safe > 0) s.safe -= 1;

    const b = s.ball;

    if (b.stuck) {
      b.x = p.x + 40;
      b.y = p.y - b.r;
      b.vx = 0;
      b.vy = 0;
      s.wait += 1;
      if (s.wait >= 30) {
        b.stuck = false;
        b.vx = g.random() < 0.5 ? -2.5 : 2.5;
        b.vy = -speed(g);
      }
      return;
    }

    // Geschwindigkeit: Betrag der vertikalen Geschwindigkeit, Richtung bleibt erhalten
    const sp = speed(g);
    b.vy = b.vy < 0 ? -sp : sp;

    b.x += b.vx;
    b.y += b.vy;

    // Waende
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - b.r) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    // Decke
    if (b.y < g.TOP + b.r) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Schlaeger
    if (b.vy > 0 && g.hit(b, p)) {
      b.vy = -Math.abs(b.vy);
      b.vx = g.clamp((b.x - (p.x + 40)) / 40 * 4, -5, 5);
      b.y = p.y - b.r;
      g.sound("jump");
    }

    // Steine: hoechstens einer pro Frame
    const idx = s.bricks.findIndex((br) => g.hit(b, br));
    if (idx >= 0) {
      s.bricks.splice(idx, 1);
      b.vy = -b.vy;
      g.addScore(10 * g.level);
      g.sound("pop");
    }

    // Pizza faellt raus
    if (b.y > g.H + b.r) {
      g.sound("hurt");
      g.loseLife();
      resetBall(s);
      s.safe = 60;
      return;
    }

    // Level geschafft
    if (s.bricks.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.bricks = makeBricks(g);
      resetBall(s);
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    for (const br of s.bricks) {
      d.rect(br.x, br.y, br.w, br.h, br.col, { round: 3, line: true });
      d.circle(br.x + 11, br.y - 2, 4, br.col, { line: true });
      d.circle(br.x + br.w - 11, br.y - 2, 4, br.col, { line: true });
    }

    const p = s.paddle;
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.rect(p.x, p.y, p.w, p.h, "red", { round: 7, shadow: true, line: true });
    }

    d.emoji("🍕", s.ball.x, s.ball.y, 26);

    if (s.ball.stuck && s.wait < 30) {
      d.text("Gleich geht's los", g.W / 2, 520, { size: 16, color: "ink", align: "center" });
    }
  }
};

function speed(g) {
  return Math.min(8, 4 + 0.5 * g.level);
}

function makeBricks(g) {
  const out = [];
  const rows = Math.min(3 + g.level, 6);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 8; c++) {
      out.push({ x: 20 + c * 40, y: g.TOP + 30 + r * 21, w: 39, h: 18, col: COLORS[r % 4] });
    }
  }
  return out;
}

function resetBall(s) {
  s.ball = { x: s.paddle.x + 40, y: s.paddle.y - 10, r: 10, vx: 0, vy: 0, stuck: true };
  s.wait = 0;
}

