  update(s, input, g) {
    const p = s.paddle;
    if (input.left) p.x -= 5;
    if (input.right) p.x += 5;
    p.x = g.clamp(p.x, 0, g.W - p.w);
    if (s.safe > 0) s.safe -= 1;
    if (s.msg > 0) s.msg -= 1;

    const b = s.ball;

    if (b.stuck) {
      b.x = p.x + p.w / 2;
      b.y = p.y - b.r;
      b.vx = 0;
      b.vy = 0;
      s.wait += 1;
      if (s.wait >= 30) {
        b.stuck = false;
        // Startwinkel: Horizontal zufaellig zwischen 1.8 und 3.3, Richtung zufaellig
        const mag = 1.8 + g.random() * 1.5;
        b.vx = g.random() < 0.5 ? -mag : mag;
        b.vy = -speed(g);
      }
      return;
    }

    // Vertikale Geschwindigkeit: Betrag konstant, Richtung bleibt erhalten
    const sp = speed(g);
    b.vy = b.vy < 0 ? -sp : sp;

    // Vorherige Position merken (fuer die Wahl der Abprallseite bei Steinen)
    const px = b.x;
    const py = b.y;

    b.x += b.vx;
    b.y += b.vy;

    // Waende
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - b.r) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    // Decke
    if (b.y < g.TOP + b.r) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Schlaeger: Abprallwinkel abhaengig von der Trefferstelle (Mitte = senkrecht, Rand = flach)
    if (b.vy > 0 && g.hit(b, p)) {
      b.vy = -Math.abs(b.vy);
      const off = (b.x - (p.x + p.w / 2)) / (p.w / 2);
      let vx = g.clamp(off * 5, -5, 5);
      // Mindest-Horizontalgeschwindigkeit, damit der Ball nicht senkrecht hin und her springt
      if (Math.abs(vx) < 1.2) vx = vx < 0 ? -1.2 : 1.2;
      b.vx = vx;
      b.y = p.y - b.r;
      g.sound("jump");
    }

    // Steine: hoechstens einer pro Frame; Abprallseite anhand der Ueberlappung waehlen
    const idx = s.bricks.findIndex((br) => g.hit(b, br));
    if (idx >= 0) {
      const br = s.bricks[idx];
      s.bricks.splice(idx, 1);
      const fromSide = px + b.r <= br.x || px - b.r >= br.x + br.w;
      if (fromSide) {
        b.vx = -b.vx;
        b.x = px;
        if (Math.abs(b.vx) < 1) b.vx = b.vx < 0 ? -1 : 1;
      } else {
        b.vy = -b.vy;
        b.y = py;
      }
      g.addScore(10 * g.level);
      g.sound("pop");
    }

    // Pizza faellt raus
    if (b.y > g.H + b.r) {
      g.sound("hurt");
      g.loseLife();
      resetBall(s);
      s.safe = 60;
      return;
    }

    // Level geschafft: alle Steine weg
    if (s.bricks.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.bricks = makeBricks(g);
      s.msg = 120;
      resetBall(s);
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    for (const br of s.bricks) {
      d.rect(br.x, br.y, br.w, br.h, br.col, { round: 3, line: true });
      d.circle(br.x + 11, br.y - 2, 4, br.col, { line: true });
      d.circle(br.x + br.w - 11, br.y - 2, 4, br.col, { line: true });
    }

    const p = s.paddle;
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.rect(p.x, p.y, p.w, p.h, "red", { round: 7, shadow: true, line: true });
    }

    d.emoji("🍕", s.ball.x, s.ball.y, 26);

    if (s.ball.stuck && s.wait < 30) {
      d.text("Gleich geht's los", g.W / 2, 520, { size: 16, color: "ink", align: "center" });
    }

    if (s.msg > 0) {
      d.text("Level geschafft", g.W / 2, 300, { size: 28, color: "ink", align: "center" });
    }
  }
};

function speed(g) {
  return Math.min(8, 4 + 0.5 * g.level);
}

// Level 1: 1 Reihe, Level 2: 2 Reihen, ... maximal 6 Reihen
function makeBricks(g) {
  const out = [];
  const rows = Math.min(g.level, 6);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 8; c++) {
      out.push({ x: 20 + c * 40, y: g.TOP + 30 + r * 21, w: 39, h: 18, col: COLORS[r % 4] });
    }
  }
  return out;
}

function resetBall(s) {
  s.ball = { x: s.paddle.x + s.paddle.w / 2, y: s.paddle.y - 10, r: 10, vx: 0, vy: 0, stuck: true };
  s.wait = 0;
}

// Autobahn-Ueberholer (nur Spiel-API, keine Importe): roter Sportwagen zwischen vier Spuren.
// Andere Autos ueberholen, Punkte fuer jedes ueberholte Auto, Beruehrung kostet ein Leben.
// Steuerung: links/rechts wechselt Spur, oben gibt Gas, unten bremst.
const LANES = [59, 129, 199, 269]; // linke Kante der Autos: Spurmitte minus 16
const OTHER_EMOJIS = ["🚗", "🚙", "🚕", "🚐", "🚚"];

export default {
  title: "Autobahn-Überholer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return {
      car: { x: 199, y: 520, w: 32, h: 56 },
      others: [],
      speed: 5,
      safe: 0,
      spawn: 0,
      passed: 0,
      dash: 0
    };
  },

  update(s, input, g) {
    const car = s.car;

    // Spur wechseln und Tempo regeln
    if (input.left) car.x -= 4;
    if (input.right) car.x += 4;
    car.x = g.clamp(car.x, 44, 316 - car.w);
    if (input.up) s.speed = Math.min(10, s.speed + 0.1);
    if (input.down) s.speed = Math.max(3, s.speed - 0.1);

    // Fahrbahn scrollt mit dem Tempo
    s.dash = (s.dash + s.speed) % 60;

    if (s.safe > 0) s.safe -= 1;

    // Verkehr erscheinen lassen
    s.spawn -= 1;
    if (s.spawn <= 0) {
      spawnCars(s, g);
      const lo = Math.max(20, 50 - 6 * g.level);
      s.spawn = g.randInt(lo, lo + 30);
    }

    // Andere Autos bewegen sich relativ zum eigenen Tempo; Ueberholen gibt Punkte
    for (const o of s.others) {
      o.y += Math.max(1, s.speed - o.v);
      if (!o.scored && o.y > car.y + car.h) {
        o.scored = true;
        g.addScore(10);
        g.sound("coin");
        s.passed += 1;
        if (s.passed % 10 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }

    // Beruehrung: Spielerbox etwas kleiner als das Bild
    if (s.safe === 0) {
      const box = { x: car.x + 2, y: car.y + 2, w: car.w - 4, h: car.h - 4 };
      for (const o of s.others) {
        if (g.hit(box, o)) {
          o.gone = true;
          g.sound("hurt");
          g.loseLife();
          s.safe = 90;
          break;
        }
      }
    }

    s.others = s.others.filter((o) => !o.gone && o.y <= g.H + 60);
  },

  draw(s, d, g) {
    d.clear("ink");
    d.rect(40, 0, 280, g.H, "ink");
    d.line(40, 0, 40, g.H, "cream", 4);
    d.line(320, 0, 320, g.H, "cream", 4);

    // Gestrichelte Spurlinien, scrollend
    const off = s.dash % 60;
    for (const lx of [110, 180, 250]) {
      for (let y = off - 60; y < g.H; y += 60) {
        const y1 = Math.max(0, y);
        const y2 = Math.min(g.H, y + 30);
        if (y2 > y1) d.line(lx, y1, lx, y2, "cream", 3);
      }
    }

    // Seitenstreifen
    d.rect(0, 0, 40, g.H, "yellow");
    d.rect(320, 0, 40, g.H, "cream");

    // Andere Autos
    for (const o of s.others) d.emoji(o.emoji, o.x + 16, o.y + 28, 40);

    // Spielerwagen, blinkt nach Treffer
    const car = s.car;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.rect(car.x, car.y + 8, car.w, car.h - 16, "red", { round: 8, line: true });
      d.emoji("🏎️", car.x + 16, car.y + 28, 44);
    }

    d.text("Tempo " + Math.floor(s.speed * 20) + " km/h", 180, 70, { size: 14, color: "cream", align: "center" });
  }
};

function freeLanes(s) {
  const out = [];
  for (const lx of LANES) {
    if (!s.others.some((o) => o.x === lx && o.y < 80)) out.push(lx);
  }
  return out;
}

function addCar(s, g, lx) {
  s.others.push({
    x: lx,
    y: -60,
    w: 32,
    h: 56,
    v: 2 + g.random() * 1.5,
    emoji: OTHER_EMOJIS[g.randInt(0, OTHER_EMOJIS.length - 1)],
    scored: false,
    gone: false
  });
}

function spawnCars(s, g) {
  const free = freeLanes(s);
  if (free.length === 0) return;
  const first = free[g.randInt(0, free.length - 1)];
  addCar(s, g, first);
  // Ab Level 2 manchmal eine zweite Spur, aber immer mindestens eine Spur frei bleibt
  if (g.level >= 2 && free.length >= 3 && g.random() < 0.3) {
    const rest = free.filter((lx) => lx !== first);
    addCar(s, g, rest[g.randInt(0, rest.length - 1)]);
  }
}

