    if (s.spawn <= 0) {
      spawnCars(s, g);
      const lo = Math.max(20, 50 - 6 * g.level);
      s.spawn = g.randInt(lo, lo + 30);
    }

    // Andere Autos bewegen sich relativ zum eigenen Tempo; Ueberholen gibt Punkte
    for (const o of s.others) {
      o.y += Math.max(1, s.speed - o.v);
      if (!o.scored && o.y > car.y + car.h) {
        o.scored = true;
        g.addScore(10);
        g.sound("coin");
        s.passed += 1;
        if (s.passed % 10 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }

    // Beruehrung: Spielerbox etwas kleiner als das Bild
    if (s.safe === 0) {
      const box = { x: car.x + 2, y: car.y + 2, w: car.w - 4, h: car.h - 4 };
      for (const o of s.others) {
        if (g.hit(box, o)) {
          o.gone = true;
          g.sound("hurt");
          g.loseLife();
          s.safe = 90;
          break;
        }
      }
    }

    s.others = s.others.filter((o) => !o.gone && o.y <= g.H + 60);
  },

  draw(s, d, g) {
    d.clear("ink");
    d.rect(40, 0, 280, g.H, "ink");
    d.line(40, 0, 40, g.H, "cream", 4);
    d.line(320, 0, 320, g.H, "cream", 4);

    // Gestrichelte Spurlinien, scrollend
    const off = s.dash % 60;
    for (const lx of [110, 180, 250]) {
      for (let y = off - 60; y < g.H; y += 60) {
        const y1 = Math.max(0, y);
        const y2 = Math.min(g.H, y + 30);
        if (y2 > y1) d.line(lx, y1, lx, y2, "cream", 3);
      }
    }

    // Seitenstreifen
    d.rect(0, 0, 40, g.H, "yellow");
    d.rect(320, 0, 40, g.H, "cream");

    // Andere Autos
    for (const o of s.others) d.emoji(o.emoji, o.x + 16, o.y + 28, 40);

    // Spielerwagen, blinkt nach Treffer
    const car = s.car;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.rect(car.x, car.y + 8, car.w, car.h - 16, "red", { round: 8, line: true });
      d.emoji("🏎️", car.x + 16, car.y + 28, 44);
    }

    d.text("Tempo " + Math.floor(s.speed * 20) + " km/h", 180, 70, { size: 14, color: "cream", align: "center" });
  }
};

function freeLanes(s) {
  const out = [];
  for (const lx of LANES) {
    if (!s.others.some((o) => o.x === lx && o.y < 80)) out.push(lx);
  }
  return out;
}

function addCar(s, g, lx) {
  s.others.push({
    x: lx,
    y: -60,
    w: 32,
    h: 56,
    v: 2 + g.random() * 1.5,
    emoji: OTHER_EMOJIS[g.randInt(0, OTHER_EMOJIS.length - 1)],
    scored: false,
    gone: false
  });
}

function spawnCars(s, g) {
  const free = freeLanes(s);
  if (free.length === 0) return;
  const first = free[g.randInt(0, free.length - 1)];
  addCar(s, g, first);
  // Ab Level 2 manchmal eine zweite Spur, aber immer mindestens eine Spur frei bleibt
  if (g.level >= 2 && free.length >= 3 && g.random() < 0.3) {
    const rest = free.filter((lx) => lx !== first);
    addCar(s, g, rest[g.randInt(0, rest.length - 1)]);
  }
}

// Felsen-Funker (nur Spiel-API, keine Importe): Raumschiff drehen, fliegen und schiessen.
// Felsen zerfallen in kleinere Brocken. Berührt ein Fels das Schiff, kostet das ein Leben.
const STARS = [[20, 70], [90, 120], [150, 300], [300, 90], [330, 200], [60, 420], [250, 480], [340, 560], [120, 600], [200, 160], [40, 250], [310, 380]];
const MAX_ROCKS = 36;

export default {
  title: "Felsen-Funker",
  controls: ["left", "right", "up", "fire"],
  lives: 3,

  init(g) {
    const s = {
      ship: { x: 180, y: 340, vx: 0, vy: 0, a: 0 },
      shots: [],
      rocks: [],
      safe: 60,
      cool: 0,
      quiet: 0
    };
    const count = Math.min(3 + g.level, 9);
    for (let i = 0; i < count; i++) s.rocks.push(edgeRock(s, g, 3));
    return s;
  },

  update(s, input, g) {
    const sh = s.ship;

    // Drehen und Schub
    if (input.left) sh.a = (sh.a - 4 + 360) % 360;
    if (input.right) sh.a = (sh.a + 4) % 360;
    if (input.up) {
      sh.vx += g.sin(sh.a) * 0.15;
      sh.vy -= g.cos(sh.a) * 0.15;
    }
    const sp = Math.sqrt(sh.vx * sh.vx + sh.vy * sh.vy);
    if (sp > 5) {
      sh.vx = sh.vx * 5 / sp;
      sh.vy = sh.vy * 5 / sp;
    }
    sh.vx *= 0.99;
    sh.vy *= 0.99;
    sh.x += sh.vx;
    sh.y += sh.vy;
    wrap(sh, g);

    if (s.safe > 0) s.safe -= 1;
    if (s.cool > 0) s.cool -= 1;

    // Schuss in Blickrichtung
    if ((input.firePressed || input.fire) && s.cool === 0 && s.shots.length < 4) {
      s.shots.push({
        x: sh.x + g.sin(sh.a) * 14,
        y: sh.y - g.cos(sh.a) * 14,
        vx: g.sin(sh.a) * 7 + sh.vx * 0.3,
        vy: -g.cos(sh.a) * 7 + sh.vy * 0.3,
        r: 3,
        life: 55
      });
      s.cool = 12;
      g.sound("shoot");
    }

    // Schuesse bewegen
    for (const shot of s.shots) {
      shot.x += shot.vx;
      shot.y += shot.vy;
      shot.life -= 1;
      wrap(shot, g);
    }
    s.shots = s.shots.filter((shot) => shot.life > 0);

    // Felsen bewegen
    for (const rk of s.rocks) {
      rk.x += rk.vx;
      rk.y += rk.vy;
      wrap(rk, g);
    }

    // Felsen gegen Schiff (nur wenn nicht unverwundbar)
    if (s.safe === 0) {
      const hitRock = s.rocks.some((rk) => g.hit({ x: rk.x, y: rk.y, r: rk.r }, { x: sh.x, y: sh.y, r: 12 }));
      if (hitRock) {
        g.sound("hurt");
        g.loseLife();
        sh.x = 180; sh.y = 340; sh.vx = 0; sh.vy = 0; sh.a = 0;
        s.safe = 90;
        s.quiet = 0;
        return;
      }
    }

    // Schuesse gegen Felsen
    const rest = [];
    for (const rk of s.rocks) {
      let idx = -1;
      for (let i = 0; i < s.shots.length; i++) {
        const shot = s.shots[i];
        if (g.hit({ x: shot.x, y: shot.y, r: shot.r }, { x: rk.x, y: rk.y, r: rk.r })) { idx = i; break; }
      }
      if (idx < 0) { rest.push(rk); continue; }
      s.shots.splice(idx, 1);
      g.addScore([0, 100, 50, 20][rk.size] * g.level);
      g.sound("pop");
      if (rk.size > 1 && rest.length < MAX_ROCKS) {
        rest.push(makeRock(g, rk.x, rk.y, rk.size - 1));
        rest.push(makeRock(g, rk.x, rk.y, rk.size - 1));
      }
    }
    s.rocks = rest;

    // Extra-Fels, wenn lange kein Treffer
    s.quiet += 1;
    if (s.quiet >= 600) {
      s.quiet = 0;
      if (s.rocks.length < MAX_ROCKS) s.rocks.push(edgeRock(s, g, 2));
    }

    // Naechstes Level
    if (s.rocks.length === 0) {
      g.nextLevel();
      g.sound("level");
      const count = Math.min(3 + g.level, 9);
      for (let i = 0; i < count; i++) s.rocks.push(edgeRock(s, g, 3));
    }
  },

  draw(s, d, g) {
    d.clear("ink");
    for (const p of STARS) d.circle(p[0], p[1], 1, "cream");

    for (const rk of s.rocks) d.emoji("🪨", rk.x, rk.y, rk.r * 2);
    for (const shot of s.shots) d.circle(shot.x, shot.y, 3, "yellow");

    const sh = s.ship;
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🚀", sh.x, sh.y, 30);
      d.line(sh.x, sh.y, sh.x + g.sin(sh.a) * 20, sh.y - g.cos(sh.a) * 20, "yellow", 3);
    }
  }
};

function wrap(o, g) {
  if (o.x < 0) o.x += g.W;
  if (o.x > g.W) o.x -= g.W;
  if (o.y < g.TOP) o.y = g.H;
  if (o.y > g.H) o.y = g.TOP;
}

function makeRock(g, x, y, size) {
  const ang = g.random() * 360;
  const speed = (0.5 + g.random()) * (1 + 0.1 * (g.level - 1));
  return { x: x, y: y, vx: g.sin(ang) * speed, vy: -g.cos(ang) * speed, size: size, r: 10 * size + 4 };
}

function edgeRock(s, g, size) {
  let x = 0;
  let y = 0;
  for (let tries = 0; tries < 20; tries++) {
    const side = g.randInt(0, 3);
    if (side === 0) { x = g.random() * g.W; y = g.TOP + 2; }
    else if (side === 1) { x = g.random() * g.W; y = g.H - 2; }
    else if (side === 2) { x = 2; y = g.TOP + g.random() * (g.H - g.TOP); }
    else { x = g.W - 2; y = g.TOP + g.random() * (g.H - g.TOP); }
    if (g.dist({ x: x, y: y }, s.ship) >= 120) break;
  }
  return makeRock(g, x, y, size);
}

