// Hinweis: Es gibt kein Graeten-Emoji. Die Fischgraeten sind aus Linien (ink) gezeichnet, kein echtes Graeten-Bild.
// Moewen fliegen hin und her und kosten bei Beruehrung ein Leben.
const GRAV = 0.5, JUMP = -10.5, START_Y = 554;
const STARS = [[40, 90], [120, 100], [200, 80], [260, 150], [60, 200], [150, 170], [330, 230], [20, 260], [230, 210]];

export default {
  title: "Dachkatze",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 20, y: START_Y, w: 24, h: 26, vx: 0, vy: 0, ground: true },
      plats: [], bones: [], gulls: [], safe: 0, timer: 0
    };
    build(s, g);
    return s;
  },

  update(s, input, g) {
    const me = s.me;
    me.vx = input.left ? -3 : input.right ? 3 : 0;
    if (input.up && me.ground) { me.vy = JUMP; me.ground = false; g.sound("jump"); }
    me.vy = Math.min(me.vy + GRAV, 12);
    const oldBottom = me.y + me.h;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);
    me.y += me.vy;
    me.ground = false;
    if (me.vy >= 0) {
      for (const p of s.plats) {
        const over = me.x + me.w > p.x && me.x < p.x + p.w;
        if (over && oldBottom <= p.y && me.y + me.h >= p.y) {
          me.y = p.y - me.h; me.vy = 0; me.ground = true;
        }
      }
    }

    if (s.safe > 0) s.safe -= 1;
    s.timer += 1;

    // Moewen fliegen hin und her
    for (const gl of s.gulls) {
      gl.x += gl.vx;
      if (gl.x < gl.min) { gl.x = gl.min; gl.vx = Math.abs(gl.vx); }
      if (gl.x + gl.w > gl.max) { gl.x = gl.max - gl.w; gl.vx = -Math.abs(gl.vx); }
    }
    if (s.safe === 0 && s.gulls.some((gl) => g.hit(me, gl))) {
      g.sound("hurt"); g.loseLife(); respawn(s); return;
    }

    // Fischgraeten einsammeln
    for (const b of s.bones) {
      if (!b.got && g.hit(me, b)) { b.got = true; g.addScore(10); g.sound("coin"); }
    }
    s.bones = s.bones.filter((b) => !b.got);

    // Abgrund
    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); respawn(s); return; }

    // Level geschafft
    if (s.bones.length === 0) {
      g.addScore(50);
      if (g.level >= 6) { g.win(); return; }
      g.nextLevel(); g.sound("level"); build(s, g); return;
    }

    // Zeitlimit pro Level
    if (s.timer > 3000) { g.gameOver(); return; }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.circle(322, 110, 18, "yellow");
    for (const [x, y] of STARS) d.circle(x, y, 2, "ink");

    s.plats.forEach((p, i) => {
      if (i === 0) d.rect(0, 596, 110, 44, "ink", { round: 6 });
      d.rect(p.x, p.y, p.w, 16, "yellow", { round: 6, shadow: true, line: true });
    });

    for (const b of s.bones) drawBone(d, b.x, b.y);

    for (const gl of s.gulls) d.emoji("🐦", gl.x + gl.w / 2, gl.y + gl.h / 2, 26);

    const me = s.me;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) d.emoji("🐱", me.x + me.w / 2, me.y + me.h / 2, 30);
  }
};

function build(s, g) {
  const plats = [{ x: 0, y: 580, w: 110, h: 60 }];
  let cx = 55;
  for (let row = 1; row <= 5; row++) {
    const w = g.randInt(80, 130);
    const y = 580 - row * 88;
    cx = g.clamp(cx + g.randInt(-110, 110), w / 2 + 4, g.W - w / 2 - 4);
    plats.push({ x: cx - w / 2, y, w, h: 16 });
  }
  // zwei Dächer unten rechts mit Luecke (Abgrund)
  plats.push({ x: g.randInt(150, 180), y: 580, w: g.randInt(60, 80), h: 16 });
  plats.push({ x: g.randInt(275, 285), y: 580, w: g.randInt(50, 70), h: 16 });

  s.plats = plats;
  // Fischgraete je Dach (nicht auf dem Startdach, damit Nichtstun 0 Punkte bringt)
  s.bones = [];
  for (let i = 1; i < plats.length; i++) {
    const p = plats[i];
    s.bones.push({ x: p.x + p.w / 2 - 9, y: p.y - 28, w: 18, h: 18, got: false });
  }
  // Moewen: je Level eine mehr, hoechstens 4
  s.gulls = [];
  const n = Math.min(g.level, 4);
  for (let k = 0; k < n; k++) {
    const roof = plats[g.randInt(1, 5)];
    const sign = g.randInt(0, 1) === 0 ? -1 : 1;
    s.gulls.push({
      x: roof.x + roof.w / 2 - 13, y: roof.y - 44, w: 26, h: 22,
      vx: sign * (1 + 0.2 * g.level),
      min: Math.max(0, roof.x - 20),
      max: Math.min(g.W - 26, roof.x + roof.w + 80)
    });
  }
  s.timer = 0;
  respawn(s);
}

function respawn(s) {
  const me = s.me;
  me.x = 20; me.y = START_Y; me.vx = 0; me.vy = 0; me.ground = true;
  s.safe = 60;
}

function drawBone(d, x, y) {
  const cy = y + 9;
  d.line(x + 1, cy, x + 17, cy, "ink", 2);
  for (const rx of [x + 4, x + 9, x + 14]) {
    d.line(rx, cy, rx + 4, cy - 6, "ink", 2);
    d.line(rx, cy, rx + 4, cy + 6, "ink", 2);
  }
}

