// Huhn-Flatterflug (nur Spiel-API, keine Importe). Eigene Grafik: Huhn-Emoji und Formen, kein Original-Motiv.
// Tippen oder Knopf fire laesst das Huhn flattern. Durch die Luecken der Roehren fliegen, Wand, Boden und Decke kosten ein Leben.
const PW = 52;

export default {
  title: "Huhn-Flatterflug",
  controls: ["fire"],
  lives: 3,

  init(g) {
    return {
      hen: { x: 80, y: 300, w: 28, h: 28, vy: 0 },
      pipes: [],
      safe: 0,
      spawn: 40,
      count: 0
    };
  },

  update(s, input, g) {
    const hen = s.hen;

    if (input.firePressed) {
      hen.vy = -6.2;
      g.sound("jump");
    }
    hen.vy = Math.min(hen.vy + 0.35, 8);
    hen.y += hen.vy;

    if (s.safe > 0) s.safe -= 1;

    s.spawn -= 1;
    if (s.spawn <= 0) {
      s.pipes.push(newPipe(g));
      s.spawn = 95;
    }

    const speed = Math.min(4, 2 + 0.3 * (g.level - 1));
    for (const p of s.pipes) {
      p.x -= speed;
      if (!p.passed && p.x + PW < hen.x) {
        p.passed = true;
        g.addScore(1);
        g.sound("coin");
        s.count += 1;
        if (s.count % 5 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }
    s.pipes = s.pipes.filter((p) => p.x > -60);

    if (s.safe === 0) {
      let bad = hen.y < g.TOP || hen.y + hen.h > g.H - 20;
      for (const p of s.pipes) {
        const top = { x: p.x, y: g.TOP, w: PW, h: p.gapY - p.gapH / 2 - g.TOP };
        const bot = { x: p.x, y: p.gapY + p.gapH / 2, w: PW, h: g.H - 20 - (p.gapY + p.gapH / 2) };
        if (g.hit(hen, top) || g.hit(hen, bot)) bad = true;
      }
      if (bad) {
        g.sound("hurt");
        g.loseLife();
        s.safe = 70;
        hen.y = 300;
        hen.vy = 0;
        s.pipes = s.pipes.filter((p) => p.x >= 150);
        return;
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let i = 0; i < 4; i++) {
      const cx = ((g.frame * 0.5 + i * 130) % (g.W + 80)) - 40;
      d.circle(cx, g.TOP + 60 + (i % 2) * 90, 26, "yellow");
    }
    for (const p of s.pipes) {
      const topH = p.gapY - p.gapH / 2 - g.TOP;
      const botY = p.gapY + p.gapH / 2;
      d.rect(p.x, g.TOP, PW, topH, "yellow", { round: 6, line: true });
      d.rect(p.x, botY, PW, g.H - 20 - botY, "yellow", { round: 6, line: true });
    }
    d.rect(0, g.H - 20, g.W, 20, "ink");
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🐔", s.hen.x + 14, s.hen.y + 14, 34);
    }
  }
};

function newPipe(g) {
  const gapH = Math.max(130, 190 - 8 * (g.level - 1));
  const gapY = g.randInt(g.TOP + 30 + gapH / 2, g.H - 60 - gapH / 2);
  return { x: g.W + 10, gapY, gapH, passed: false };
}

