// Tennis-Duell (nur Spiel-API, keine Importe). Hochkant: Schlaeger unten (du) und oben (Computer).
// Der Ball springt zwischen den Schlaegern und den Seitenwaenden. Verfehlst du ihn, verlierst du ein Leben.
// Verfehlt der Computer ihn, gibt es Punkte. Steuerung: links und rechts.
export default {
  title: "Tennis-Duell",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 150, y: 600, w: 60, h: 12 },
      cpu: { x: 150, y: 70, w: 60, h: 12 },
      ball: { x: 180, y: 344, r: 8, vx: 0, vy: 0 },
      wait: 0,
      hits: 0,
      cpuMiss: false,
      safe: 0
    };
    serve(s, g);
    return s;
  },

  update(s, input, g) {
    const me = s.me;
    const cpu = s.cpu;
    const b = s.ball;

    // Spieler-Schlaeger
    if (input.right) me.x += 5;
    if (input.left) me.x -= 5;
    me.x = g.clamp(me.x, 4, g.W - me.w - 4);

    // Computer-Schlaeger folgt dem Ball, mit Fehlerzone und gelegentlichem Verfehlen
    let cpuSpeed = Math.min(2.2 + 0.4 * g.level, 4.2);
    if (s.cpuMiss) cpuSpeed = cpuSpeed / 2;
    const diff = b.x - (cpu.x + cpu.w / 2);
    if (Math.abs(diff) >= 6) {
      cpu.x += g.clamp(diff, -cpuSpeed, cpuSpeed);
    }
    cpu.x = g.clamp(cpu.x, 4, g.W - cpu.w - 4);

    // Aufschlag-Pause: Ball steht, danach geht er los
    if (s.wait > 0) {
      s.wait -= 1;
      if (s.wait === 0) {
        let vx = g.randInt(-2, 2);
        if (vx === 0) vx = 1;
        b.vx = vx;
        b.vy = 4;
      }
      return;
    }

    // Ball bewegen
    b.x += b.vx;
    b.y += b.vy;

    // Seitenwaende
    if (b.x <= 4 + b.r) {
      b.x = 4 + b.r;
      b.vx = Math.abs(b.vx);
    }
    if (b.x >= g.W - 4 - b.r) {
      b.x = g.W - 4 - b.r;
      b.vx = -Math.abs(b.vx);
    }

    // Treffer am Spieler-Schlaeger (Ball kommt von oben)
    if (b.vy > 0 && b.y + b.r >= me.y && b.y - b.r <= me.y + me.h &&
        b.x >= me.x - b.r && b.x <= me.x + me.w + b.r) {
      b.vy = -Math.min(Math.abs(b.vy) + 0.15, 9);
      b.vx = g.clamp(((b.x - (me.x + me.w / 2)) / 30) * 4, -4, 4);
