// Ballon-Duell in den Wolken (nur Spiel-API, keine Importe).
// Eine Person steuert eine Ente, der Computer-Gegner ist eine Eule. Wer dreimal nass ist, verliert das Duell.
// Es gibt nur Wasserballons, kein Blut und keine Gewalt.
const CLOUDS = [
  { x: 20, y: 120, w: 110, h: 34 },
  { x: 220, y: 200, w: 120, h: 36 },
  { x: 60, y: 300, w: 150, h: 40 },
  { x: 250, y: 400, w: 90, h: 30 }
];

export default {
  title: "Ballon-Duell in den Wolken",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    return {
      p: { x: 160, y: 540, w: 36, h: 32 },
      opp: { x: g.W / 2 - 18, y: g.TOP + 40, w: 36, h: 32, hp: 3, wet: 0 },
      dir: 1,
      ody: 0.4,
      targetX: g.W / 2,
      timer: 0,
      pballs: [],
      oballs: [],
      cool: 0,
      ocool: 60,
      safe: 0,
      pwet: 0,
      pdir: 0
    };
  },

  update(s, input, g) {
    const p = s.p;
    const o = s.opp;
    s.timer += 1;

    // Spieler: sofortige Bewegung in den erlaubten Bereichen
    p.x = g.clamp(p.x + (input.left ? -3.5 : 0) + (input.right ? 3.5 : 0), 4, g.W - p.w - 4);
    p.y = g.clamp(p.y + (input.up ? -3.5 : 0) + (input.down ? 3.5 : 0), 350, g.H - 40);
    s.pdir = (input.right ? 1 : 0) - (input.left ? 1 : 0);

    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;
    if (s.pwet > 0) s.pwet -= 1;
    if (o.wet > 0) o.wet -= 1;

    // Eigene Wasserballons
    if ((input.firePressed || input.fire) && s.cool === 0 && s.pballs.length < 3) {
      s.pballs.push({ x: p.x + p.w / 2, y: p.y, r: 7, vy: -7 });
      s.cool = 15;
      g.sound("shoot");
    }
    for (const b of s.pballs) b.y += b.vy;

    // Gegner-KI: Zielwechsel alle 30 Frames, waagerecht hin und her, sanft zum Spieler
    if (s.timer % 30 === 0) {
      s.targetX = g.clamp(p.x + p.w / 2 + g.randInt(-40, 40), 20, g.W - 20);
    }
    const speed = 1.2 + 0.3 * g.level;
    o.x += s.dir * speed;
    const cx = o.x + o.w / 2;
    o.x += g.clamp((s.targetX - cx) * 0.03, -1, 1);
    if (o.x < 4) { o.x = 4; s.dir = 1; }
    if (o.x + o.w > g.W - 4) { o.x = g.W - 4 - o.w; s.dir = -1; }
    o.y += s.ody;
    if (o.y < g.TOP + 10 || o.y > 260) {
      s.ody = -s.ody;
      o.y = g.clamp(o.y, g.TOP + 10, 260);
    }

    // Gegner wirft Wasserballons Richtung Spieler (mit kleinem Versatz je nach Spielerrichtung)
    s.ocool -= 1;
    if (s.ocool <= 0) {
      const aim = g.clamp((p.x + p.w / 2 - cx) / 120, -1.5, 1.5);
      s.oballs.push({ x: cx, y: o.y + o.h, r: 7, vy: 3 + 0.3 * g.level, vx: aim + s.pdir * 0.3 });
      s.ocool = Math.max(40, 100 - 10 * g.level) + g.randInt(0, 30);
    }
    for (const b of s.oballs) { b.x += b.vx; b.y += b.vy; }

    // Treffer des Spielerballons auf den Gegner
    let duelWon = false;
    for (const b of s.pballs) {
      if (!b.gone && g.hit(b, o)) {
        b.gone = true;
        o.hp -= 1;
        o.wet = 30;
        g.addScore(10 * g.level);
        g.sound("pop");
        if (o.hp <= 0) { duelWon = true; break; }
      }
    }
    s.pballs = s.pballs.filter((b) => !b.gone && b.y > g.TOP && b.y < g.H + 10);

    if (duelWon) {
      g.addScore(50);
      g.nextLevel();
      g.sound("level");
      o.hp = 3;
      o.wet = 0;
      o.x = g.W / 2 - 18;
      o.y = g.TOP + 40;
      s.dir = 1;
      s.pballs = [];
      s.oballs = [];
      s.ocool = 60;
      return;
    }

    // Treffer gegnerischer Ballons auf den Spieler
    let hitPlayer = false;
    for (const b of s.oballs) {
      if (s.safe === 0 && g.hit(b, p)) {
        b.gone = true;
        hitPlayer = true;
        break;
      }
    }
    if (hitPlayer) {
      g.loseLife();
      g.sound("hurt");
      s.safe = 60;
      s.pwet = 30;
      s.oballs = [];
    }
    s.oballs = s.oballs.filter((b) => !b.gone && b.y > g.TOP && b.y < g.H + 10);

    if (g.frame >= 3000) { g.gameOver(); }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const c of CLOUDS) d.rect(c.x, c.y, c.w, c.h, "yellow", { round: 18 });

    const o = s.opp;
    const p = s.p;

    // Gegner (blinkt, wenn nass)
    if (o.wet === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🦉", o.x + o.w / 2, o.y + o.h / 2, 36);
    }
    if (o.wet > 0) d.emoji("💦", o.x + o.w / 2, o.y - 6, 20);

    // Spieler (blinkt nach Treffer)
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🦆", p.x + p.w / 2, p.y + p.h / 2, 36);
    }
    if (s.pwet > 0) d.emoji("💦", p.x + p.w / 2, p.y - 6, 20);

    for (const b of s.pballs) d.circle(b.x, b.y, b.r, "yellow", { line: true });
    for (const b of s.oballs) d.circle(b.x, b.y, b.r, "ink", { line: true });

    // Anzeige: drei Tropfen fuer die Gegner-Lebenspunkte (voll = noch offen, Umriss = schon nass)
    d.text("Gegner", 8, g.TOP + 8, { size: 14, color: "ink", align: "left" });
    for (let i = 0; i < 3; i++) {
      const x = g.W - 30 - i * 26;
      if (i < o.hp) d.emoji("💧", x, g.TOP + 8, 18);
      else d.circle(x, g.TOP + 8, 8, "cream", { line: true });
    }
  }
};

