      o.x = g.clamp(o.x + (input.left ? -3.5 : 0) + (input.right ? 3.5 : 0), 4, g.W - o.w - 4);
      o.y = g.clamp(o.y + (input.up ? -3.5 : 0) + (input.down ? 3.5 : 0), g.TOP + 10, 260);
    }

    // Ballons fliegen
    for (const b of s.pballs) { b.x += b.vx; b.y += b.vy; }
    for (const b of s.oballs) { b.x += b.vx; b.y += b.vy; }

    // Treffer Spieler 1 -> Eule (Spieler 2)
    for (const b of s.pballs) {
      if (!b.gone && g.hit(b, o)) {
        b.gone = true;
        o.hp -= 1;
        o.wet = 30;
        g.addScore(10 * g.level);
        g.sound("pop");
        if (o.hp <= 0) {
          g.addScore(50);
          g.sound("win");
          g.win();
          return;
        }
      }
    }
    s.pballs = s.pballs.filter((b) => !b.gone && b.y > g.TOP && b.y < g.H + 10);

    // Treffer Spieler 2 -> Ente (Spieler 1), nur wenn nicht gerade geschuetzt
    for (const b of s.oballs) {
      if (!b.gone && s.safe === 0 && g.hit(b, p)) {
        b.gone = true;
        s.safe = 60;
        s.pwet = 30;
        g.sound("hurt");
        g.loseLife();
        break;
      }
    }
    s.oballs = s.oballs.filter((b) => !b.gone && b.y > g.TOP && b.y < g.H + 10);

    // Zugwechsel: Wurf per fire oder Zeitablauf
