      p.x = g.clamp(p.x + (input.left ? -3.5 : 0) + (input.right ? 3.5 : 0), 4, g.W - p.w - 4);
      p.y = g.clamp(p.y + (input.up ? -3.5 : 0) + (input.down ? 3.5 : 0), 350, g.H - 40);
    } else {
      o.x = g.clamp(o.x + (input.left ? -3.5 : 0) + (input.right ? 3.5 : 0), 4, g.W - o.w - 4);
      o.y = g.clamp(o.y + (input.up ? -3.5 : 0) + (input.down ? 3.5 : 0), g.TOP + 10, 260);
    }

    // Ballons fliegen
    for (const b of s.pballs) { b.x += b.vx; b.y += b.vy; }
    for (const b of s.oballs) { b.x += b.vx; b.y += b.vy; }

    // Treffer Spieler 1 -> Eule (Spieler 2)
    for (const b of s.pballs) {
      if (!b.gone && g.hit(b, o)) {
        b.gone = true;
        o.hp -= 1;
        o.wet = 30;
        g.addScore(10 * g.level);
        g.sound("pop");
        if (o.hp <= 0) {
          g.addScore(50);
          g.sound("win");
          g.win();
          return;
        }
      }
    }
    s.pballs = s.pballs.filter((b) => !b.gone && b.y > g.TOP && b.y < g.H + 10);

    // Treffer Spieler 2 -> Ente (Spieler 1), nur wenn nicht gerade geschuetzt
    for (const b of s.oballs) {
      if (!b.gone && s.safe === 0 && g.hit(b, p)) {
        b.gone = true;
        s.safe = 60;
        s.pwet = 30;
        g.sound("hurt");
        g.loseLife();
        break;
      }
    }
    s.oballs = s.oballs.filter((b) => !b.gone && b.y > g.TOP && b.y < g.H + 10);

    // Zugwechsel: Wurf per fire oder Zeitablauf
    s.tt += 1;
    const canThrow = s.turn === 0 ? s.pballs.length < MAX_BALLS : s.oballs.length < MAX_BALLS;
    let switchTurn = false;
    if (input.firePressed && canThrow) {
      throwBall(s, g, false);
      switchTurn = true;
    } else if (s.tt >= TURN_LEN) {
      if (canThrow) throwBall(s, g, true);
      switchTurn = true;
    }
    if (switchTurn) {
      s.turn = 1 - s.turn;
      s.tt = 0;
    }

    if (g.frame >= 3000) { g.gameOver(); return; }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const c of CLOUDS) d.rect(c.x, c.y, c.w, c.h, "yellow", { round: 18 });

    const o = s.opp;
    const p = s.p;

    // Spieler 2 (Eule), blinkt wenn nass
    if (o.wet === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🦉", o.x + o.w / 2, o.y + o.h / 2, 36);
    }
    if (o.wet > 0) d.emoji("💦", o.x + o.w / 2, o.y - 6, 20);

    // Spieler 1 (Ente), blinkt nach Treffer
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🦆", p.x + p.w / 2, p.y + p.h / 2, 36);
    }
    if (s.pwet > 0) d.emoji("💦", p.x + p.w / 2, p.y - 6, 20);

    for (const b of s.pballs) d.circle(b.x, b.y, b.r, "yellow", { line: true });
    for (const b of s.oballs) d.circle(b.x, b.y, b.r, "ink", { line: true });

    // Anzeige: wer ist dran
    d.text(s.turn === 0 ? "Spieler 1 ist dran" : "Spieler 2 ist dran", g.W / 2, g.H - 10, { size: 14, color: "ink", align: "center" });

    // Anzeige: Tropfen fuer die Lebenspunkte der Eule (voll = noch offen, Umriss = schon nass)
    d.text("Spieler 2", 8, g.TOP + 8, { size: 14, color: "ink", align: "left" });
    for (let i = 0; i < 3; i++) {
      const x = g.W - 30 - i * 26;
      if (i < o.hp) d.emoji("💧", x, g.TOP + 8, 18);
      else d.circle(x, g.TOP + 8, 8, "cream", { line: true });
    }
  }
};

// Wirft einen Ballon der Figur, die gerade dran ist. auto = true: Zeitablauf, mit leichtem Zielen.
function throwBall(s, g, auto) {
  const p = s.p;
  const o = s.opp;
  const pc = p.x + p.w / 2;
  const oc = o.x + o.w / 2;
  if (s.turn === 0) {
    const vx = auto ? g.clamp((oc - pc) / 120, -1.5, 1.5) : 0;
    s.pballs.push({ x: pc, y: p.y, r: 7, vy: -7, vx: vx, gone: false });
  } else {
    const vx = auto ? g.clamp((pc - oc) / 120, -1.5, 1.5) : 0;
    s.oballs.push({ x: oc, y: o.y + o.h, r: 7, vy: 3 + 0.3 * g.level, vx: vx, gone: false });
  }
  g.sound("shoot");
}

