// Die Formen sind Kuchen-Emojis (je Form ein eigenes), Farbe bleibt bei den vier erlaubten Farben.
// Haekchen h5 (bunte Stuecke) ist nicht machbar: Ersatz sind die unterschiedlichen Kuchen-Emojis.

const COLS = 10, ROWS = 20, CELL = 28, X0 = 40, Y0 = 64;
const EMO = ["🍰", "🧁", "🍩", "🍪", "🥧", "🍫", "🍓"];
