  },

  update(s, input, g) {
    if (s.moveCool > 0) s.moveCool -= 1;
    const p = s.piece;

    // Seitwaerts, Wiederholsperre 6 Frames
    if (s.moveCool === 0) {
      if (input.left && free(s, p.cells, p.x - 1, p.y)) { p.x -= 1; s.moveCool = 6; }
      else if (input.right && free(s, p.cells, p.x + 1, p.y)) { p.x += 1; s.moveCool = 6; }
    }

    // Drehen um 90 Grad, nur wenn frei
    if (input.firePressed) {
      const turned = rotCells(p.cells);
      if (free(s, turned, p.x, p.y)) p.cells = turned;
    }

    // Fallen: mit down alle 2 Frames, sonst Intervall nach Level und Zeit
    const every = input.down ? 2 : Math.max(4, 12 - 2 * (g.level - 1) - Math.floor(g.frame / 600));
    s.fall += 1;
    if (s.fall >= every) {
      s.fall = 0;
      if (free(s, p.cells, p.x, p.y + 1)) p.y += 1;
      else lock(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("yellow");
    d.rect(X0, Y0, COLS * CELL, ROWS * CELL, "cream", { round: 4, line: true });
    for (let c = 1; c < COLS; c++) d.line(X0 + c * CELL, Y0, X0 + c * CELL, Y0 + ROWS * CELL, "ink", 1);
    for (let r = 1; r < ROWS; r++) d.line(X0, Y0 + r * CELL, X0 + COLS * CELL, Y0 + r * CELL, "ink", 1);

