    for (const c of p.cells) {
      const x = p.x + c.x, y = p.y + c.y;
      if (y >= 0) d.emoji(EMO[p.kind - 1], X0 + x * CELL + CELL / 2, Y0 + y * CELL + CELL / 2, 24);
    }
