  }
};

function emptyGrid() {
  const grid = [];
  for (let r = 0; r < ROWS; r++) grid.push(emptyRow());
  return grid;
}

function emptyRow() {
  const row = [];
  for (let c = 0; c < COLS; c++) row.push(0);
  return row;
}

function toCells(pairs) {
  const out = [];
  for (const pr of pairs) out.push({ x: pr[0], y: pr[1] });
  return out;
}

function rotCells(cells) {
  const out = [];
  for (const c of cells) out.push({ x: 0 - c.y, y: c.x });
  return out;
}

// Zelle frei: innerhalb der Spalten, nicht unter dem Boden, nicht belegt (oberhalb des Feldes ist frei)
function free(s, cells, px, py) {
  for (const c of cells) {
    const x = px + c.x, y = py + c.y;
    if (x < 0 || x >= COLS || y >= ROWS) return false;
    if (y >= 0 && s.grid[y][x] !== 0) return false;
  }
  return true;
}

function spawn(s, g) {
  const kind = s.nextKind;
  s.nextKind = g.randInt(1, 7);
  s.piece = { kind: kind, cells: toCells(SHAPES[kind - 1]), x: 3, y: 0 };
  s.fall = 0;
  if (!free(s, s.piece.cells, s.piece.x, s.piece.y)) {
    g.sound("hurt");
    g.loseLife();
    s.grid = emptyGrid();
  }
}

function lock(s, g) {
  const p = s.piece;
  for (const c of p.cells) {
    const x = p.x + c.x, y = p.y + c.y;
    if (y >= 0 && y < ROWS && x >= 0 && x < COLS) s.grid[y][x] = p.kind;
  }
  g.sound("hit");
  g.addScore(4);

  const n = clearRows(s);
  if (n > 0) {
    g.addScore(100 * n * n);
    g.sound("coin");
    const before = Math.floor(s.lines / 5);
    s.lines += n;
    const after = Math.floor(s.lines / 5);
    if (after > before) {
      for (let k = before; k < after; k++) g.nextLevel();
      g.sound("level");
    }
  }
  spawn(s, g);
}

function clearRows(s) {
  let n = 0;
  const keep = [];
  for (const row of s.grid) {
    let full = true;
    for (const v of row) if (v === 0) full = false;
    if (full) n += 1;
    else keep.push(row);
  }
  for (let i = 0; i < n; i++) keep.unshift(emptyRow());
  s.grid = keep;
  return n;
}

