// Hunderter-Wuerfeln (nur Spiel-API, keine Importe): Schweinchen-Wuerfeln fuer 4 Personen am selben Geraet.
// Eine 1 kostet die Runde. Wer zuerst 100 Punkte hat, gewinnt.
// Hinweis: Die Laufzeit-Anzeige oben zeigt nur die Punkte der aktuellen Person. Die vier Staende werden im Feld gemalt.
const PIPS = [
  [],
  [[0, 0]],
  [[-35, -35], [35, 35]],
  [[-35, -35], [0, 0], [35, 35]],
  [[-35, -35], [35, -35], [-35, 35], [35, 35]],
  [[-35, -35], [35, -35], [0, 0], [-35, 35], [35, 35]],
  [[-35, -35], [-35, 0], [-35, 35], [35, -35], [35, 0], [35, 35]]
];

export default {
  title: "Hunderter-Wuerfeln",
  controls: ["fire", "down"],
  lives: 3,

  init(g) {
    return {
      scores: [0, 0, 0, 0],
      cur: 0,
      turn: 0,
      die: 1,
      rolling: 0,
      msg: "",
      msgT: 0,
      idle: 0,
      over: false,
      winner: -1,
      downPrev: false,
      downs: 0
    };
  },

  update(s, input, g) {
    if (s.over) return;
    if (g.frame >= 3000) { s.over = true; g.gameOver(); return; }

    if (s.msgT > 0) s.msgT -= 1;
    const active = input.fire || input.down || input.firePressed;
    if (active) s.idle = 0; else s.idle += 1;

    // Rollanimation und Ergebnis
    if (s.rolling > 0) {
      s.rolling -= 1;
      if (s.rolling > 0) {
        if (s.rolling % 4 === 0) s.die = g.randInt(1, 6);
      } else {
        finishRoll(s, g);
      }
    }

    // Wuerfeln (Taste fire neu gedrueckt oder Tippen)
    if (input.firePressed) {
      if (s.rolling === 0) {
        s.rolling = 30;
