    d.rect(110 + off, 260, 140, 140, "cream", { round: 20, shadow: true, line: true });
    const cx = 180 + off, cy = 330;
    const pips = PIPS[s.die] || [];
    for (const p of pips) d.circle(cx + p[0], cy + p[1], 12, "ink");

    d.text("Runde: " + s.turn, 180, 420, { size: 24, color: "ink", align: "center" });

    // Wer ist dran (gross)
    if (s.winner < 0) {
      d.text("Spieler " + (s.cur + 1) + " ist dran", 180, 462, { size: 26, color: "ink", align: "center" });
    }

    // Meldung und Hilfe
    if (s.msgT > 0 && s.msg) d.text(s.msg, 180, 530, { size: 18, color: "red", align: "center" });
    d.text("Nach 40 Wuerfen gewinnt der hoechste Stand. Oben: nur aktuelle Person.", 180, 575, { size: 12, color: "ink", align: "center" });
    d.text("Tippen = wuerfeln, Pfeil unten = sichern", 180, 600, { size: 16, color: "ink", align: "center" });

    // Siegesanzeige
    if (s.winner >= 0) {
      d.rect(30, 250, 300, 170, "yellow", { round: 16, line: true });
      d.text("Spieler " + (s.winner + 1) + " gewinnt!", 180, 290, { size: 28, color: "ink", align: "center" });
      d.emoji("🐸", 180, 370, 56);
