// Gummibaerchen-Schaetzen (nur Spiel-API, keine Importe): Im Glas liegen Baerchen. Du schaetzt die Anzahl,
// der Roboter schaetzt auch. Wer naeher dran ist, gewinnt die Runde.
const COLS = ["yellow", "red", "ink", "cream"];

export default {
  title: "Gummibärchen-Schätzen",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      phase: "look", n: 0, bears: [], guess: 50, botGuess: 0, timer: 0,
      round: 0, wins: 0, lastWin: false, msg: "", hrep: 0, vrep: 0
    };
    newRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "look") {
      s.timer += 1;
      if (input.firePressed || s.timer >= lookTime(g)) { s.phase = "guess"; s.timer = 0; }
      return;
    }

    if (s.phase === "guess") {
      // Links/rechts: +-1, bei Halten alle 4 Frames
      const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
      if (dx !== 0) {
        if (s.hrep <= 0) { s.guess += dx; s.hrep = 3; }
        s.hrep -= 1;
      } else {
        s.hrep = 0;
      }
      // Hoch/runter: +-10, bei Halten alle 8 Frames
      const dv = (input.up ? 10 : 0) - (input.down ? 10 : 0);
      if (dv !== 0) {
        if (s.vrep <= 0) { s.guess += dv; s.vrep = 7; }
        s.vrep -= 1;
      } else {
        s.vrep = 0;
      }
      s.guess = g.clamp(s.guess, 1, 200);
      s.timer += 1;
      if (input.firePressed || s.timer >= 600) confirmGuess(s, g);
      return;
    }

    // reveal
    s.timer += 1;
    if (s.timer < 150) return;
    if (s.wins >= 5) { g.win(); return; }
    if (s.lastWin) { g.nextLevel(); g.sound("level"); }
    s.round += 1;
    newRound(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
