      }
      s.guess = g.clamp(s.guess, 1, 200);
      s.timer += 1;
      if (input.firePressed || s.timer >= 600) confirmGuess(s, g);
      return;
    }

    // reveal: Mindestwartezeit 30 Frames, danach startet fire die naechste Runde
    s.timer += 1;
    if (s.timer < 30) return;
    if (!input.firePressed) return;
    if (s.wins >= 5) { g.win(); return; }
    if (s.lastWin) { g.nextLevel(); g.sound("level"); }
    s.round += 1;
    newRound(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Gummibärchen-Schätzen", 180, 80, { size: 22, color: "ink", align: "center" });
    d.text("Runde " + (s.round + 1) + "   Level " + g.level, 180, 115, { size: 14, color: "ink", align: "center" });
    d.rect(80, 150, 200, 260, "cream", { round: 20, line: true });

    if (s.phase === "look") {
      for (const b of s.bears) d.circle(b.x, b.y, 5, COLS[b.c], { line: true });
      d.text("Schau genau!", 180, 440, { size: 20, color: "ink", align: "center" });
      d.text("fire oder Pfeil = weiter", 180, 540, { size: 16, color: "ink", align: "center" });
      d.emoji("🤖", 140, 590, 30);
      d.text("Roboter wartet...", 165, 590, { size: 16, color: "ink", align: "left" });
    } else if (s.phase === "guess") {
      d.text("?", 180, 300, { size: 64, color: "ink", align: "center" });
      d.emoji("🐻", 40, 470, 30);
      d.text("◀", 115, 470, { size: 28, color: "ink", align: "center" });
      d.text(String(s.guess), 180, 470, { size: 48, color: "ink", align: "center" });
      d.text("▶", 245, 470, { size: 28, color: "ink", align: "center" });
      d.text("fire = bestätigen", 180, 540, { size: 16, color: "ink", align: "center" });
      d.emoji("🤖", 140, 590, 30);
      d.text("Roboter schätzt auch!", 165, 590, { size: 16, color: "ink", align: "left" });
    } else {
      d.text(String(s.n), 180, 300, { size: 64, color: "ink", align: "center" });
      d.text(s.msg, 180, 440, { size: 22, color: "ink", align: "center" });
      d.text("Du: " + s.guess, 180, 470, { size: 20, color: "ink", align: "center" });
      d.text("Roboter: " + s.botGuess, 180, 505, { size: 20, color: "ink", align: "center" });
      // Gut sichtbarer Hinweis fuer den Start der naechsten Runde
      d.rect(40, 518, 280, 44, "red", { round: 12, shadow: true, line: true });
      d.text("fire = neue Runde", 180, 547, { size: 22, color: "cream", align: "center" });
      d.emoji("🤖", 140, 590, 30);
      d.text("Ich habe " + s.botGuess + " geschätzt.", 165, 590, { size: 16, color: "ink", align: "left" });
    }
  }
};

function lookTime(g) {
  return Math.max(60, 150 - g.level * 20);
}

function newRound(s, g) {
  s.n = g.randInt(30, 120);
  s.bears = [];
  for (let i = 0; i < s.n; i++) {
    s.bears.push({ x: g.randInt(86, 274), y: g.randInt(158, 402), c: g.randInt(0, 3) });
  }
  s.phase = "look";
  s.timer = 0;
  s.guess = 50;
  s.botGuess = 0;
  s.hrep = 0;
  s.vrep = 0;
  s.msg = "";
  s.lastWin = false;
}

function confirmGuess(s, g) {
  const dev = g.level >= 2 ? Math.floor(s.n / (3 + g.level * 2)) : Math.floor(s.n / 3);
  s.botGuess = Math.max(1, s.n + g.randInt(-dev, dev));
  s.phase = "reveal";
  s.timer = 0;
  const dp = Math.abs(s.guess - s.n);
  const db = Math.abs(s.botGuess - s.n);
  g.addScore(5);
  if (dp <= db) {
    s.lastWin = true;
    s.wins += 1;
    g.addScore(10 + Math.max(0, 50 - dp));
    g.sound("win");
    s.msg = "Du gewinnst!";
  } else {
    s.lastWin = false;
    s.msg = "Roboter gewinnt";
    g.sound("hurt");
    g.loseLife();
  }
}

// Apfel-Schlange (nur Spiel-API, keine Importe). Schlange auf einem Raster, Aepfel machen sie laenger.
// Wand oder eigener Koerper kostet ein Leben. Steuerung: Pfeiltasten, Steuerkreuz oder Wischen.
const CELL = 20, COLS = 18, ROWS = 29, Y0 = 56;

export default {
  title: "Apfel-Schlange",
  controls: ["up", "down", "left", "right"],
  lives: 3,

  init(g) {
    const s = { body: [], dir: { x: 1, y: 0 }, next: { x: 1, y: 0 }, apple: { x: 0, y: 0 }, wait: 0, eaten: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    const want = input.up ? { x: 0, y: -1 } : input.down ? { x: 0, y: 1 } : input.left ? { x: -1, y: 0 } : input.right ? { x: 1, y: 0 } : null;
    if (want && !(want.x === -s.dir.x && want.y === -s.dir.y)) s.next = { x: want.x, y: want.y };

    s.wait += 1;
    if (s.wait < Math.max(4, 9 - g.level)) return;
    s.wait = 0;

    s.dir = { x: s.next.x, y: s.next.y };
    const head = { x: s.body[0].x + s.dir.x, y: s.body[0].y + s.dir.y };
    const crash = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS ||
      s.body.some((p) => p.x === head.x && p.y === head.y);

    if (crash) {
      g.sound("hurt");
      g.loseLife();
      reset(s, g);
      return;
    }

    s.body.unshift(head);
    if (head.x === s.apple.x && head.y === s.apple.y) {
      g.addScore(10);
      g.sound("coin");
      s.eaten += 1;
      if (s.eaten % 5 === 0) { g.nextLevel(); g.sound("level"); }
      placeApple(s, g);
    } else {
      s.body.pop();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    s.body.forEach((p, i) => {
      d.rect(p.x * CELL + 1, Y0 + p.y * CELL + 1, CELL - 2, CELL - 2, i === 0 ? "red" : "ink", { round: 6 });
    });
  }
};

function reset(s, g) {
  s.body = [{ x: 6, y: 14 }, { x: 5, y: 14 }, { x: 4, y: 14 }];
  s.dir = { x: 1, y: 0 };
  s.next = { x: 1, y: 0 };
  s.wait = 0;
  placeApple(s, g);
}

function placeApple(s, g) {
  for (let tries = 0; tries < 200; tries++) {
    const a = { x: g.randInt(0, COLS - 1), y: g.randInt(0, ROWS - 1) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = a; return; }
  }
}

