// Autobahn-Flitzer (nur Spiel-API, keine Importe): roter Sportwagen auf 4 Spuren, Ueberholen gibt Punkte,
// Beruehrung kostet ein Leben. Hoch/Runter fuer Gas und Bremse. Mit der Zeit wird es schneller und dichter.
const LANES = [67.5, 142.5, 217.5, 292.5];

export default {
  title: "Autobahn-Flitzer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return {
      me: { x: 180 - 17, y: 520, w: 34, h: 60 },
      speed: 5,
      scroll: 0,
      cars: [],
      spawn: 0,
      safe: 0,
      passed: 0
    };
  },

  update(s, input, g) {
    const me = s.me;

    // Lenken, Fahrbahnrand
    if (input.left) me.x -= 4;
    if (input.right) me.x += 4;
    me.x = g.clamp(me.x, 34, 296);

    // Tempo: Gas, Bremse, sonst langsam zurueck auf 5
    if (input.up) s.speed = Math.min(9, s.speed + 0.1);
    else if (input.down) s.speed = Math.max(3, s.speed - 0.15);
    else s.speed += (5 - s.speed) * 0.02;

    // Fahrbahnmarkierungen scrollen
    s.scroll = (s.scroll + s.speed) % 60;

    // Punkte fuers Dabeisein
    if (g.frame % 30 === 0) g.addScore(1);

    // Verkehr erzeugen
    s.spawn -= 1;
    if (s.spawn <= 0) {
      s.spawn = Math.max(25, 70 - 6 * g.level) + g.randInt(0, 20);
      const x = LANES[g.randInt(0, 3)] - 17;
      const busy = s.cars.some((c) => Math.abs(c.x - x) < 20 && c.y < 100);
      if (!busy && s.cars.length < 8) {
        s.cars.push({
          x: x,
          y: -70,
          w: 34,
          h: 60,
          v: 2.5 + g.random() * 1.5 + 0.3 * g.level,
          drift: g.random() < 0.35, // manche Autos ziehen langsam zur Spur des Spielers
          counted: false
        });
      }
    }

    // Autos bewegen sich
    for (const c of s.cars) {
      c.y += Math.max(0.8, s.speed - c.v + 2);
      if (c.drift && c.y < me.y - 60) {
        c.x += g.clamp(me.x - c.x, -0.6, 0.6);
      }
    }

    // Kollision
    if (s.safe > 0) s.safe -= 1;
    if (s.safe === 0) {
      const pr = { x: me.x + 4, y: me.y + 4, w: me.w - 8, h: me.h - 8 };
      const i = s.cars.findIndex((c) => g.hit(pr, { x: c.x + 4, y: c.y + 4, w: c.w - 8, h: c.h - 8 }));
      if (i >= 0) {
        s.cars.splice(i, 1);
        s.safe = 90;
        g.sound("hurt");
        g.loseLife();
        return;
      }
    }

    // Ueberholt: Auto ist unter dem Spieler vorbei
    for (const c of s.cars) {
      if (!c.counted && c.y > me.y + me.h) {
        c.counted = true;
        s.passed += 1;
        g.addScore(10 * g.level);
        g.sound("coin");
        if (s.passed % 8 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }

    // Autos unten aus dem Feld entfernen
    s.cars = s.cars.filter((c) => c.y <= 660);
  },

  draw(s, d, g) {
    d.clear("ink");

    // Fahrbahnrand
    d.line(30, 0, 30, g.H, "cream", 3);
    d.line(330, 0, 330, g.H, "cream", 3);

    // Gestrichelte Spurlinien
    const off = s.scroll % 60;
    for (const x of [105, 180, 255]) {
      for (let y = off - 60; y < g.H; y += 60) d.line(x, y, x, y + 30, "yellow", 3);
    }

    // Andere Autos
    for (const c of s.cars) {
      d.rect(c.x, c.y, c.w, c.h, "cream", { round: 8, line: true });
      d.emoji("🚗", c.x + c.w / 2, c.y + c.h / 2, 30);
    }

    // Spieler (blinkt waehrend Schutzzeit)
    const me = s.me;
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.rect(me.x, me.y, me.w, me.h, "red", { round: 10, shadow: true, line: true });
      d.rect(me.x + 6, me.y + 14, me.w - 12, 14, "cream");
      d.circle(me.x + 8, me.y + 5, 3, "yellow");
      d.circle(me.x + me.w - 8, me.y + 5, 3, "yellow");
    }

    // Tempoanzeige
    d.text(Math.round(s.speed * 30) + " km/h", 340, 620, { size: 16, color: "cream", align: "right" });
  }
};

