// Pizza-Ausbruch (nur Spiel-API, keine Importe). Eine Pizza fliegt, prallt an Waenden und am Schlaeger ab
// und bricht Steine aus der Mauer. Die Steine sind eigene Bausteine (Rechtecke mit Noppen), kein Lego.
const PAD_Y = 600, BALL_Y = 590, BALL_R = 9, STUCK = 40;
const COLORS = ["yellow", "red", "ink", "cream"];

export default {
  title: "Pizza-Ausbruch",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return {
      paddle: { x: 140, y: PAD_Y, w: 80, h: 14 },
      ball: { x: 180, y: BALL_Y, r: BALL_R, vx: 0, vy: 0 },
      bricks: wall(g),
      stuck: STUCK
    };
  },

  update(s, input, g) {
    const p = s.paddle;
    if (input.left) p.x -= 5;
    if (input.right) p.x += 5;
    p.x = g.clamp(p.x, 0, g.W - p.w);

    const b = s.ball;

    // Pizza klebt auf dem Schlaeger, dann startet sie automatisch
    if (s.stuck > 0) {
      s.stuck -= 1;
      b.x = p.x + p.w / 2;
      b.y = BALL_Y;
      b.vx = 0;
      b.vy = 0;
      if (s.stuck > 0) return;
      launch(b, g);
    }

    b.x += b.vx;
    b.y += b.vy;

    // Waende und Decke
    if (b.x - b.r < 0) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x + b.r > g.W) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y - b.r < g.TOP) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Schlaeger
    if (b.vy > 0 && circleRect(b, p)) {
      b.vy = -Math.abs(b.vy);
      b.vx = g.clamp((b.x - (p.x + p.w / 2)) / 40 * 5, -5, 5);
      b.y = p.y - b.r;
      g.sound("jump");
    }

    // Steine: nur die erste Kollision je Frame
    let hit = -1;
    for (let i = 0; i < s.bricks.length; i++) {
      if (circleRect(b, s.bricks[i])) { hit = i; break; }
    }
    if (hit >= 0) {
      s.bricks.splice(hit, 1);
      b.vy = -b.vy;
      g.addScore(10 * g.level);
      g.sound("pop");
    }

    // Geschwindigkeit begrenzen, nie waagerecht stecken bleiben
    b.vx = g.clamp(b.vx, -8, 8);
    b.vy = g.clamp(b.vy, -8, 8);
    if (Math.abs(b.vy) < 2) b.vy = b.vy < 0 ? -2 : 2;

    // Unten herausgefallen
    if (b.y > g.H + 20) {
      g.sound("hurt");
      g.loseLife();
      s.stuck = STUCK;
      resetBall(s);
      return;
    }

