}

// Felsen-Funker (nur Spiel-API, keine Importe): Raumschiff dreht und fliegt, schiesst Strahlen auf Felsbrocken.
// Grosse Felsen zerbrechen in kleinere. Beruehrung kostet ein Leben. Alles wrappt an den Raendern.
const TOP = 48;
const RADIUS = { 3: 34, 2: 22, 1: 12 };
const SCORE = { 3: 20, 2: 50, 1: 100 };

export default {
  title: "Felsen-Funker",
  controls: ["left", "right", "up", "fire"],
  lives: 3,

  init(g) {
    const s = {
      ship: { x: 180, y: 344, angle: -90, vx: 0, vy: 0, r: 14 },
      shots: [],
      rocks: [],
      safe: 60,
      cool: 0,
      wave: 1
    };
    spawnWave(s, g, Math.min(8, 3 + g.level));
    return s;
  },

  update(s, input, g) {
    const ship = s.ship;

    // Schutzzeit nach Treffer
    if (s.safe > 0) s.safe -= 1;

    // Drehen
    if (input.left) ship.angle -= 4;
    if (input.right) ship.angle += 4;
    if (ship.angle < -180) ship.angle += 360;
    if (ship.angle > 180) ship.angle -= 360;

    // Schub
    if (input.up) {
      ship.vx += g.cos(ship.angle) * 0.15;
      ship.vy += g.sin(ship.angle) * 0.15;
    }
    const sp = Math.sqrt(ship.vx * ship.vx + ship.vy * ship.vy);
    if (sp > 5) { ship.vx = ship.vx * 5 / sp; ship.vy = ship.vy * 5 / sp; }
    ship.vx *= 0.995;
    ship.vy *= 0.995;
    ship.x += ship.vx;
    ship.y += ship.vy;
    wrap(ship, g);

    // Schiessen
    if (s.cool > 0) s.cool -= 1;
    if ((input.firePressed || input.fire) && s.cool === 0 && s.shots.length < 5) {
      const c = g.cos(ship.angle);
      const sn = g.sin(ship.angle);
      s.shots.push({
        x: ship.x + c * 16,
        y: ship.y + sn * 16,
        vx: c * 8 + ship.vx * 0.3,
        vy: sn * 8 + ship.vy * 0.3,
        life: 50,
        done: false
      });
      s.cool = 10;
      g.sound("shoot");
    }

    // Schuesse bewegen und altern
    for (const shot of s.shots) {
      shot.x += shot.vx;
      shot.y += shot.vy;
      wrap(shot, g);
      shot.life -= 1;
    }
    s.shots = s.shots.filter((sh) => sh.life > 0 && !sh.done);

    // Felsen bewegen
    for (const rock of s.rocks) {
      rock.x += rock.vx;
      rock.y += rock.vy;
      wrap(rock, g);
    }

    // Schuss gegen Fels: Fels zerbricht in zwei kleinere (ausser kleinste)
    const kids = [];
    for (const shot of s.shots) {
      for (const rock of s.rocks) {
        if (!rock.dead && g.hit({ x: shot.x, y: shot.y, r: 3 }, rock)) {
          rock.dead = true;
          shot.done = true;
          g.addScore(SCORE[rock.size] * g.level);
          g.sound("pop");
          if (rock.size > 1) {
            kids.push(newRock(g, rock.x, rock.y, rock.size - 1, 1.25));
            kids.push(newRock(g, rock.x, rock.y, rock.size - 1, 1.25));
          }
          break;
        }
      }
    }
    s.rocks = s.rocks.filter((r) => !r.dead).concat(kids);

    // Schiff gegen Fels
    if (s.safe === 0) {
      for (const rock of s.rocks) {
        if (g.hit({ x: ship.x, y: ship.y, r: 12 }, rock)) {
          g.sound("hurt");
          g.loseLife();
          resetShip(s);
          return;
        }
      }
    }

    // Zusaetzlicher Fels ab Frame 1800 alle 300 Frames
    if (g.frame >= 1800 && g.frame % 300 === 0) {
      const p = edgePoint(g);
      s.rocks.push(newRock(g, p.x, p.y, 2, 1));
    }

    // Welle geraeumt: naechstes Level
    if (s.rocks.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.wave += 1;
      spawnWave(s, g, Math.min(8, 3 + g.level));
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    for (const rock of s.rocks) {
      d.circle(rock.x, rock.y, rock.r, "yellow", { line: true });
      d.emoji("🪨", rock.x, rock.y, rock.r * 2);
    }

    for (const shot of s.shots) d.circle(shot.x, shot.y, 3, "red");

    const ship = s.ship;
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🚀", ship.x, ship.y, 30);
      d.line(ship.x, ship.y, ship.x + g.cos(ship.angle) * 16, ship.y + g.sin(ship.angle) * 16, "red", 3);
    }
  }
};

// Felsen mit Startgeschwindigkeit in zufaellige Richtung
function newRock(g, x, y, size, boost) {
  const sp = ((0.4 + 0.15 * g.level) + g.random() * 0.7) * boost;
  const a = g.randInt(0, 359);
  return { x: x, y: y, vx: g.cos(a) * sp, vy: g.sin(a) * sp, size: size, r: RADIUS[size], dead: false };
}

// Neue Welle: n grosse Felsen, mindestens 120 px vom Schiff entfernt
function spawnWave(s, g, n) {
  s.rocks = [];
  for (let i = 0; i < n; i++) {
    let p = edgePoint(g);
    for (let t = 0; t < 60 && g.dist(p, s.ship) < 120; t++) p = edgePoint(g);
    s.rocks.push(newRock(g, p.x, p.y, 3, 1));
  }
}

// Zufaelliger Punkt am Feldrand
function edgePoint(g) {
  const side = g.randInt(0, 3);
  const h = g.H - g.TOP;
  if (side === 0) return { x: 0, y: g.TOP + g.random() * h };
  if (side === 1) return { x: g.W, y: g.TOP + g.random() * h };
  if (side === 2) return { x: g.random() * g.W, y: g.TOP };
  return { x: g.random() * g.W, y: g.H };
}

// Schiff zurueck in die Mitte, kurz unverwundbar
function resetShip(s) {
  s.ship.x = 180;
  s.ship.y = 344;
  s.ship.vx = 0;
  s.ship.vy = 0;
  s.safe = 90;
}

// Randwrap: links/rechts auf Feldbreite, oben/unten im Spielbereich TOP..H
function wrap(o, g) {
  const h = g.H - TOP;
  if (o.x < 0) o.x += g.W;
  else if (o.x >= g.W) o.x -= g.W;
  if (o.y < TOP) o.y += h;
  else if (o.y >= g.H) o.y -= h;
}

