versuche.code:
// Dach-Katze (nur Spiel-API, keine Importe). Die Katze springt von Dach zu Dach, sammelt Fische
// und weicht Kraehen aus. Ziel: der Fisch ganz oben. Haken h4 (echte Graeten) ist nicht machbar,
// deshalb sind es Fisch-Emojis 🐟 als Ersatz; das zeigt das Spiel auch an.
const GRAV = 0.5, JUMP = -10.5, FLOOR = 610, ROOF_H = 16;

export default {
  title: "Dach-Katze",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 30, y: FLOOR - 30, w: 22, h: 30, vx: 0, vy: 0, ground: true },
      roofs: [], fish: [], crows: [],
      goal: { x: 0, y: 0, w: 24, h: 30 },
      safe: 0, lvlAt: 0
    };
    build(s, g);
    return s;
  },

  update(s, input, g) {
    const me = s.me;
    me.vx = input.left ? -3 : input.right ? 3 : 0;
    if (input.up && me.ground) { me.vy = JUMP; me.ground = false; g.sound("jump"); }
    me.vy = Math.min(me.vy + GRAV, 12);
    const oldBottom = me.y + me.h;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);
    me.y += me.vy;
    me.ground = false;
    if (me.vy >= 0) {
      for (const p of s.roofs) {
        const over = me.x + me.w > p.x && me.x < p.x + p.w;
        if (over && oldBottom <= p.y && me.y + me.h >= p.y) { me.y = p.y - me.h; me.vy = 0; me.ground = true; }
      }
    }
    if (s.safe > 0) s.safe -= 1;

    for (const c of s.crows) {
      c.x += c.vx;
      if (c.x < c.min || c.x + c.w > c.max) c.vx = -c.vx;
      c.x = g.clamp(c.x, c.min, c.max - c.w);
    }
    if (s.safe === 0 && s.crows.some((c) => g.hit(me, c))) {
      g.sound("hurt"); g.loseLife(); respawn(s); return;
    }

    for (const f of s.fish) {
      if (!f.got && g.hit(me, f)) { f.got = true; g.addScore(10); g.sound("coin"); }
    }
    s.fish = s.fish.filter((f) => !f.got);

    if (g.hit(me, s.goal)) { g.addScore(50); g.nextLevel(); g.sound("level"); build(s, g); return; }

    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); respawn(s); return; }

    // Sicherung: zu lange ohne Levelaufstieg endet die Runde
    if (g.frame - s.lvlAt > 3000) { g.gameOver(); }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.circle(60, 80, 14, "yellow");
    d.circle(300, 110, 9, "yellow");
    d.circle(200, 70, 5, "yellow");
    d.text("Fische statt Graeten (Ersatz)", g.W / 2, 62, { size: 12, color: "ink", align: "center" });

    for (const r of s.roofs) {
      d.rect(r.x, r.y, r.w, r.h, "yellow", { round: 8, shadow: true, line: true });
      if (r.row > 0) d.rect(r.x + r.w - 24, r.y - 14, 10, 14, "ink");
    }
    for (const f of s.fish) d.emoji("🐟", f.x + 9, f.y + 9, 24);
    d.emoji("🐠", s.goal.x + 12, s.goal.y + 15, 30);
    for (const c of s.crows) d.emoji("🐦", c.x + c.w / 2, c.y + c.h / 2, 26);

    const me = s.me;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) d.emoji("🐱", me.x + 11, me.y + 15, 34);
  }
};

function build(s, g) {
  s.lvlAt = g.frame;
  s.roofs = [{ x: 0, y: FLOOR, w: g.W, h: 30, row: 0 }];
  s.fish = [];
  s.crows = [];
  let cx = 60;
  for (let row = 1; row <= 5; row++) {
    const w = g.randInt(90, 140), y = FLOOR - row * 92;
    cx = g.clamp(cx + g.randInt(-110, 110), w / 2 + 4, g.W - w / 2 - 4);
    s.roofs.push({ x: cx - w / 2, y, w, h: ROOF_H, row });
    if (row < 5) s.fish.push({ x: cx - 9, y: y - 20, w: 18, h: 18, got: false });
  }
  const top = s.roofs[s.roofs.length - 1];
  s.goal = { x: top.x + top.w / 2 - 12, y: top.y - 30, w: 24, h: 30 };

  // Boden-Krähe: laeuft ueber die ganze Breite
  s.crows.push({ x: 200, y: FLOOR - 22, w: 26, h: 22, vx: -1.2, min: 0, max: g.W });

  // Krähen auf den Dächern ab Reihe 2, je Level eine mehr (max. 4)
  const roofCrows = Math.min(g.level, 4);
  const speed = 0.8 + 0.2 * g.level;
  for (let i = 0; i < roofCrows; i++) {
    const r = s.roofs[2 + (i % 4)];
    s.crows.push({ x: r.x, y: r.y - 22, w: 26, h: 22, vx: i % 2 === 0 ? speed : -speed, min: r.x, max: r.x + r.w });
  }
  respawn(s);
}

function respawn(s) {
  s.me.x = 30; s.me.y = FLOOR - 30; s.me.vx = 0; s.me.vy = 0; s.me.ground = true; s.safe = 60;
}

