// Ballon-Duell (nur Spiel-API, keine Importe): Du fliegst als Pinguin unten, der Roboter oben.
// Wasserballons treffen, bis der Gegner dreimal nass ist. Seine Ballons machen dich nass. Kein Blut, keine Gewalt.
export default {
  title: "Ballon-Duell",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    return {
      me: { x: 163, y: 540, w: 34, h: 34 },
      foe: { x: 161, y: 90, w: 38, h: 38, dir: 1, wet: 0, wobble: 0 },
      mine: [],
      theirs: [],
      cool: 0,
      foeCool: Math.max(30, 70 - 8 * g.level),
      safe: 0,
      splash: []
    };
  },

  update(s, input, g) {
    const me = s.me;
    const foe = s.foe;

    // Spieler bewegen
    if (input.left) me.x -= 4;
    if (input.right) me.x += 4;
    if (input.up) me.y -= 4;
    if (input.down) me.y += 4;
    me.x = g.clamp(me.x, 4, g.W - me.w - 4);
    me.y = g.clamp(me.y, 380, 600);

    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;

    // Eigene Wasserballons werfen
    if ((input.firePressed || input.fire) && s.cool === 0 && s.mine.length < 3) {
      s.mine.push({ x: me.x + 17, y: me.y, r: 7 });
      s.cool = 15;
      g.sound("shoot");
    }
    for (const b of s.mine) b.y -= 8;
    s.mine = s.mine.filter((b) => b.y > g.TOP && b.x > -10 && b.x < g.W + 10);

    // Gegner bewegen
    const speed = 1.5 + 0.4 * g.level;
    foe.x += foe.dir * speed;
    if (foe.x < 4 || foe.x > g.W - foe.w - 4) {
      foe.dir = -foe.dir;
      foe.x = g.clamp(foe.x, 4, g.W - foe.w - 4);
    }
    if (g.random() < 0.01) foe.dir = -foe.dir;
    foe.wobble += 1;
    foe.y = 71 + 30 * g.sin(g.frame * 3);
    const fx = foe.x + foe.w / 2;
    const fy = foe.y + foe.h / 2;

    // Gegner wirft Ballons nach unten
    s.foeCool -= 1;
    if (s.foeCool <= 0) {
      s.foeCool = Math.max(30, 70 - 8 * g.level);
      let vx = 0;
      if (g.random() < 0.6) vx = g.clamp((me.x + 17 - fx) * 0.02, -1.5, 1.5);
      s.theirs.push({ x: fx, y: fy + 22, vx: vx, r: 7 });
    }
    const fallSpeed = 3 + 0.5 * g.level;
    for (const b of s.theirs) {
      b.x += b.vx;
      b.y += fallSpeed;
    }
    s.theirs = s.theirs.filter((b) => b.y < g.H + 10 && b.x > -20 && b.x < g.W + 20);

    // Eigene Ballons treffen den Gegner
    let hits = 0;
    s.mine = s.mine.filter((b) => {
      if (g.dist({ x: b.x, y: b.y }, { x: fx, y: fy }) < 25) {
        hits += 1;
        return false;
      }
      return true;
    });
    if (hits > 0) {
      foe.wet += hits;
      g.addScore(10 * g.level * hits);
      g.sound("pop");
      s.splash.push({ x: fx, y: fy, t: 30 });
    }
    if (foe.wet >= 3) {
      g.addScore(30 * g.level);
      g.nextLevel();
      g.sound("level");
      foe.wet = 0;
      s.mine = [];
      s.theirs = [];
    }

    // Gegnerballons treffen den Spieler
    if (s.safe === 0) {
      const pcx = me.x + 17;
      const pcy = me.y + 17;
      const hit = s.theirs.some((b) => g.dist({ x: b.x, y: b.y }, { x: pcx, y: pcy }) < 22);
      if (hit) {
        s.theirs = [];
        s.safe = 60;
        s.splash.push({ x: pcx, y: pcy, t: 30 });
        g.sound("hurt");
        g.loseLife();
      }
    }

    // Splash-Tropfen altern
    for (const p of s.splash) p.t -= 1;
    s.splash = s.splash.filter((p) => p.t > 0);
  },

  draw(s, d, g) {
    d.clear("cream");

    // Gestrichelte Mittellinie
    for (let x = 0; x < g.W; x += 24) d.line(x, 330, x + 12, 330, "yellow", 3);

    // Deko-Wolken
    const cloudY = [200, 450, 250];
    for (let i = 0; i < 3; i++) {
      const cx = ((g.frame * 0.3 + i * 140) % 400) - 20;
      d.emoji("☁️", cx, cloudY[i], 40);
    }

    // Anzeige der Nass-Treffer des Gegners (3 Kreise)
    for (let i = 0; i < 3; i++) {
      const cx = 20 + i * 20;
      if (i < s.foe.wet) d.circle(cx, 56, 6, "yellow", { line: true });
      else d.circle(cx, 56, 6, "cream", { line: true });
    }

    const fx = s.foe.x + s.foe.w / 2;
    const fy = s.foe.y + s.foe.h / 2;

    // Splash-Tropfen
    for (const p of s.splash) d.emoji("💦", p.x, p.y, 30);

    // Gegner
    d.emoji("🤖", fx, fy, 40);
    if (s.foe.wet > 0) d.emoji("💦", fx, fy - 30, 24);

    // Ballons
    for (const b of s.theirs) d.circle(b.x, b.y, b.r, "red", { line: true });
    for (const b of s.mine) d.circle(b.x, b.y, b.r, "yellow", { line: true });

    // Spieler (blinkt nach Treffer)
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🐧", s.me.x + 17, s.me.y + 17, 36);
    }
  }
};

