export default {
  title: "Ballon-Duell",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    return {
      me: { x: 163, y: 540, w: 34, h: 34 },
      foe: { x: 161, y: 90, w: 38, h: 38, dir: 1, wet: 0, wobble: 0 },
      mine: [],
      theirs: [],
      cool: 0,
      foeCool: Math.max(30, 70 - 8 * g.level),
      safe: 0,
      wet: 0,
      splash: []
    };
  },

  update(s, input, g) {
    const me = s.me;
    const foe = s.foe;

    // Spieler bewegen
    if (input.left) me.x -= 4;
    if (input.right) me.x += 4;
    if (input.up) me.y -= 4;
    if (input.down) me.y += 4;
    me.x = g.clamp(me.x, 4, g.W - me.w - 4);
    me.y = g.clamp(me.y, 380, 600);

    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;
    if (s.wet > 0) s.wet -= 1;

    // Eigene Wasserballons werfen
    if ((input.firePressed || input.fire) && s.cool === 0 && s.mine.length < 3) {
      s.mine.push({ x: me.x + 17, y: me.y, r: 7 });
      s.cool = 15;
      g.sound("shoot");
    }
    for (const b of s.mine) b.y -= 8;
    s.mine = s.mine.filter((b) => b.y > g.TOP && b.x > -10 && b.x < g.W + 10);

    // Gegner bewegen
    const speed = 1.5 + 0.4 * g.level;
    foe.x += foe.dir * speed;
    if (foe.x < 4 || foe.x > g.W - foe.w - 4) {
      foe.dir = -foe.dir;
      foe.x = g.clamp(foe.x, 4, g.W - foe.w - 4);
    }
    if (g.random() < 0.01) foe.dir = -foe.dir;
    foe.wobble += 1;
    foe.y = 71 + 30 * g.sin(g.frame * 3);
    const fx = foe.x + foe.w / 2;
    const fy = foe.y + foe.h / 2;

    // Gegner wirft Ballons nach unten
    s.foeCool -= 1;
    if (s.foeCool <= 0) {
      s.foeCool = Math.max(30, 70 - 8 * g.level);
      let vx = 0;
      if (g.random() < 0.6) vx = g.clamp((me.x + 17 - fx) * 0.02, -1.5, 1.5);
      s.theirs.push({ x: fx, y: fy + 22, vx: vx, r: 7 });
    }
    const fallSpeed = 3 + 0.5 * g.level;
    for (const b of s.theirs) {
      b.x += b.vx;
      b.y += fallSpeed;
    }
    s.theirs = s.theirs.filter((b) => b.y < g.H + 10 && b.x > -20 && b.x < g.W + 20);

    // Eigene Ballons treffen den Gegner
    let hits = 0;
    s.mine = s.mine.filter((b) => {
      if (g.dist({ x: b.x, y: b.y }, { x: fx, y: fy }) < 25) {
        hits += 1;
        return false;
      }
      return true;
    });
    if (hits > 0) {
      foe.wet += hits;
      g.addScore(10 * g.level * hits);
      g.sound("pop");
      s.splash.push({ x: fx, y: fy, t: 30 });
    }
    // Drei nasse Treffer: Sieg, das Duell ist vorbei
    if (foe.wet >= 3) {
      g.addScore(30 * g.level);
      g.sound("win");
      foe.wet = 3;
      s.mine = [];
      s.theirs = [];
      g.win();
      return;
