    const blinkOn = s.safe === 0 || (s.safe >> 2) % 2 === 0;
    if (blinkOn) d.emoji("🐧", s.me.x + 17, s.me.y + 17, 36);
    if (s.wet > 0) d.emoji("💦", s.me.x + 17, s.me.y - 8, 24);
  }
};

