      if (u.h > 0) d.rect(u.x, u.y, u.w, u.h, "ink", { round: 6, line: true });
    }

    // Boden
    d.rect(0, FLOOR, g.W, 30, "yellow", { line: true });

    // Huhn: immer sichtbar. Gelber Untergrund als Kontrast, in der Schutzzeit blinkt ein roter Ring.
    const cx = s.bird.x + s.bird.w / 2, cy = s.bird.y + s.bird.h / 2;
    d.circle(cx, cy, 22, "yellow", { line: true });
    if (s.safe > 0 && (g.frame >> 2) % 2 === 0) d.circle(cx, cy, 26, "red", { line: true });
    d.emoji("🐔", cx, cy, 40);

    // Tipp-Hinweis in den ersten 120 Frames
    if (g.frame < 120) d.text("Tippen = flattern", 180, 100, { size: 16, color: "ink", align: "center" });
  }
};

function pipeTop(p, g) {
  return { x: p.x, y: g.TOP, w: p.w, h: p.gapY - p.gap / 2 - g.TOP };
}
function pipeBottom(p, g) {
  const y = p.gapY + p.gap / 2;
  return { x: p.x, y: y, w: p.w, h: FLOOR - y };
}

// Tennis-Duell (nur Spiel-API, keine Importe). Gedrehtes Pong: Mittellinie quer, du unten, der Computer oben.
const W = 360, TOP = 48, MID = 343, SERVE_WAIT = 45, BALL_R = 8;

export default {
  title: "Tennis-Duell",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 148, y: 600, w: 64, h: 12 },
      cpu: { x: 148, y: 80, w: 64, h: 12 },
      ball: { x: 180, y: 340, vx: 0, vy: 0, r: BALL_R },
      serve: SERVE_WAIT,
      hits: 0,
      cpuMiss: 0,
      safe: 0
    };
    launch(s, g, g.random() < 0.5 ? 1 : -1);
    return s;
  },

  update(s, input, g) {
    if (g.frame >= 3300) { g.gameOver(); return; }

    const me = s.me;
    if (input.left) me.x -= 5;
    if (input.right) me.x += 5;
    me.x = g.clamp(me.x, 4, g.W - me.w - 4);

    // Computer: schnell bei aufsteigendem Ball, langsam zur Mitte sonst
    const cpu = s.cpu;
    const b = s.ball;
    const toward = b.vy < 0 ? b.x - cpu.w / 2 : (g.W - cpu.w) / 2;
    const step = b.vy < 0 ? 1.6 + 0.25 * g.level : 0.8 + 0.1 * g.level;
    cpu.x += g.clamp(toward - cpu.x, -step, step);
    cpu.x = g.clamp(cpu.x, 4, g.W - cpu.w - 4);

    // Aufschlag-Wartezeit: der Ball ruht
    if (s.serve > 0) { s.serve -= 1; return; }

    b.x += b.vx;
    b.y += b.vy;

    // Seitenwaende
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - b.r) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }

    // Mein Schlaeger
    if (b.vy > 0 && g.hit(b, me)) {
      b.y = me.y - b.r;
      b.vy = -Math.min(9, Math.abs(b.vy) + 0.3);
      b.vx = clampV(((b.x - (me.x + me.w / 2)) / (me.w / 2)) * 5, -6, 6);
      s.hits += 1;
      g.addScore(1);
      g.sound("jump");
    }

    // Schlaeger des Computers
    if (b.vy < 0 && g.hit(b, cpu)) {
      b.y = cpu.y + cpu.h + b.r;
      b.vy = Math.min(9, Math.abs(b.vy));
      b.vx = clampV(((b.x - (cpu.x + cpu.w / 2)) / (cpu.w / 2)) * 5, -6, 6);
      g.sound("hit");
    }

    // Ich verpasse den Ball
    if (b.y > g.H + b.r) {
      g.sound("hurt");
      g.loseLife();
      launch(s, g, -1);
      return;
    }

    // Der Computer verpasst den Ball
    if (b.y < TOP - 10) {
      g.addScore(10 * g.level);
      g.sound("coin");
      s.cpuMiss += 1;
      if (s.cpuMiss % 3 === 0) { g.nextLevel(); g.sound("level"); }
      launch(s, g, 1);
      return;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(4, 56, 352, 576, "yellow", { round: 10, line: true });
    for (let x = 16; x < g.W - 16; x += 24) d.line(x, MID, x + 12, MID, "ink", 2);
    d.rect(s.cpu.x, s.cpu.y, s.cpu.w, s.cpu.h, "ink", { round: 6 });
    d.rect(s.me.x, s.me.y, s.me.w, s.me.h, "red", { round: 6 });
    d.circle(s.ball.x, s.ball.y, s.ball.r, "yellow", { line: true });
    d.emoji("🎾", s.ball.x, s.ball.y, 22);
  }
};

function launch(s, g, dir) {
  const speed = 3 + 0.4 * g.level + Math.min(1.5, s.hits * 0.02);
  let vx = g.randInt(-2, 2);
  if (vx === 0) vx = 1;
  s.ball = { x: W / 2, y: MID, vx: vx, vy: dir * speed, r: BALL_R };
  s.serve = SERVE_WAIT;
}

function clampV(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

