// Kuchen-Stapler (nur Spiel-API, keine Importe).
// Kuchenstuecke fallen von oben. Links/rechts bewegen, hoch dreht, runter laesst schneller fallen.
// Volle Reihen verschwinden und geben Punkte. Kommt der Stapel oben nicht mehr rein, verliert man ein Leben.
// Bleibt man zu lange ohne volle Reihe, wird der Teig kalt und man verliert ein Leben.
const CELL = 24, COLS = 10, ROWS = 24, X0 = 60, Y0 = 56;
const IDLE_LIMIT = 900;
const MOVE_REPEAT = 6, ROT_REPEAT = 10;

// Sieben Formen, je vier Zellen [x, y] relativ zum Ursprung der Figur.
const SHAPES = [
  [[-1, 0], [0, 0], [1, 0], [2, 0]],   // I
  [[0, 0], [1, 0], [0, 1], [1, 1]],    // O
  [[-1, 0], [0, 0], [1, 0], [0, 1]],   // T
  [[0, 0], [1, 0], [-1, 1], [0, 1]],   // S
  [[-1, 0], [0, 0], [0, 1], [1, 1]],   // Z
  [[-1, 0], [-1, 1], [0, 1], [1, 1]],  // J
  [[1, 0], [-1, 1], [0, 1], [1, 1]]    // L
];
// Kuchenarten 1..4
const CAKES = ["🍰", "🧁", "🍩", "🍪"];
const BACK = ["red", "ink", "yellow", "cream"];

export default {
  title: "Kuchen-Stapler",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    const s = {
      grid: emptyGrid(),
      piece: null,
      wait: 0,
      moveCool: 0,
      rotCool: 0,
      idle: 0,
      lr: 0,
      cleared: 0
    };
    spawnPiece(s, g);
    return s;
  },

  update(s, input, g) {
    // Wiederholsperren: erster Druck sofort, danach im Takt; bei Loslassen zuruecksetzen
    if (!input.left && !input.right) s.moveCool = 0;
    else if (s.moveCool > 0) s.moveCool -= 1;
    if (!input.up) s.rotCool = 0;
    else if (s.rotCool > 0) s.rotCool -= 1;

    const p = s.piece;

    // Seitwaerts
    if ((input.left || input.right) && s.moveCool === 0) {
      const dx = input.left ? -1 : 1;
      if (valid(s.grid, p.kind, p.rot, p.x + dx, p.y)) p.x += dx;
      s.moveCool = MOVE_REPEAT;
    }

    // Drehen
    if (input.up && s.rotCool === 0) {
      const nr = (p.rot + 1) % 4;
      if (valid(s.grid, p.kind, nr, p.x, p.y)) p.rot = nr;
      s.rotCool = ROT_REPEAT;
    }

    // Zeitdruck: zu lange keine volle Reihe kostet ein Leben
    s.idle += 1;
    if (s.idle >= IDLE_LIMIT) {
      s.idle = 0;
      g.sound("hurt");
      g.loseLife();
    }

    // Fallen; schneller mit der Zeit und mit dem Level
    const speedLevel = g.level + Math.floor(g.frame / 1200);
    const interval = input.down ? 2 : Math.max(6, 32 - 3 * speedLevel);
    s.wait += 1;
    if (s.wait >= interval) {
      s.wait = 0;
      if (valid(s.grid, p.kind, p.rot, p.x, p.y + 1)) p.y += 1;
      else freeze(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(X0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 8, line: true });
    for (let c = 1; c < COLS; c++) d.line(X0 + c * CELL, Y0, X0 + c * CELL, Y0 + ROWS * CELL, "cream", 1);
    for (let r = 1; r < ROWS; r++) d.line(X0, Y0 + r * CELL, X0 + COLS * CELL, Y0 + r * CELL, "cream", 1);

    // Festes Gebaeck
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const v = s.grid[r][c];
