    g.sound("lose");
    g.gameOver();
  }
}

function freeze(s, g) {
  const p = s.piece;
  for (const [cx, cy] of cellsOf(p.kind, p.rot)) s.grid[p.y + cy][p.x + cx] = p.type;
  g.addScore(1);
  g.sound("hit");
  clearLines(s, g);
  spawnPiece(s, g);
}

function clearLines(s, g) {
  const kept = s.grid.filter((row) => row.some((v) => v === 0));
  const n = ROWS - kept.length;
  if (n === 0) return;
  const fresh = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let c = 0; c < COLS; c++) row.push(0);
    fresh.push(row);
  }
  s.grid = fresh.concat(kept);
  g.addScore(10 * g.level * n + (n > 1 ? 20 * (n - 1) : 0));
  g.sound("pop");
  s.cleared += n;
  s.lr += n;
  while (s.lr >= 5) {
    s.lr -= 5;
    g.nextLevel();
    g.sound("level");
  }
}

// Würfel-Rennen 100 (nur Spiel-API, keine Importe): Vier Spieler würfeln reihum, wer zuerst 100 Punkte hat, gewinnt.
// Eine 1 bringt nichts und beendet den Zug, eine 6 gibt einen Extrawurf. Ein Gerät, vier Plätze.
const PIPS = [[4], [0, 8], [0, 4, 8], [0, 2, 6, 8], [0, 2, 4, 6, 8], [0, 2, 3, 5, 6, 8]];
const ANIMALS = ["🐶", "🐱", "🐸", "🐼"];

export default {
  title: "Würfel-Rennen 100",
  controls: ["fire"],
  lives: 1,

  init(g) {
    return {
      scores: [0, 0, 0, 0],
      turn: 0,
      turnPts: 0,
      die: 0,
      shown: 1,
      roll: 0,
      wait: 0,
      idle: 0,
      msg: "",
      total: 0,
      done: false
    };
  },

  update(s, input, g) {
    if (s.done) return;

    // Zeitlimit: höchste Punktzahl gewinnt
    if (g.frame > 3300) {
      let best = 0;
      for (let i = 1; i < 4; i++) if (s.scores[i] > s.scores[best]) best = i;
      s.done = true;
      s.msg = "Zeit ist um!";
      g.sound("win");
      g.win();
      return;
    }

    // Würfelanimation
    if (s.roll > 0) {
      s.roll -= 1;
      s.shown = g.randInt(1, 6);
      if (s.roll === 0) finish(s, g);
      s.total = maxScore(s);
      return;
    }

    if (s.wait > 0) s.wait -= 1;
    s.idle += 1;
    // Tippen/Feuer würfelt; ohne Wurf 600 Frames lang würfelt der Zug automatisch
    if (s.wait === 0 && (input.firePressed || s.idle >= 600)) {
      s.roll = 30;
      s.idle = 0;
      s.msg = "";
    }
    s.total = maxScore(s);
  },

  draw(s, d, g) {
    d.clear("cream");

    // Vier Karten 2x2
    for (let i = 0; i < 4; i++) {
      const x = 15 + (i % 2) * 170;
      const y = 70 + (i >> 1) * 80;
      const active = i === s.turn;
      d.rect(x, y, 160, 70, active ? "yellow" : "cream", { round: 12, line: true });
      d.emoji(ANIMALS[i], x + 34, y + 35, 40);
      d.text(String(s.scores[i]), x + 110, y + 28, { size: 28, color: "ink", align: "center" });
    }

    // Würfel
    d.rect(110, 270, 140, 140, "cream", { round: 20, shadow: true, line: true });
    const v = s.roll > 0 ? s.shown : s.die;
    if (v >= 1 && v <= 6) {
      for (const k of PIPS[v - 1]) {
        const cx = 180 + ((k % 3) - 1) * 35;
        const cy = 340 + (Math.floor(k / 3) - 1) * 35;
        d.circle(cx, cy, 10, "ink");
      }
    }

    // Texte
    d.text("Spieler " + (s.turn + 1) + " ist dran", 180, 450, { size: 24, color: "ink", align: "center" });
    d.text("Tippen oder Feuer zum Würfeln", 180, 490, { size: 18, color: "ink", align: "center" });
    if (s.msg) d.text(s.msg, 180, 540, { size: 20, color: "red", align: "center" });

    // Fortschrittsbalken mit höchstem Stand
    const best = maxScore(s);
    d.rect(20, 590, 320, 18, "cream", { round: 9, line: true });
    const fill = g.clamp(Math.round(320 * best / 100), 0, 320);
    if (fill > 0) d.rect(20, 590, fill, 18, "red", { round: 9 });
    d.text("Höchster Stand: " + best + " / 100", 180, 620, { size: 16, color: "ink", align: "center" });
  }
};

function maxScore(s) {
  let m = 0;
  for (let i = 0; i < 4; i++) if (s.scores[i] > m) m = s.scores[i];
  return m;
}

function finish(s, g) {
  const die = g.randInt(1, 6);
  s.die = die;
  s.shown = die;
  g.sound("jump");
  const cur = s.turn;

  if (die === 1) {
    s.msg = "Pech! Eine 1";
    g.sound("hurt");
    s.turn = (cur + 1) % 4;
    s.turnPts = 0;
  } else {
    s.scores[cur] += die;
    s.turnPts += die;
    g.addScore(die);
    g.sound("coin");
    if (s.scores[cur] >= 100) {
      s.done = true;
      s.msg = "Spieler " + (cur + 1) + " gewinnt!";
      g.sound("win");
      g.win();
      return;
    }
    if (die === 6) {
      s.msg = "Noch mal, eine 6!";
    } else {
      s.msg = "";
      s.turn = (cur + 1) % 4;
      s.turnPts = 0;
    }
  }
  s.wait = 40;
  s.total = maxScore(s);
}

