// Gummibärchen-Schätzen (nur Spiel-API, keine Importe).
// Im Glas liegen Gummibärchen. Du schätzt die Anzahl, der Computer schätzt auch.
// Wer näher dran ist, gewinnt die Runde. Der Computer-Tipp ist absichtlich ungenau.
const MAXB = 120;

export default {
  title: "Gummibärchen-Schätzen",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      phase: "guess", truth: 0, guess: 50, cpu: 0, wait: 0, rounds: 0, wins: 0,
      msg: "", bears: [], timer: 600, rep: 0, da: 0, db: 0
    };
    startRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "guess") {
      let delta = 0;
      if (input.up) delta += 1;
      if (input.down) delta -= 1;
      if (input.right) delta += 10;
      if (input.left) delta -= 10;
      if (delta !== 0) {
        if (s.rep === 0) {
          s.guess = g.clamp(s.guess + delta, 0, 200);
          s.rep = 6;
        } else {
          s.rep -= 1;
        }
      } else {
        s.rep = 0;
      }
      s.timer -= 1;
      if (input.firePressed || s.timer <= 0) confirm(s, g);
      return;
    }

    // Auflösung
    s.wait -= 1;
    if (s.wait <= 0 || (input.firePressed && s.wait <= 120)) {
      if (s.wins >= 5) { g.win(); return; }
      if (s.rounds >= 12) { g.gameOver(); return; }
      startRound(s, g);
    }
  },

  draw(s, d) {
    d.clear("cream");
    // Glas, Füllung, Bären, Deckel
    d.rect(80, 110, 200, 260, "cream", { round: 20, line: true });
    d.rect(84, 114, 192, 252, "yellow", { round: 16 });
    for (const b of s.bears) d.emoji(b.e, b.x, b.y, 16);
