}

function newGull(fast) {
  return { cx: GX, cy: GY, px: GX, py: GY, dir: { x: 0, y: 1 }, wait: 0, fast: fast };
}

function stepMe(s) {
  const me = s.me;
  me.px = me.cx;
  me.py = me.cy;
  if (open(s, me.cx + me.next.x, me.cy + me.next.y)) {
    me.dir = { x: me.next.x, y: me.next.y };
    me.cx += me.dir.x;
    me.cy += me.dir.y;
  } else if (open(s, me.cx + me.dir.x, me.cy + me.dir.y)) {
    me.cx += me.dir.x;
    me.cy += me.dir.y;
  }
}

function moveGull(s, g, gl) {
  const opts = [];
  for (const d of DIRS) {
    if (open(s, gl.cx + d.x, gl.cy + d.y)) opts.push(d);
  }
  if (opts.length === 0) return;
  const back = { x: -gl.dir.x, y: -gl.dir.y };
  const fwd = opts.filter((d) => !(d.x === back.x && d.y === back.y));
  const pool = fwd.length > 0 ? fwd : opts;
  let pick;
  if (g.random() < 0.6) {
    let best = 1e9;
    pick = pool[0];
    for (const d of pool) {
      const nd = Math.abs(gl.cx + d.x - s.me.cx) + Math.abs(gl.cy + d.y - s.me.cy);
      if (nd < best) {
        best = nd;
        pick = d;
      }
    }
  } else {
    pick = pool[g.randInt(0, pool.length - 1)];
  }
  gl.px = gl.cx;
  gl.py = gl.cy;
  gl.cx += pick.x;
  gl.cy += pick.y;
  gl.dir = { x: pick.x, y: pick.y };
}

function touching(me, gl) {
  const same = gl.cx === me.cx && gl.cy === me.cy;
  const swap = gl.cx === me.px && gl.cy === me.py && gl.px === me.cx && gl.py === me.cy;
  return same || swap;
}

