// Donut-Labyrinth (nur Spiel-API, keine Importe). Mechanik frei gewaehlt; Donut und Voegel sind eigene Figuren.
// Ehrlich: Die Gegner sind Voegel 🐦. Ein Moewen-Emoji gibt es nicht, deshalb heissen sie hier Voegel, nicht Moewen.
// Streusel einsammeln, Voegeln ausweichen, alle Streusel = naechstes Level.
// Ein Vogel jagt von Anfang an gezielt (kuerzester Weg zum Donut), die anderen teils gezielt, sonst Zufall.
// Der Donut ist schneller als die normalen Voegel, damit Ausweichen moeglich ist.
// Nur Streusel in erreichbaren Gaengen zaehlen (buildGrid), damit jedes Level abschliessbar ist.
const CELL = 20, COLS = 18, ROWS = 28, Y0 = 64;
const SX = 9, SY = 25;   // Start des Donuts (unten Mitte, Korridor)
const GX = 9, GY = 1;    // Start der Voegel (oben Mitte, Korridor)
const DIRS = [{ x: 0, y: -1 }, { x: 0, y: 1 }, { x: -1, y: 0 }, { x: 1, y: 0 }];

// Linke Haelfte je 9 Zeichen; die rechte Haelfte ist gespiegelt (Zeile = L + rueckwaerts L).
// '#' Wand, '.' Weg (Streusel nur in Gangzeilen r % 4 === 1, siehe buildGrid), ' ' Weg ohne Streusel.
const MAP = [
  "#########",
  "#.  .  . ",
  "# #####  ",
  "#.  .  . ",
  "##### #  ",
  "#.  .  . ",
  "# #####  ",
  "#.  .  . ",
  "### #####",
  "#.  .  . ",
  "# #####  ",
  "#.  .  . ",
  "##### #  ",
  "#.  .  . ",
  "# #####  ",
  "#.  .  . ",
  "### #####",
  "#.  .  . ",
  "# #####  ",
  "#.  .  . ",
  "##### #  ",
  "#.  .  . ",
  "# #####  ",
  "#.  .  . ",
  "### #####",
  "#.  .  . ",
  "# #####  ",
  "#########"
];

export default {
  title: "Donut-Labyrinth",
  controls: ["up", "down", "left", "right"],
  lives: 3,

  init(g) {
    const s = { grid: buildGrid(), left: 0, me: null, gulls: [], safe: 0, extra: false };
    s.left = countStreusel(s.grid);
    placeAll(s, g);
    return s;
  },

  update(s, input, g) {
    const me = s.me;
    if (input.up) me.next = { x: 0, y: -1 };
    else if (input.down) me.next = { x: 0, y: 1 };
    else if (input.left) me.next = { x: -1, y: 0 };
    else if (input.right) me.next = { x: 1, y: 0 };

    if (s.safe > 0) s.safe -= 1;

    // Donut: alle 6 Frames einen Schritt (bei hohem Level etwas schneller)
    const dDelay = Math.max(3, 6 - Math.floor(g.level / 2));
    me.wait += 1;
    if (me.wait >= dDelay) {
      me.wait = 0;
      stepMe(s);
    }
    if (s.grid[me.cy][me.cx] === 1) {
      s.grid[me.cy][me.cx] = 0;
      s.left -= 1;
      g.addScore(10);
      g.sound("coin");
    }
    if (s.left === 0) {
      g.addScore(50);
      g.nextLevel();
      g.sound("level");
      s.grid = buildGrid();
      s.left = countStreusel(s.grid);
      placeAll(s, g);
      return;
    }

    // Voegel: jagende Voegel (chase) gehen den kuerzesten Weg zum Donut, die anderen meist auch.
    // Jagende Voegel sind etwas langsamer als der Donut (Ausweichen moeglich).
    // Die schnelle Extra-Voegel (nach dem Zeitlimit) jagt ebenfalls.
    for (const gl of s.gulls) {
      gl.wait += 1;
      const gDelay = gl.fast ? 4 : gl.chase ? Math.max(8, 10 - g.level) : Math.max(10, 12 - g.level);
      if (gl.wait >= gDelay) {
        gl.wait = 0;
        if (gl.fast || gl.chase) chaseStep(s, gl);
        else moveGull(s, g, gl);
      }
    }

    // Zeitlimit: nach 3000 Frames kommt ein schneller jagender Vogel dazu.
    if (!s.extra && g.frame >= 3000) {
      s.extra = true;
      s.gulls.push(newGull(true, true));
    }

    // Kollision
    for (const gl of s.gulls) {
      if (s.safe === 0 && touching(me, gl)) {
        g.sound("hurt");
        g.loseLife();
        placeAll(s, g);
        s.safe = 90;
        return;
      }
    }
  },

  draw(s, d) {
    d.clear("cream");
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const v = s.grid[r][c];
        const x = c * CELL, y = Y0 + r * CELL;
        if (v === 2) d.rect(x + 1, y + 1, CELL - 2, CELL - 2, "ink", { round: 5 });
        else if (v === 1) d.circle(x + 10, y + 10, 2, "red");
      }
    }
    const me = s.me;
    if (s.safe === 0 || Math.floor(s.safe / 4) % 2 === 0) {
      d.emoji("🍩", me.cx * CELL + 10, Y0 + me.cy * CELL + 10, 18);
    }
    for (const gl of s.gulls) {
      d.emoji("🐦", gl.cx * CELL + 10, Y0 + gl.cy * CELL + 10, 20);
    }
    d.text("Voegel jagen dich (Moewen: kein Emoji vorhanden)", 180, 636, { size: 11, color: "ink", align: "center" });
  }
};

function inside(x, y) {
  return x >= 0 && x < COLS && y >= 0 && y < ROWS;
}

function open(s, x, y) {
  return inside(x, y) && s.grid[y][x] !== 2;
}

function buildGrid() {
  const grid = [];
  for (let r = 0; r < ROWS; r++) {
    const L = MAP[r];
    const row = [];
    for (let c = 0; c < COLS; c++) {
      const ch = c < 9 ? L[c] : L[COLS - 1 - c];
      // Streusel nur auf '.'-Feldern der Gangzeilen r % 4 === 1
      row.push(ch === "#" ? 2 : ch === "." && r % 4 === 1 ? 1 : 0);
    }
    grid.push(row);
  }
  // Streusel, die vom Start aus nicht erreichbar sind, entfernen (jedes Level bleibt loesbar)
  const seen = distFrom(grid, SX, SY, true);
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (grid[r][c] === 1 && seen[r][c] < 0) grid[r][c] = 0;
    }
  }
  return grid;
}

function countStreusel(grid) {
  let n = 0;
  for (const row of grid) for (const v of row) if (v === 1) n += 1;
  return n;
}

function placeAll(s, g) {
  s.me = { cx: SX, cy: SY, px: SX, py: SY, dir: { x: -1, y: 0 }, next: { x: -1, y: 0 }, wait: 0 };
  s.gulls = [];
  const n = g.level >= 3 ? 3 : 2;
  // Erster Vogel jagt immer; weitere Voegel jagen teils
  for (let i = 0; i < n; i++) s.gulls.push(newGull(false, i === 0));
  if (s.extra) s.gulls.push(newGull(true, true));
}

function newGull(fast, chase) {
  return { cx: GX, cy: GY, px: GX, py: GY, dir: { x: 0, y: 1 }, wait: 0, fast: fast, chase: chase };
}

// Breitensuche ab (sx, sy). Mit grid-Argument (Rohgitter) oder mit s (Spielzustand).
// Liefert Entfernungen in Schritten; -1 = nicht erreichbar.
function distFrom(src, sx, sy, isGrid) {
  const blocked = isGrid
    ? (x, y) => !inside(x, y) || src[y][x] === 2
    : (x, y) => !open(src, x, y);
  const dist = [];
  for (let r = 0; r < ROWS; r++) {
    const row = [];
    for (let c = 0; c < COLS; c++) row.push(-1);
    dist.push(row);
  }
  const qx = [sx], qy = [sy];
  dist[sy][sx] = 0;
  for (let i = 0; i < qx.length; i++) {
    for (const dir of DIRS) {
      const nx = qx[i] + dir.x, ny = qy[i] + dir.y;
      if (!blocked(nx, ny) && dist[ny][nx] < 0) {
        dist[ny][nx] = dist[qy[i]][qx[i]] + 1;
        qx.push(nx);
        qy.push(ny);
      }
    }
  }
  return dist;
}

function stepMe(s) {
  const me = s.me;
  me.px = me.cx;
  me.py = me.cy;
  if (open(s, me.cx + me.next.x, me.cy + me.next.y)) {
    me.dir = { x: me.next.x, y: me.next.y };
    me.cx += me.dir.x;
    me.cy += me.dir.y;
  } else if (open(s, me.cx + me.dir.x, me.cy + me.dir.y)) {
    me.cx += me.dir.x;
    me.cy += me.dir.y;
  }
}

// Jagender Vogel: geht den kuerzesten Weg zum Donut.
function chaseStep(s, gl) {
  const dist = distFrom(s, s.me.cx, s.me.cy, false);
  let best = -1;
  let pick = null;
  for (const dir of DIRS) {
    const nx = gl.cx + dir.x, ny = gl.cy + dir.y;
    if (!open(s, nx, ny)) continue;
    const dd = dist[ny][nx];
    if (dd < 0) continue;
    if (pick === null || dd < best) {
      best = dd;
      pick = dir;
    }
  }
  if (pick === null) return;
  gl.px = gl.cx;
  gl.py = gl.cy;
  gl.cx += pick.x;
  gl.cy += pick.y;
  gl.dir = { x: pick.x, y: pick.y };
}

function moveGull(s, g, gl) {
  const opts = [];
  for (const dir of DIRS) {
    if (open(s, gl.cx + dir.x, gl.cy + dir.y)) opts.push(dir);
  }
  if (opts.length === 0) return;
  const back = { x: -gl.dir.x, y: -gl.dir.y };
  const fwd = opts.filter((dir) => !(dir.x === back.x && dir.y === back.y));
  const pool = fwd.length > 0 ? fwd : opts;
  let pick;
  // 60% gezielt auf den Donut zu, sonst Zufall
  if (g.random() < 0.6) {
    let best = 1e9;
    pick = pool[0];
    for (const dir of pool) {
      const nd = Math.abs(gl.cx + dir.x - s.me.cx) + Math.abs(gl.cy + dir.y - s.me.cy);
      if (nd < best) {
        best = nd;
        pick = dir;
      }
    }
  } else {
    pick = pool[g.randInt(0, pool.length - 1)];
  }
  gl.px = gl.cx;
  gl.py = gl.cy;
  gl.cx += pick.x;
  gl.cy += pick.y;
  gl.dir = { x: pick.x, y: pick.y };
}

function touching(me, gl) {
  const same = gl.cx === me.cx && gl.cy === me.cy;
  const swap = gl.cx === me.px && gl.cy === me.py && gl.px === me.cx && gl.py === me.cy;
  return same || swap;
}

