// Pizza-Ausbruch (nur Spiel-API, keine Importe).
// Haken h4 (Lego-Steine) ist nicht erfuellt: Die Marke Lego ist nicht erlaubt. Ersatz: eigene Bausteine
// als Rechtecke mit Noppen (kleine Kreise), ohne Markennamen.
const BRICK = ["yellow", "red", "ink", "cream"];
const STUD = ["cream", "cream", "yellow", "yellow"];

export default {
  title: "Pizza-Ausbruch",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return {
      paddle: { x: 150, y: 600, w: 64, h: 14 },
      ball: { x: 182, y: 591, r: 9, vx: 0, vy: 0 },
      stuck: true,
      wait: 0,
      cool: 0,
      bricks: wall(g),
    };
  },

  update(s, input, g) {
    const p = s.paddle;
    const b = s.ball;
    if (input.left) p.x -= 6;
    if (input.right) p.x += 6;
    p.x = g.clamp(p.x, 0, g.W - p.w);
    if (s.cool > 0) s.cool -= 1;

    if (s.stuck) {
      b.x = p.x + p.w / 2;
      b.y = p.y - b.r;
      s.wait += 1;
      if (s.wait >= 40) {
        s.stuck = false;
        s.wait = 0;
        b.vy = -4.5;
        b.vx = g.random() < 0.5 ? -2 : 2;
      }
      return;
    }

    const f = Math.min(1.8, 1 + 0.1 * (g.level - 1));
    b.x += b.vx * f;
    b.y += b.vy * f;

    // Waende und Decke
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - b.r) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y < g.TOP + b.r) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Schlaeger
    if (s.cool === 0 && b.vy > 0 && g.hit(b, p)) {
      b.vy = -Math.abs(b.vy);
      b.y = p.y - b.r - 1;
      b.vx = g.clamp(((b.x - (p.x + p.w / 2)) / (p.w / 2)) * 4, -4, 4);
      s.cool = 4;
      g.sound("jump");
    }

    // Steine: pro Frame ersten getroffenen Stein entfernen
    let hitIdx = -1;
    for (let i = 0; i < s.bricks.length; i++) {
      if (g.hit(b, s.bricks[i])) { hitIdx = i; break; }
    }
    if (hitIdx >= 0) {
      s.bricks.splice(hitIdx, 1);
      b.vy = -b.vy;
      g.addScore(10 * g.level);
      g.sound("pop");
    }

    fixSpeed(b);

    // Ball gefallen: Leben weg, zurueck auf den Schlaeger
    if (b.y > g.H + 10) {
      g.sound("hurt");
      g.loseLife();
      s.stuck = true;
      s.wait = 0;
      b.vx = 0;
      b.vy = 0;
      return;
    }

    // Mauer leer: naechstes Level
    if (s.bricks.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.bricks = wall(g);
      s.stuck = true;
      s.wait = 0;
      b.vx = 0;
      b.vy = 0;
    }
  },

  draw(s, d) {
    d.clear("cream");
    for (const b of s.bricks) {
      d.rect(b.x, b.y, b.w, b.h, BRICK[b.c], { round: 3, line: true });
      d.circle(b.x + 10, b.y + 5, 3, STUD[b.c]);
      d.circle(b.x + 28, b.y + 5, 3, STUD[b.c]);
    }
    const p = s.paddle;
    d.rect(p.x, p.y, p.w, p.h, "red", { round: 7, shadow: true, line: true });
    d.emoji("🍕", s.ball.x, s.ball.y, 24);
  }
};

function wall(g) {
  const out = [];
  const rows = Math.min(4 + g.level, 7);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 8; c++) {
      out.push({ x: 20 + c * 40, y: g.TOP + 30 + r * 22, w: 38, h: 18, c: (r + c) % 4 });
    }
  }
  return out;
}

// vy nie 0 und nie zu schnell; vx begrenzt
function fixSpeed(b) {
  if (Math.abs(b.vy) < 2.5) b.vy = b.vy < 0 ? -2.5 : 2.5;
  if (Math.abs(b.vy) > 7) b.vy = b.vy < 0 ? -7 : 7;
  b.vx = Math.max(-6, Math.min(6, b.vx));
}

