      stuck: true,
      wait: 0,
      cool: 0,
      bricks: wall(g),
    };
  },

  update(s, input, g) {
    const p = s.paddle;
    const b = s.ball;
    if (input.left) p.x -= 6;
    if (input.right) p.x += 6;
    p.x = g.clamp(p.x, 0, g.W - p.w);
    if (s.cool > 0) s.cool -= 1;

    if (s.stuck) {
      b.x = p.x + p.w / 2;
      b.y = p.y - b.r;
      s.wait += 1;
      if (s.wait >= 40) {
        s.stuck = false;
        s.wait = 0;
        b.vy = -4.5;
        b.vx = g.random() < 0.5 ? -2 : 2;
      }
      return;
    }

    const f = Math.min(1.8, 1 + 0.1 * (g.level - 1));
    b.x += b.vx * f;
    b.y += b.vy * f;

    // Waende und Decke
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - b.r) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y < g.TOP + b.r) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Schlaeger: Winkel aus Trefferposition; nie reine Senkrechte (sonst endloses Prellen ohne Steine)
    if (s.cool === 0 && b.vy > 0 && g.hit(b, p)) {
