  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 8; c++) {
      out.push({ x: 20 + c * 40, y: g.TOP + 30 + r * 22, w: 38, h: 18, c: (r + c) % 4 });
    }
  }
  return out;
}

// vy nie 0 und nicht zu schnell; vx nie fast senkrecht und begrenzt
function fixSpeed(b) {
  if (Math.abs(b.vy) < 2.5) b.vy = b.vy < 0 ? -2.5 : 2.5;
  if (Math.abs(b.vy) > 7) b.vy = b.vy < 0 ? -7 : 7;
  if (Math.abs(b.vx) < 0.8 && (b.vx !== 0 || b.vy !== 0)) b.vx = b.vx < 0 ? -0.8 : 0.8;
  b.vx = Math.max(-6, Math.min(6, b.vx));
}

// Pizza-Ausbruch (nur Spiel-API, keine Importe).
// Bausteine sind eigene Rechtecke mit Noppen. Markensteine sind nicht umgesetzt (nicht erfuellt).
// Punkte: Steintreffer (10 * Level), Schlaeger-Rueckschlag (3 * Level), Ueberleben (1 Punkt je 30 Frames).
// Levelwechsel: Level 1 hat 1 Reihe (8 Steine), jedes Level eine Reihe mehr. Ist die Mauer leer,
// ruft das Spiel g.nextLevel() auf, zeigt eine Levelmeldung und baut eine neue Mauer.
const BRICK = ["yellow", "red", "ink", "cream"];
const STUD = ["cream", "cream", "yellow", "yellow"];

export default {
  title: "Pizza-Ausbruch",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return {
      paddle: { x: 150, y: 600, w: 64, h: 14 },
      ball: { x: 182, y: 591, r: 9, vx: 0, vy: 0 },
      stuck: true,
      wait: 0,
      cool: 0,
      alive: 0,
      flash: 0,
      bricks: wall(g),
    };
  },

  update(s, input, g) {
    const p = s.paddle;
    const b = s.ball;
    if (input.left) p.x -= 6;
    if (input.right) p.x += 6;
    p.x = g.clamp(p.x, 0, g.W - p.w);
    if (s.cool > 0) s.cool -= 1;
    if (s.flash > 0) s.flash -= 1;

    if (s.stuck) {
      b.x = p.x + p.w / 2;
      b.y = p.y - b.r;
      s.wait += 1;
      if (s.wait >= 25) {
        s.stuck = false;
        s.wait = 0;
        b.vy = -6;
        b.vx = g.random() < 0.5 ? -2 : 2;
      }
      return;
    }

    // Ueberleben: solange der Ball im Spiel ist, gibt es Punkte
    s.alive += 1;
    if (s.alive % 30 === 0) g.addScore(1);

    const f = Math.min(1.8, 1 + 0.1 * (g.level - 1));
    const px = b.x;
    const py = b.y;
    b.x += b.vx * f;
    b.y += b.vy * f;

    // Waende und Decke
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - b.r) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y < g.TOP + b.r) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Schlaeger: Winkel aus Trefferposition; nie reine Senkrechte
    if (s.cool === 0 && b.vy > 0 && g.hit(b, p)) {
      b.vy = -Math.abs(b.vy);
      b.y = p.y - b.r - 1;
      b.vx = g.clamp(((b.x - (p.x + p.w / 2)) / (p.w / 2)) * 4, -4, 4);
      if (Math.abs(b.vx) < 1) b.vx = (g.random() < 0.5 ? -1 : 1) * (1 + g.random());
      s.cool = 4;
      g.addScore(3 * g.level);
      g.sound("jump");
    }

    // Steine: pro Frame ersten getroffenen Stein entfernen, Richtung aus der Anflugseite
    let hitIdx = -1;
    for (let i = 0; i < s.bricks.length; i++) {
      if (g.hit(b, s.bricks[i])) { hitIdx = i; break; }
    }
    if (hitIdx >= 0) {
      const br = s.bricks[hitIdx];
      const fromAboveOrBelow = py + b.r <= br.y || py - b.r >= br.y + br.h;
      if (fromAboveOrBelow) b.vy = -b.vy;
      else b.vx = -b.vx;
      s.bricks.splice(hitIdx, 1);
      g.addScore(10 * g.level);
      g.sound("pop");
    }

    fixSpeed(b);

    // Ball gefallen: Leben weg, zurueck auf den Schlaeger
    if (b.y > g.H + 10) {
      g.sound("hurt");
      g.loseLife();
      s.stuck = true;
      s.wait = 0;
      s.cool = 0;
      b.vx = 0;
      b.vy = 0;
      return;
    }

    // Mauer leer: Level-Bonus, naechstes Level, neue Mauer
    if (s.bricks.length === 0) {
      g.addScore(50 * g.level);
      g.nextLevel();
      g.sound("level");
      s.bricks = wall(g);
      s.flash = 120;
      s.stuck = true;
      s.wait = 0;
      s.cool = 0;
      b.vx = 0;
      b.vy = 0;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const b of s.bricks) {
      d.rect(b.x, b.y, b.w, b.h, BRICK[b.c], { round: 3, line: true });
      d.circle(b.x + 10, b.y + 5, 3, STUD[b.c]);
      d.circle(b.x + 28, b.y + 5, 3, STUD[b.c]);
    }
    if (s.flash > 0) {
      d.text("Level " + g.level + " erreicht!", g.W / 2, g.H / 2, { size: 28, color: "red", align: "center" });
    }
    const p = s.paddle;
    d.rect(p.x, p.y, p.w, p.h, "red", { round: 7, shadow: true, line: true });
    d.emoji("🍕", s.ball.x, s.ball.y, 24);
  }
};

// Mauer: 8 Spalten, Reihen = min(Level, 6). Level 1 = 8 Steine (eine Reihe), damit die Mauer in 60 s raeumbar ist.
function wall(g) {
  const out = [];
  const rows = Math.min(g.level, 6);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 8; c++) {
      out.push({ x: 20 + c * 40, y: g.TOP + 30 + r * 22, w: 38, h: 18, c: (r + c) % 4 });
    }
  }
  return out;
}

// vy nie 0 und nicht zu schnell; vx nie fast senkrecht und begrenzt
function fixSpeed(b) {
  if (Math.abs(b.vy) < 2.5) b.vy = b.vy < 0 ? -2.5 : 2.5;
  if (Math.abs(b.vy) > 7) b.vy = b.vy < 0 ? -7 : 7;
  if (Math.abs(b.vx) < 0.8 && (b.vx !== 0 || b.vy !== 0)) b.vx = b.vx < 0 ? -0.8 : 0.8;
  b.vx = Math.max(-6, Math.min(6, b.vx));
}

// Apfel-Schlange (nur Spiel-API, keine Importe).
// Hinweis zur Haekchenliste: [h6] (Nokia-Look mit gruenem Bildschirm) ist nicht umsetzbar, weil nur die Farben
// yellow, cream, ink und red erlaubt sind. Ersatz: gelbes Spielfeld mit dunklen Bloecken, kein Gruen.
const CELL = 20, COLS = 18, ROWS = 29, Y0 = 56;

export default {
  title: "Apfel-Schlange",
  controls: ["up", "down", "left", "right"],
  lives: 3,

  init(g) {
    const s = { body: [], dir: { x: 1, y: 0 }, next: { x: 1, y: 0 }, apple: { x: 0, y: 0 }, wait: 0, eaten: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    const want = input.up ? { x: 0, y: -1 } : input.down ? { x: 0, y: 1 } : input.left ? { x: -1, y: 0 } : input.right ? { x: 1, y: 0 } : null;
    if (want && !(want.x === -s.dir.x && want.y === -s.dir.y)) s.next = want;

    s.wait += 1;
    // Tempo steigt mit Level (jeder 5. Apfel) und mit der Zeit (alle 1200 Frames, also alle 20 s, ein Schritt schneller)
    const delay = Math.max(4, 9 - g.level - Math.floor(g.frame / 1200));
    if (s.wait < delay) return;
    s.wait = 0;

    s.dir = { x: s.next.x, y: s.next.y };
    const head = { x: s.body[0].x + s.dir.x, y: s.body[0].y + s.dir.y };
    const crash = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS || s.body.some((p) => p.x === head.x && p.y === head.y);
    if (crash) { g.sound("hurt"); g.loseLife(); reset(s, g); return; }

    s.body.unshift(head);
    if (head.x === s.apple.x && head.y === s.apple.y) {
      g.addScore(10); g.sound("coin"); s.eaten += 1;
      if (s.eaten % 5 === 0) { g.nextLevel(); g.sound("level"); }
      placeApple(s, g);
    } else {
      s.body.pop();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    s.body.forEach((p, i) => d.rect(p.x * CELL + 1, Y0 + p.y * CELL + 1, CELL - 2, CELL - 2, i === 0 ? "red" : "ink", { round: 6 }));
  }
};

function reset(s, g) {
  s.body = [{ x: 6, y: 14 }, { x: 5, y: 14 }, { x: 4, y: 14 }];
  s.dir = { x: 1, y: 0 };
  s.next = { x: 1, y: 0 };
  s.wait = 0;
  placeApple(s, g);
}

function placeApple(s, g) {
  for (let tries = 0; tries < 200; tries++) {
    const a = { x: g.randInt(0, COLS - 1), y: g.randInt(0, ROWS - 1) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = a; return; }
  }
}

