// Autobahn-Flitzer (nur Spiel-API, keine Importe): roter Sportwagen auf der Autobahn, Autos ueberholen, nicht anfahren.
const PY = 540;
const EMO = ["🚙", "🚌", "🚚", "🚕"];

export default {
  title: "Autobahn-Flitzer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return { px: 163, speed: 5, scroll: 0, cars: [], spawn: 40, safe: 0, passed: 0, t: 0 };
  },

  update(s, input, g) {
    // Gas und Bremse; ohne Eingabe kehrt tempo zu 5 zurueck
    if (input.up) s.speed = Math.min(9, s.speed + 0.05);
    else if (input.down) s.speed = Math.max(3, s.speed - 0.1);
    else if (s.speed > 5) s.speed = Math.max(5, s.speed - 0.02);
    else if (s.speed < 5) s.speed = Math.min(5, s.speed + 0.02);

    // Lenken innerhalb der Strasse
    if (input.left) s.px -= 4;
    if (input.right) s.px += 4;
    s.px = g.clamp(s.px, 36, g.W - 70);

    // Strassenmarkierung scrollt
    s.scroll = (s.scroll + s.speed) % 40;

    s.t += 1;
    if (s.safe > 0) s.safe -= 1;

    // Zeitlimit: Strecke geschafft
    if (s.t >= 3000) { g.win(); return; }

    // Spawn oben in einer freien Spur
    s.spawn -= 1;
    if (s.spawn <= 0) {
      const lane = g.randInt(0, 2);
      const x = 80 + lane * 100 - 17;
      let blocked = false;
      for (const c of s.cars) if (c.x === x && c.y < 120) blocked = true;
      if (!blocked && s.cars.length < 8) {
        s.cars.push({ x: x, y: -70, w: 34, h: 60, v: g.randInt(2, 4) + 0.3 * g.level, e: g.randInt(0, 3) });
      }
      s.spawn = gap(g);
    }

    // Relative Bewegung: positiv = nach unten
    for (const c of s.cars) c.y += s.speed - c.v;

    // Kollision, Ueberholen, Entfernen
    const me = { x: s.px + 5, y: PY + 5, w: 24, h: 50 };
    const keep = [];
    for (const c of s.cars) {
      const box = { x: c.x, y: c.y, w: c.w, h: c.h };
      if (s.safe === 0 && g.hit(me, box)) {
        g.sound("hurt");
        g.loseLife();
        s.safe = 90;
        continue;
      }
      if (c.y > g.H + 80) {
        g.addScore(10 * g.level);
        g.sound("coin");
        s.passed += 1;
        if (s.passed % 10 === 0) { g.nextLevel(); g.sound("level"); }
        continue;
      }
      if (c.y < -120) continue;
      keep.push(c);
    }
    s.cars = keep;
  },

  draw(s, d, g) {
    d.clear("ink");
    // Fahrbahnrand
    d.line(30, g.TOP, 30, g.H, "cream", 3);
    d.line(330, g.TOP, 330, g.H, "cream", 3);
