// Felsen-Flieger: Raumschiff dreht sich, schiebt sich mit Schub voran und schiesst Lichtstrahlen auf Felsen.
// Felsen zerbrechen in kleinere Stuecke. Alle Raender sind offen (Umbruch). Keine Importe.
const TOP = 48, SPAN = 592, W = 360;
const RADIUS = { 3: 28, 2: 18, 1: 10 };
const POINTS = { 3: 20, 2: 50, 1: 100 };
const STARS = [[30, 90], [120, 70], [250, 120], [330, 200], [60, 260], [200, 300], [310, 380], [90, 450], [260, 520], [40, 600], [170, 610], [340, 560]];

export default {
  title: "Felsen-Flieger",
  controls: ["left", "right", "up", "fire"],
  lives: 3,

  init(g) {
    const s = { ship: { x: 180, y: 344, a: 0, vx: 0, vy: 0 }, shots: [], rocks: [], safe: 60, cool: 0, wave: 0 };
    spawnWave(s, g);
    return s;
  },

  update(s, input, g) {
    const ship = s.ship;

    // Schiff: drehen, Schub, Reibung, Geschwindigkeit begrenzen, bewegen mit Umbruch
    if (input.left) ship.a -= 4;
    if (input.right) ship.a += 4;
    ship.a = ((ship.a % 360) + 360) % 360;
    if (input.up) {
      ship.vx += g.sin(ship.a) * 0.15;
      ship.vy -= g.cos(ship.a) * 0.15;
    }
    ship.vx *= 0.99;
    ship.vy *= 0.99;
    const sp = Math.sqrt(ship.vx * ship.vx + ship.vy * ship.vy);
    if (sp > 5) { ship.vx = ship.vx * 5 / sp; ship.vy = ship.vy * 5 / sp; }
    ship.x = wrap(ship.x + ship.vx, 0, W);
    ship.y = wrap(ship.y + ship.vy, TOP, SPAN);

    // Schuesse erzeugen
    if (s.cool > 0) s.cool -= 1;
    if ((input.firePressed || input.fire) && s.cool === 0 && s.shots.length < 5) {
      s.shots.push({
        x: ship.x + g.sin(ship.a) * 16, y: ship.y - g.cos(ship.a) * 16,
        vx: g.sin(ship.a) * 7, vy: -g.cos(ship.a) * 7, life: 55, r: 3
      });
      s.cool = 12;
      g.sound("shoot");
    }
    for (const sh of s.shots) {
      sh.x = wrap(sh.x + sh.vx, 0, W);
      sh.y = wrap(sh.y + sh.vy, TOP, SPAN);
      sh.life -= 1;
    }

    // Felsen bewegen
    for (const r of s.rocks) {
      r.x = wrap(r.x + r.vx, 0, W);
      r.y = wrap(r.y + r.vy, TOP, SPAN);
      r.rot = (r.rot + 2) % 360;
    }
    // Alle 120 Frames: ein zufaelliger Fels driftet ein wenig auf das Schiff zu
    if (g.frame % 120 === 0 && s.rocks.length > 0) {
      const r = s.rocks[g.randInt(0, s.rocks.length - 1)];
      const dx = ship.x - r.x, dy = ship.y - r.y;
      const len = Math.sqrt(dx * dx + dy * dy);
      if (len > 0) {
        r.vx += dx / len * 0.15;
        r.vy += dy / len * 0.15;
        const rs = Math.sqrt(r.vx * r.vx + r.vy * r.vy);
        if (rs > 4.5) { r.vx = r.vx * 4.5 / rs; r.vy = r.vy * 4.5 / rs; }
      }
    }

    // Schuss gegen Fels
    const newRocks = [];
    for (const sh of s.shots) {
      if (sh.dead) continue;
      for (const r of s.rocks) {
        if (r.dead) continue;
        if (g.hit({ x: sh.x, y: sh.y, r: sh.r }, { x: r.x, y: r.y, r: RADIUS[r.size] })) {
          sh.dead = true;
          r.dead = true;
          g.sound("pop");
          g.addScore(POINTS[r.size] * g.level);
          if (r.size > 1) {
            for (let k = 0; k < 2; k++) {
              if (s.rocks.length + newRocks.length >= 30) break;
              newRocks.push(makeRock(g, r.x, r.y, r.size - 1, 0.9 + 0.25 * g.level));
            }
          }
          break;
        }
      }
    }
    s.shots = s.shots.filter((sh) => !sh.dead && sh.life > 0);
    s.rocks = s.rocks.filter((r) => !r.dead).concat(newRocks);

    // Schiff gegen Fels
    if (s.safe > 0) s.safe -= 1;
    if (s.safe === 0) {
      const hitRock = s.rocks.some((r) => g.hit({ x: ship.x, y: ship.y, r: 14 }, { x: r.x, y: r.y, r: RADIUS[r.size] }));
      if (hitRock) {
        g.sound("hurt");
        g.loseLife();
        ship.x = 180; ship.y = 344; ship.vx = 0; ship.vy = 0;
        s.safe = 90;
        return;
      }
    }

    // Welle geschafft
    if (s.rocks.length === 0) {
      if (g.level >= 6) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      spawnWave(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("ink");
    for (const p of STARS) d.circle(p[0], p[1], 1.5, "cream");
    for (const r of s.rocks) d.emoji("🪨", r.x, r.y, RADIUS[r.size] * 2);
    for (const sh of s.shots) d.circle(sh.x, sh.y, sh.r, "yellow");
    const ship = s.ship;
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      const ex = ship.x + g.sin(ship.a) * 22;
      const ey = ship.y - g.cos(ship.a) * 22;
      d.line(ship.x, ship.y, ex, ey, "yellow", 3);
      d.emoji("🚀", ship.x, ship.y, 30);
    }
  }
};

function wrap(v, lo, span) {
  while (v < lo) v += span;
  while (v >= lo + span) v -= span;
  return v;
}

function makeRock(g, x, y, size, speed) {
  const ang = g.randInt(0, 359);
  return { x, y, vx: g.sin(ang) * speed, vy: g.cos(ang) * speed, size, rot: 0 };
}

function spawnWave(s, g) {
  s.wave += 1;
  const n = 3 + g.level;
  for (let i = 0; i < n; i++) {
    let x = 0, y = 0, ok = false;
    for (let t = 0; t < 30 && !ok; t++) {
      const side = g.randInt(0, 3);
      if (side === 0) { x = 0; y = TOP + g.random() * SPAN; }
      else if (side === 1) { x = W - 1; y = TOP + g.random() * SPAN; }
      else if (side === 2) { y = TOP; x = g.random() * W; }
      else { y = TOP + SPAN - 1; x = g.random() * W; }
      if (g.dist({ x, y }, s.ship) >= 120) ok = true;
    }
    if (ok) s.rocks.push(makeRock(g, x, y, 3, 0.5 + 0.2 * g.level));
  }
}

