// Wasserballon-Duell (nur Spiel-API, keine Importe). Der Spieler (Pinguin) wirft Wasserballons nach oben
// auf den Computer-Gegner (Frosch), der zurueckwirft. Keine Gewalt: nur Wasser und Tropfen.
export default {
  title: "Wasserballon-Duell",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    return {
      me: { x: 160, y: 570, w: 40, h: 40 },
      foe: { x: 160, y: 80, w: 40, h: 40, dir: 1, cool: 60, wet: 0 },
      mine: [],
      theirs: [],
      cool: 0,
      safe: 0,
      foeFlash: 0,
      myFlash: 0
    };
  },

  update(s, input, g) {
    const me = s.me;
    const foe = s.foe;

    // Timer herunterzaehlen
    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;
    if (s.foeFlash > 0) s.foeFlash -= 1;
    if (s.myFlash > 0) s.myFlash -= 1;
    if (foe.cool > 0) foe.cool -= 1;

    // Spieler bewegen
    if (input.left) me.x -= 4;
    if (input.right) me.x += 4;
    me.x = g.clamp(me.x, 4, g.W - 44);

    // Gegner bewegen: seitlich, am Rand umkehren, zufaellig auch
    foe.x += foe.dir * (1.5 + 0.4 * g.level);
    if (foe.x <= 8) { foe.x = 8; foe.dir = 1; }
    else if (foe.x >= g.W - 48) { foe.x = g.W - 48; foe.dir = -1; }
    if (g.random() < 0.01) foe.dir = -foe.dir;

    // Gegner wirft: zielt auf den Spieler oder wirft zufaellig
    if (foe.cool === 0 && (Math.abs(foe.x - me.x) < 60 || g.random() < 0.02)) {
      s.theirs.push({ x: foe.x + 20, y: foe.y + 44, r: 8 });
      foe.cool = Math.max(25, 70 - 8 * g.level) + g.randInt(0, 20);
    }

    // Eigener Wurf
    if ((input.fire || input.firePressed) && s.cool === 0 && s.mine.length < 3) {
      s.mine.push({ x: me.x + 20, y: 560, r: 8 });
      s.cool = 15;
      g.sound("shoot");
    }

    // Ballons bewegen
    for (const m of s.mine) m.y -= 8;
    const fall = 3 + 0.5 * g.level;
    for (const t of s.theirs) t.y += fall;

    // Ballons gegeneinander: beide verschwinden
    for (const m of s.mine) {
      for (const t of s.theirs) {
        if (!m.gone && !t.gone && g.hit(m, t)) {
          m.gone = true;
          t.gone = true;
          g.sound("hit");
          break;
        }
      }
    }

    // Eigene Ballons treffen den Gegner
    for (const m of s.mine) {
      if (!m.gone && g.hit(m, foe)) {
        m.gone = true;
        foe.wet += 1;
        s.foeFlash = 30;
        g.addScore(10 * g.level);
        g.sound("pop");
        if (foe.wet >= 3) {
          g.addScore(50);
          g.nextLevel();
          g.sound("level");
          foe.wet = 0;
          s.mine = [];
          s.theirs = [];
          break;
        }
      }
    }

    // Gegner-Ballons treffen den Spieler
    for (const t of s.theirs) {
      if (!t.gone && s.safe === 0 && g.hit(t, me)) {
        t.gone = true;
        s.safe = 60;
        s.myFlash = 30;
        g.sound("hurt");
        g.loseLife();
        break;
      }
    }

    // Aufraeumen: Entfernte und Ballons ausserhalb des Feldes raus
    s.mine = s.mine.filter((m) => !m.gone && m.y >= g.TOP && m.y <= g.H);
    s.theirs = s.theirs.filter((t) => !t.gone && t.y >= g.TOP && t.y <= g.H);
  },

  draw(s, d, g) {
    d.clear("cream");

    // Gestrichelte Trennlinie
    for (let x = 0; x < g.W; x += 24) d.line(x, 330, x + 12, 330, "ink", 2);

    // Ballons
