// Huhn im Flug (nur Spiel-API, keine Importe): Das Huhn ist staendig im Flug und sinkt durch die Schwerkraft.
// Ein Tippen oder die Feuertaste laesst es flattern. Durch die Luecken der Roehren fliegen gibt Punkte.
const GRAV = 0.35, FLAP = -6.5, MAXFALL = 8, PIPE_W = 52, FLOOR_Y = 620;

export default {
  title: "Huhn im Flug",
  controls: ["fire"],
  lives: 3,

  init(g) {
    return { hen: { x: 90, y: 300, w: 26, h: 26, vy: 0 }, pipes: [], spawn: 0, safe: 0, count: 0 };
  },

  update(s, input, g) {
    const h = s.hen;
    if (s.safe > 0) s.safe -= 1;

    // 1) Flattern
    if (input.firePressed) { h.vy = FLAP; g.sound("jump"); }

    // 2) Schwerkraft
    h.vy = Math.min(h.vy + GRAV, MAXFALL);
    h.y += h.vy;

    // 3) Roehren: spawnen, bewegen, aufraeumen
    const speed = Math.min(4, 2 + 0.2 * g.level);
    const gap = Math.max(120, 170 - 8 * (g.level - 1));
    const last = s.pipes[s.pipes.length - 1];
    if (!last || last.x < g.W - 190) {
      const gapY = s.spawn === 0 ? g.randInt(200, 330) : g.randInt(g.TOP + 50, g.H - 80 - gap);
      s.pipes.push({ x: g.W, gapY: gapY, gap: gap, passed: false });
      s.spawn += 1;
    }
    for (const p of s.pipes) p.x -= speed;
    s.pipes = s.pipes.filter((p) => p.x >= -60);

    // 4) Punkte: Roehre ganz hinter dem Huhn
    for (const p of s.pipes) {
      if (!p.passed && p.x + PIPE_W < h.x) {
        p.passed = true;
        s.count += 1;
        g.addScore(1);
        g.sound("coin");
        if (s.count % 5 === 0) { g.nextLevel(); g.sound("level"); }
      }
    }

    // 5) Kollision: Roehren, Decke, Boden
    if (s.safe === 0) {
      let hurt = h.y < g.TOP || h.y + h.h > FLOOR_Y;
      for (const p of s.pipes) {
        if (hurt) break;
        if (g.hit(h, { x: p.x, y: 0, w: PIPE_W, h: p.gapY })) hurt = true;
        else if (g.hit(h, { x: p.x, y: p.gapY + p.gap, w: PIPE_W, h: g.H - (p.gapY + p.gap) })) hurt = true;
      }
      if (hurt) {
        g.sound("hurt");
        g.loseLife();
        h.x = 90; h.y = 300; h.vy = 0;
        s.pipes = [];
        s.spawn = 0;
        s.safe = 60;
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    // Wolken als Deko, nur aus g.frame berechnet
    for (let i = 0; i < 3; i++) {
      const cx = g.W + 40 - (((g.frame * 0.5) + i * 130) % (g.W + 80));
      d.emoji("☁️", cx, 90 + i * 110, 40);
    }

    // Roehren mit Kappen
    for (const p of s.pipes) {
      d.rect(p.x, 0, PIPE_W, p.gapY, "yellow", { line: true, shadow: false });
      d.rect(p.x - 5, p.gapY - 16, 62, 16, "ink");
      const by = p.gapY + p.gap;
      d.rect(p.x, by, PIPE_W, g.H - by, "yellow", { line: true, shadow: false });
      d.rect(p.x - 5, by, 62, 16, "ink");
    }

    // Boden
    d.rect(0, FLOOR_Y, g.W, 20, "yellow", { line: true });

    // Huhn (blinkt waehrend Schutzzeit)
    const h = s.hen;
    if (s.safe === 0 || ((s.safe >> 2) % 2) === 0) d.emoji("🐔", h.x + 13, h.y + 13, 34);
  }
};

