// Dach-Katze (nur Spiel-API, keine Importe). Die Katze springt von Dach zu Dach, sammelt Fischgraeten
// und weicht Moewen aus. Fallen vom Dach kostet ein Leben. Zeitlimit pro Level: 3000 Frames.
const GRAV = 0.5, JUMP = -10.5, FLOOR = 610, LIMIT = 3000, ROOF_COUNT = 6;

export default {
  title: "Dach-Katze",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 20, y: 0, w: 22, h: 28, vx: 0, vy: 0, ground: true },
      plats: [], fish: [], gulls: [],
      flag: { x: 0, y: 0, w: 24, h: 30 },
      safe: 0, timer: 0
    };
    build(s, g);
    return s;
  },

  update(s, input, g) {
    const me = s.me;
    s.timer += 1;
    if (s.timer > LIMIT) { g.gameOver(); return; }

    me.vx = input.left ? -3 : input.right ? 3 : 0;
    if (input.up && me.ground) { me.vy = JUMP; me.ground = false; g.sound("jump"); }
    me.vy = Math.min(me.vy + GRAV, 12);
    const oldBottom = me.y + me.h;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);
    me.y += me.vy;
    me.ground = false;
    if (me.vy >= 0) {
      for (const p of s.plats) {
        const over = me.x + me.w > p.x && me.x < p.x + p.w;
        if (over && oldBottom <= p.y && me.y + me.h >= p.y) {
          me.y = p.y - me.h; me.vy = 0; me.ground = true;
        }
      }
    }
    if (s.safe > 0) s.safe -= 1;

    // Fischgraeten einsammeln
    for (const f of s.fish) {
      if (!f.got && g.hit(me, f)) { f.got = true; g.addScore(10); g.sound("coin"); }
    }
    s.fish = s.fish.filter((f) => !f.got);

    // Moewen fliegen hin und her, Wendung am Rand
    for (const gull of s.gulls) {
      gull.x += gull.vx;
      if (gull.x < 0 || gull.x + gull.w > g.W) gull.vx = -gull.vx;
      gull.x = g.clamp(gull.x, 0, g.W - gull.w);
      if (s.safe === 0 && g.hit(me, gull)) { g.sound("hurt"); g.loseLife(); respawn(s); return; }
    }

    // Ziel: Fahne auf dem obersten Dach
    if (g.hit(me, s.flag)) {
      g.addScore(50); g.nextLevel(); g.sound("level");
      build(s, g);
      return;
    }

    // Vom Dach gefallen
    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); respawn(s); }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.circle(300, 110, 28, "yellow", { line: true });
    d.rect(0, 622, g.W, 18, "ink");
    for (const p of s.plats) {
      d.rect(p.x, p.y, p.w, p.h, "ink", { round: 4, shadow: true, line: true });
      d.rect(p.x + 2, p.y, p.w - 4, 4, "yellow", { round: 2 });
    }
    for (const f of s.fish) d.emoji("🐟", f.x + 9, f.y + 7, 22);
    for (const gull of s.gulls) d.emoji("🐦", gull.x + 12, gull.y + 10, 26);
    d.emoji("🚩", s.flag.x + 12, s.flag.y + 15, 30);
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🐱", s.me.x + 11, s.me.y + 14, 30);
    }
  }
};

// Baut ein Level: 6 Daecher in Stufen nach oben, Fische, Moewen, Fahne.
function build(s, g) {
  const lvl = g.level;
  // Maximale Luecke begrenzt, damit der Sprung (JUMP, GRAV, vx 3) auch erreichbar bleibt.
  const maxGap = Math.min(70 + 5 * lvl, 90);
  s.plats = [{ x: 0, y: 600, w: 140, h: 18 }];
  let prev = s.plats[0];
  for (let i = 1; i < ROOF_COUNT; i++) {
    const w = g.randInt(70, 110);
    const gap = g.randInt(20, maxGap);
    const y = 600 - i * 88;
    const rightX = prev.x + prev.w + gap;
    const leftX = prev.x - gap - w;
    const rightOk = rightX + w <= g.W - 4;
    const leftOk = leftX >= 4;
    let x;
    if (rightOk && (!leftOk || g.random() < 0.5)) x = rightX;
    else if (leftOk) x = leftX;
    else x = g.clamp(rightX, 4, g.W - w - 4);
    s.plats.push({ x: x, y: y, w: w, h: 18 });
    prev = s.plats[i];
  }

  s.fish = [];
  for (let i = 1; i < ROOF_COUNT; i++) {
    const p = s.plats[i];
    s.fish.push({ x: p.x + p.w / 2 - 9, y: p.y - 26, w: 18, h: 14, got: false });
  }

  s.gulls = [];
  const count = Math.min(1 + lvl, 4);
  for (let k = 0; k < count; k++) {
    const y = lvl >= 2 ? s.plats[g.randInt(1, ROOF_COUNT - 1)].y - 22 : 300;
    const dir = g.random() < 0.5 ? 1 : -1;
    s.gulls.push({ x: g.randInt(0, g.W - 24), y: y, w: 24, h: 20, vx: dir * (1 + 0.3 * lvl) });
  }

  const top = s.plats[ROOF_COUNT - 1];
  s.flag = { x: top.x + top.w / 2 - 12, y: top.y - 30, w: 24, h: 30 };
  s.timer = 0;
  respawn(s);
}

// Katze zurueck auf das Start-Dach, kurz unverwundbar.
function respawn(s) {
  const start = s.plats[0];
  s.me.x = 20;
  s.me.y = start.y - s.me.h;
  s.me.vx = 0;
  s.me.vy = 0;
  s.me.ground = true;
  s.safe = 60;
}

