  s.me.ground = true;
  s.safe = 60;
}

// Dach-Katze (nur Spiel-API, keine Importe). Die Katze springt von Dach zu Dach, sammelt Fischgraeten
// und weicht Moewen aus. Fallen vom Dach kostet ein Leben. Das Spiel endet nur, wenn die Leben weg sind.
const GRAV = 0.5, JUMP = -10.5, FLOOR = 610, ROOF_COUNT = 6, LEVEL_FRAMES = 3000;

export default {
  title: "Dach-Katze",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 20, y: 0, w: 22, h: 28, vx: 0, vy: 0, ground: true },
      plats: [], fish: [], gulls: [],
      flag: { x: 0, y: 0, w: 24, h: 30 },
      safe: 0,
      timer: 0
    };
    build(s, g);
    return s;
  },

  update(s, input, g) {
    const me = s.me;

    me.vx = input.left ? -3 : input.right ? 3 : 0;
    if (input.up && me.ground) { me.vy = JUMP; me.ground = false; g.sound("jump"); }
    me.vy = Math.min(me.vy + GRAV, 12);
    const oldBottom = me.y + me.h;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);
    me.y += me.vy;
    me.ground = false;
    if (me.vy >= 0) {
      for (const p of s.plats) {
        const over = me.x + me.w > p.x && me.x < p.x + p.w;
        if (over && oldBottom <= p.y && me.y + me.h >= p.y) {
          me.y = p.y - me.h; me.vy = 0; me.ground = true;
        }
      }
    }
    if (s.safe > 0) s.safe -= 1;

    // Zeitlimit pro Level (Sicherheit, damit das Spielende erreichbar ist)
    s.timer += 1;
    if (s.timer > LEVEL_FRAMES) { g.gameOver(); return; }

    // Fischgraeten einsammeln
    for (const f of s.fish) {
      if (!f.got && g.hit(me, f)) { f.got = true; g.addScore(10); g.sound("coin"); }
    }
    s.fish = s.fish.filter((f) => !f.got);

    // Moewen fliegen hin und her, Wendung am Rand
    for (const gull of s.gulls) {
      gull.x += gull.vx;
      if (gull.x < 0 || gull.x + gull.w > g.W) gull.vx = -gull.vx;
      gull.x = g.clamp(gull.x, 0, g.W - gull.w);
      if (s.safe === 0 && g.hit(me, gull)) { g.sound("hurt"); g.loseLife(); respawn(s); return; }
    }

    // Ziel: Fahne auf dem obersten Dach
    if (g.hit(me, s.flag)) {
      g.addScore(50); g.nextLevel(); g.sound("level");
      build(s, g);
      return;
    }

    // Vom Dach gefallen
    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); respawn(s); }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.circle(300, 110, 28, "yellow", { line: true });
    d.rect(0, 622, g.W, 18, "ink");
    for (const p of s.plats) {
      d.rect(p.x, p.y, p.w, p.h, "ink", { round: 4, shadow: true, line: true });
      d.rect(p.x + 2, p.y, p.w - 4, 4, "yellow", { round: 2 });
    }
    for (const f of s.fish) drawBone(d, f.x + 9, f.y + 7);
    for (const gull of s.gulls) d.emoji("🐦", gull.x + 12, gull.y + 10, 26);
    d.emoji("🚩", s.flag.x + 12, s.flag.y + 15, 30);
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🐱", s.me.x + 11, s.me.y + 14, 30);
    }
  }
};

// Fischgraete aus Formen: Mittelgraete, Rippen oben und unten, Kopf.
function drawBone(d, cx, cy) {
  d.line(cx - 8, cy, cx + 6, cy, "ink", 2);
  for (let dx = -6; dx <= 2; dx += 4) {
    d.line(cx + dx, cy, cx + dx + 3, cy - 5, "ink", 2);
    d.line(cx + dx, cy, cx + dx + 3, cy + 5, "ink", 2);
  }
  d.circle(cx + 8, cy, 3, "ink");
}

// Baut ein Level: 6 Daecher in Stufen nach oben, Graeten, Moewen, Fahne.
// Level 1 ist leicht: Luecken hoechstens 50 px, keine Moewen, keine Graete auf dem obersten Dach
// (die Fahne liegt dort). Ab Level 2 steigt die Schwierigkeit: Moewen, groessere Luecken
// (bis 130 px, sprungerreichbar).
function build(s, g) {
  const lvl = g.level;
  const maxGap = lvl <= 1 ? 50 : Math.min(60 + 10 * lvl, 130);
  s.timer = 0;
  s.plats = [{ x: 0, y: 600, w: 140, h: 18 }];
  let prev = s.plats[0];
  for (let i = 1; i < ROOF_COUNT; i++) {
    const w = g.randInt(70, 110);
    const gap = g.randInt(20, maxGap);
    const y = 600 - i * 88;
    const rightX = prev.x + prev.w + gap;
    const leftX = prev.x - gap - w;
    const rightOk = rightX + w <= g.W - 4;
    const leftOk = leftX >= 4;
    let x;
    if (rightOk && (!leftOk || g.random() < 0.5)) x = rightX;
    else if (leftOk) x = leftX;
    else x = g.clamp(rightX, 4, g.W - w - 4);
    s.plats.push({ x: x, y: y, w: w, h: 18 });
    prev = s.plats[i];
  }

  // Graeten nur auf Daechern 1 bis ROOF_COUNT-2, das oberste Dach bleibt fuer die Fahne frei
  s.fish = [];
  for (let i = 1; i <= ROOF_COUNT - 2; i++) {
    const p = s.plats[i];
    s.fish.push({ x: p.x + p.w / 2 - 9, y: p.y - 26, w: 18, h: 14, got: false });
  }

  s.gulls = [];
  const count = Math.min(Math.max(lvl - 1, 0), 4);
  const speed = 0.8 + 0.25 * (lvl - 1);
  for (let k = 0; k < count; k++) {
    const y = s.plats[g.randInt(1, ROOF_COUNT - 1)].y - 22;
    const dir = g.random() < 0.5 ? 1 : -1;
    s.gulls.push({ x: g.randInt(0, g.W - 24), y: y, w: 24, h: 20, vx: dir * speed });
  }

  const top = s.plats[ROOF_COUNT - 1];
  s.flag = { x: top.x + top.w / 2 - 12, y: top.y - 30, w: 24, h: 30 };
  respawn(s);
}

// Katze zurueck auf das Start-Dach, kurz unverwundbar.
function respawn(s) {
  const start = s.plats[0];
  s.me.x = 20;
  s.me.y = start.y - s.me.h;
  s.me.vx = 0;
  s.me.vy = 0;
  s.me.ground = true;
  s.safe = 60;
}

// Tennis-Duell (nur Spiel-API, keine Importe): Du spielst unten, der Computer oben.
// Der Ball prallt an Seitenwaenden und Schlaegern ab. Verpasst du ihn, verlierst du ein Leben.
// Verpasst der Computer ihn, gibt es Punkte. Nach 9 gewonnenen Ballwechseln ist das Spiel gewonnen.
const CX = 180;   // Mitte des Feldes (x)
const CY = 344;   // Mitte des Feldes (y)

export default {
  title: "Tennis-Duell",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 150, y: 590, w: 60, h: 12 },
      cpu: { x: 150, y: 70, w: 60, h: 12 },
      ball: { x: CX, y: CY, r: 8, vx: 0, vy: 4 },
      wait: 45,
      rally: 0,
      won: 0,
      err: 0
    };
    serve(s, g);
    return s;
  },

  update(s, input, g) {
    const me = s.me;
    const cpu = s.cpu;
    const b = s.ball;

    // 1) Spieler
    if (input.left) me.x -= 6;
    if (input.right) me.x += 6;
    me.x = g.clamp(me.x, 4, g.W - me.w - 4);

    // 2) Computer: Reaktionsfehler alle 40 Frames neu, Ziel Mitte wenn Ball wegfliegt
    if (g.frame % 40 === 0) s.err = g.randInt(-25, 25);
    const away = b.vy > 0;
    const target = away
      ? CX - cpu.w / 2
      : b.x + s.err - cpu.w / 2;
    const step = (2.6 + 0.3 * g.level) * (away ? 0.5 : 1);
    const dx = target - cpu.x;
    if (Math.abs(dx) <= step) cpu.x = target;
    else cpu.x += Math.sign(dx) * step;
    cpu.x = g.clamp(cpu.x, 4, g.W - cpu.w - 4);

    // 3) Ball: beim Aufschlag steht er still
    if (s.wait > 0) {
      s.wait -= 1;
      return;
    }
    b.x += b.vx;
    b.y += b.vy;
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - b.r) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }

    // 4) Schlaeger-Treffer
    if (b.vy > 0 && g.hit(b, me)) {
      b.y = me.y - b.r;
      b.vy = -Math.min(Math.abs(b.vy) * 1.04, 11);
      b.vx = aim(b, me);
      s.rally += 1;
      g.addScore(1);
      g.sound("jump");
    } else if (b.vy < 0 && g.hit(b, cpu)) {
      b.y = cpu.y + cpu.h + b.r;
      b.vy = Math.min(Math.abs(b.vy), 11);
      b.vx = aim(b, cpu);
      g.sound("hit");
    }
    fixSpeed(b);

    // 5) Ball raus
    if (b.y > g.H + 10) {
      g.sound("hurt");
      g.loseLife();
      me.x = 150;
      serve(s, g);
      return;
    }
    if (b.y < g.TOP - 10) {
      g.addScore(10 * g.level);
      g.sound("coin");
      s.won += 1;
      if (s.won >= 9) { g.win(); return; }
      if (s.won % 3 === 0) { g.nextLevel(); g.sound("level"); }
      serve(s, g);
      return;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    // Mittellinie aus kurzen Strichen
    for (let x = 0; x < 360; x += 24) d.rect(x + 4, CY - 2, 14, 4, "yellow");
    // Seitenwaende
    d.line(0, 48, 0, 640, "ink", 3);
    d.line(360, 48, 360, 640, "ink", 3);
    // Computer-Schlaeger und Roboter
    d.rect(s.cpu.x, s.cpu.y, s.cpu.w, s.cpu.h, "ink", { round: 6, shadow: true });
    d.emoji("🤖", s.cpu.x + s.cpu.w / 2, 58, 22);
    // Spieler-Schlaeger
    d.rect(s.me.x, s.me.y, s.me.w, s.me.h, "red", { round: 6, shadow: true, line: true });
    // Ball (blinkt beim Aufschlag)
    if (!(s.wait > 0 && (g.frame >> 2) % 2 === 0)) {
      d.emoji("🎾", s.ball.x, s.ball.y, 22);
    }
  }
};

// Neuer Aufschlag: Ball in der Mitte, nach unten, nach 45 Frames Wartezeit
function serve(s, g) {
  const sp = 4 + 0.5 * (g.level - 1);
  let vx = g.randInt(-2, 2);
  if (vx === 0) vx = 1;
  s.ball = { x: CX, y: CY, r: 8, vx: vx, vy: sp };
  s.wait = 45;
  s.rally = 0;
}

// Richtung abhaengig vom Treffpunkt auf dem Schlaeger
function aim(b, p) {
  const v = (b.x - (p.x + p.w / 2)) / (p.w / 2) * 5;
  return Math.max(-7, Math.min(7, v));
}

// Geschwindigkeit begrenzen: nie waagerecht, nie zu schnell
function fixSpeed(b) {
  b.vx = Math.max(-7, Math.min(7, b.vx));
  if (Math.abs(b.vy) < 3) b.vy = b.vy < 0 ? -3 : 3;
  if (Math.abs(b.vy) > 11) b.vy = b.vy < 0 ? -11 : 11;
}

