// Memory-Paare (nur Spiel-API, keine Importe). Sechs Tier-Paare liegen verdeckt auf dem Brett.
// Cursor mit den Pfeilen bewegen, mit fire aufdecken. Passende Paare bleiben offen, sonst gibt es ein Leben weniger.
const SYMS = ["🐶", "🐱", "🐰", "🐸", "🦊", "🐼"];
const COLS = 4, ROWS = 3, CW = 70, CH = 90, GAP = 14, X0 = 19, YS = [150, 254, 358];
const WAIT_FRAMES = 45;

export default {
  title: "Memory-Paare",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    // Doppelte Symbole erzeugen und mit Fisher-Yates mischen
    const syms = [];
    for (const k of SYMS) { syms.push(k); syms.push(k); }
    for (let i = syms.length - 1; i > 0; i--) {
      const j = g.randInt(0, i);
      const t = syms[i]; syms[i] = syms[j]; syms[j] = t;
    }
    const cards = [];
    for (let i = 0; i < COLS * ROWS; i++) {
      const col = i % COLS, row = Math.floor(i / COLS);
      cards.push({ x: X0 + col * (CW + GAP), y: YS[row], w: CW, h: CH, sym: syms[i], state: 0 });
    }
    return {
      cards,
      cur: 0,
      open: [],
      wait: 0,
      found: 0,
      misses: 0,
      prev: { left: false, right: false, up: false, down: false }
    };
  },

  update(s, input, g) {
    // Nur neu gedrueckte Richtungen bewegen den Cursor
    const pr = {
      left: !!input.left && !s.prev.left,
      right: !!input.right && !s.prev.right,
      up: !!input.up && !s.prev.up,
      down: !!input.down && !s.prev.down
    };
    s.prev = { left: !!input.left, right: !!input.right, up: !!input.up, down: !!input.down };

    const col = s.cur % COLS, row = Math.floor(s.cur / COLS);
    if (pr.left && col > 0) s.cur -= 1;
    if (pr.right && col < COLS - 1) s.cur += 1;
    if (pr.up && row > 0) s.cur -= COLS;
    if (pr.down && row < ROWS - 1) s.cur += COLS;
    s.cur = g.clamp(s.cur, 0, COLS * ROWS - 1);

    // Nach einem Fehlversuch: Karten nach der Wartezeit wieder verdecken
    if (s.wait > 0) {
      s.wait -= 1;
      if (s.wait === 0) {
        for (const i of s.open) s.cards[i].state = 0;
        s.open = [];
      }
    }

    // Aufdecken mit fire (nur wenn nichts wartet)
    if (input.firePressed && s.wait === 0) {
      const c = s.cards[s.cur];
      if (c.state === 0 && s.open.length < 2) {
        c.state = 1;
        s.open.push(s.cur);
        g.sound("jump");
        if (s.open.length === 2) {
          const a = s.cards[s.open[0]], b = s.cards[s.open[1]];
          if (a.sym === b.sym) {
            a.state = 2; b.state = 2;
            s.open = [];
            s.found += 1;
            g.addScore(20);
            g.sound("coin");
            if (s.found === SYMS.length) {
              g.addScore(50);
              g.sound("win");
              g.win();
              return;
            }
          } else {
            s.misses += 1;
            s.wait = WAIT_FRAMES;
            g.sound("hurt");
            g.loseLife();
          }
        }
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Paare gefunden " + s.found + "/6", g.W / 2, 100, { size: 20, color: "ink", align: "center" });

    for (let i = 0; i < s.cards.length; i++) {
      const c = s.cards[i];
      if (c.state === 0) {
        d.rect(c.x, c.y, c.w, c.h, "yellow", { round: 10, shadow: true, line: true });
        d.text("?", c.x + c.w / 2, c.y + c.h / 2 + 12, { size: 36, color: "ink", align: "center" });
      } else if (c.state === 1) {
        d.rect(c.x, c.y, c.w, c.h, "cream", { round: 10, line: true });
        d.emoji(c.sym, c.x + c.w / 2, c.y + c.h / 2, 44);
      } else {
        d.rect(c.x, c.y, c.w, c.h, "yellow", { round: 10 });
        d.rect(c.x + 4, c.y + 4, c.w - 8, c.h - 8, "cream", { round: 8 });
        d.emoji(c.sym, c.x + c.w / 2, c.y + c.h / 2, 44);
      }
    }

    // Cursor als roter Rahmen um die aktuelle Karte
    const k = s.cards[s.cur];
    const l = k.x - 4, t = k.y - 4, r = k.x + k.w + 4, b = k.y + k.h + 4;
    d.line(l, t, r, t, "red", 4);
    d.line(l, b, r, b, "red", 4);
    d.line(l, t, l, b, "red", 4);
    d.line(r, t, r, b, "red", 4);
  }
};

