// Kuchen-Stapler (nur Spiel-API, keine Importe). Kuchenstuecke aus 4 Zellen fallen ins Raster.
// Volle Reihen verschwinden. Steuerung: links/rechts bewegen, unten schneller fallen, fire dreht.
// Hinweis: Die Stuecke sind in vier Farben (rot, gelb, schwarz, creme) mit Kuchen-Emojis markiert,
// nicht wirklich bunt (Plattform hat nur die vier Farben).

const COLS = 10, ROWS = 20, CELL = 28, X0 = 40, Y0 = 70;
const COL = ["red", "yellow", "ink", "cream"];
const EMO = ["🍰", "🧁", "🍩", "🍪"];

// Grundformen (I, O, T, S, Z, J, L) als Zellkoordinaten [x, y], Drehungen werden daraus berechnet
const SHAPES = [
  [[0, 1], [1, 1], [2, 1], [3, 1]],
  [[1, 0], [2, 0], [1, 1], [2, 1]],
  [[1, 0], [0, 1], [1, 1], [2, 1]],
  [[1, 0], [2, 0], [0, 1], [1, 1]],
  [[0, 0], [1, 0], [1, 1], [2, 1]],
  [[0, 0], [0, 1], [1, 1], [2, 1]],
  [[2, 0], [0, 1], [1, 1], [2, 1]]
];

function rotCells(c) {
  const r = [];
  let mx = 0, my = 0;
  for (let i = 0; i < c.length; i++) {
    const nx = -c[i][1], ny = c[i][0];
    r.push([nx, ny]);
    if (i === 0 || nx < mx) mx = nx;
    if (i === 0 || ny < my) my = ny;
  }
  return r.map((p) => [p[0] - mx, p[1] - my]);
}

function cellsOf(kind, rot) {
  let c = SHAPES[kind];
  for (let i = 0; i < rot; i++) c = rotCells(c);
  return c;
}

function emptyRow() {
  const row = [];
  for (let i = 0; i < COLS; i++) row.push(0);
  return row;
}

function emptyGrid() {
  const g = [];
  for (let r = 0; r < ROWS; r++) g.push(emptyRow());
  return g;
}

function fits(grid, cells, px, py) {
  for (let i = 0; i < cells.length; i++) {
    const nx = px + cells[i][0], ny = py + cells[i][1];
    if (nx < 0 || nx >= COLS || ny >= ROWS) return false;
    if (ny >= 0 && grid[ny][nx] !== 0) return false;
  }
  return true;
}

export default {
  title: "Kuchen-Stapler",
  controls: ["left", "right", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      grid: emptyGrid(),
      piece: null,
      nextKind: g.randInt(0, 6),
      next: g.randInt(1, 4),
      fall: 0,
      rows: 0,
      move: 0
    };
    spawn(s, g);
    return s;
  },

  update(s, input, g) {
    const p = s.piece;
    const dir = input.left ? -1 : input.right ? 1 : 0;

    // Seitwaerts: sofort bei Druck-Beginn, danach alle 6 Frames
    if (dir !== 0) {
      if (s.move > 0) {
        s.move -= 1;
      } else {
        if (fits(s.grid, cellsOf(p.kind, p.rot), p.x + dir, p.y)) p.x += dir;
        s.move = 6;
      }
    } else {
      s.move = 0;
    }

    // Drehen um 90 Grad, nur wenn frei
    if (input.firePressed) {
      const nr = (p.rot + 1) % 4;
      if (fits(s.grid, cellsOf(p.kind, nr), p.x, p.y)) p.rot = nr;
    }

    // Fallen: Zaehler waechst, down beschleunigt
    s.fall += 1;
    if (input.down) s.fall += 8;
    const th = Math.max(6, 24 - 4 * (g.level - 1));
    if (s.fall >= th) {
      s.fall = 0;
      if (fits(s.grid, cellsOf(p.kind, p.rot), p.x, p.y + 1)) p.y += 1;
      else lock(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(X0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 8, line: true });
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const v = s.grid[r][c];
        if (v !== 0) drawCell(d, c, r, v);
      }
    }
    if (s.piece) {
      const cells = cellsOf(s.piece.kind, s.piece.rot);
      for (let i = 0; i < cells.length; i++) {
        const cx = s.piece.x + cells[i][0], cy = s.piece.y + cells[i][1];
        if (cy >= 0) drawCell(d, cx, cy, s.piece.sort);
      }
    }
    d.emoji(EMO[s.next - 1], 330, 90, 24);
  }
};

function drawCell(d, c, r, sort) {
  const x = X0 + c * CELL, y = Y0 + r * CELL;
  d.rect(x + 1, y + 1, CELL - 2, CELL - 2, COL[sort - 1], { round: 6, line: true });
  d.emoji(EMO[sort - 1], x + CELL / 2, y + CELL / 2, 18);
}

function lock(s, g) {
  const p = s.piece;
  const cells = cellsOf(p.kind, p.rot);
  for (let i = 0; i < cells.length; i++) {
    const nx = p.x + cells[i][0], ny = p.y + cells[i][1];
    if (ny >= 0) s.grid[ny][nx] = p.sort;
  }
  g.addScore(5);
  g.sound("hit");

  // Volle Reihen entfernen, oben neue leere Reihen
  let n = 0;
  const keep = [];
  for (let r = 0; r < ROWS; r++) {
    const row = s.grid[r];
    let full = true;
    for (let c = 0; c < COLS; c++) if (row[c] === 0) { full = false; break; }
    if (full) n += 1;
    else keep.push(row);
  }
  while (keep.length < ROWS) keep.unshift(emptyRow());
  s.grid = keep;

  if (n > 0) {
    g.addScore(100 * n * g.level);
    g.sound("pop");
    const before = Math.floor(s.rows / 5);
    s.rows += n;
    if (Math.floor(s.rows / 5) > before) {
      g.nextLevel();
      g.sound("level");
    }
  }

  spawn(s, g);
}

function spawn(s, g) {
  s.piece = { kind: s.nextKind, rot: 0, x: 3, y: 0, sort: s.next };
  s.nextKind = g.randInt(0, 6);
  s.next = g.randInt(1, 4);
  s.fall = 0;
  s.move = 0;
  const p = s.piece;
  if (!fits(s.grid, cellsOf(p.kind, p.rot), p.x, p.y)) {
    g.sound("hurt");
    g.loseLife();
    s.grid = emptyGrid();
  }
}

