    if (input.down) s.fall += 8;
    const th = Math.max(6, 24 - 4 * (g.level - 1));
    if (s.fall >= th) {
      s.fall = 0;
      if (fits(s.grid, cellsOf(p.kind, p.rot), p.x, p.y + 1)) p.y += 1;
      else lock(s, g);
    }

    // Kuchenboden steigt im Takt von unten (wird mit dem Level schneller)
    s.rise += 1;
    const every = Math.max(20, 50 - 5 * (g.level - 1));
    if (s.rise >= every) {
      s.rise = 0;
      pushRow(s, g);
    }
