}

// Neue Reihe von unten: Stapel rutscht eine Reihe nach oben, unten eine Reihe mit einer Luecke
function pushRow(s, g) {
  const top = s.grid[0];
  for (let c = 0; c < COLS; c++) {
    if (top[c] !== 0) { overflow(s, g); return; }
  }
  s.grid.shift();
  const gap = g.randInt(0, COLS - 1);
  const row = [];
  for (let c = 0; c < COLS; c++) row.push(c === gap ? 0 : g.randInt(1, 4));
  s.grid.push(row);

  // Ein fallendes Stueck wird nach oben geschoben, wenn es sonst im neuen Boden steckt
  const p = s.piece;
  if (!fits(s.grid, cellsOf(p.kind, p.rot), p.x, p.y)) {
    p.y -= 1;
    if (!fits(s.grid, cellsOf(p.kind, p.rot), p.x, p.y)) overflow(s, g);
  }
}

function overflow(s, g) {
  g.sound("hurt");
  g.loseLife();
  s.grid = emptyGrid();
  s.rise = 0;
  spawn(s, g);
}

function lock(s, g) {
  const p = s.piece;
  const cells = cellsOf(p.kind, p.rot);
  for (let i = 0; i < cells.length; i++) {
    const nx = p.x + cells[i][0], ny = p.y + cells[i][1];
    if (ny >= 0) s.grid[ny][nx] = p.sort;
  }
  g.addScore(5);
  g.sound("hit");

  // Volle Reihen entfernen, oben neue leere Reihen
  let n = 0;
  const keep = [];
  for (let r = 0; r < ROWS; r++) {
    const row = s.grid[r];
    let full = true;
    for (let c = 0; c < COLS; c++) if (row[c] === 0) { full = false; break; }
    if (full) n += 1;
    else keep.push(row);
  }
  while (keep.length < ROWS) keep.unshift(emptyRow());
  s.grid = keep;

  if (n > 0) {
    g.addScore(100 * n * g.level);
    g.sound("pop");
    const before = Math.floor(s.rows / 5);
    s.rows += n;
    if (Math.floor(s.rows / 5) > before) {
      g.nextLevel();
      g.sound("level");
    }
  }

  spawn(s, g);
}

function spawn(s, g) {
  s.piece = { kind: s.nextKind, rot: 0, x: 3, y: 0, sort: s.next };
  s.nextKind = g.randInt(0, 6);
  s.next = g.randInt(1, 4);
  s.fall = 0;
  s.move = 0;
  const p = s.piece;
  if (!fits(s.grid, cellsOf(p.kind, p.rot), p.x, p.y)) {
    g.sound("hurt");
    g.loseLife();
    s.grid = emptyGrid();
    s.rise = 0;
  }
}

