        const cx = s.piece.x + cells[i][0], cy = s.piece.y + cells[i][1];
        if (cy >= 0) drawCell(d, cx, cy, s.piece.sort);
      }
    }
    d.emoji(EMO[s.next - 1], 330, 90, 24);
  }
};

function drawCell(d, c, r, sort) {
  const x = X0 + c * CELL, y = Y0 + r * CELL;
  d.rect(x + 1, y + 1, CELL - 2, CELL - 2, COL[sort - 1], { round: 6, line: true });
  d.emoji(EMO[sort - 1], x + CELL / 2, y + CELL / 2, 18);
}

// Stueck ist gesetzt: einsetzen, volle Reihen markieren (Blinken), sonst naechstes Stueck
function lock(s, g) {
  const p = s.piece;
  const cells = cellsOf(p.kind, p.rot);
  for (let i = 0; i < cells.length; i++) {
    const nx = p.x + cells[i][0], ny = p.y + cells[i][1];
    if (ny >= 0) s.grid[ny][nx] = p.sort;
  }
  s.piece = null;
  g.addScore(5);
  g.sound("hit");

  // Volle Reihen sammeln (noch nicht entfernen, erst nach dem Blinken)
  const full = [];
  for (let r = 0; r < ROWS; r++) {
    let isFull = true;
    for (let c = 0; c < COLS; c++) if (s.grid[r][c] === 0) { isFull = false; break; }
    if (isFull) full.push(r);
  }

  if (full.length > 0) {
    s.full = full;
    s.blink = 18;
  } else {
    spawn(s, g);
  }
}

// Volle Reihen entfernen, Punkte vergeben, Level pruefen, naechstes Stueck
function clearFull(s, g) {
  const n = s.full.length;
  const keep = [];
  for (let r = 0; r < ROWS; r++) {
    if (s.full.indexOf(r) < 0) keep.push(s.grid[r]);
  }
  while (keep.length < ROWS) keep.unshift(emptyRow());
  s.grid = keep;
  s.full = [];

  g.addScore(100 * n * g.level);
  g.sound("pop");
  const before = Math.floor(s.rows / 2);
  s.rows += n;
  const after = Math.floor(s.rows / 2);
  if (after > before) {
    for (let k = before; k < after; k++) g.nextLevel();
    g.sound("level");
  }

  spawn(s, g);
}

// Naechstes Stueck oben einsetzen. Passt es nicht, steht der Stapel oben an: Leben weg, Brett leeren.
function spawn(s, g) {
  s.piece = { kind: s.nextKind, rot: 0, x: 3, y: 0, sort: s.next };
  s.nextKind = g.randInt(0, 6);
  s.next = g.randInt(1, 4);
  s.fall = 0;
  s.move = 0;
  const p = s.piece;
  if (!fits(s.grid, cellsOf(p.kind, p.rot), p.x, p.y)) {
    g.sound("hurt");
    g.loseLife();
    s.grid = emptyGrid();
    s.piece.x = 3;
    s.piece.y = 0;
    s.piece.rot = 0;
  }
}

