  title: "Würfel-Rennen bis 100",
  controls: ["fire"],
  lives: 1,

  init(g) {
    return {
      scores: [0, 0, 0, 0],
      turn: 0,
      die: 1,
      shown: 1,
      phase: "wait",
      timer: 0,
      rolls: 0,
      winner: -1,
      waitT: 0,
      gain: 0
    };
  },

  update(s, input, g) {
    // Siegesanzeige: 30 Frames warten, dann Spiel beenden
    if (s.phase === "win") {
      s.timer -= 1;
      if (s.timer <= 0) g.win();
      return;
    }

    // Frame-Limit: wer vorne liegt, gewinnt
    if (s.winner < 0 && g.frame >= FRAME_LIMIT) {
      let leader = 0;
      for (let i = 1; i < 4; i++) if (s.scores[i] > s.scores[leader]) leader = i;
      s.winner = leader;
      s.phase = "win";
      s.timer = WIN_T;
      g.sound("win");
      return;
    }

