      s.timer -= 1;
      if (s.timer > 0) return;
      if (s.scores[s.turn] >= TARGET) {
        s.winner = s.turn;
        s.phase = "win";
        s.timer = WIN_T;
        g.sound("win");
        return;
      }
      s.turn = (s.turn + 1) % 4;
      s.phase = "wait";
      s.waitT = 0;
    }
  },

  draw(s, d) {
    d.clear("cream");

    // Anzeige: wer ist am Zug
    d.text("Am Zug:", 20, 80, { size: 24, color: "ink", align: "left" });
    d.emoji(EMO[s.turn], 150, 80, 44);

    // Vier Karten im 2x2-Raster
    for (let i = 0; i < 4; i++) {
      const x = i % 2 === 0 ? 20 : 190;
      const y = i < 2 ? 110 : 220;
      const cur = i === s.turn && s.winner < 0;
      d.rect(x, y, 150, 90, cur ? "yellow" : "cream", { round: 12, line: true, shadow: cur });
