    const pips = PIPS[s.shown] || PIPS[1];
    for (const p of pips) d.circle(180 + p[0], 420 + p[1], 9, "ink");

    d.text("Feuer = Würfeln", 180, 520, { size: 20, color: "ink", align: "center" });

    if (s.phase === "show") {
      d.text("+" + s.gain + " Punkte (Wurf x3)", 180, 560, { size: 22, color: "ink", align: "center" });
    }

    if (s.phase === "win" && s.winner >= 0) {
      d.text("Sieger:", 140, 600, { size: 28, color: "ink", align: "right" });
      d.emoji(EMO[s.winner], 200, 600, 44);
    }
  }
};

function startRoll(s, g) {
  s.phase = "roll";
  s.timer = ROLL_T;
  s.waitT = 0;
  g.sound("shoot");
}

