// Gummibaerchen-Schaetzen (nur Spiel-API, keine Importe): Ein Glas voller Baerchen, du schaetzt die Anzahl.
// Der Computer schaetzt mit Zufallsabweichung. Wer naeher dran ist, gewinnt die Runde. 3 Runden.
// Hinweis: In der Merkphase beendet jede Taste die Anzeige sofort (fuer Bots und zum Weiterkommen).
export default {
  title: "Gummibärchen-Schätzen",
  controls: ["up", "down", "left", "right", "fire"],
  lives: 3,

  init(g) {
    const n = g.randInt(20, 150);
    return {
      phase: "show",
      t: 0,
      timer: 0,
      round: 1,
      n: n,
      bears: makeBears(g, n),
      guess: 50,
      cpu: makeCpu(g, n),
      pScore: 0,
      cScore: 0,
      msg: "",
      rep: 0
    };
  },

  update(s, input, g) {
    if (s.phase === "show") {
      s.t += 1;
      const any = input.up || input.down || input.left || input.right || input.fire || input.firePressed;
      if (any || s.t >= 240) {
        s.phase = "guess";
        s.t = 0;
        s.rep = 0;
      }
      return;
    }

    if (s.phase === "guess") {
      s.t += 1;
      const held = input.up || input.down || input.left || input.right;
      if (!held) {
        s.rep = 0;
      } else if (s.rep > 0) {
        s.rep -= 1;
      } else {
        if (input.up) s.guess += 1;
        if (input.down) s.guess -= 1;
        if (input.right) s.guess += 10;
        if (input.left) s.guess -= 10;
        s.guess = g.clamp(s.guess, 1, 200);
        s.rep = 6;
      }
      if (input.firePressed || s.t >= 600) {
        const dp = Math.abs(s.guess - s.n);
        const dc = Math.abs(s.cpu - s.n);
        if (dp < dc) {
          s.pScore += 1;
          g.addScore(100 - Math.min(dp, 100) + 50);
          g.sound("coin");
          s.msg = "Du gewinnst!";
        } else if (dc < dp) {
          s.cScore += 1;
          g.sound("hurt");
          g.loseLife();
          s.msg = "Computer gewinnt!";
        } else {
          g.sound("pop");
          s.msg = "Unentschieden";
        }
        s.phase = "result";
        s.timer = 180;
        s.t = 0;
      }
      return;
    }

    // Phase 'result': Aufloesung zeigen, dann naechste Runde oder Spielende
    s.timer -= 1;
    if (input.firePressed || s.timer <= 0) {
      if (s.round >= 3) {
        if (s.pScore > s.cScore) g.win();
        else g.gameOver();
        return;
      }
      const n = g.randInt(20, 150);
      s.round += 1;
      s.n = n;
      s.bears = makeBears(g, n);
      s.cpu = makeCpu(g, n);
      s.guess = 50;
      s.phase = "show";
      s.t = 0;
      s.msg = "";
      s.rep = 0;
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.text("Runde " + s.round + " von 3", 180, 70, { size: 20, color: "ink", align: "center" });

    // Glas, Baeren, Deckel
    d.rect(80, 150, 200, 300, "yellow", { round: 24, line: true });
    for (const b of s.bears) d.emoji("🐻", b.x, b.y, 18);
    d.rect(70, 130, 220, 24, "red", { round: 8 });

    if (s.phase === "show") {
      d.text("Merk dir die Menge!", 180, 520, { size: 20, color: "ink", align: "center" });
    } else if (s.phase === "guess") {
      d.text("Du schätzt: " + s.guess, 180, 520, { size: 32, color: "ink", align: "center" });
      d.text("Hoch/Runter = 1, Links/Rechts = 10, Tippen = fertig", 180, 575, { size: 12, color: "ink", align: "center" });
    } else {
      d.text("Echte Zahl: " + s.n, 180, 510, { size: 20, color: "ink", align: "center" });
      d.text("Du: " + s.guess + "   Computer: " + s.cpu, 180, 540, { size: 20, color: "ink", align: "center" });
      d.text(s.msg, 180, 580, { size: 20, color: "ink", align: "center" });
    }
  }
};

function makeBears(g, n) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const c = i % 10;
    const r = Math.floor(i / 10);
    out.push({
      x: 92 + c * 18 + g.randInt(-2, 2),
      y: 172 + r * 19 + g.randInt(-2, 2),
      rot: g.randInt(-20, 20)
    });
  }
  return out;
}

function makeCpu(g, n) {
  const k = Math.floor(n / 3);
  return Math.max(1, n + g.randInt(-k, k));
}

