// Gummibaerchen-Schaetzen (nur Spiel-API, keine Importe): Ein Glas voller Baerchen. Zwei Personen am selben Geraet
// schaetzen abwechselnd die Anzahl. Wer naeher dran ist, gewinnt die Runde. Nach 3 Runden entscheidet der Stand.
// Ablauf je Runde: Anzeige (Glas) -> Spieler 1 schaetzt (verdeckt) -> Geraet weitergeben -> Spieler 2 schaetzt -> Aufloesung.
// Taste oder Tippen beendet die Anzeige- und Wechselphasen sofort. Punkte: 30 je abgegebener Schaetzung, 50 fuer den Rundensieg.
const SHOW = 120, GUESS = 420, PASS = 60, RESULT = 150, MIN_SKIP = 10;

export default {
  title: "Gummibärchen-Schätzen",
  controls: ["up", "down", "left", "right", "fire"],
  lives: 1,

  init(g) {
    const n = g.randInt(20, 150);
    return {
      phase: "show",
      t: 0,
      round: 1,
      n: n,
      bears: makeBears(g, n),
      guess: 50,
      g1: 50,
      g2: 50,
      s1: 0,
      s2: 0,
      msg: "",
      rep: 0
    };
  },

  update(s, input, g) {
    const any = input.up || input.down || input.left || input.right || input.fire || input.firePressed;
    s.t += 1;

    if (s.phase === "show") {
      if ((any && s.t >= MIN_SKIP) || s.t >= SHOW) startGuess(s, "guess1");
      return;
    }

    if (s.phase === "guess1" || s.phase === "guess2") {
      stepGuess(s, input, g);
      if (input.firePressed || s.t >= GUESS) {
        g.addScore(30);
        if (s.phase === "guess1") {
          s.g1 = s.guess;
          s.phase = "pass";
          s.t = 0;
          g.sound("pop");
        } else {
          s.g2 = s.guess;
          resolve(s, g);
        }
      }
      return;
    }

    if (s.phase === "pass") {
      if ((any && s.t >= MIN_SKIP) || s.t >= PASS) startGuess(s, "guess2");
      return;
    }

    // Phase 'result': Aufloesung zeigen, dann naechste Runde oder Spielende
    if ((any && s.t >= MIN_SKIP) || s.t >= RESULT) {
