// Pizza-Ausbrecher (nur Spiel-API, keine Importe): Eine Pizza prallt vom Paddel ab und zerstoert die Steinmauer.
// Steuerung: Pfeile, Steuerkreuz oder Wischen zum Bewegen, fire (bzw. Tippen) startet die Pizza.
const BW = 40, BH = 18, COLS = 8;
const ROW_COLORS = ["red", "yellow", "ink"];

export default {
  title: "Pizza-Ausbrecher",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    const s = {
      paddle: { x: (g.W - 70) / 2, y: 600, w: 70, h: 14 },
      ball: { x: g.W / 2, y: 584, vx: 0, vy: 0, r: 10, onPaddle: true },
      bricks: []
    };
    s.bricks = wall(g);
    return s;
  },

  update(s, input, g) {
    const P = s.paddle;
    const b = s.ball;

    if (input.left) P.x -= 5;
    if (input.right) P.x += 5;
    P.x = g.clamp(P.x, 0, g.W - P.w);

    if (b.onPaddle) {
      b.x = P.x + P.w / 2;
      b.y = 584;
      if (input.firePressed) {
        b.onPaddle = false;
        b.vx = 2.5 + 0.3 * (g.level - 1);
        b.vy = -(4.5 + 0.3 * (g.level - 1));
        g.sound("shoot");
      }
      return;
    }

    b.x += b.vx;
    b.y += b.vy;

    // Waende und obere Kante
    if (b.x - b.r < 0) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x + b.r > g.W) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y - b.r < g.TOP) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Paddel-Treffer: Ball kommt von oben und liegt im Paddelbereich
    if (b.vy > 0 && b.y + b.r >= P.y && b.y + b.r <= P.y + P.h + 12 &&
        b.x >= P.x - 4 && b.x <= P.x + P.w + 4) {
      b.y = P.y - b.r;
      b.vy = -Math.abs(b.vy);
      b.vx = (b.x - (P.x + P.w / 2)) * 0.08;
    }

    // Ziegel-Treffer: ersten getroffenen lebenden Ziegel
    for (const k of s.bricks) {
      if (k.alive && g.hit(b, k)) {
        k.alive = false;
        b.vy = -b.vy;
        g.addScore(10 * g.level);
        g.sound("pop");
        break;
      }
    }

    // Ball faellt unten raus: Leben weg, Ball zurueck aufs Paddel
    if (b.y - b.r > g.H) {
      g.sound("hurt");
      g.loseLife();
      putOnPaddle(s, g);
      return;
    }

    // Mauer abgebaut: naechstes Level oder Sieg auf Level 5
    if (!s.bricks.some((k) => k.alive)) {
      if (g.level >= 5) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      s.bricks = wall(g);
      putOnPaddle(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const k of s.bricks) {
      if (k.alive) d.rect(k.x, k.y, k.w, k.h, ROW_COLORS[k.col], { round: 3, line: true });
    }
    d.rect(s.paddle.x, s.paddle.y, s.paddle.w, s.paddle.h, "red", { round: 7 });
    d.emoji("🍕", s.ball.x, s.ball.y, 24);
    if (s.ball.onPaddle) {
      d.text("Feuer startet die Pizza", g.W / 2, 540, { size: 16, color: "ink", align: "center" });
    }
  }
};

function wall(g) {
  const out = [];
  const rows = Math.min(4 + g.level, 8);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < COLS; c++) {
      out.push({ x: 8 + c * 44, y: g.TOP + 30 + r * 22, w: BW, h: BH, alive: true, col: r % 3 });
    }
  }
  return out;
}

function putOnPaddle(s, g) {
  const b = s.ball;
  b.onPaddle = true;
  b.vx = 0;
  b.vy = 0;
  b.x = s.paddle.x + s.paddle.w / 2;
  b.y = 584;
}

