    s.dir = { x: s.next.x, y: s.next.y };
    const head = { x: s.body[0].x + s.dir.x, y: s.body[0].y + s.dir.y };
    const crash = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS || s.body.some((p) => p.x === head.x && p.y === head.y);
    if (crash) { g.sound("hurt"); g.loseLife(); reset(s, g); return; }
    s.body.unshift(head);
    if (head.x === s.apple.x && head.y === s.apple.y) {
      g.addScore(10); g.sound("coin"); s.eaten += 1;
      // Level-Wechsel schon nach jedem 2. Apfel: das Tempo steigt frueh und spuerbar
      if (s.eaten % 2 === 0) { g.nextLevel(); g.sound("level"); }
      placeApple(s, g);
    } else s.body.pop();
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    s.body.forEach((p, i) => d.rect(p.x * CELL + 1, Y0 + p.y * CELL + 1, CELL - 2, CELL - 2, i === 0 ? "red" : "ink", { round: 6 }));
  }
};

function reset(s, g) {
  s.body = [{ x: 6, y: 14 }, { x: 5, y: 14 }, { x: 4, y: 14 }];
  s.dir = { x: 1, y: 0 }; s.next = { x: 1, y: 0 }; s.wait = 0;
  placeNear(s, g);
}

// Apfel nahe der Startposition der Schlange (Feld x 8..13, y 10..18), sonst irgendwo frei
function placeNear(s, g) {
  for (let tries = 0; tries < 60; tries++) {
    const a = { x: g.randInt(8, 13), y: g.randInt(10, 18) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = a; return; }
  }
  placeApple(s, g);
}

function placeApple(s, g) {
  for (let tries = 0; tries < 200; tries++) {
    const a = { x: g.randInt(0, COLS - 1), y: g.randInt(0, ROWS - 1) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = a; return; }
  }
}

// Autobahn-Ueberholer (nur Spiel-API, keine Importe).
// Der rote Sportwagen wechselt die Spur und regelt das Tempo. Entgegenkommende Autos
// von oben werden ueberholt (Punkte). Ein Zusammenstoss kostet ein Leben.
const LANES = [100, 180, 260];

export default {
  title: "Autobahn-Ueberholer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return { px: 180, py: 540, speed: 4, cars: [], protect: 0, overtakes: 0 };
  },

  update(s, input, g) {
    // Spur und Tempo
    if (input.left) s.px -= 4;
    if (input.right) s.px += 4;
    s.px = g.clamp(s.px, 100, 260);
    if (input.up) s.speed = Math.min(8, s.speed + 0.1);
    if (input.down) s.speed = Math.max(2.5, s.speed - 0.1);

    if (s.protect > 0) s.protect -= 1;

    // Neue Autos von oben, auf zufaelliger Spur
    if (g.random() < 0.02 + 0.004 * g.level && s.cars.length < 15) {
      s.cars.push({ x: LANES[g.randInt(0, 2)], y: -60, v: g.randInt(1, 2), counted: false });
    }

    // Bewegung, Kollision, Ueberholen
    const pr = { x: s.px - 17, y: s.py - 28, w: 34, h: 56 };
    const keep = [];
    for (const c of s.cars) {
      c.y += s.speed - c.v;
      const box = { x: c.x - 17, y: c.y - 28, w: 34, h: 56 };
      if (s.protect === 0 && g.hit(pr, box)) {
        s.protect = 60;
        g.sound("hurt");
        g.loseLife();
        continue;
      }
      if (!c.counted && c.y > s.py + 40) {
        c.counted = true;
        g.addScore(10);
        s.overtakes += 1;
        g.sound("pop");
        if (s.overtakes % 10 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
      if (c.y <= g.H + 60) keep.push({ x: c.x, y: c.y, v: c.v, counted: c.counted });
    }
    s.cars = keep;
  },

  draw(s, d, g) {
    d.clear("cream");
    // Strasse
    d.rect(40, g.TOP, 280, g.H - g.TOP, "ink");
    // Gestrichelte gelbe Spurlinien, bewegen sich nach unten
    const off = (g.frame * 4) % 80;
    for (let y = g.TOP + off; y < g.H; y += 80) {
      d.line(140, y, 140, y + 40, "yellow", 4);
      d.line(220, y, 220, y + 40, "yellow", 4);
    }
    // Entgegenkommende Autos
    for (const c of s.cars) d.emoji("🚗", c.x, c.y, 40);
    // Eigener Sportwagen, blinkt waehrend des Schutzes
    if (s.protect === 0 || (s.protect >> 2) % 2 === 0) {
      d.rect(s.px - 17, s.py - 28, 34, 56, "red", { round: 8, line: true });
      d.emoji("🏎️", s.px, s.py, 36);
    }
  }
};

