// Felsen-Jaeger (nur Spiel-API, keine Importe): Das Raumschiff schiesst Strahlen nach oben,
// grosse Felsbrocken zerbrechen in kleinere. Beruehrt ein Fels das Schiff, verliert man ein Leben.
const SPEED = 3;
const SHOT_V = -9;
const SHOT_R = 4;
const MAX_SHOTS = 4;
const COOL = 12;
const SAFE = 90;
const SHIP_R = 16;
const SPAWN_DIST = 120;
const STAGE_PTS = { 3: 20, 2: 50, 1: 100 };
const STAGE_R = { 3: 28, 2: 18, 1: 11 };

export default {
  title: "Felsen-Jaeger",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      ship: { x: 180, y: 560, r: SHIP_R },
      shots: [],
      rocks: [],
      cool: 0,
      safe: SAFE
    };
    s.rocks = spawnRocks(s, g, 3 + g.level);
    return s;
  },

  update(s, input, g) {
    const ship = s.ship;

    // Bewegung des Schiffs
    if (input.left) ship.x -= SPEED;
    if (input.right) ship.x += SPEED;
    if (input.up) ship.y -= SPEED;
    if (input.down) ship.y += SPEED;
    ship.x = g.clamp(ship.x, SHIP_R, g.W - SHIP_R);
    ship.y = g.clamp(ship.y, g.TOP + SHIP_R, g.H - SHIP_R);

    // Zaehler
    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;

    // Schuss nach oben
    if ((input.firePressed || input.fire) && s.cool === 0 && s.shots.length < MAX_SHOTS) {
      s.shots.push({ x: ship.x, y: ship.y - SHIP_R, r: SHOT_R, vy: SHOT_V, dead: false });
      s.cool = COOL;
      g.sound("shoot");
    }
    for (const sh of s.shots) sh.y += sh.vy;

    // Schuss gegen Fels: Fels zerbricht in kleinere Brocken
    const born = [];
    for (const sh of s.shots) {
      if (sh.dead) continue;
      for (const rk of s.rocks) {
        if (rk.gone || !g.hit(sh, rk)) continue;
        sh.dead = true;
        rk.gone = true;
        g.addScore(STAGE_PTS[rk.size]);
        g.sound("pop");
        if (rk.size > 1) {
          const k = rk.size - 1;
          born.push(makeRock(rk.x - 4, rk.y, k, rk.vx + 0.9, rk.vy - 0.4));
          born.push(makeRock(rk.x + 4, rk.y, k, rk.vx - 0.9, rk.vy + 0.4));
        }
        break;
      }
    }
    s.shots = s.shots.filter((sh) => !sh.dead && sh.y > g.TOP - SHOT_R);
    s.rocks = s.rocks.filter((rk) => !rk.gone).concat(born);

    // Felsen bewegen sich und tauchen am gegenueberliegenden Rand wieder auf
    for (const rk of s.rocks) {
      rk.x += rk.vx;
      rk.y += rk.vy;
      if (rk.x < -rk.r) rk.x = g.W + rk.r;
      else if (rk.x > g.W + rk.r) rk.x = -rk.r;
      if (rk.y < g.TOP - rk.r) rk.y = g.H + rk.r;
      else if (rk.y > g.H + rk.r) rk.y = g.TOP - rk.r;
    }

    // Felsen gegen Schiff
    for (const rk of s.rocks) {
      if (s.safe === 0 && g.hit(ship, rk)) {
        rk.gone = true;
        g.sound("hurt");
        g.loseLife();
        ship.x = g.W / 2;
        ship.y = (g.TOP + g.H) / 2;
        s.safe = SAFE;
        break;
      }
    }
    s.rocks = s.rocks.filter((rk) => !rk.gone);

    // Level geschafft
    if (s.rocks.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.rocks = spawnRocks(s, g, 3 + g.level);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const rk of s.rocks) d.emoji("🌑", rk.x, rk.y, rk.r * 2);
    for (const sh of s.shots) d.circle(sh.x, sh.y, sh.r, "red");
    const blink = s.safe > 0 && (g.frame >> 2) % 2 === 0;
    if (!blink) d.emoji("🚀", s.ship.x, s.ship.y, 32);
  }
};

function makeRock(x, y, size, vx, vy) {
  return { x: x, y: y, r: STAGE_R[size], size: size, vx: vx, vy: vy, gone: false };
}

function spawnRocks(s, g, n) {
  const out = [];
  for (let i = 0; i < n; i++) {
    let x = 0;
    let y = 0;
    for (let t = 0; t < 200; t++) {
      x = g.randInt(0, g.W);
      y = g.randInt(g.TOP + 30, g.H - 30);
      if (g.dist({ x: x, y: y }, s.ship) >= SPAWN_DIST) break;
    }
    const sp = 0.6 + 0.2 * g.level;
    const a = g.randInt(0, 359);
    out.push(makeRock(x, y, 3, g.cos(a) * sp, g.sin(a) * sp));
  }
  return out;
}

