// Dach-Katze (nur Spiel-API, keine Importe): Die Katze springt von Dach zu Dach,
// sammelt Fischgraeten ein und weicht Voegeln aus, die auf den Daechern laufen.
const GRAV = 0.5, JUMP = -10.5, FALL_MAX = 12, TIME_LIMIT = 5400, FLOOR_Y = 610;

export default {
  title: "Dach-Katze",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = { cat: { x: 30, y: 580, w: 22, h: 30, vy: 0, ground: true }, roofs: [], fish: [], foes: [], safe: 0 };
    build(s, g);
    return s;
  },

  update(s, input, g) {
    if (g.frame >= TIME_LIMIT) { g.gameOver(); return; }
    const cat = s.cat;

    // Seitwaerts und Sprung (nur am Boden)
    const dx = input.left ? -3 : input.right ? 3 : 0;
    cat.x = g.clamp(cat.x + dx, 0, g.W - cat.w);
    if (input.up && cat.ground) { cat.vy = JUMP; cat.ground = false; g.sound("jump"); }

    // Schwerkraft und Landung auf Daechern
    const oldBottom = cat.y + cat.h;
    cat.vy = Math.min(cat.vy + GRAV, FALL_MAX);
    cat.y += cat.vy;
    cat.ground = false;
    if (cat.vy >= 0) {
      for (const r of s.roofs) {
        const over = cat.x + cat.w > r.x && cat.x < r.x + r.w;
        if (over && oldBottom <= r.y && cat.y + cat.h >= r.y) {
          cat.y = r.y - cat.h; cat.vy = 0; cat.ground = true;
        }
      }
    }

    if (s.safe > 0) s.safe -= 1;

    // Voegel laufen auf ihrem Dach hin und her
    for (const c of s.foes) {
      c.x += c.vx;
      if (c.x < c.min) { c.x = c.min; c.vx = Math.abs(c.vx); }
      if (c.x > c.max) { c.x = c.max; c.vx = -Math.abs(c.vx); }
      if (s.safe === 0 && g.hit(cat, c)) {
        g.sound("hurt");
        g.loseLife();
        respawn(s);
        return;
      }
    }

    // Fischgraeten einsammeln
    for (const f of s.fish) {
      if (!f.got && g.hit(cat, f)) { f.got = true; g.addScore(10); g.sound("coin"); }
    }
    s.fish = s.fish.filter((f) => !f.got);

    // Hinunterfallen kostet ein Leben
    if (cat.y > g.H) {
      g.sound("hurt");
      g.loseLife();
      respawn(s);
      return;
    }

    // Alle Graeten eingesammelt: naechstes Level oder Sieg nach 3 Leveln
    if (s.fish.length === 0) {
      if (g.level >= 3) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      build(s, g);
      respawn(s);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.roofs) {
      d.rect(r.x, r.y, r.w, r.h, "red", { round: 6, line: true });
      for (let x = r.x + 12; x < r.x + r.w - 4; x += 18) d.line(x, r.y + 3, x, r.y + r.h - 3, "yellow", 2);
    }
    for (const f of s.fish) {
      const cx = f.x + f.w / 2;
      d.line(cx, f.y, cx, f.y + f.h, "ink", 2);
      for (let k = 0; k < 3; k++) {
        const yy = f.y + 3 + k * 4;
        d.line(cx, yy, cx - 5, yy - 3, "ink", 2);
        d.line(cx, yy, cx + 5, yy - 3, "ink", 2);
      }
    }
    for (const c of s.foes) d.emoji("🐦", c.x + c.w / 2, c.y + c.h / 2, 24);
    const cat = s.cat;
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) d.emoji("🐈", cat.x + cat.w / 2, cat.y + cat.h / 2, 30);
    const sec = Math.max(0, Math.ceil((TIME_LIMIT - g.frame) / 60));
    d.text("Zeit " + String(sec) + " s", 350, 32, { size: 18, color: "ink", align: "right" });
  }
};

function build(s, g) {
  s.roofs = []; s.fish = []; s.foes = [];
  const rows = Math.min(3 + g.level, 6);
  for (let r = 0; r < rows; r++) {
    const y = FLOOR_Y - r * 90;
    if (r === 0) {
      for (let i = 0; i < 3; i++) addRoof(s, g, i * 120, 120, y, false);
    } else {
      addRoof(s, g, g.randInt(4, 30), g.randInt(90, 130), y, true);
      addRoof(s, g, g.randInt(190, 230), g.randInt(90, 126), y, true);
    }
  }
}

function addRoof(s, g, x, w, y, foe) {
  s.roofs.push({ x: x, y: y, w: w, h: 16 });
  s.fish.push({ x: x + w / 2 - 8, y: y - 20, w: 16, h: 16, got: false });
  if (foe && g.random() < 0.5) {
    s.foes.push({ x: x + 4, y: y - 22, w: 22, h: 22, vx: 0.6 + 0.2 * g.level, min: x, max: x + w - 22 });
  }
}

function respawn(s) {
  s.cat.x = 30; s.cat.y = 580; s.cat.vy = 0; s.cat.ground = true;
  s.safe = 60;
}

