// Wasserballon-Duell (nur Spiel-API, keine Importe): Ente unten wirft Wasserballons nach oben auf den Frosch,
// der oben zurueckspritzt. Getroffen wird nur nass gespritzt, kein Blut.
const DUCK_Y = 580, FOE_Y = 90, HALF = 17, TIME_LIMIT = 3600;

export default {
  title: "Wasserballon-Duell",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    return {
      me: { x: 160, y: DUCK_Y },
      safe: 0,
      cool: 0,
      mine: [],
      theirs: [],
      foe: { x: 170, y: FOE_Y, dir: 1 },
      foeWet: 0,
      spit: g.randInt(45, 75),
      hits: 0
    };
  },

  update(s, input, g) {
    if (g.frame >= TIME_LIMIT) { g.gameOver(); return; }

    // Ente bewegen
    if (input.left) s.me.x -= 4;
    if (input.right) s.me.x += 4;
    s.me.x = g.clamp(s.me.x, HALF, g.W - HALF);

    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;
    if (s.foeWet > 0) s.foeWet -= 1;

    // Eigene Ballons werfen
    if (input.firePressed && s.cool === 0 && s.mine.length < 3) {
      s.mine.push({ x: s.me.x, y: s.me.y - 20, r: 7 });
      s.cool = 15;
      g.sound("shoot");
    }
    for (const b of s.mine) b.y -= 6;
    s.mine = s.mine.filter((b) => b.y + b.r > g.TOP);

    // Frosch wandert hin und her
    const speed = 1.2 + 0.3 * (g.level - 1);
    s.foe.x += s.foe.dir * speed;
    if (s.foe.x <= 20) { s.foe.x = 20; s.foe.dir = 1; }
    if (s.foe.x >= 320) { s.foe.x = 320; s.foe.dir = -1; }

    // Frosch spuckt Ballons zur Ente
    s.spit -= 1;
    if (s.spit <= 0) {
      const dev = g.randInt(-30, 30);
      const vx = g.clamp((s.me.x + dev - s.foe.x) / 40, -3, 3);
      const vy = 3 + 0.4 * g.level;
      s.theirs.push({ x: s.foe.x, y: s.foe.y + 20, r: 7, vx: vx, vy: vy });
      s.spit = g.randInt(Math.max(20, 45 - 5 * (g.level - 1)), Math.max(30, 75 - 5 * (g.level - 1)));
    }
    for (const b of s.theirs) { b.x += b.vx; b.y += b.vy; }
    s.theirs = s.theirs.filter((b) => b.y < g.H + 10 && b.x > -20 && b.x < g.W + 20);

    // Treffer: eigene Ballons gegen Frosch
    const foeRect = { x: s.foe.x - HALF, y: s.foe.y - HALF, w: 34, h: 34 };
    let foeHits = 0;
    s.mine = s.mine.filter((b) => {
      if (g.hit(b, foeRect)) { foeHits += 1; return false; }
      return true;
    });
    for (let i = 0; i < foeHits; i++) {
      s.hits += 1;
      g.addScore(10 * g.level);
      g.sound("pop");
      s.foeWet = 20;
      if (s.hits >= 15) { g.win(); return; }
      if (s.hits % 5 === 0) { g.nextLevel(); g.sound("level"); }
    }

    // Treffer: Frosch-Ballons gegen Ente
    const meRect = { x: s.me.x - HALF, y: s.me.y - HALF, w: 34, h: 34 };
    if (s.safe === 0) {
      let gotWet = false;
      s.theirs = s.theirs.filter((b) => {
        if (!gotWet && g.hit(b, meRect)) { gotWet = true; return false; }
        return true;
      });
      if (gotWet) {
        s.safe = 60;
        g.sound("hurt");
        g.loseLife();
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.line(0, 300, g.W, 300, "yellow", 3);
    d.text("Treffer " + s.hits + "/15", 12, 24, { size: 18, color: "ink", align: "left" });

    // Frosch mit Spritzer
    d.emoji("🐸", s.foe.x, s.foe.y, 34);
    if (s.foeWet > 0) d.emoji("💦", s.foe.x + 18, s.foe.y - 18, 22);

    // Ballons
    for (const b of s.mine) d.circle(b.x, b.y, b.r, "yellow", { line: true });
    for (const b of s.theirs) d.circle(b.x, b.y, b.r, "yellow", { line: true });

    // Ente blinkt, wenn sie nass und unverwundbar ist
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) d.emoji("🦆", s.me.x, s.me.y, 34);
    if (s.safe > 0) d.emoji("💦", s.me.x + 18, s.me.y - 18, 22);
  }
};

