// Tennis am Netz (nur Spiel-API, keine Importe).
// Links schlaegt der Spieler, rechts der Computer. Der Ball prallt an Schlaegern und Kanten ab.
const PAD_W = 10, PAD_H = 80, PAD_SPEED = 5, MAX_SPEED = 9, BALL_R = 7, WIN_POINTS = 30;

export default {
  title: "Tennis am Netz",
  controls: ["up", "down"],
  lives: 3,

  init(g) {
    const s = {
      pl: { x: 12, y: 300, w: PAD_W, h: PAD_H },
      cp: { x: 338, y: 300, w: PAD_W, h: PAD_H },
      ball: { x: g.W / 2, y: (g.TOP + g.H) / 2, r: BALL_R, vx: 3, vy: 0 },
      speed: 3,
      aim: 0,
      points: 0
    };
    serve(s, g, g.random() < 0.5 ? -1 : 1);
    return s;
  },

  update(s, input, g) {
    const pl = s.pl, cp = s.cp, b = s.ball;

    // Spieler-Schlaeger
    if (input.up) pl.y -= PAD_SPEED;
    if (input.down) pl.y += PAD_SPEED;
    pl.y = g.clamp(pl.y, g.TOP, g.H - pl.h);

    // Computer-Schlaeger: folgt dem Ball, aber langsam und mit Zufalls-Versatz
    if (g.frame % 45 === 0) s.aim = (g.random() - 0.5) * 50;
    const diff = (b.y + s.aim) - (cp.y + cp.h / 2);
    cp.y = g.clamp(cp.y + g.clamp(diff, -3.2, 3.2), g.TOP, g.H - cp.h);

    // Ball bewegen
    b.x += b.vx;
    b.y += b.vy;
    if (b.y - b.r < g.TOP) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }
    if (b.y + b.r > g.H) { b.y = g.H - b.r; b.vy = -Math.abs(b.vy); }

    // Treffer: nur wenn der Ball auf den Schlaeger zufliegt
    if (b.vx < 0 && g.hit(pl, b)) {
      b.x = pl.x + pl.w + b.r;
      bounce(s, pl, g);
    } else if (b.vx > 0 && g.hit(cp, b)) {
      b.x = cp.x - b.r;
      bounce(s, cp, g);
    }

    // Ball verlaesst links: Spieler verfehlt
    if (b.x < 0) {
      g.sound("hurt");
      g.loseLife();
      serve(s, g, 1);
      return;
    }

    // Ball verlaesst rechts: Computer verfehlt
    if (b.x > g.W) {
      g.addScore(10);
      g.sound("coin");
      s.points += 1;
      if (s.points >= WIN_POINTS) { g.win(); return; }
      if (s.points % 2 === 0) {
        g.nextLevel();
        g.sound("level");
        s.speed = Math.min(s.speed + 0.5, MAX_SPEED);
      }
      serve(s, g, -1);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(4, g.TOP + 4, g.W - 8, g.H - g.TOP - 8, "cream", { round: 12, line: true });
    for (let y = g.TOP + 10; y < g.H - 10; y += 24) d.rect(g.W / 2 - 3, y, 6, 12, "ink");
    d.rect(s.pl.x, s.pl.y, s.pl.w, s.pl.h, "red", { round: 4 });
    d.rect(s.cp.x, s.cp.y, s.cp.w, s.cp.h, "yellow", { round: 4, line: true });
    d.circle(s.ball.x, s.ball.y, s.ball.r, "ink");
  }
};

