  for (let c = 0; c < 18; c++) r += (c === 0 || c === 17 || !gaps.includes(c)) ? "#" : ".";
  return r;
}
const MAZE = [
  WALL, OPEN, sep([16]), OPEN, sep([1]), OPEN, sep([16]), OPEN, sep([1]), OPEN,
  sep([1, 9, 16]), OPEN, sep([16]), OPEN, sep([1]), OPEN, sep([16]), OPEN, sep([1]), OPEN,
  sep([16]), OPEN, sep([1]), OPEN, WALL
