    buildCrumbs(s);
    resetPositions(s, g);
    return s;
  },

  update(s, input, g) {
    // Gewuenschte Richtung merken, bis sie umgesetzt werden kann
    if (input.left) { s.wx = -1; s.wy = 0; }
    else if (input.right) { s.wx = 1; s.wy = 0; }
    else if (input.up) { s.wx = 0; s.wy = -1; }
    else if (input.down) { s.wx = 0; s.wy = 1; }

    if (s.safe > 0) s.safe -= 1;

