const MAZE = [
  "##################",
  "#................#",
  "################.#",
  "#................#",
  "#.################",
  "#................#",
  "################.#",
  "#................#",
  "#.################",
  "#................#",
  "#.#######.######.#",
  "#................#",
  "################.#",
  "#................#",
  "#.################",
  "#................#",
  "################.#",
  "#................#",
  "#.################",
  "#................#",
  "################.#",
  "#................#",
  "#.################",
  "#................#",
  "##################"
];

function free(c, r) {
  return c >= 0 && c < COLS && r >= 0 && r < ROWS && MAZE[r].charAt(c) !== "#";
}

// Laufweg-Entfernung aller Felder zum Ziel (lokal, kein Zustand).
function distMap(tc, tr) {
  const d = [];
  for (let i = 0; i < COLS * ROWS; i++) d.push(-1);
  const q = [tr * COLS + tc];
  d[tr * COLS + tc] = 0;
  for (let i = 0; i < q.length; i++) {
    const idx = q[i];
    const c = idx % COLS, r = Math.floor(idx / COLS);
    for (const o of DIRS) {
      const nc = c + o[0], nr = r + o[1];
      if (free(nc, nr) && d[nr * COLS + nc] < 0) {
        d[nr * COLS + nc] = d[idx] + 1;
        q.push(nr * COLS + nc);
      }
    }
  }
  return d;
}

function buildCrumbs(s) {
  s.crumbs = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (MAZE[r].charAt(c) === "." && !(c === START.c && r === START.r)) s.crumbs.push({ c: c, r: r });
    }
  }
}

function resetPositions(s, g) {
  s.me = { c: START.c, r: START.r };
  s.wx = 0; s.wy = 0; s.dx = 0; s.dy = 0;
  s.mt = 0; s.gt = 0;
  s.safe = 60;
  const n = Math.min(g.level + 1, 4);
  s.gulls = [];
  for (let i = 0; i < n; i++) s.gulls.push({ c: CORNERS[i].c, r: CORNERS[i].r, dx: 0, dy: 0 });
}

function moveGull(gl, dm, g) {
  const opts = [];
  for (const o of DIRS) if (free(gl.c + o[0], gl.r + o[1])) opts.push(o);
  if (opts.length === 0) return;
  let pool = opts.filter((o) => !(o[0] === -gl.dx && o[1] === -gl.dy));
  if (pool.length === 0) pool = opts;
  let pick = pool[0];
  if (g.random() < 0.3) {
    pick = pool[g.randInt(0, pool.length - 1)];
  } else {
    let best = 99999;
    for (const o of pool) {
      const v = dm[(gl.r + o[1]) * COLS + (gl.c + o[0])];
      const val = v < 0 ? 9998 : v;
      if (val < best) { best = val; pick = o; }
    }
  }
  gl.dx = pick[0]; gl.dy = pick[1];
  gl.c += pick[0]; gl.r += pick[1];
}

export default {
  title: "Donut im Labyrinth",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    const s = { me: null, crumbs: [], gulls: [], wx: 0, wy: 0, dx: 0, dy: 0, mt: 0, gt: 0, safe: 60 };
    buildCrumbs(s);
    resetPositions(s, g);
    return s;
  },

  update(s, input, g) {
    // Gewuenschte Richtung merken, bis sie umgesetzt werden kann
    if (input.left) { s.wx = -1; s.wy = 0; }
    else if (input.right) { s.wx = 1; s.wy = 0; }
    else if (input.up) { s.wx = 0; s.wy = -1; }
    else if (input.down) { s.wx = 0; s.wy = 1; }

    if (s.safe > 0) s.safe -= 1;

    // Donut: alle 8 Frames ein Feld
    s.mt += 1;
    if (s.mt >= 8) {
      s.mt = 0;
      const me = s.me;
      if (free(me.c + s.wx, me.r + s.wy)) { s.dx = s.wx; s.dy = s.wy; }
      if (free(me.c + s.dx, me.r + s.dy)) { me.c += s.dx; me.r += s.dy; }
      let got = false;
      s.crumbs = s.crumbs.filter((k) => {
        if (k.c === me.c && k.r === me.r) { got = true; return false; }
        return true;
      });
      if (got) { g.addScore(10); g.sound("coin"); }
    }

    // Moewen (als Voegel 🕊️ dargestellt): alle 12 Frames ein Feld
    s.gt += 1;
    if (s.gt >= 12) {
      s.gt = 0;
      const dm = distMap(s.me.c, s.me.r);
      for (const gl of s.gulls) moveGull(gl, dm, g);
    }

    // Kontakt: nur gleiches Feld
    if (s.safe === 0 && s.gulls.some((gl) => gl.c === s.me.c && gl.r === s.me.r)) {
      g.sound("hurt");
      g.loseLife();
      resetPositions(s, g);
      return;
    }

    // Level geschafft: alle Streusel gesammelt
    if (s.crumbs.length === 0) {
      if (g.level >= 3) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      buildCrumbs(s);
      resetPositions(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (MAZE[r].charAt(c) === "#") d.rect(c * CELL, Y0 + r * CELL, CELL, CELL, "ink", { round: 4 });
      }
    }
    for (const k of s.crumbs) d.circle(k.c * CELL + CELL / 2, Y0 + k.r * CELL + CELL / 2, 3, "yellow");
    for (const gl of s.gulls) d.emoji("🕊️", gl.c * CELL + CELL / 2, Y0 + gl.r * CELL + CELL / 2, 18);
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🍩", s.me.c * CELL + CELL / 2, Y0 + s.me.r * CELL + CELL / 2, 20);
    }
    d.text("Moewen sind hier Voegel 🕊️ (kein Moewen-Emoji)", g.W / 2, 628, { size: 12, color: "ink", align: "center" });
  }
};

