// Huhn-Huepfer (nur Spiel-API, keine Importe): Das Huhn schwebt links und sinkt von allein.
// Fire oder Tippen laesst es hochflattern. Durch die Luecken der Hindernispaare von rechts hindurch.
// Boden, Decke, Hindernisse kosten ein Leben. Jedes passierte Paar gibt einen Punkt.
const BIRD_X = 80;
const BIRD_W = 30;
const BIRD_H = 28;
const BIRD_Y0 = 300;
const OB_W = 56;

export default {
  title: "Huhn-Huepfer",
  controls: ["fire"],
  lives: 3,

  init(g) {
    return { y: BIRD_Y0, vy: 0, obs: [], t: 0 };
  },

  update(s, input, g) {
    // Flattern
    if (input.firePressed) {
      s.vy = -6.5;
      g.sound("jump");
    }
    // Schwerkraft
    s.vy = Math.min(s.vy + 0.35, 7);
    s.y += s.vy;

    // Decke: Gefahr (Huhn wird auf die Decke gesetzt, Leben kostet es)
    if (s.y < g.TOP + 14) {
      s.y = g.TOP + 14;
      s.vy = 0;
      hurt(s, g);
      return;
    }
    // Boden: Unterkante erreicht die sichtbare Bodenlinie
    if (s.y + BIRD_H / 2 >= floorY(g)) {
      hurt(s, g);
      return;
    }

    // Hindernisse bewegen sich nach links
    const speed = 2 + 0.3 * (g.level - 1);
    for (const p of s.obs) p.x -= speed;

    // Spawn alle 100 Frames am rechten Rand
    s.t += 1;
    if (s.t % 100 === 0) {
      s.obs.push({ x: g.W, gapY: g.randInt(g.TOP + 60, g.H - 200), passed: false });
    }

    // Kollision mit beiden Rechtecken jedes Paares
    const gap = gapSize(g);
    const box = { x: BIRD_X - BIRD_W / 2, y: s.y - BIRD_H / 2, w: BIRD_W, h: BIRD_H };
    for (const p of s.obs) {
      const top = { x: p.x, y: g.TOP, w: OB_W, h: p.gapY - g.TOP };
