const GRAV = 0.3;        // Fallbeschleunigung (vorher 0.25, damit das Huhn nicht zu lange schwebt)
const MAX_VY = 6;        // Hoechstgeschwindigkeit beim Fallen
const FLAP_VY = -5.5;    // Flatterstaerke: steigt ca. 50 px, Tippen im Rhythmus haelt die Hoehe
const SPAWN_AT = 35;     // Spawn-Takt: Frame 35, 155, 275 ... (alle 120 Frames)
const SPAWN_EVERY = 120;
const FIRST_X = 250;     // erstes Paar steht zu Beginn in Sichtweite
const RESPAWN_X = 250;   // nach einem Leben steht sofort ein Paar in Sichtweite
const FIRST_GAP_Y = BIRD_Y0 - 80; // Luecke liegt um die Start-Hoehe des Huhns
const SPEED0 = 1.5;      // Grundtempo der Hindernisse
const AIR_EVERY = 30;    // alle 30 Frames in der Luft ein Punkt

export default {
  title: "Huhn-Huepfer",
  controls: ["fire"],
  lives: 3,

  init(g) {
    return {
      y: BIRD_Y0,
