    // Schwerkraft
    s.vy = Math.min(s.vy + GRAV, MAX_VY);
    s.y += s.vy;

    // Decke: Gefahr (in der Schonzeit nur abprallen)
    if (s.y < g.TOP + 14) {
      s.y = g.TOP + 14;
      s.vy = 0;
      if (s.grace === 0) {
        hurt(s, g);
        return;
      }
    }
    // Boden: Unterkante erreicht die sichtbare Bodenlinie (in der Schonzeit nur abprallen)
    if (s.y + BIRD_H / 2 >= floorY(g)) {
      if (s.grace === 0) {
        hurt(s, g);
        return;
      }
      s.y = floorY(g) - BIRD_H / 2 - 1;
      s.vy = -4;
    }

    // Ueberleben: alle 30 Frames in der Luft ein Punkt
    s.air += 1;
    if (s.air % AIR_EVERY === 0) g.addScore(1);

    // Hindernisse bewegen sich nach links
    const speed = SPEED0 + 0.3 * (g.level - 1);
