    if (s.grace === 0) {
      for (const p of s.obs) {
        const top = { x: p.x, y: g.TOP, w: OB_W, h: p.gapY - g.TOP };
        const bottom = { x: p.x, y: p.gapY + gap, w: OB_W, h: g.H - (p.gapY + gap) };
        if (g.hit(box, top) || g.hit(box, bottom)) {
