    const gap = gapSize(g);
    for (const p of s.obs) {
      d.rect(p.x, g.TOP, OB_W, p.gapY - g.TOP, "ink", { round: 6 });
      d.rect(p.x, p.gapY + gap, OB_W, g.H - (p.gapY + gap), "ink", { round: 6 });
    }
