    const period = input.down ? 3 : Math.max(5, 40 - 3 * g.level);
    s.tick += 1;
    if (s.tick >= period) {
      s.tick = 0;
      const p = { k: s.cur.k, x: s.cur.x, y: s.cur.y + 1, r: s.cur.r };
      if (fits(s.grid, cellsOf(p))) s.cur.y += 1;
      else lockPiece(s, g);
    }

    // Der Teig steigt: alle paar Sekunden eine Reihe von unten
    s.rise += 1;
    if (s.rise >= Math.max(90, 150 - 10 * g.level)) {
      s.rise = 0;
      raise(s, g);
    }
  },

