    for (let r = 1; r < ROWS; r++) d.line(X0, Y0 + r * CELL, X0 + COLS * CELL, Y0 + r * CELL, "ink", 1);
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const v = s.grid[r][c];
        if (v > 0) d.emoji(EMO[v - 1], X0 + c * CELL + CELL / 2, Y0 + r * CELL + CELL / 2, 28);
      }
