// Wuerfeln bis 100 (nur Spiel-API, keine Importe): Vier Spieler wuerfeln Zug fuer Zug am selben Geraet.
// Feuer wuerfelt, Pfeil oben sichert die Zugpunkte. Eine 1 kostet die Zugpunkte und ein gemeinsames Pech-Leben.
const DICE = ["🎲", "⚀", "⚁", "⚂", "⚃", "⚄", "⚅"];

export default {
  title: "Wuerfeln bis 100",
  controls: ["fire", "up"],
  lives: 3,

  init(g) {
    return { cur: 0, turn: 0, total: [0, 0, 0, 0], wurf: 0, upWas: false, msg: "", msgT: 0 };
  },

  update(s, input, g) {
    const upNow = input.up ? true : false;
    const upEdge = upNow && !s.upWas;
    s.upWas = upNow;
    if (s.msgT > 0) s.msgT -= 1;

    let ended = false;

    if (input.firePressed) {
      const w = g.randInt(1, 6);
      s.wurf = w;
      if (w === 1) {
        s.turn = 0;
        s.cur = (s.cur + 1) % 4;
        s.msg = "Pech: eine 1, Zug vorbei";
        s.msgT = 90;
        ended = true;
        g.sound("hurt");
        g.loseLife();
      } else {
        s.turn += w;
        g.sound("pop");
      }
    }

    if (upEdge && !ended) {
      const gain = s.turn;
      s.total[s.cur] += gain;
      g.addScore(gain);
      s.turn = 0;
      if (s.total[s.cur] >= 100) {
        g.sound("win");
        g.win();
        return;
      }
      s.cur = (s.cur + 1) % 4;
      g.sound("coin");
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    for (let i = 0; i < 4; i++) {
      const y = 84 + i * 40;
      if (i === s.cur) d.rect(16, y - 18, 328, 36, "yellow", { round: 10 });
      d.text("Spieler " + (i + 1), 40, y, { size: 22, color: "ink" });
      d.text(String(s.total[i]), 320, y, { size: 22, color: "ink", align: "right" });
    }

    d.rect(110, 250, 140, 140, "cream", { round: 16, line: true });
    const face = s.wurf > 0 ? DICE[s.wurf] : DICE[0];
    d.emoji(face, 180, 320, 110);

    d.text("Am Zug: Spieler " + (s.cur + 1), 180, 420, { size: 24, color: "ink", align: "center" });
    d.text("Zugpunkte: " + s.turn, 180, 460, { size: 24, color: "ink", align: "center" });
    if (s.msgT > 0) d.text(s.msg, 180, 500, { size: 20, color: "red", align: "center" });
    d.text("Ziel: 100 Punkte", 180, 540, { size: 20, color: "ink", align: "center" });
    d.text("Feuer: wuerfeln, Pfeil oben: sichern", 180, 580, { size: 18, color: "ink", align: "center" });
  }
};

