versuche.code:
// Gummibaerchen-Schaetzen (nur Spiel-API, keine Importe). Ein Glas mit Baerchen blitzt kurz auf,
// dann wird geschaetzt. Der Computer schaetzt auch; wer naeher dran ist, gewinnt die Runde.
const GLAS = { x: 90, y: 150, w: 180, h: 320 };
const COLS = 6, ROWS = 7, CELLS = COLS * ROWS;
const SHOW_FRAMES = 240, GUESS_LIMIT = 600, RESULT_FRAMES = 120, ROUNDS = 5, REPEAT = 6;

export default {
  title: "Gummibärchen-Schätzen",
  controls: ["up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      phase: "show", t: 0, round: 1, n: 0, bears: [], guess: 20, cguess: 0,
      wins: 0, rep: 0, timer: 0, dp: 0, dc: 0, verdict: "", timedOut: false
    };
    newRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "show") {
      adjust(s, input, g);
      s.t += 1;
      if (s.t >= SHOW_FRAMES) {
        s.phase = "guess";
        s.t = 0;
        s.timer = 0;
        s.bears = [];
      }
      return;
    }

    if (s.phase === "guess") {
      adjust(s, input, g);
      s.timer += 1;
      if (input.firePressed) resolve(s, g, false);
      else if (s.timer >= GUESS_LIMIT) resolve(s, g, true);
      return;
    }

    // Ergebnis-Phase
    s.t += 1;
    if (s.t >= RESULT_FRAMES) {
      if (s.round % 3 === 0) g.nextLevel();
      if (s.round >= ROUNDS) {
        if (s.wins >= 3) g.win();
        else g.gameOver();
        return;
      }
      s.round += 1;
      newRound(s, g);
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(GLAS.x, GLAS.y, GLAS.w, GLAS.h, "yellow", { round: 16, line: true });

    if (s.phase === "show") {
      for (const b of s.bears) d.emoji("🐻", b.x, b.y, 18);
      d.text("Wie viele?", 180, 110, { size: 28, color: "ink", align: "center" });
      const left = Math.max(0, Math.ceil((SHOW_FRAMES - s.t) / 60));
      d.text("Noch " + left + " s", 180, 135, { size: 16, color: "ink", align: "center" });
    } else if (s.phase === "guess") {
      d.text(String(s.guess), 180, 320, { size: 56, color: "ink", align: "center" });
      d.text("Hoch/Runter: Schaetzung", 180, 110, { size: 18, color: "ink", align: "center" });
      d.text("Feuer: bestaetigen", 180, 135, { size: 18, color: "ink", align: "center" });
      const remain = Math.max(0, (GUESS_LIMIT - s.timer) / GUESS_LIMIT);
      d.rect(GLAS.x, GLAS.y + GLAS.h + 14, Math.round(GLAS.w * remain), 8, "red", { round: 4 });
    } else {
      d.text("Es waren " + s.n, 180, 260, { size: 34, color: "ink", align: "center" });
      d.text("Du: " + s.guess + "   CPU: " + s.cguess, 180, 310, { size: 22, color: "ink", align: "center" });
      d.text(s.verdict, 180, 370, { size: 16, color: "red", align: "center" });
    }

    d.text("Runde " + s.round + " von " + ROUNDS, 180, 600, { size: 18, color: "ink", align: "center" });
  }
};

function newRound(s, g) {
  s.n = g.randInt(8, 40);
  s.guess = 20;
  s.cguess = Math.max(0, s.n + g.randInt(-12, 12));
  s.phase = "show";
  s.t = 0;
  s.timer = 0;
  s.rep = 0;
  s.timedOut = false;
  s.verdict = "";

  const cells = [];
  for (let i = 0; i < CELLS; i++) cells.push(i);
  for (let i = 0; i < s.n; i++) {
    const j = g.randInt(i, CELLS - 1);
    const tmp = cells[i];
    cells[i] = cells[j];
    cells[j] = tmp;
  }

  s.bears = [];
  for (let i = 0; i < s.n; i++) {
    const idx = cells[i];
    const c = idx % COLS;
    const r = Math.floor(idx / COLS);
    s.bears.push({
      x: GLAS.x + 15 + c * 30 + g.randInt(-4, 4),
      y: GLAS.y + 22 + r * 45 + g.randInt(-6, 6)
    });
  }
}

function adjust(s, input, g) {
  if (input.up || input.down) {
    if (s.rep > 0) {
      s.rep -= 1;
    } else {
      const step = input.up ? 1 : -1;
      s.guess = g.clamp(s.guess + step, 0, 99);
      s.rep = REPEAT;
    }
  } else {
    s.rep = 0;
  }
}

function resolve(s, g, timedOut) {
  s.timedOut = timedOut;
  s.dp = Math.abs(s.guess - s.n);
  s.dc = Math.abs(s.cguess - s.n);
  const won = !timedOut && s.dp <= s.dc;
  if (won) {
    s.wins += 1;
    g.addScore(10 * g.level);
    g.sound("coin");
    s.verdict = "Du warst naeher dran!";
  } else {
    g.sound("hurt");
    g.loseLife();
    s.verdict = timedOut ? "Zu langsam, Runde verloren." : "Der Computer war naeher dran.";
  }
  s.phase = "result";
  s.t = 0;
}

