const GLAS = { x: 90, y: 150, w: 180, h: 320 };
const COLS = 6, ROWS = 7, CELLS = COLS * ROWS;
const SHOW_FRAMES = 240, GUESS_LIMIT = 600, REVEAL_FRAMES = 90, RESULT_FRAMES = 120, ROUNDS = 5, REPEAT = 6;

export default {
  title: "Gummibärchen-Schätzen",
  controls: ["up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      phase: "show", t: 0, round: 1, n: 0, bears: [], guess: 20, cguess: 0,
      wins: 0, rep: 0, timer: 0, dp: 0, dc: 0, verdict: "", timedOut: false
    };
    newRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "show") {
      adjust(s, input, g);
      s.t += 1;
      if (s.t >= SHOW_FRAMES) {
        s.phase = "guess";
        s.t = 0;
        s.timer = 0;
        s.bears = [];
      }
      return;
    }

    if (s.phase === "guess") {
      adjust(s, input, g);
      s.timer += 1;
      if (input.firePressed) startReveal(s, false);
