// Pizza-Ziegelbrecher (nur Spiel-API, keine Importe): Eine Pizza prallt vom Balken ab und zerlegt Ziegel-Reihen.
// Fällt die Pizza unten raus, geht ein Leben verloren. Alle Ziegel weg: naechste Runde, nach Level 3 gewonnen.
const COLORS = ["red", "yellow", "ink"];
const PAD_W = 70, PAD_H = 12, PAD_Y = 600;
const BALL_R = 9;
const PAUSE_AFTER_LOSS = 30;
const AUTO_LAUNCH = 240;

export default {
  title: "Pizza-Ziegelbrecher",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    const s = {
      pad: { x: 145, y: PAD_Y, w: PAD_W, h: PAD_H },
      ball: { x: 180, y: PAD_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: 0, stuck: true },
      bricks: makeBricks(g),
      pause: 0,
      idle: 0
    };
    return s;
  },

  update(s, input, g) {
    const pad = s.pad;
    if (input.left) pad.x -= 5;
    if (input.right) pad.x += 5;
    pad.x = g.clamp(pad.x, 4, g.W - pad.w - 4);

    const b = s.ball;

    if (b.stuck) {
      b.x = pad.x + pad.w / 2;
      b.y = pad.y - b.r - 1;
      if (s.pause > 0) { s.pause -= 1; return; }
      s.idle += 1;
      if (input.fire || input.firePressed || s.idle >= AUTO_LAUNCH) {
        const f = 1 + 0.1 * g.level;
        b.vx = 3 * f;
        b.vy = -4 * f;
        b.stuck = false;
        s.idle = 0;
        g.sound("shoot");
      }
      return;
    }

    b.x += b.vx;
    b.y += b.vy;

    // Waende links, rechts und oben
    if (b.x - b.r < 0) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x + b.r > g.W) { b.x = g.W - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y - b.r < g.TOP) { b.y = g.TOP + b.r; b.vy = Math.abs(b.vy); }

    // Treffer am Balken
    if (b.vy > 0 && g.hit(b, pad)) {
      b.vy = -Math.abs(b.vy);
      b.y = pad.y - b.r;
      const off = b.x - (pad.x + pad.w / 2);
      b.vx = off * 0.08;
    }

    // Treffer an einem Ziegel: ein Ziegel pro Frame, an der kuerzeren Seite abprallen
    for (let i = 0; i < s.bricks.length; i++) {
      const k = s.bricks[i];
      if (g.hit(b, k)) {
        const ox = Math.min(b.x + b.r - k.x, k.x + k.w - (b.x - b.r));
        const oy = Math.min(b.y + b.r - k.y, k.y + k.h - (b.y - b.r));
        if (ox < oy) b.vx = -b.vx;
        else b.vy = -b.vy;
        s.bricks.splice(i, 1);
        g.addScore(10 * g.level);
        g.sound("pop");
        break;
      }
    }

    // Verlust: Pizza unten raus
    if (b.y > g.H) {
      g.sound("hurt");
      g.loseLife();
      setStuck(s, pad);
      s.pause = PAUSE_AFTER_LOSS;
      return;
    }

    // Level geschafft
    if (s.bricks.length === 0) {
      if (g.level >= 3) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      s.bricks = makeBricks(g);
      setStuck(s, pad);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const k of s.bricks) d.rect(k.x, k.y, k.w, k.h, k.col, { round: 4, line: true });
    d.rect(s.pad.x, s.pad.y, s.pad.w, s.pad.h, "ink", { round: 6 });
    d.emoji("🍕", s.ball.x, s.ball.y, 24);
  }
};

function makeBricks(g) {
  const out = [];
  const rows = Math.min(3 + g.level, 6);
