// Autobahn-Ueberholer (nur Spiel-API, keine Importe). Roter Sportwagen auf drei Spuren.
// Gegner ueberholen = Punkte. Beruehrung kostet ein Leben. 30 Ueberholungen gewinnen.
const LANES = [100, 180, 260];

export default {
  title: "Autobahn-Ueberholer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return {
      me: { x: 162, y: 520, w: 36, h: 56 },
      speed: 4,
      off: 0,
      cars: [],
      passed: 0,
      safe: 0
    };
  },

  update(s, input, g) {
    const me = s.me;

    // Seitwaerts, begrenzt auf die Fahrbahn
    if (input.left) me.x -= 4;
    if (input.right) me.x += 4;
    me.x = g.clamp(me.x, 42, 282);

    // Geschwindigkeit: Gas bis 8, Bremse bis 1
    if (input.up) s.speed = Math.min(8, s.speed + 0.1);
    if (input.down) s.speed = Math.max(1, s.speed - 0.2);

    // Fahrbahnlinien scrollen mit der Geschwindigkeit
    s.off = (s.off + s.speed) % 80;

    if (s.safe > 0) s.safe -= 1;

    // Neue Gegner oben in zufaelliger Spur
    if (g.random() < 0.02 + 0.005 * g.level) {
      const lane = g.randInt(0, 2);
      s.cars.push({
        x: LANES[lane] - 18,
        y: g.TOP - 56,
        w: 36,
        h: 56,
        v: g.randInt(1, 3),
        counted: false,
        gone: false
      });
    }

    // Gegner bewegen sich; hoehere Level machen sie etwas schneller
    const factor = 1 + 0.1 * (g.level - 1);
    for (const c of s.cars) c.y += (s.speed - c.v) * factor;

    // Kollision mit Schutzzeit
    if (s.safe === 0) {
      for (const c of s.cars) {
        if (!c.gone && g.hit(me, c)) {
          c.gone = true;
          g.sound("hurt");
          g.loseLife();
          s.safe = 60;
          break;
        }
      }
    }

    // Ueberholt: Gegner liegt unter dem Spieler-Wagen und ist noch nicht gezaehlt
    for (const c of s.cars) {
      if (!c.gone && !c.counted && c.y > me.y + me.h) {
        c.counted = true;
        s.passed += 1;
        g.addScore(10 * g.level);
        g.sound("pop");
        if (s.passed % 10 === 0) {
          g.nextLevel();
          g.sound("level");
        }
        if (s.passed >= 30) {
          g.win();
          return;
        }
      }
    }

    // Aufraeumen: weg unterhalb des Feldes oder oberhalb der Anzeige
    s.cars = s.cars.filter((c) => !c.gone && c.y < g.H && c.y + c.h > g.TOP);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(40, g.TOP, 280, g.H - g.TOP, "ink", { round: 4 });

    // Mittellinien zwischen den Spuren, scrollen mit s.off
    for (let y = g.TOP + s.off; y < g.H; y += 80) {
      d.rect(138, y, 4, 40, "yellow");
      d.rect(218, y, 4, 40, "yellow");
    }

    // Gegner
    for (const c of s.cars) {
      d.rect(c.x, c.y, c.w, c.h, "cream", { round: 6, line: true });
      d.emoji("🚙", c.x + c.w / 2, c.y + c.h / 2, 30);
    }

    // Spieler-Wagen, blinkt in der Schutzzeit
    const me = s.me;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.rect(me.x, me.y, me.w, me.h, "red", { round: 6, line: true });
      d.emoji("🏎️", me.x + me.w / 2, me.y - 14, 30);
    }
  }
};

