const RAD = { big: 36, mid: 22, small: 12 };
const EMO = { big: 60, mid: 40, small: 24 };
const PTS = { big: 20, mid: 50, small: 100 };
const NEXT = { big: "mid", mid: "small" };
const SHIP_R = 14;

export default {
  title: "Felsen-Jaeger im All",
  controls: ["left", "right", "up", "fire"],
  lives: 3,

  init(g) {
    const s = {
      ship: { x: 180, y: 560, vx: 0, vy: 0, a: 0 },
      shots: [],
      rocks: [],
      safe: 0,
      spawnT: 90
    };
    for (let i = 0; i < 3 + g.level; i++) s.rocks.push(edgeRock(g, "big"));
    return s;
  },

  update(s, input, g) {
    const sh = s.ship;

    // Drehen und Schub
    if (input.left) sh.a -= 4;
    if (input.right) sh.a += 4;
    if (sh.a > 180) sh.a -= 360;
    if (sh.a < -180) sh.a += 360;
    if (input.up) {
      sh.vx += g.sin(sh.a) * 0.15;
      sh.vy -= g.cos(sh.a) * 0.15;
    }
    const speed = Math.sqrt(sh.vx * sh.vx + sh.vy * sh.vy);
    if (speed > 5) { sh.vx = sh.vx * 5 / speed; sh.vy = sh.vy * 5 / speed; }
    sh.vx *= 0.99;
    sh.vy *= 0.99;
    sh.x += sh.vx;
    sh.y += sh.vy;
    wrapPoint(sh, g);

    // Schuesse
    if (input.firePressed && s.shots.length < 4) {
      const dx = g.sin(sh.a), dy = -g.cos(sh.a);
      s.shots.push({ x: sh.x + dx * 16, y: sh.y + dy * 16, vx: dx * 7, vy: dy * 7, life: 60 });
      g.sound("shoot");
    }
    for (const b of s.shots) {
      b.x += b.vx;
      b.y += b.vy;
      b.life -= 1;
      wrapPoint(b, g);
    }
    s.shots = s.shots.filter((b) => b.life > 0);

    // Felsen bewegen
    for (const r of s.rocks) {
      r.x += r.vx;
      r.y += r.vy;
      wrapPoint(r, g);
    }

    // Treffer Schuss gegen Fels
    const kept = [];
    for (const r of s.rocks) {
      let hit = false;
      for (const b of s.shots) {
        if (!b.gone && g.hit({ x: b.x, y: b.y, r: 4 }, r)) { b.gone = true; hit = true; break; }
      }
      if (!hit) { kept.push(r); continue; }
      g.addScore(PTS[r.size] * g.level);
      g.sound("pop");
      const child = NEXT[r.size];
      if (child) { kept.push(childRock(g, r, child)); kept.push(childRock(g, r, child)); }
    }
    s.rocks = kept;
    s.shots = s.shots.filter((b) => !b.gone);

    // Kollision Fels gegen Schiff
    if (s.safe > 0) {
      s.safe -= 1;
    } else if (s.rocks.some((r) => g.hit({ x: sh.x, y: sh.y, r: SHIP_R }, r))) {
      g.sound("hurt");
      g.loseLife();
      sh.x = 180; sh.y = 320; sh.vx = 0; sh.vy = 0; sh.a = 0;
      s.safe = 90;
    }

    // Spawn grosser Felsen am Rand
    s.spawnT -= 1;
    if (s.spawnT <= 0) {
      if (s.rocks.length < 20) s.rocks.push(edgeRock(g, "big"));
      s.spawnT = Math.max(40, 90 - g.level);
    }

    // Level geschafft
    if (s.rocks.length === 0) {
      g.nextLevel();
      g.sound("level");
      if (g.level >= 4) { g.win(); return; }
      for (let i = 0; i < 3 + g.level; i++) s.rocks.push(edgeRock(g, "big"));
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const b of s.shots) d.circle(b.x, b.y, 3, "red");
    for (const r of s.rocks) d.emoji("🪨", r.x, r.y, EMO[r.size]);
    const sh = s.ship;
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🚀", sh.x, sh.y, 30);
      d.line(sh.x, sh.y, sh.x + g.sin(sh.a) * 22, sh.y - g.cos(sh.a) * 22, "ink", 3);
    }
  }
};

function wrapPoint(o, g) {
  if (o.x < 0) o.x += g.W;
  else if (o.x >= g.W) o.x -= g.W;
  if (o.y < g.TOP) o.y += g.H - g.TOP;
  else if (o.y >= g.H) o.y -= g.H - g.TOP;
}

function speedOf(g, size) {
  const base = size === "big" ? 0.5 : size === "mid" ? 0.9 : 1.4;
  return base + g.random() * 0.6;
}

function edgeRock(g, size) {
  const x = g.random() < 0.5 ? 2 : g.W - 2;
  const y = g.TOP + g.random() * (g.H - g.TOP);
  const ang = g.random() * 360;
  const sp = speedOf(g, size);
  return { x: x, y: y, vx: g.sin(ang) * sp, vy: g.cos(ang) * sp, size: size, r: RAD[size] };
}

function childRock(g, parent, size) {
  const ang = g.random() * 360;
  const sp = speedOf(g, size);
  return { x: parent.x, y: parent.y, vx: g.sin(ang) * sp, vy: g.cos(ang) * sp, size: size, r: RAD[size] };
}

