// Katze auf den Daechern (nur Spiel-API, keine Importe).
// Die Katze springt von Dach zu Dach, sammelt Fische und weicht Voegeln aus.
// Hinweis: Es gibt kein Fischgraeten-Emoji. Stattdessen sammelt die Katze Fische 🐟.
const GRAV = 0.5, JUMP = -10.5, FLOOR = 610;

export default {
  title: "Katze auf den Daechern",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 30, y: FLOOR - 30, w: 22, h: 30, vx: 0, vy: 0, ground: true },
      plats: [],
      fish: [],
      birds: [],
      flag: { x: 0, y: 0, w: 24, h: 30 },
      safe: 0
    };
    build(s, g);
    return s;
  },

  update(s, input, g) {
    const me = s.me;
    me.vx = input.left ? -3 : input.right ? 3 : 0;
    if (input.up && me.ground) {
      me.vy = JUMP;
      me.ground = false;
      g.sound("jump");
    }
    me.vy = Math.min(me.vy + GRAV, 12);
    const oldBottom = me.y + me.h;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);
    me.y += me.vy;
    me.ground = false;
    if (me.vy >= 0) {
      for (const p of s.plats) {
        const over = me.x + me.w > p.x && me.x < p.x + p.w;
        if (over && oldBottom <= p.y && me.y + me.h >= p.y) {
          me.y = p.y - me.h;
          me.vy = 0;
          me.ground = true;
        }
      }
    }

    if (s.safe > 0) s.safe -= 1;

    // Voegel kreisen von links nach rechts und wackeln auf und ab
    for (const b of s.birds) {
      b.x += b.vx;
      if (b.x > g.W + 30) b.x = -40;
      b.y = b.y0 + 14 * g.sin((g.frame * 3 + b.ph) % 360);
      if (s.safe === 0 && g.hit(me, { x: b.x, y: b.y, w: 28, h: 20 })) {
        g.sound("hurt");
        g.loseLife();
        respawn(s);
        return;
      }
    }

    // Fische einsammeln
    for (const f of s.fish) {
      if (!f.got && g.hit(me, f)) {
        f.got = true;
        g.addScore(10);
        g.sound("coin");
      }
    }
    s.fish = s.fish.filter((f) => !f.got);

    // Fahne auf dem obersten Dach: naechstes Level
    if (g.hit(me, s.flag)) {
      g.addScore(50);
      g.nextLevel();
      g.sound("level");
      build(s, g);
      return;
    }

    // Absturz
    if (me.y > g.H) {
      g.sound("hurt");
      g.loseLife();
      respawn(s);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(0, FLOOR, g.W, 30, "yellow", { round: 8, shadow: true, line: true });
    for (const p of s.plats.slice(1)) d.rect(p.x, p.y, p.w, p.h, "red", { round: 8, shadow: true, line: true });
    for (const f of s.fish) d.emoji("🐟", f.x + f.w / 2, f.y + f.h / 2, 16);
    for (const b of s.birds) d.emoji("🐦", b.x + 14, b.y + 10, 26);
    d.emoji("🚩", s.flag.x + 12, s.flag.y + 15, 30);
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🐱", s.me.x + s.me.w / 2, s.me.y + s.me.h / 2, 30);
    }
    d.text("Fische statt Fischgraeten", g.W / 2, 40, { size: 10, color: "ink", align: "center" });
  }
};

function build(s, g) {
  s.plats = [{ x: 0, y: FLOOR, w: g.W, h: 30 }];
  s.fish = [];
  let cx = 60;
  for (let row = 1; row <= 5; row++) {
    const w = g.randInt(90, 140), y = FLOOR - row * 92;
    cx = g.clamp(cx + g.randInt(-110, 110), w / 2 + 4, g.W - w / 2 - 4);
    const p = { x: cx - w / 2, y, w, h: 16 };
    s.plats.push(p);
    s.fish.push({ x: p.x + w / 2 - 8, y: y - 18, w: 16, h: 16, got: false });
  }
  const top = s.plats[s.plats.length - 1];
  s.flag = { x: top.x + top.w / 2 - 12, y: top.y - 30, w: 24, h: 30 };

  // Voegel: eine pro Level, hoechstens sechs
  s.birds = [];
  const n = Math.min(g.level, 6);
  for (let i = 0; i < n; i++) {
    s.birds.push({
      x: g.randInt(0, g.W),
      y0: g.randInt(g.TOP + 40, g.H - 160),
      y: 0,
      vx: g.randInt(1, 2),
      ph: g.randInt(0, 359)
    });
  }
  respawn(s);
}

function respawn(s) {
  s.me.x = 30;
  s.me.y = FLOOR - 30;
  s.me.vx = 0;
  s.me.vy = 0;
  s.me.ground = true;
  s.safe = 60;
}

// Katze auf den Daechern (nur Spiel-API, keine Importe).
