// Hinweis: Es gibt kein Fischgraeten-Emoji. Stattdessen sammelt die Katze Fische 🐟.
// Wer 15 Sekunden auf einem Dach ohne Fahne verbringt, rutscht ab und verliert ein Leben.
const GRAV = 0.5, JUMP = -10.5, FLOOR = 610;
const LIMIT = 900; // Frames (15 s) pro Leben bis zum Abrutschen

export default {
