// Donut im Labyrinth (nur Spiel-API, keine Importe). Der Donut sammelt Streusel,
// Moewen (🐦) jagen ihn durch feste Gaenge. Die Karte ist fest, nur der Zustand aendert sich.
const COLS = 18, ROWS = 26, CELL = 20, Y0 = 56;
const START = { x: 9, y: 23 };
const GULL_STARTS = [{ x: 1, y: 1 }, { x: 16, y: 23 }, { x: 16, y: 1 }, { x: 1, y: 23 }];
const MAP = [
  "##################",
  "#................#",
  "#.##....##....##.#",
  "#................#",
  "#....##....##....#",
  "#....##....##....#",
  "#.##....##....##.#",
  "#................#",
  "#....##....##....#",
  "#....##....##....#",
  "#.##....##....##.#",
  "#................#",
  "#....##....##....#",
  "#....##....##....#",
  "#.##....##....##.#",
  "#................#",
  "#....##....##....#",
  "#....##....##....#",
  "#.##....##....##.#",
  "#................#",
  "#....##....##....#",
  "#....##....##....#",
  "#.##....##....##.#",
  "#................#",
  "#....##....##....#",
  "##################"
];

export default {
  title: "Donut im Labyrinth",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    const s = {};
    build(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.safe > 0) s.safe -= 1;

    // Richtungswunsch merken (wird beim naechsten moeglichen Abbiegen umgesetzt)
    if (input.left) { s.wx = -1; s.wy = 0; }
    else if (input.right) { s.wx = 1; s.wy = 0; }
    else if (input.up) { s.wx = 0; s.wy = -1; }
    else if (input.down) { s.wx = 0; s.wy = 1; }

    // Donut bewegt sich alle 8 Frames um eine Zelle
    s.mt += 1;
    if (s.mt >= 8) {
      s.mt = 0;
      if ((s.wx !== 0 || s.wy !== 0) && !wall(s.px + s.wx, s.py + s.wy)) {
        s.dx = s.wx; s.dy = s.wy; s.wx = 0; s.wy = 0;
      }
      if (s.dx !== 0 || s.dy !== 0) {
        if (!wall(s.px + s.dx, s.py + s.dy)) {
          s.px += s.dx; s.py += s.dy;
        } else {
          s.dx = 0; s.dy = 0;
        }
      }
    }

    // Streusel fressen
    const i = s.py * COLS + s.px;
    if (s.dots[i] === 1) {
      s.dots[i] = 0;
      s.left -= 1;
      g.addScore(10);
      g.sound("coin");
    }

    // Moewen bewegen sich alle paar Frames um eine Zelle
    const interval = Math.max(7, 10 - (g.level - 1));
    if (g.frame % interval === 0) {
      for (const gl of s.gulls) {
        const dir = pickDir(gl, s, g);
        gl.dx = dir.dx;
        gl.dy = dir.dy;
        gl.x += dir.dx;
        gl.y += dir.dy;
      }
    }

    // Kollision Donut und Moewe
    if (s.safe === 0) {
      let caught = false;
      for (const gl of s.gulls) if (gl.x === s.px && gl.y === s.py) caught = true;
      if (caught) {
        g.sound("hurt");
        g.loseLife();
        resetPositions(s);
        return;
      }
    }

    // Level geschafft
    if (s.left <= 0) {
      g.addScore(50);
      g.nextLevel();
      g.sound("level");
      build(s, g);
      return;
    }

    // Zeitlimit pro Level (ohne Sieg)
    s.lt += 1;
    if (s.lt >= 7200) { g.gameOver(); return; }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const cx = x * CELL, cy = Y0 + y * CELL;
        if (wall(x, y)) {
          d.rect(cx + 1, cy + 1, CELL - 2, CELL - 2, "yellow", { round: 4, line: true });
        } else if (s.dots[y * COLS + x] === 1) {
          d.circle(cx + CELL / 2, cy + CELL / 2, 3, "ink");
        }
      }
    }
    for (const gl of s.gulls) {
      d.emoji("🐦", gl.x * CELL + CELL / 2, Y0 + gl.y * CELL + CELL / 2, 26);
    }
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.emoji("🍩", s.px * CELL + CELL / 2, Y0 + s.py * CELL + CELL / 2, 28);
    }
  }
};

function wall(x, y) {
  if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return true;
  return MAP[y].charAt(x) === "#";
}

function isGullStart(x, y, n) {
  for (let i = 0; i < n; i++) if (GULL_STARTS[i].x === x && GULL_STARTS[i].y === y) return true;
  return false;
}

function build(s, g) {
  const n = Math.min(g.level + 1, 4);
  const dots = [];
  let left = 0;
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      let on = !wall(x, y);
      if (x === START.x && y === START.y) on = false;
      if (isGullStart(x, y, n)) on = false;
      dots.push(on ? 1 : 0);
      if (on) left += 1;
    }
  }
  s.dots = dots;
  s.left = left;
  s.gulls = [];
  for (let i = 0; i < n; i++) s.gulls.push({ x: GULL_STARTS[i].x, y: GULL_STARTS[i].y, dx: 0, dy: 0 });
  s.px = START.x; s.py = START.y;
  s.dx = 0; s.dy = 0; s.wx = 0; s.wy = 0; s.mt = 0;
  s.safe = 60;
  s.lt = 0;
}

function resetPositions(s) {
  s.px = START.x; s.py = START.y;
  s.dx = 0; s.dy = 0; s.wx = 0; s.wy = 0; s.mt = 0;
  for (let i = 0; i < s.gulls.length; i++) {
    s.gulls[i].x = GULL_STARTS[i].x;
    s.gulls[i].y = GULL_STARTS[i].y;
    s.gulls[i].dx = 0;
    s.gulls[i].dy = 0;
  }
  s.safe = 60;
}

// Moewe waehlt ihre Richtung: an Kreuzungen meist die Richtung, die dem Donut naeher kommt,
// sonst zufaellig. Keine Umkehr, ausser in einer Sackgasse.
function pickDir(gl, s, g) {
  const all = [{ dx: 1, dy: 0 }, { dx: -1, dy: 0 }, { dx: 0, dy: 1 }, { dx: 0, dy: -1 }];
  const opts = [];
  for (const d of all) if (!wall(gl.x + d.dx, gl.y + d.dy)) opts.push(d);
  if (opts.length === 0) return { dx: 0, dy: 0 };
  const fwd = [];
  for (const d of opts) if (!(d.dx === -gl.dx && d.dy === -gl.dy)) fwd.push(d);
  const cand = fwd.length > 0 ? fwd : opts;
  if (g.random() < 0.6) {
    let best = cand[0];
    let bestD = Math.abs(gl.x + best.dx - s.px) + Math.abs(gl.y + best.dy - s.py);
    for (let i = 1; i < cand.length; i++) {
      const d = cand[i];
      const dist = Math.abs(gl.x + d.dx - s.px) + Math.abs(gl.y + d.dy - s.py);
      if (dist < bestD) { best = d; bestD = dist; }
    }
    return { dx: best.dx, dy: best.dy };
  }
  const pick = cand[g.randInt(0, cand.length - 1)];
  return { dx: pick.dx, dy: pick.dy };
}

