  controls: ["up"],
  lives: 3,

  init(g) {
    const s = {
      bird: { x: BX, y: BY0, w: BW, h: BH, vy: 0 },
      pipes: [makePipe(FIRST, g)],
      passed: 0,
      safe: 0,
      prevUp: false
    };
    return s;
  },

  update(s, input, g) {
    if (s.safe > 0) s.safe -= 1;

    // Flattern nur beim Neudruecken (Flanke)
    const flap = !!input.up && !s.prevUp;
    s.prevUp = !!input.up;

    const b = s.bird;
    if (flap) { b.vy = FLAP; g.sound("jump"); }
    b.vy = Math.min(b.vy + GRAV, VMAX);
    b.y += b.vy;

    // Saeulen scrollen und entfernen
    const sp = 2 + 0.3 * (g.level - 1);
    for (const p of s.pipes) p.x -= sp;
    s.pipes = s.pipes.filter((p) => p.x + PW >= 0);

    // Neue Saeule im Abstand von 200 px
    const last = s.pipes[s.pipes.length - 1];
    if (!last) s.pipes.push(makePipe(FIRST, g));
    else if (last.x + SPACING <= g.W) s.pipes.push(makePipe(last.x + SPACING, g));

