    for (const p of s.pipes) {
      if (!p.passed && p.x + PW < CX) {
        p.passed = true;
        g.addScore(10);
        s.passed += 1;
        g.sound("pop");
        if (s.passed >= 5) {
          s.passed = 0;
          g.nextLevel();
          g.sound("level");
        }
      }
    }

    // Kollision: Saeule, Decke, Boden
    if (s.safe === 0) {
