// Wasserball-Duell (nur Spiel-API, keine Importe). Zwei Tiere werfen abwechselnd Wasserballons.
// Zug fuer Zug am selben Geraet. Treffer machen die Gegenfigur nass. Keine Gewalt, kein Blut.
const GROUND = 600, FIG_X = [40, 320], R_HIT = 24, GRAV = 0.12, WAIT = 40, LIMIT = 420, THROWS = 10;

export default {
  title: "Wasserball-Duell",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    return {
      turn: 0, ang: [45, 135], pow: [5, 5], cap: 10,
      ball: null, trail: [], wait: 0, throws: 0, timer: 0,
      wet: 0, wetOn: 0, hits: 0, pts: [0, 0]
    };
  },

  update(s, input, g) {
    if (s.wet > 0) s.wet -= 1;
    const me = s.turn;

    if (s.ball === null) {
      if (s.wait > 0) { s.wait -= 1; return; }
      s.timer += 1;
      if (input.left) s.ang[me] = g.clamp(s.ang[me] - 2, 10, 170);
      if (input.right) s.ang[me] = g.clamp(s.ang[me] + 2, 10, 170);
      if (input.up) s.pow[me] = Math.min(s.pow[me] + 1, s.cap);
      if (input.down) s.pow[me] = Math.max(s.pow[me] - 1, 1);
      if (input.firePressed) {
        // Winkel direkt verwenden: cos ist fuer B negativ, also fliegt der Ball nach links.
        const p = s.pow[me];
        s.ball = {
          x: FIG_X[me], y: GROUND - 20,
          vx: p * 0.9 * g.cos(s.ang[me]),
          vy: -p * 0.9 * g.sin(s.ang[me])
        };
        s.trail = [];
        s.timer = 0;
        g.sound("shoot");
      } else if (s.timer >= LIMIT) {
        g.loseLife();
        g.sound("hurt");
        endThrow(s, g);
      }
      return;
    }

    // Ballflug
    const b = s.ball;
    b.vy += GRAV;
    b.x += b.vx;
    b.y += b.vy;
    s.trail.push({ x: b.x, y: b.y });
    if (s.trail.length > 40) s.trail.shift();

    const target = { x: FIG_X[1 - me], y: GROUND };
    if (g.dist(b, target) < R_HIT) {
      s.pts[me] += 10;
      s.hits += 1;
      g.addScore(10);
      g.sound("pop");
      s.wet = 60;
      s.wetOn = 1 - me;
      if (s.hits % 2 === 0) { g.nextLevel(); s.cap += 1; }
      endThrow(s, g);
    } else if (b.x < -20 || b.x > g.W + 20 || b.y >= GROUND) {
      g.loseLife();
      g.sound("hurt");
      endThrow(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.line(0, 610, g.W, 610, "yellow", 6);
    for (let x = 0; x < g.W; x += 60) d.circle(x + 30, 622, 6, "yellow");

    // Figuren mit eigener Farbe
    d.circle(FIG_X[0], GROUND, 24, "yellow");
    d.circle(FIG_X[1], GROUND, 24, "red");
    d.emoji("🐸", FIG_X[0], GROUND, 36);
    d.emoji("🐻", FIG_X[1], GROUND, 36);

    // Anzeige, wer am Zug ist
    if (s.ball === null && s.wait === 0) d.circle(FIG_X[s.turn], 560, 5, "red");

    // Zielhilfe: Flugbahn-Punkte fuer aktuellen Wurf
    if (s.ball === null && s.wait === 0) {
      const me = s.turn, p = s.pow[me];
      const vx = p * 0.9 * g.cos(s.ang[me]);
      const vy = -p * 0.9 * g.sin(s.ang[me]);
      for (let k = 1; k <= 6; k++) {
        const t = k * 6;
        const px = FIG_X[me] + vx * t;
        const py = GROUND - 20 + vy * t + 0.5 * GRAV * t * t;
        if (py < GROUND && px > 0 && px < g.W) d.circle(px, py, 3, "ink");
      }
    }

    // Flugbahn
    for (const p of s.trail) d.circle(p.x, p.y, 2, "ink");

    if (s.ball !== null) d.emoji("💧", s.ball.x, s.ball.y, 18);

    if (s.wet > 0) d.emoji("💦", FIG_X[s.wetOn], 555, 30);
  }
};

function endThrow(s, g) {
  s.ball = null;
  s.trail = [];
  s.throws += 1;
  if (s.throws >= THROWS) { finish(s, g); return; }
  s.turn = 1 - s.turn;
  s.wait = WAIT;
  s.timer = 0;
}

function finish(s, g) {
  const a = s.pts[0], b = s.pts[1];
  const top = Math.max(a, b);
  if (a !== b && top >= 30) g.win();
  else g.gameOver();
}

