// Wasserball-Duell (nur Spiel-API, keine Importe). Zwei Tiere werfen abwechselnd Wasserballons.
// Zug fuer Zug am selben Geraet. Treffer machen die Gegenfigur nass. Keine Gewalt, kein Blut.
// Sieger entscheiden die Treffer. Punkte gibt es fuer Treffer (10) und Spritzer (3), wenn der
// Ballon knapp neben der Gegenfigur ins Wasser faellt. Spritzer zaehlen nicht fuer den Sieg.
const GROUND = 600, FIG_X = [40, 320], R_HIT = 24, GRAV = 0.12, WAIT = 40, LIMIT = 240, THROWS = 10;
const SPLASH_RANGE = 100, SPLASH_POINTS = 3, HIT_POINTS = 10;
const NAMES = ["Frosch", "Bär"];

export default {
  title: "Wasserball-Duell",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    return {
      turn: 0, ang: [45, 135], pow: [5, 5], cap: 10,
      ball: null, trail: [], wait: 0, throws: 0, timer: 0,
      wet: 0, wetOn: 0, hits: [0, 0], pts: [0, 0], winner: null
    };
  },

  update(s, input, g) {
    if (s.throws >= THROWS) return;
    if (s.wet > 0) s.wet -= 1;
    const me = s.turn;

    if (s.ball === null) {
      if (s.wait > 0) { s.wait -= 1; return; }
      s.timer += 1;
      if (input.left) s.ang[me] = g.clamp(s.ang[me] - 2, 10, 170);
      if (input.right) s.ang[me] = g.clamp(s.ang[me] + 2, 10, 170);
      if (input.up) s.pow[me] = Math.min(s.pow[me] + 1, s.cap);
      if (input.down) s.pow[me] = Math.max(s.pow[me] - 1, 1);
      if (input.firePressed) {
        // Winkel direkt verwenden: cos ist fuer B negativ, also fliegt der Ball nach links.
        const p = s.pow[me];
        s.ball = {
          x: FIG_X[me], y: GROUND - 20,
          vx: p * 0.9 * g.cos(s.ang[me]),
          vy: -p * 0.9 * g.sin(s.ang[me])
        };
        s.trail = [];
        s.timer = 0;
        g.sound("shoot");
      } else if (s.timer >= LIMIT) {
        // Zeitablauf: Zug verfaellt ohne Leben-Verlust, der Zug wechselt.
        g.sound("hurt");
        endThrow(s, g);
      }
      return;
    }

    // Ballflug
    const b = s.ball;
    b.vy += GRAV;
    b.x += b.vx;
    b.y += b.vy;
    s.trail.push({ x: b.x, y: b.y });
    if (s.trail.length > 40) s.trail.shift();

    const target = { x: FIG_X[1 - me], y: GROUND };
    if (g.dist(b, target) < R_HIT) {
      // Treffer: zaehlt fuer den Sieg und bringt Punkte
      s.hits[me] += 1;
      s.pts[me] += HIT_POINTS;
      g.addScore(HIT_POINTS);
      g.sound("pop");
      s.wet = 60;
      s.wetOn = 1 - me;
      const total = s.hits[0] + s.hits[1];
      if (total % 2 === 0) { g.nextLevel(); s.cap += 1; }
      endThrow(s, g);
    } else if (b.x < -20 || b.x > g.W + 20 || b.y >= GROUND) {
      // Spritzer: Ballon landet knapp neben der Gegenfigur im Wasser (Punkte, kein Sieg-Treffer)
      if (b.y >= GROUND && b.x >= 0 && b.x <= g.W && Math.abs(b.x - target.x) < SPLASH_RANGE) {
        s.pts[me] += SPLASH_POINTS;
        g.addScore(SPLASH_POINTS);
        g.sound("coin");
      } else {
        // Fehlwurf: kein Leben-Verlust, nur Ton
        g.sound("hurt");
      }
      endThrow(s, g);
    }
  },

