    // Trefferstand beider Figuren immer sichtbar (unter der Anzeigeleiste)
    d.text(NAMES[0] + " " + s.hits[0] + " : " + s.hits[1] + " " + NAMES[1], g.W / 2, 80, { size: 22, color: "ink", align: "center" });
    d.text("Treffer " + s.hits[0] + " : " + s.hits[1], g.W / 2, 104, { size: 16, color: "ink", align: "center" });
    d.text("Wurf " + Math.min(s.throws + 1, THROWS) + " / " + THROWS, g.W / 2, 126, { size: 16, color: "ink", align: "center" });

    // Figuren mit eigener Farbe
    d.circle(FIG_X[0], GROUND, 24, "yellow");
    d.circle(FIG_X[1], GROUND, 24, "red");
    d.emoji("🐸", FIG_X[0], GROUND, 36);
    d.emoji("🐻", FIG_X[1], GROUND, 36);

    // Anzeige, wer am Zug ist
    if (s.ball === null && s.wait === 0 && s.throws < THROWS) d.circle(FIG_X[s.turn], 560, 5, "red");

    // Zielhilfe: Flugbahn-Punkte fuer aktuellen Wurf
    if (s.ball === null && s.wait === 0 && s.throws < THROWS) {
      const me = s.turn, p = s.pow[me];
      const vx = p * 0.9 * g.cos(s.ang[me]);
      const vy = -p * 0.9 * g.sin(s.ang[me]);
      for (let k = 1; k <= 6; k++) {
        const t = k * 6;
        const px = FIG_X[me] + vx * t;
        const py = GROUND - 20 + vy * t + 0.5 * GRAV * t * t;
        if (py < GROUND && px > 0 && px < g.W) d.circle(px, py, 3, "ink");
      }
    }

    // Flugbahn
    for (const p of s.trail) d.circle(p.x, p.y, 2, "ink");

    if (s.ball !== null) d.emoji("💧", s.ball.x, s.ball.y, 18);

    if (s.wet > 0) d.emoji("💦", FIG_X[s.wetOn], 555, 30);

    // Siegerfeld am Spielende, passend zum Trefferstand
    if (s.throws >= THROWS) {
      const text = s.winner === -1 ? "Unentschieden" : "Sieger: " + NAMES[s.winner];
      d.rect(30, 280, 300, 100, "cream", { round: 12, line: true });
      d.text(text, g.W / 2, 316, { size: 26, color: "ink", align: "center" });
      d.text("Treffer " + s.hits[0] + " : " + s.hits[1], g.W / 2, 350, { size: 18, color: "ink", align: "center" });
    }
  }
};

function endThrow(s, g) {
  s.ball = null;
  s.trail = [];
  s.throws += 1;
  if (s.throws >= THROWS) { finish(s, g); return; }
  s.turn = 1 - s.turn;
  s.wait = WAIT;
  s.timer = 0;
}

// Sieger nach Treffern (nicht nach Punkten). Gleichstand = Unentschieden.
function finish(s, g) {
  const a = s.hits[0], b = s.hits[1];
  if (a > b) { s.winner = 0; g.win(); }
  else if (b > a) { s.winner = 1; g.win(); }
  else { s.winner = -1; g.gameOver(); }
}

