// Enkel-Memory (nur Spiel-API, keine Importe): 6 Tier-Paare suchen, Fehlversuche kosten ein Leben.
// Ersatz fuer Fotos der Enkel: Tier-Emojis als Paare.
const SYMS = ["🐶", "🐱", "🐰", "🐸", "🐵", "🦊"];
const CW = 70, CH = 96;

export default {
  title: "Enkel-Memory",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    const syms = [];
    for (let i = 0; i < 12; i++) syms.push(SYMS[i % 6]);
    // Fisher-Yates mit dem Seed-Zufall
    for (let i = 11; i > 0; i--) {
      const j = g.randInt(0, i);
      const t = syms[i];
      syms[i] = syms[j];
      syms[j] = t;
    }
    const cards = [];
    for (let i = 0; i < 12; i++) {
      const c = i % 4, r = Math.floor(i / 4);
      cards.push({ x: 24 + c * 84, y: 88 + r * 116, w: CW, h: CH, sym: syms[i], open: false, done: false });
    }
    return { cards: cards, cur: 0, first: null, second: null, hide: 0, cool: 0 };
  },

  update(s, input, g) {
    if (s.cool > 0) s.cool -= 1;
    const dirHeld = input.left || input.right || input.up || input.down;
    if (!dirHeld) {
      s.cool = 0;
    } else if (s.cool === 0) {
      const col = s.cur % 4, row = Math.floor(s.cur / 4);
      let nc = col, nr = row;
      if (input.left) nc = col - 1;
      else if (input.right) nc = col + 1;
      else if (input.up) nr = row - 1;
      else if (input.down) nr = row + 1;
      if (nc >= 0 && nc < 4 && nr >= 0 && nr < 3) s.cur = nr * 4 + nc;
      s.cool = 8;
    }

    // Falsches Paar wird nach 40 Frames wieder zugedeckt; in dieser Zeit kein Aufdecken
    if (s.hide > 0) {
      s.hide -= 1;
      if (s.hide === 0) {
        if (s.first !== null) s.cards[s.first].open = false;
        if (s.second !== null) s.cards[s.second].open = false;
        s.first = null;
        s.second = null;
      }
      return;
    }

    if (input.firePressed) {
      const c = s.cards[s.cur];
      if (!c.open && !c.done) {
        c.open = true;
        g.sound("pop");
        if (s.first === null) {
          s.first = s.cur;
        } else {
          const f = s.cards[s.first];
          s.second = s.cur;
          if (f.sym === c.sym) {
            f.done = true;
            c.done = true;
            s.first = null;
            s.second = null;
            g.addScore(10);
            g.sound("coin");
            let all = true;
            for (const k of s.cards) if (!k.done) all = false;
            if (all) {
              g.addScore(50);
              g.win();
            }
          } else {
            s.hide = 40;
            g.sound("hurt");
            g.loseLife();
          }
        }
      }
    }
  },

  draw(s, d) {
    d.clear("cream");
    for (const c of s.cards) {
      if (c.done) {
        d.rect(c.x, c.y, c.w, c.h, "ink", { round: 8 });
        d.rect(c.x + 4, c.y + 4, c.w - 8, c.h - 8, "cream", { round: 6 });
        d.emoji(c.sym, c.x + c.w / 2, c.y + c.h / 2, 40);
      } else if (c.open) {
        d.rect(c.x, c.y, c.w, c.h, "cream", { round: 8, line: true });
        d.emoji(c.sym, c.x + c.w / 2, c.y + c.h / 2, 40);
      } else {
        d.rect(c.x, c.y, c.w, c.h, "yellow", { round: 8, line: true });
      }
    }
    const cc = s.cards[s.cur];
    d.rect(cc.x - 3, cc.y - 3, cc.w + 6, cc.h + 6, "red", { round: 10, line: true });
  }
};

