  g.addScore(10);

  if (above) {
    g.sound("hurt");
    g.loseLife();
    s.board = [];
    spawn(s, g);
    return;
  }

  const cnt = [];
  for (let y = 0; y < ROWS; y++) cnt.push(0);
  for (const b of s.board) cnt[b.y] += 1;
  const full = [];
  let k = 0;
  for (let y = 0; y < ROWS; y++) {
    const f = cnt[y] === COLS;
    full.push(f);
    if (f) k += 1;
  }

  if (k > 0) {
    const nb = [];
    for (const b of s.board) {
      if (full[b.y]) continue;
      let shift = 0;
      for (let y = b.y + 1; y < ROWS; y++) if (full[y]) shift += 1;
      nb.push({ x: b.x, y: b.y + shift, e: b.e });
    }
