    for (let i = 0; i < k; i++) {
      s.lines += 1;
      g.addScore(100 * g.level);
      if (s.lines % 5 === 0) {
        g.nextLevel();
        g.sound("level");
      }
    }
    g.sound("coin");
    if (s.lines >= 12) {
      g.win();
      return;
    }
  }

  spawn(s, g);
}

