// Tennis gegen Computer (nur Spiel-API, keine Importe).
// Mein Schlaeger links, Computer-Schlaeger rechts. Der Ball prallt ab; je nach Trefferstelle wird er schraeg.
// Komme ich unter dem Ball durch, verliere ich ein Leben. Trifft der Ball die Seite des Computers vorbei, gibt es Punkte.
const PAD_W = 10, PAD_H = 90, BALL_R = 8, MAX_VX = 9, MAX_VY = 7;

export default {
  title: "Tennis gegen Computer",
  controls: ["up", "down"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 20, y: 300, w: PAD_W, h: PAD_H },
      cpu: { x: 330, y: 300, w: PAD_W, h: PAD_H },
      ball: { x: 180, y: 340, vx: 3, vy: 0, r: BALL_R },
      wait: 0,
      won: 0,
      spd: 1
    };
    serve(s, g, g.random() < 0.5 ? -1 : 1);
    return s;
  },

  update(s, input, g) {
    const me = s.me, cpu = s.cpu, b = s.ball;

    // Mein Schlaeger
    if (input.up) me.y -= 5;
    if (input.down) me.y += 5;
    me.y = g.clamp(me.y, g.TOP + 4, g.H - 94);

    // Computer-Schlaeger folgt der Ballmitte, mit kleinem Zufallsfehler
    const sp = 3 + 0.4 * g.level;
    const step = g.clamp(b.y - (cpu.y + PAD_H / 2), -sp, sp) + (g.random() - 0.5) * 1.2;
    cpu.y = g.clamp(cpu.y + step, g.TOP + 4, g.H - 94);

    // Wartezeit vor dem Aufschlag
    if (s.wait > 0) { s.wait -= 1; return; }

    b.x += b.vx;
    b.y += b.vy;

    // Obere und untere Kante
    if (b.y < g.TOP + 8) { b.y = 2 * (g.TOP + 8) - b.y; b.vy = Math.abs(b.vy); }
    else if (b.y > g.H - 8) { b.y = 2 * (g.H - 8) - b.y; b.vy = -Math.abs(b.vy); }

    // Treffer auf meinen Schlaeger (von links kommend)
    if (b.vx < 0 && overlap(b, me)) {
      b.x = me.x + me.w + b.r;
      b.vx = Math.min(MAX_VX, -b.vx * 1.03);
      b.vy = g.clamp(b.vy + (b.y - (me.y + PAD_H / 2)) / 20, -MAX_VY, MAX_VY);
      g.sound("hit");
    }
    // Treffer auf den Computer-Schlaeger (von rechts kommend)
    else if (b.vx > 0 && overlap(b, cpu)) {
      b.x = cpu.x - b.r;
      b.vx = -Math.min(MAX_VX, b.vx * 1.03);
      b.vy = g.clamp(b.vy + (b.y - (cpu.y + PAD_H / 2)) / 20, -MAX_VY, MAX_VY);
      g.sound("hit");
    }

    // Ball verlaesst links das Feld: ein Leben weg
    if (b.x + b.r < 0) {
      g.sound("hurt");
      g.loseLife();
      serve(s, g, g.random() < 0.5 ? -1 : 1);
      return;
    }

    // Ball verlaesst rechts das Feld: Punkt fuer mich
    if (b.x - b.r > g.W) {
      g.addScore(10 * g.level);
      g.sound("coin");
      s.won += 1;
      if (s.won >= 5) {
        s.won = 0;
        g.nextLevel();
        g.sound("level");
        s.spd *= 1.1;
        if (g.level >= 3) { g.win(); return; }
      }
      serve(s, g, -1); // zum Spieler hin
      return;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    // gestrichelte Mittellinie
    for (let y = g.TOP + 8; y < g.H - 8; y += 24) d.rect(178, y, 4, 12, "ink");
    // Schlaeger
    d.rect(s.me.x, s.me.y, s.me.w, s.me.h, "ink", { round: 4 });
    d.rect(s.cpu.x, s.cpu.y, s.cpu.w, s.cpu.h, "ink", { round: 4 });
    // Ball
    d.emoji("🎾", s.ball.x, s.ball.y, 18);
  }
};

// Neuer Aufschlag in Richtung dir (-1 links zum Spieler, 1 rechts zum Computer), mit 40 Frames Wartezeit
function serve(s, g, dir) {
  s.ball = {
    x: 180,
    y: 340,
    vx: dir * (3 + g.random()) * s.spd,
    vy: -2 + 4 * g.random(),
    r: BALL_R
  };
  s.wait = 40;
}

// Kollision Kreis (Ball) mit Rechteck (Schlaeger)
function overlap(b, p) {
  return b.x + b.r > p.x && b.x - b.r < p.x + p.w && b.y + b.r > p.y && b.y - b.r < p.y + p.h;
}

