      if (s.won >= WIN_PTS) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      s.spd = Math.min(1.6, s.spd * 1.1);
      serve(s, g, -1); // zum Spieler hin
      return;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    // gestrichelte Mittellinie
    for (let y = g.TOP + 8; y < g.H - 8; y += 24) d.rect(178, y, 4, 12, "ink");
    // Spielstand: Du : PC, mit Untergrund, damit die Mittellinie nicht stoert
    d.rect(110, g.TOP + 12, 140, 28, "cream", { round: 8, line: true });
    d.text("Du " + s.won + " : " + s.cpuPts + " PC", 180, g.TOP + 19, { size: 20, color: "ink", align: "center" });
