    }
  },

  draw(s, d, g) {
    d.clear("cream");

    // Anzeige: vier Kaesten mit Name und Gesamtpunkten, aktive Person rot umrandet
    for (let i = 0; i < 4; i++) {
      const x = 6 + i * 88, y = 56, w = 84, h = 60;
      if (i === s.p) {
        d.rect(x - 3, y - 3, w + 6, h + 6, "red", { round: 10 });
        d.rect(x, y, w, h, "cream", { round: 8, line: true });
      } else {
        d.rect(x, y, w, h, "yellow", { round: 8, line: true });
      }
      d.text("Spieler " + (i + 1), x + w / 2, y + 16, { size: 12, color: "ink", align: "center" });
      d.text(String(s.pts[i]), x + w / 2, y + 42, { size: 20, color: "ink", align: "center" });
    }

    // Mitte: zwei Wuerfel mit Augen (bleiben stehen, bis der naechste Wurf kommt)
    drawDie(d, 120, 260, s.a);
    drawDie(d, 240, 260, s.b);

    d.text("Zugpunkte: " + s.t, g.W / 2, 340, { size: 28, color: "ink", align: "center" });

    // Meldung zum letzten Zug (erklaert den Zugwechsel)
    if (s.msgT > 0) {
      d.text(s.msg, g.W / 2, 400, { size: 18, color: "red", align: "center" });
      d.text(s.msg2, g.W / 2, 426, { size: 16, color: "ink", align: "center" });
    }

    d.text("Am Zug: Spieler " + (s.p + 1), g.W / 2, 470, { size: 20, color: "red", align: "center" });

    // Hinweis unten
    d.text("fire = wuerfeln, right = sichern", g.W / 2, 600, { size: 16, color: "ink", align: "center" });
  }
};

function nextPlayer(s) {
  s.p = (s.p + 1) % 4;
}

function drawDie(d, cx, cy, v) {
  d.rect(cx - 30, cy - 30, 60, 60, "cream", { round: 10, shadow: true, line: true });
  if (v === 0) {
    d.text("?", cx, cy, { size: 28, color: "ink", align: "center" });
    return;
  }
  const pips = PIPS[v];
  for (let i = 0; i < pips.length; i++) {
    const dx = pips[i][0] * 15;
    const dy = pips[i][1] * 15;
    d.circle(cx + dx, cy + dy, 5, "ink");
  }
}

// Gummibär-Schätzen (nur Spiel-API, keine Importe): Im Glas liegen Gummibärchen. Du und der Computer schätzen die Anzahl.
// Wer näher dran ist, gewinnt die Runde. Der Computer-Gegner verliert dir gegenüber nie absichtlich, sondern rät im Band um die echte Zahl.
// Steuerung: Pfeile oder Steuerkreuz ändern die Zahl (oben/unten ±1, links/rechts ±5), Fire bestätigt.

export default {
  title: "Gummibär-Schätzen",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      round: 1,
      wins: 0,
      cpuWins: 0,
      guess: 20,
      rep: 0,
      t: 0,
      phase: "schaetzen",
      timer: 0,
      cpu: 0,
      real: 0,
      bears: [],
      msg: ""
    };
    newRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "schaetzen") {
      let step = 0;
      if (input.up) step += 1;
      if (input.down) step -= 1;
      if (input.right) step += 5;
      if (input.left) step -= 5;
      if (step === 0) {
        s.rep = 0;
      } else if (s.rep === 0) {
        s.guess = g.clamp(s.guess + step, 0, 99);
        s.rep = 8;
      } else {
        s.rep -= 1;
      }
      s.t += 1;
      if (input.firePressed || s.t >= 400) lockGuess(s, g);
    } else {
      s.timer -= 1;
      if (s.timer <= 0) nextRoundOrEnd(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Runde " + s.round + " von 5", 180, 80, { size: 20, color: "ink", align: "center" });
    d.text("Du " + s.wins + " : " + s.cpuWins + " Computer", 180, 110, { size: 18, color: "ink", align: "center" });
    d.rect(110, 200, 140, 300, "cream", { round: 14, line: true });
    for (const b of s.bears) d.emoji(b.e, b.x, b.y, 18);
    if (s.phase === "schaetzen") {
      d.text("Wie viele Gummibärchen sind im Glas?", 180, 170, { size: 16, color: "ink", align: "center" });
      d.text("Deine Schätzung", 180, 520, { size: 18, color: "ink", align: "center" });
      d.text(String(s.guess), 180, 545, { size: 56, color: "red", align: "center" });
      d.text("Pfeile aendern - Fire bestaetigt", 180, 615, { size: 14, color: "ink", align: "center" });
    } else {
      d.text("Computer: " + s.cpu, 180, 520, { size: 18, color: "ink", align: "center" });
      d.text("Du: " + s.guess, 180, 548, { size: 18, color: "ink", align: "center" });
      d.text("Echte Anzahl: " + s.real, 180, 576, { size: 20, color: "red", align: "center" });
      d.text(s.msg, 180, 612, { size: 16, color: "ink", align: "center" });
    }
  }
};

function newRound(s, g) {
  const n = g.randInt(8, 40);
  s.bears = [];
  for (let i = 0; i < n; i++) {
    let p = null;
    for (let t = 0; t < 30; t++) {
      p = { x: g.randInt(128, 232), y: g.randInt(218, 482), e: g.randInt(0, 1) === 0 ? "🐻" : "🍬" };
      if (!s.bears.some((b) => g.dist(b, p) < 17)) break;
    }
    s.bears.push(p);
  }
  s.real = s.bears.length;
  s.guess = 20;
  s.rep = 0;
  s.t = 0;
  s.phase = "schaetzen";
  s.timer = 0;
  s.cpu = 0;
  s.msg = "";
}

function lockGuess(s, g) {
  const real = s.real;
  const band = Math.min(12, 2 + g.level * 2);
  const dev = g.randInt(0, band);
  const sign = g.randInt(0, 1) === 0 ? -1 : 1;
  s.cpu = g.clamp(real + sign * dev, 0, 99);
  const pd = Math.abs(s.guess - real);
  const cd = Math.abs(s.cpu - real);
  if (pd === 0) g.addScore(30);
  let computerWon = false;
  if (pd < cd) {
    s.wins += 1;
    g.addScore(10 * g.level);
    g.sound("coin");
    s.msg = "Du gewinnst die Runde!";
  } else if (cd < pd) {
    s.cpuWins += 1;
    computerWon = true;
    g.sound("hurt");
    s.msg = "Der Computer war naeher dran.";
  } else {
    s.msg = "Gleichstand - niemand punktet.";
  }
  s.phase = "ergebnis";
  s.timer = 120;
  if (computerWon) g.loseLife();
}

function nextRoundOrEnd(s, g) {
  if (s.round % 5 === 0) {
    g.nextLevel();
    g.sound("level");
  }
  if (s.round >= 5) {
    if (s.wins > s.cpuWins) g.win();
    else g.gameOver();
    return;
  }
  s.round += 1;
  newRound(s, g);
}

