// Mau-Mau gegen den Computer (nur Spiel-API, keine Importe).
// Hinweise: Es gibt kein Eichel-Emoji, daher steht 🌰 fuer Eichel. Bildkarten (Koenig, Bube) sind nicht machbar:
// die Werte 11 bis 14 stehen als Zahl im Text.

const SUITS = ["❤️", "🔔", "🌰", "🍀"];
const CARD_W = 26, CARD_H = 60, STEP = 28, HAND_Y = 480;
const MAX_HAND = 12, AI_WAIT = 30, PLAYER_COOL = 12, CURSOR_COOL = 8, WIN_ROUNDS = 5;

export default {
  title: "Mau-Mau gegen den Computer",
  controls: ["left", "right", "up", "fire"],
  lives: 3,

  init(g) {
    const s = { stock: [], pile: [], me: [], cpu: [], cur: 0, wait: 0, pc: 0, mc: 0, wins: 0 };
    deal(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.pc > 0) s.pc -= 1;
    if (s.mc > 0) s.mc -= 1;
    if (s.cur >= s.me.length) s.cur = Math.max(0, s.me.length - 1);

    // Cursor in der eigenen Hand
    if (s.mc === 0) {
      if (input.left && s.cur > 0) { s.cur -= 1; s.mc = CURSOR_COOL; }
      else if (input.right && s.cur < s.me.length - 1) { s.cur += 1; s.mc = CURSOR_COOL; }
    }

    // Spieler-Zug
    if (s.pc === 0) {
      if (input.firePressed) {
        const c = s.me[s.cur];
        if (c && playable(c, top(s))) {
          s.me.splice(s.cur, 1);
          s.pile.push(c);
          s.cur = Math.max(0, Math.min(s.cur, s.me.length - 1));
          g.addScore(5);
          g.sound("pop");
          s.pc = PLAYER_COOL;
          if (s.me.length === 0) { roundEnd(s, g, true); return; }
        } else {
          g.sound("hurt");
        }
      } else if (input.up && !s.me.some((c) => playable(c, top(s)))) {
        if (draw(s, g, s.me)) {
          g.sound("coin");
          s.pc = PLAYER_COOL;
          if (s.me.length >= MAX_HAND) { roundEnd(s, g, false); return; }
        }
      }
    }

    // Keine Runde mehr moeglich (Stapel leer, niemand kann legen): wer weniger Karten hat, gewinnt
    if (stalled(s)) {
      if (s.me.length < s.cpu.length) roundEnd(s, g, true);
      else if (s.me.length > s.cpu.length) roundEnd(s, g, false);
      else deal(s, g);
      return;
    }

    // Computer wartet 30 Frames, dann legt er die hoechste passende Karte oder zieht
    s.wait += 1;
    if (s.wait < AI_WAIT) return;
    s.wait = 0;
    const t = top(s);
    let best = -1;
    for (let i = 0; i < s.cpu.length; i++) {
      if (playable(s.cpu[i], t) && (best < 0 || s.cpu[i].v > s.cpu[best].v)) best = i;
    }
    if (best >= 0) {
      const c = s.cpu.splice(best, 1)[0];
      s.pile.push(c);
      g.sound("jump");
      if (s.cpu.length === 0) roundEnd(s, g, false);
      return;
    }
    draw(s, g, s.cpu);
  },

  draw(s, d, g) {
    d.clear("cream");

    // Computer: verdeckte Karten und Anzahl
    const nc = s.cpu.length;
    const cx0 = (g.W - (nc * 16 - 6)) / 2;
    d.text("Computer", 16, 58, { size: 14, color: "ink", align: "left" });
    d.text(String(nc), 344, 58, { size: 14, color: "ink", align: "right" });
    for (let i = 0; i < nc; i++) d.rect(cx0 + i * 16, 78, 22, 30, "ink", { round: 4 });

    // Stapel links (verdeckt), offene Karte in der Mitte
    d.rect(40, 200, 70, 96, "ink", { round: 6, shadow: true });
    d.text(String(s.stock.length), 75, 240, { size: 20, color: "cream", align: "center" });
    if (s.pile.length > 0) drawCard(d, 250, 200, 70, 96, top(s), 34, 28);

    // Spieler-Hand mit Cursor
    d.text("Du   Runden " + s.wins + "/" + WIN_ROUNDS, 16, 452, { size: 14, color: "ink", align: "left" });
    const n = s.me.length;
    const hx0 = (g.W - (n * STEP - (STEP - CARD_W))) / 2;
    const cur = Math.min(s.cur, Math.max(0, n - 1));
    for (let i = 0; i < n; i++) {
      const x = hx0 + i * STEP;
      if (i === cur) d.rect(x - 3, HAND_Y - 3, CARD_W + 6, CARD_H + 6, "red", { round: 8 });
      drawCard(d, x, HAND_Y, CARD_W, CARD_H, s.me[i], 14, 12);
    }

    // Hinweis, was jetzt geht
    const can = s.me.some((c) => playable(c, top(s)));
    const hint = can ? "Feuer legt die Karte, Links/Rechts waehlt" : "Keine passende Karte: Hoch zieht eine";
    d.text(hint, 180, 560, { size: 12, color: "ink", align: "center" });
  }
};

function drawCard(d, x, y, w, h, c, es, ts) {
  d.rect(x, y, w, h, "yellow", { round: 6, line: true });
  d.emoji(SUITS[c.s], x + w / 2, y + h * 0.33, es);
  d.text(String(c.v + 7), x + w / 2, y + h * 0.7, { size: ts, color: "ink", align: "center" });
}

function top(s) {
  return s.pile[s.pile.length - 1];
}

function playable(c, t) {
  return c.s === t.s || c.v === t.v;
}

function shuffle(list, g) {
  for (let i = list.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const tmp = list[i];
    list[i] = list[j];
    list[j] = tmp;
  }
}

function deal(s, g) {
  const stock = [];
  for (let su = 0; su < 4; su++) for (let v = 0; v < 8; v++) stock.push({ s: su, v: v });
  shuffle(stock, g);
  s.me = [];

