}

function top(s) {
  return s.pile[s.pile.length - 1];
}

function playable(c, t) {
  return c.s === t.s || c.v === t.v;
}

function shuffle(list, g) {
  for (let i = list.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const tmp = list[i];
    list[i] = list[j];
    list[j] = tmp;
  }
}

// Der Ablagestapel (ohne oberste Karte) wird neu gemischt, wenn der Ziehstapel leer ist.
function recycle(s, g) {
  if (s.pile.length <= 1) return;
  const keep = s.pile.pop();
  s.stock = s.pile;
  s.pile = [keep];
  shuffle(s.stock, g);
}

// Zieht eine Karte vom Stapel in die gegebene Hand. Gibt true zurueck, wenn etwas gezogen wurde.
function drawOne(s, g, hand) {
  if (s.stock.length === 0) recycle(s, g);
  if (s.stock.length === 0) return false;
  hand.push(s.stock.pop());
  return true;
}

function stalled(s) {
  if (s.stock.length > 0 || s.pile.length > 1) return false;
  const t = top(s);
  return !s.me.some((c) => playable(c, t)) && !s.cpu.some((c) => playable(c, t));
}

function endRound(s, g, playerWon) {
  if (playerWon) {
    s.wins += 1;
    g.addScore(20);
    g.sound("level");
    if (s.wins >= WIN_ROUNDS) { g.win(); return; }
    g.nextLevel();
  } else {
    g.sound("lose");
    g.loseLife();
  }
  deal(s, g);
}

function deal(s, g) {
  const deck = [];
  for (let su = 0; su < 4; su++) for (let v = 0; v < 8; v++) deck.push({ s: su, v: v });
  shuffle(deck, g);
  s.me = [];
  s.cpu = [];
  for (let i = 0; i < START_HAND; i++) {
    s.me.push(deck.pop());
    s.cpu.push(deck.pop());
  }
  s.pile = [deck.pop()];
  s.stock = deck;
  s.cur = 0;
  s.wait = 0;
  s.pc = 0;
  s.mc = 0;
}

