      if (playable(s.cpu[i], t) && (best < 0 || s.cpu[i].v > s.cpu[best].v)) best = i;
    }
    if (best >= 0) {
      const c = s.cpu.splice(best, 1)[0];
      s.pile.push(c);
      g.sound("jump");
      if (s.cpu.length === 0) { endRound(s, g, false); }
      return;
    }
    drawOne(s, g, s.cpu);
  },

  draw(s, d, g) {
    d.clear("cream");

    // Computer: verdeckte Karten und Anzahl
    const nc = s.cpu.length;
    const cx0 = (g.W - (nc * 16 - 6)) / 2;
    d.text("Computer", 16, 58, { size: 14, color: "ink", align: "left" });
    d.text(String(nc), 344, 58, { size: 14, color: "ink", align: "right" });
    for (let i = 0; i < nc; i++) d.rect(cx0 + i * 16, 78, 22, 30, "ink", { round: 4 });

    // Stapel links (verdeckt), offene Karte in der Mitte
    d.rect(40, 200, 70, 96, "ink", { round: 6, shadow: true });
    d.text(String(s.stock.length), 75, 240, { size: 20, color: "cream", align: "center" });
    if (s.pile.length > 0) drawCard(d, 250, 200, 70, 96, top(s), 34, 28);

    // Spieler-Hand mit Cursor
    d.text("Du   Runden " + s.wins + "/" + WIN_ROUNDS, 16, 452, { size: 14, color: "ink", align: "left" });
    const n = s.me.length;
    const hx0 = (g.W - (n * STEP - (STEP - CARD_W))) / 2;
    const cur = Math.min(s.cur, Math.max(0, n - 1));
    for (let i = 0; i < n; i++) {
      const x = hx0 + i * STEP;
      if (i === cur) d.rect(x - 3, HAND_Y - 3, CARD_W + 6, CARD_H + 6, "red", { round: 8 });
      drawCard(d, x, HAND_Y, CARD_W, CARD_H, s.me[i], 14, 12);
    }

    // Hinweise
    const can = s.me.some((c) => playable(c, top(s)));
    const hint = can ? "Feuer legt, Links/Rechts waehlt" : "Keine passende Karte: Hoch zieht eine";
    d.text(hint, 180, 560, { size: 12, color: "ink", align: "center" });
    d.text("Zahlen 11-14 statt Bildkarten", 180, 620, { size: 10, color: "ink", align: "center" });
  }
};

function drawCard(d, x, y, w, h, c, es, ts) {
  d.rect(x, y, w, h, "yellow", { round: 6, line: true });
  d.emoji(SUITS[c.s], x + w / 2, y + h * 0.33, es);
  d.text(String(c.v + 7), x + w / 2, y + h * 0.7, { size: ts, color: "ink", align: "center" });
}

function top(s) {
  return s.pile[s.pile.length - 1];
}

function playable(c, t) {
  return c.s === t.s || c.v === t.v;
}

function shuffle(list, g) {
  for (let i = list.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const tmp = list[i];
    list[i] = list[j];
    list[j] = tmp;
  }
}

// Der Ablagestapel (ohne oberste Karte) wird neu gemischt, wenn der Ziehstapel leer ist.
function recycle(s, g) {
  if (s.pile.length <= 1) return;
  const keep = s.pile.pop();
  s.stock = s.pile;
  s.pile = [keep];
  shuffle(s.stock, g);
}

// Zieht eine Karte vom Stapel in die gegebene Hand. Gibt true zurueck, wenn etwas gezogen wurde.
function drawOne(s, g, hand) {
  if (s.stock.length === 0) recycle(s, g);
  if (s.stock.length === 0) return false;
  hand.push(s.stock.pop());
  return true;
}

function stalled(s) {
  if (s.stock.length > 0 || s.pile.length > 1) return false;
  const t = top(s);
  return !s.me.some((c) => playable(c, t)) && !s.cpu.some((c) => playable(c, t));
}

function endRound(s, g, playerWon) {
  if (playerWon) {
    s.wins += 1;
    g.addScore(20);
    g.sound("level");
    if (s.wins >= WIN_ROUNDS) { g.win(); return; }
    g.nextLevel();
  } else {
    g.sound("lose");
    g.loseLife();
  }
  deal(s, g);
}

function deal(s, g) {
  const deck = [];
  for (let su = 0; su < 4; su++) for (let v = 0; v < 8; v++) deck.push({ s: su, v: v });
  shuffle(deck, g);
  s.me = [];
  s.cpu = [];
  for (let i = 0; i < START_HAND; i++) {
    s.me.push(deck.pop());
    s.cpu.push(deck.pop());
  }
  s.pile = [deck.pop()];
  s.stock = deck;
  s.cur = 0;
  s.wait = 0;
  s.pc = 0;
  s.mc = 0;
}

