// Alle Veraenderungen liegen in s. Modulvariablen werden nicht veraendert.
const BALL_R = 8;
const PAD_Y = 600;
const PAD_H = 14;
const PAD_W = 70;
const ATTACH_Y = 585;
const MAX_SPEED = 7;
const MAX_MUL = 1.75;

export default {
  title: "Pizza-Ausbrecher",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return {
      pad: { x: 145, y: PAD_Y, w: PAD_W, h: PAD_H },
      ball: { x: 180, y: ATTACH_Y, vx: 0, vy: 0, r: BALL_R },
      att: 60,
      mul: 1,
      bricks: makeBricks(g.TOP)
    };
  },

  update(s, input, g) {
    const p = s.pad;
    const b = s.ball;

    // Schlaeger bewegen
    if (input.left) p.x -= 5;
    if (input.right) p.x += 5;
    p.x = g.clamp(p.x, 0, g.W - p.w);

    // Pizza liegt auf dem Schlaeger, bis der Startzaehler abgelaufen ist
    if (s.att > 0) {
      s.att -= 1;
      b.x = p.x + p.w / 2;
      b.y = ATTACH_Y;
      b.vx = 0;
      b.vy = 0;
      if (s.att === 0) {
        b.vx = 3 * s.mul;
        b.vy = -4 * s.mul;
      }
      return;
    }

    // Bewegung
    b.x += b.vx;
    b.y += b.vy;

    // Waende und obere Grenze
    if (b.x < 8) { b.x = 8; b.vx = Math.abs(b.vx); }
    if (b.x > g.W - 8) { b.x = g.W - 8; b.vx = -Math.abs(b.vx); }
    if (b.y < g.TOP + 8) { b.y = g.TOP + 8; b.vy = Math.abs(b.vy); }

    // Schlaegertreffer (nur beim Fallen)
    if (b.vy > 0 && b.y + BALL_R >= p.y && b.y <= p.y + p.h && b.x >= p.x && b.x <= p.x + p.w) {
      b.y = p.y - BALL_R;
      b.vy = -Math.abs(b.vy);
      b.vx = g.clamp(((b.x - (p.x + p.w / 2)) / 35) * 4, -5, 5);
      g.sound("hit");
    }

    // Bausteintreffer: hoechstens einer pro Frame
    let hitIdx = -1;
    for (let i = 0; i < s.bricks.length; i++) {
      if (ballHitsRect(b, s.bricks[i])) { hitIdx = i; break; }
    }
    if (hitIdx >= 0) {
      s.bricks = s.bricks.filter((_, i) => i !== hitIdx);
      b.vy = -b.vy;
      g.addScore(10 * g.level);
      g.sound("pop");
    }

    // Geschwindigkeit begrenzen
    b.vx = g.clamp(b.vx, -MAX_SPEED, MAX_SPEED);
    b.vy = g.clamp(b.vy, -MAX_SPEED, MAX_SPEED);

    // Pizza unten vorbei: Leben weg, neu auf den Schlaeger
    if (b.y > g.H) {
      g.sound("hurt");
      g.loseLife();
      b.x = p.x + p.w / 2;
      b.y = ATTACH_Y;
      b.vx = 0;
      b.vy = 0;
      s.att = 60;
      return;
    }

    // Level geschafft
    if (s.bricks.length === 0) {
      if (g.level >= 5) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      s.mul = Math.min(s.mul * 1.1, MAX_MUL);
      b.vx = g.clamp(b.vx * 1.1, -MAX_SPEED, MAX_SPEED);
      b.vy = g.clamp(b.vy * 1.1, -MAX_SPEED, MAX_SPEED);
      s.bricks = makeBricks(g.TOP);
      b.x = p.x + p.w / 2;
      b.y = ATTACH_Y;
      b.vx = 0;
      b.vy = 0;
      s.att = 60;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const br of s.bricks) {
      d.rect(br.x, br.y, br.w, br.h, br.c, { round: 4, line: true });
    }
    d.rect(s.pad.x, s.pad.y, s.pad.w, s.pad.h, "red", { round: 6, line: true });
    d.emoji("🍕", s.ball.x, s.ball.y, 26);
  }
};

function makeBricks(top) {
  const out = [];
  const colors = ["red", "yellow"];
  for (let r = 0; r < 5; r++) {
    for (let c = 0; c < 6; c++) {
      out.push({
        x: 6 + c * 58,
        y: top + 30 + r * 26,
        w: 54,
        h: 20,
        c: colors[(r + c) % 2],
        hp: 1
      });
    }
  }
  return out;
}

function ballHitsRect(b, r) {
  const nx = Math.max(r.x, Math.min(b.x, r.x + r.w));
  const ny = Math.max(r.y, Math.min(b.y, r.y + r.h));
  const dx = b.x - nx;
  const dy = b.y - ny;
  return dx * dx + dy * dy <= b.r * b.r;
}

