// Autobahn-Ueberholer (nur Spiel-API, keine Importe). Roter Sportwagen auf drei Spuren.
// Gas (oben) beschleunigt den Verkehr, Bremse (unten) verlangsamt ihn. Ueberholte Autos bringen Punkte.
const LANES = [100, 180, 260];
const EMO = ["🚙", "🚕", "🚌"];
const PY = 510;      // obere Kante des Spielers (Mitte bei y=540)
const PBOT = 570;    // Unterkante des Spielers
const CAR_W = 36;
const CAR_H = 56;

export default {
  title: "Autobahn-Ueberholer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return { cx: 180, cars: [], safe: 0, over: 0 };
  },

  update(s, input, g) {
    if (g.frame >= 7200) { g.win(); return; }

    if (s.safe > 0) s.safe -= 1;

    // Spur-Wechsel gleitend, 4 px pro Frame
    if (input.left) s.cx -= 4;
    if (input.right) s.cx += 4;
    s.cx = g.clamp(s.cx, 62, 298);

    // Verkehrstempo
    const pace = 3 + 0.3 * g.level;
    let speed = pace + (input.up ? 2 : 0) - (input.down ? 1 : 0);
    if (speed < 1) speed = 1;
    for (const c of s.cars) c.y += speed;

    const me = { x: s.cx - 20, y: PY, w: 40, h: 60 };
    const kept = [];
    for (const c of s.cars) {
      const box = { x: c.x, y: c.y, w: CAR_W, h: CAR_H };

      // Unfall: Auto verschwindet, Leben weg, kurze Schonzeit
      if (s.safe === 0 && g.hit(me, box)) {
        g.sound("hurt");
        g.loseLife();
        s.safe = 60;
        continue;
      }

      // Ueberholen: Auto ist unten am Spieler vorbei und nicht auf derselben Hoehe
      if (!c.done && c.y > PBOT) {
        c.done = true;
        if (Math.abs(c.x + CAR_W / 2 - s.cx) >= 36) {
          s.over += 1;
          g.addScore(10 * g.level);
          g.sound("pop");
          if (s.over % 5 === 0) { g.nextLevel(); g.sound("level"); }
        }
      }

      if (c.y <= g.H) kept.push(c);
    }
    s.cars = kept;

    // Neue Autos oben, Spur nicht doppelt belegen, wenn der letzte Wagen dort noch zu nah ist
    if (g.random() < 0.025 + 0.005 * g.level) {
      const lane = g.randInt(0, 2);
      const x = LANES[lane] - CAR_W / 2;
      const blocked = s.cars.some((c) => c.x === x && c.y < 40);
      if (!blocked) s.cars.push({ x: x, y: -60, k: g.randInt(0, 2), done: false });
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(60, g.TOP, 240, g.H - g.TOP, "ink");
    const off = (g.frame * 4) % 40;
    for (let y = g.TOP - 40 + off; y < g.H; y += 40) {
      d.line(140, y, 140, y + 24, "cream", 3);
      d.line(220, y, 220, y + 24, "cream", 3);
    }
    for (const c of s.cars) d.emoji(EMO[c.k], c.x + CAR_W / 2, c.y + CAR_H / 2, 36);
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.rect(s.cx - 20, PY, 40, 60, "red", { round: 8, line: true });
      d.emoji("🏎️", s.cx, PY + 30, 36);
    }
  }
};

