// Die Fahrbahn scrollt mit der eigenen Geschwindigkeit. Ziel: 7000 Streckeneinheiten.
const LANES = [100, 180, 260];
const EMO = ["🚙", "🚕", "🚌"];
const PY = 510;      // obere Kante des Spielers (Mitte bei y=540)
const PBOT = 570;    // Unterkante des Spielers
const CAR_W = 36;
const CAR_H = 56;
const GOAL = 7000;   // Streckeneinheiten bis zum Ziel
const MAX_LVL = 8;   // Obergrenze fuer Tempo und Dichte
const V_MIN = 2, V_MAX = 10, V_START = 5;

export default {
  title: "Autobahn-Ueberholer",
  controls: ["left", "right", "up", "down"],
  lives: 3,

  init(g) {
    return { cx: LANES[1], lane: 1, pl: false, pr: false, v: V_START, road: 0, dist: 0, cars: [], safe: 0, over: 0 };
  },

