    if (s.safe > 0) s.safe -= 1;

    // Spurwechsel: beim Druck (Flanke) eine Spur weiter, dann gleitend zur Spurmitte
    if (input.left && !s.pl) s.lane = Math.max(0, s.lane - 1);
    if (input.right && !s.pr) s.lane = Math.min(2, s.lane + 1);
    s.pl = !!input.left;
    s.pr = !!input.right;
    const dxs = LANES[s.lane] - s.cx;
    s.cx += g.clamp(dxs, -4, 4);
    s.cx = g.clamp(s.cx, 62, 298);

