    if (input.up) s.v += 0.15;
    if (input.down) s.v -= 0.2;
    s.v = g.clamp(s.v, V_MIN, V_MAX);

    // Fahrbahn scrollt mit eigener Geschwindigkeit, Strecke waechst
    s.road = (s.road + s.v) % 40;
    s.dist += s.v;
    if (s.dist >= GOAL) { g.win(); return; }

    // Verkehr: Autos ziehen relativ zur eigenen Geschwindigkeit (schneller fahren = Autos ziehen weniger schnell nach unten)
    const pace = 3 + 0.3 * g.level;
    const rel = Math.max(1, pace + 0.6 * (6 - s.v));
