    d.clear("cream");
    d.rect(60, g.TOP, 240, g.H - g.TOP, "ink");
    // Fahrbahnstriche scrollen mit der eigenen Geschwindigkeit
    for (let y = g.TOP - 40 + s.road; y < g.H; y += 40) {
      d.line(140, y, 140, y + 24, "cream", 3);
      d.line(220, y, 220, y + 24, "cream", 3);
    }
    for (const c of s.cars) d.emoji(EMO[c.k], c.x + CAR_W / 2, c.y + CAR_H / 2, 36);
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) {
      d.rect(s.cx - 20, PY, 40, 60, "red", { round: 8, line: true });
      d.emoji("🏎️", s.cx, PY + 30, 36);
    }
    // Fortschritt zum Ziel: Balken oben in der Fahrbahn und Prozentzahl
    const frac = g.clamp(s.dist / GOAL, 0, 1);
    d.rect(66, g.TOP + 4, 228, 6, "cream", { round: 3 });
    d.rect(66, g.TOP + 4, Math.max(1, 228 * frac), 6, "yellow", { round: 3 });
    d.text("Ziel " + Math.floor(frac * 100) + " %", 180, g.TOP + 22, { size: 14, color: "yellow", align: "center" });
  }
};

