// Felsen-Jäger im All (nur Spiel-API, keine Importe).
// Ein Raumschiff fliegt im Weltraum. Mit fire schiesst es in Flugrichtung, Felsen zerbrechen in kleinere Brocken.
// Das Emoji steht immer aufrecht; die Flugrichtung zeigt ein roter Strich (Emojis lassen sich nicht drehen).
const SHIP_X = 180, SHIP_Y = 320;

export default {
  title: "Felsen-Jäger im All",
  controls: ["left", "right", "up", "fire"],
  lives: 3,

  init(g) {
    return {
      ship: { x: SHIP_X, y: SHIP_Y, vx: 0, vy: 0, a: 0 },
      shots: [],
      rocks: wave(g),
      inv: 0,
      cool: 0
    };
  },

  update(s, input, g) {
    const sh = s.ship;

    // Drehen
    if (input.left) sh.a = norm(sh.a - 4);
    if (input.right) sh.a = norm(sh.a + 4);

    // Schub in Blickrichtung, Tempo begrenzen, Reibung
    if (input.up) {
      sh.vx += g.sin(sh.a) * 0.15;
      sh.vy -= g.cos(sh.a) * 0.15;
      const sp = Math.sqrt(sh.vx * sh.vx + sh.vy * sh.vy);
      if (sp > 5) { sh.vx = sh.vx * 5 / sp; sh.vy = sh.vy * 5 / sp; }
    }
    sh.vx *= 0.99;
    sh.vy *= 0.99;
    sh.x += sh.vx;
    sh.y += sh.vy;
    wrap(sh, g);

    if (s.inv > 0) s.inv -= 1;
    if (s.cool > 0) s.cool -= 1;

    // Schuss an der Spitze in Flugrichtung
    if (input.firePressed && s.cool === 0 && s.shots.length < 5) {
      s.shots.push({
        x: sh.x + g.sin(sh.a) * 20,
        y: sh.y - g.cos(sh.a) * 20,
        vx: g.sin(sh.a) * 8,
        vy: -g.cos(sh.a) * 8,
        r: 4,
        life: 60
      });
      s.cool = 12;
      g.sound("shoot");
    }

    // Schuesse bewegen und altern
    for (const shot of s.shots) {
      shot.x += shot.vx;
      shot.y += shot.vy;
      shot.life -= 1;
      wrap(shot, g);
    }

    // Felsen bewegen
    for (const rock of s.rocks) {
      rock.x += rock.vx;
      rock.y += rock.vy;
      wrap(rock, g);
    }

    // Schuss trifft Fels: Schuss weg, Fels zerbricht
    const rocks = [];
    for (const rock of s.rocks) {
      let hit = false;
      for (const shot of s.shots) {
        if (shot.life > 0 && g.hit(shot, rock)) { shot.life = 0; hit = true; break; }
      }
      if (!hit) { rocks.push(rock); continue; }
      g.addScore(rock.size === 3 ? 10 : rock.size === 2 ? 20 : 50);
      g.sound("pop");
      if (rock.size > 1) {
        const ang = g.random() * 360;
        const sp = Math.min(3, Math.sqrt(rock.vx * rock.vx + rock.vy * rock.vy) + 0.3);
        const size = rock.size - 1;
        const r = size === 2 ? 18 : 10;
        rocks.push({ x: rock.x, y: rock.y, vx: g.sin(ang) * sp, vy: -g.cos(ang) * sp, r: r, size: size });
        rocks.push({ x: rock.x, y: rock.y, vx: -g.sin(ang) * sp, vy: g.cos(ang) * sp, r: r, size: size });
      }
    }
    s.rocks = rocks;
    s.shots = s.shots.filter((shot) => shot.life > 0);

    // Fels trifft Schiff: Leben weg, Schiff zurueck in die Mitte, kurz unverwundbar
    if (s.inv === 0 && s.rocks.some((rock) => g.hit({ x: sh.x, y: sh.y, r: 14 }, rock))) {
      g.sound("hurt");
      g.loseLife();
      sh.x = SHIP_X; sh.y = SHIP_Y; sh.vx = 0; sh.vy = 0; sh.a = 0;
      s.inv = 90;
      s.rocks = s.rocks.filter((rock) => g.dist(rock, { x: SHIP_X, y: SHIP_Y }) >= 100);
    }

    // Welle geschafft
    if (s.rocks.length === 0) {
      if (g.level >= 5) { g.win(); return; }
      g.nextLevel();
      g.sound("level");
      s.rocks = wave(g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const rock of s.rocks) {
      d.circle(rock.x, rock.y, rock.r, "ink");
      d.emoji("🪨", rock.x, rock.y, rock.r * 2);
    }
    for (const shot of s.shots) d.circle(shot.x, shot.y, shot.r, "yellow");
    const sh = s.ship;
    if (s.inv === 0 || (s.inv >> 3) % 2 === 0) {
      d.emoji("🚀", sh.x, sh.y, 36);
    }
    // Flugrichtung: roter Strich von der Schiffsmitte
    d.line(sh.x, sh.y, sh.x + g.sin(sh.a) * 30, sh.y - g.cos(sh.a) * 30, "red", 3);
  }
};

function norm(a) {
  return ((a % 360) + 360) % 360;
}

function wrap(o, g) {
  if (o.x < 0) o.x += g.W;
  if (o.x > g.W) o.x -= g.W;
  const top = g.TOP, h = g.H - g.TOP;
  if (o.y < top) o.y += h;
  if (o.y > g.H) o.y -= h;
}

function wave(g) {
  const out = [];
  const count = g.level + 3;
  const speed = 0.5 + 0.2 * g.level;
  for (let i = 0; i < count; i++) {
    const x = g.random() < 0.5 ? 0 : g.W;
    const y = g.TOP + g.random() * (g.H - g.TOP);
    const ang = g.random() * 360;
    out.push({ x: x, y: y, vx: g.sin(ang) * speed, vy: -g.cos(ang) * speed, r: 30, size: 3 });
  }
  return out;
}

