// Dach-Katze (nur Spiel-API, keine Importe). Die Katze springt ueber Daecher, sammelt Fische,
// weicht Voegeln aus und erreicht die Fahne auf dem obersten Dach.
// Hinweis: Fischgraeten gibt es nicht (fehlt). Ersatz ist der Fisch 🐟.
const GRAV = 0.5, JUMP = -10.5, FLOOR = 610, ROW = 92;

export default {
  title: "Dach-Katze",
  controls: ["left", "right", "up"],
  lives: 3,

  init(g) {
    const s = {
      me: { x: 0, y: 0, w: 22, h: 30, vx: 0, vy: 0, ground: true },
      roofs: [], fish: [], birds: [],
      flag: { x: 0, y: 0, w: 24, h: 30 },
      safe: 0, home: 0
    };
    build(s, g);
    respawn(s);
    return s;
  },

  update(s, input, g) {
    const me = s.me;
    me.vx = input.left ? -3 : input.right ? 3 : 0;
    if (input.up && me.ground) { me.vy = JUMP; me.ground = false; g.sound("jump"); }
    me.vy = Math.min(me.vy + GRAV, 12);
    const oldBottom = me.y + me.h;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);
    me.y += me.vy;
    me.ground = false;
    if (me.vy >= 0) {
      for (let i = 0; i < s.roofs.length; i++) {
        const p = s.roofs[i];
        const over = me.x + me.w > p.x && me.x < p.x + p.w;
        if (over && oldBottom <= p.y && me.y + me.h >= p.y) {
          me.y = p.y - me.h; me.vy = 0; me.ground = true; s.home = i;
        }
      }
    }
    if (s.safe > 0) s.safe -= 1;

    // Voegel fliegen waagerecht und prallen an den Raendern ab
    for (const b of s.birds) {
      b.x += b.vx;
      if ((b.x < 0 && b.vx < 0) || (b.x + b.w > g.W && b.vx > 0)) b.vx = -b.vx;
    }
    if (s.safe === 0) {
      for (const b of s.birds) {
        if (g.hit(me, b)) { g.sound("hurt"); g.loseLife(); s.safe = 60; break; }
      }
    }

    // Fische einsammeln
    for (const f of s.fish) {
      if (!f.got && g.hit(me, f)) { f.got = true; g.addScore(10); g.sound("coin"); }
    }
    s.fish = s.fish.filter((f) => !f.got);

    // Fahne auf dem Ziel-Dach
    if (g.hit(me, s.flag)) {
      g.addScore(50); g.sound("level");
      if (g.level >= 5) { g.win(); return; }
      g.nextLevel();
      build(s, g);
      respawn(s);
      return;
    }

    // Abgrund: Leben weg, zurueck auf das letzte sichere Dach
    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); respawn(s); }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Fische statt Fischgraeten: fehlt", g.W / 2, 70, { size: 12, color: "ink", align: "center" });
    for (const r of s.roofs) d.rect(r.x, r.y, r.w, r.h, "red", { round: 6, shadow: true, line: true });
    for (const f of s.fish) d.emoji("🐟", f.x + f.w / 2, f.y + f.h / 2, 18);
    for (const b of s.birds) d.emoji("🐦", b.x + b.w / 2, b.y + b.h / 2, 26);
    d.emoji("🚩", s.flag.x + 12, s.flag.y + 15, 30);
    if (s.safe === 0 || (s.safe >> 2) % 2 === 0) d.emoji("🐱", s.me.x + s.me.w / 2, s.me.y + s.me.h / 2, 30);
  }
};

function build(s, g) {
  s.roofs = [];
  s.fish = [];
  s.birds = [];
  s.home = 0;
  let cx = 70;
  for (let row = 0; row <= 5; row++) {
    const y = FLOOR - row * ROW;
    const w = row === 0 ? 120 : g.randInt(80, 140);
    if (row === 0) cx = 70;
    else cx = g.clamp(cx + g.randInt(-70, 70), w / 2 + 4, g.W - w / 2 - 4);
    const main = { x: cx - w / 2, y: y, w: w, h: 16 };
    s.roofs.push(main);
    addFish(s, main);

    // Seitliches Dach auf gleicher Hoehe mit einer Luecke dazwischen
    if (row >= 1 && row < 5 && g.random() < 0.5) {
      const sw = g.randInt(80, 120), gap = g.randInt(40, 70);
      let sx = null;
      if (main.x + main.w + gap + sw <= g.W - 4) sx = main.x + main.w + gap;
      else if (main.x - gap - sw >= 4) sx = main.x - gap - sw;
      if (sx !== null) {
        const side = { x: sx, y: y, w: sw, h: 16 };
        s.roofs.push(side);
        addFish(s, side);
      }
    }
  }

  const n = Math.min(1 + g.level, 4);
  for (let i = 0; i < n; i++) {
    s.birds.push({
      x: g.randInt(0, g.W - 26),
      y: g.randInt(120, 500),
      w: 26, h: 22,
      vx: (i % 2 === 0 ? 1 : -1) * (0.8 + 0.2 * g.level)
    });
  }

  const top = s.roofs[5];
  s.flag = { x: top.x + top.w / 2 - 12, y: top.y - 30, w: 24, h: 30 };
}

function addFish(s, roof) {
  s.fish.push({ x: roof.x + roof.w / 2 - 8, y: roof.y - 26, w: 16, h: 16, got: false });
}

function respawn(s) {
  const r = s.roofs[s.home];
  s.me.x = r.x + r.w / 2 - s.me.w / 2;
  s.me.y = r.y - s.me.h;
  s.me.vx = 0; s.me.vy = 0; s.me.ground = true;
  s.safe = 60;
}

