versuche.code:
// Wasserballon-Duell (nur Spiel-API, keine Importe).
// Zwei Figuren stehen sich unten gegenueber und werfen Wasserballons. Zug fuer Zug am selben Geraet.
// Hinweis (nicht umgesetzt): Beide Spieler gleichzeitig mit eigenen Tasten geht auf einem Geraet nicht.
// Ersatz: Der Zug wechselt nach jedem Wurf, der aktive Spieler ist klar markiert.
// Keine Menschen, kein Blut, keine Waffen: Frosch und Ente werfen Wasserballons.

const P = [null, { x: 40, y: 600 }, { x: 300, y: 600 }];
const AIM_MAX = 12;
const SPEED = 10;
const GRAV = 0.15;
const LIMIT = 40;

function angle(i) {
  return 25 + i * 5;
}

function aimVec(s, g) {
  const dir = s.turn === 1 ? 1 : -1;
  const a = angle(s.aim);
  s.ux = dir * g.cos(a);
  s.uy = -g.sin(a);
}

function throwBalloon(s, g) {
  const dir = s.turn === 1 ? 1 : -1;
  const from = P[s.turn];
  const a = angle(s.aim);
  s.balloon = { x: from.x + dir * 18, y: from.y - 20, vx: dir * g.cos(a) * SPEED, vy: -g.sin(a) * SPEED, r: 8 };
  s.throws += 1;
  g.sound("shoot");
}

function nextTurn(s, g) {
  s.turn = 3 - s.turn;
  if (s.throws >= LIMIT) g.gameOver();
}

function fly(s, g) {
  const b = s.balloon;
  b.vy += GRAV + 0.03 * (g.level - 1);
  b.x += b.vx;
  b.y += b.vy;
  const target = P[3 - s.turn];
  if (g.hit(b, { x: target.x, y: target.y - 4, r: 18 })) {
    s.balloon = null;
    g.addScore(10);
    g.sound("hit");
    s.hits += 1;
    if (s.turn === 1) s.wet2 += 1; else s.wet1 += 1;
    const wet = s.turn === 1 ? s.wet2 : s.wet1;
    if (s.hits % 5 === 0) g.nextLevel();
    if (wet >= 3) { g.win(); return; }
    nextTurn(s, g);
    return;
  }
  if (b.y >= 610 || b.x < -30 || b.x > 390) {
    s.balloon = null;
    g.sound("lose");
    g.loseLife();
    nextTurn(s, g);
  }
}

function play(s, input, g) {
  if (s.balloon) { fly(s, g); return; }
  const key = input.left ? -1 : input.right ? 1 : 0;
  if (key !== 0) {
    if (s.tick % 6 === 0) s.aim = g.clamp(s.aim + key, 0, AIM_MAX);
    s.tick += 1;
  } else {
    s.tick = 0;
  }
  if (input.firePressed) throwBalloon(s, g);
}

export default {
  title: "Wasserballon-Duell",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    const s = { turn: 1, aim: 6, tick: 0, balloon: null, wet1: 0, wet2: 0, throws: 0, hits: 0, ux: 0, uy: 0 };
    aimVec(s, g);
    return s;
  },

  update(s, input, g) {
    play(s, input, g);
    aimVec(s, g);
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, 616, 360, 24, "yellow");

    const act = P[s.turn];
    d.circle(act.x, act.y, 26, "yellow", { line: true });
    d.emoji("🐸", P[1].x, P[1].y, 36);
    d.emoji("🦆", P[2].x, P[2].y, 36);

    for (let i = 0; i < s.wet1; i++) d.circle(P[1].x - 12 + i * 12, 560, 4, "ink");
    for (let i = 0; i < s.wet2; i++) d.circle(P[2].x - 12 + i * 12, 560, 4, "ink");

    if (s.balloon) {
      const b = s.balloon;
      d.circle(b.x, b.y, b.r, "yellow", { line: true });
    } else {
      const fx = act.x, fy = act.y - 20;
      d.line(fx, fy, fx + s.ux * 60, fy + s.uy * 60, "red", 3);
    }

    d.text(s.turn === 1 ? "Frosch am Zug" : "Ente am Zug", 180, 80, { size: 20, color: "ink", align: "center" });
    d.text(s.balloon ? "Ballon fliegt..." : "links/rechts zielen, fire wirft", 180, 110, { size: 14, color: "ink", align: "center" });
    d.text(`Wurf ${Math.min(s.throws + 1, LIMIT)} von ${LIMIT}`, 180, 135, { size: 14, color: "ink", align: "center" });
    d.text(`Nass: Frosch ${s.wet1} : Ente ${s.wet2}`, 180, 160, { size: 14, color: "ink", align: "center" });
    d.text("Ein Geraet: Zug fuer Zug", 180, 185, { size: 12, color: "ink", align: "center" });
  }
};

