// Huhn im Hoehenflug (nur Spiel-API, keine Importe).
// Das Huhn flattert mit Tippen oder fire nach oben und faellt sonst. Rohrpaare mit Luecke kommen von rechts.
const BX = 70;      // feste x-Mitte des Huhns
const BR = 14;      // Huhn-Radius fuer die Kollision
const GAP = 150;    // Luecke zwischen den Rohren
const PW = 50;      // Rohrbreite
const START_Y = 300;

export default {
  title: "Huhn im Hoehenflug",
  controls: ["fire"],
  lives: 3,

  init(g) {
    return { bird: { y: START_Y, vy: 0 }, pipes: [], passed: 0, safe: 0 };
  },

  update(s, input, g) {
    if (s.safe > 0) s.safe -= 1;

    // Flattern und Schwerkraft
    if (input.firePressed) {
      s.bird.vy = -8;
      g.sound("jump");
    }
    s.bird.vy = Math.min(s.bird.vy + 0.5, 9);
    s.bird.y += s.bird.vy;

    // Neues Rohrpaar alle 100 Frames
    if (g.frame % 100 === 0) {
      const gy = g.randInt(g.TOP + 60, g.H - 210);
      s.pipes.push({ x: g.W, gy: gy, passed: false });
    }

    // Bewegung nach links, mit steigendem Level schneller
    const speed = 2.0 + 0.3 * g.level;
    for (const p of s.pipes) {
      p.x -= speed;
      if (!p.passed && p.x + PW / 2 < BX) {
        p.passed = true;
        s.passed += 1;
        g.addScore(10);
        g.sound("coin");
        if (s.passed % 8 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }
    s.pipes = s.pipes.filter((p) => p.x > -60);

    // Kollisionen (nur ausserhalb des Schutzes)
    if (s.safe === 0) {
      const ball = { x: BX, y: s.bird.y, r: BR };
      let hurt = false;
      if (s.bird.y - BR < g.TOP || s.bird.y + BR > g.H - 30) hurt = true;
      for (const p of s.pipes) {
        const upper = { x: p.x, y: g.TOP, w: PW, h: p.gy - g.TOP };
        const lower = { x: p.x, y: p.gy + GAP, w: PW, h: g.H - 30 - (p.gy + GAP) };
        if (hitRect(ball, upper) || hitRect(ball, lower)) hurt = true;
      }
      if (hurt) {
        crash(s, g);
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const p of s.pipes) {
      d.rect(p.x, g.TOP, PW, p.gy - g.TOP, "yellow", { round: 4, line: true });
      d.rect(p.x, p.gy + GAP, PW, g.H - 30 - (p.gy + GAP), "yellow", { round: 4, line: true });
    }
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🐔", BX, s.bird.y, 30);
    }
  }
};

// Kreis (x,y Mitte, r) gegen Rechteck (x,y links oben, w, h)
function hitRect(b, r) {
  const cx = Math.max(r.x, Math.min(b.x, r.x + r.w));
  const cy = Math.max(r.y, Math.min(b.y, r.y + r.h));
  const dx = b.x - cx;
  const dy = b.y - cy;
  return dx * dx + dy * dy < b.r * b.r;
}

// Huhn verliert ein Leben, kehrt zur Startposition zurueck, Rohre werden geleert, kurzer Schutz.
function crash(s, g) {
  g.sound("hurt");
  g.loseLife();
  s.bird = { y: START_Y, vy: 0 };
  s.pipes = [];
  s.safe = 90;
}

