    s.bird.vy = Math.min(s.bird.vy + 0.5, 9);
    s.bird.y += s.bird.vy;

    // Neues Rohrpaar: Abstand sinkt mit dem Level (Zaehler in s, nicht g.frame)
    if (s.spawn > 0) {
      s.spawn -= 1;
    } else {
      const gy = g.randInt(g.TOP + 60, g.H - 210);
      const gap = Math.max(120, 150 - 5 * (g.level - 1));
      s.pipes.push({ x: g.W, gy: gy, gap: gap, passed: false });
      s.spawn = Math.max(55, 100 - 8 * g.level);
    }

    // Bewegung nach links, mit steigendem Level schneller
    const speed = 2.0 + 0.3 * g.level;
    for (const p of s.pipes) {
      p.x -= speed;
      if (!p.passed && p.x + PW / 2 < BX) {
        p.passed = true;
        s.passed += 1;
        g.addScore(10);
        g.sound("coin");
        // Schwierigkeit spuerbar: Level schon nach je 3 passierten Rohrpaaren
        if (s.passed % 3 === 0) {
          g.nextLevel();
          g.sound("level");
        }
      }
    }
    s.pipes = s.pipes.filter((p) => p.x > -60);

    // Kollisionen (nur ausserhalb des Schutzes)
    if (s.safe === 0) {
      const ball = { x: BX, y: s.bird.y, r: BR };
      let hurt = false;
      if (s.bird.y - BR < g.TOP || s.bird.y + BR > g.H - 30) hurt = true;
      for (const p of s.pipes) {
        const upper = { x: p.x, y: g.TOP, w: PW, h: p.gy - g.TOP };
        const lower = { x: p.x, y: p.gy + p.gap, w: PW, h: g.H - 30 - (p.gy + p.gap) };
        if (hitRect(ball, upper) || hitRect(ball, lower)) hurt = true;
      }
      if (hurt) {
        crash(s, g);
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const p of s.pipes) {
      d.rect(p.x, g.TOP, PW, p.gy - g.TOP, "yellow", { round: 4, line: true });
      d.rect(p.x, p.gy + p.gap, PW, g.H - 30 - (p.gy + p.gap), "yellow", { round: 4, line: true });
