    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.emoji("🐔", BX, s.bird.y, 30);
    }
  }
};

// Kreis (x,y Mitte, r) gegen Rechteck (x,y links oben, w, h)
function hitRect(b, r) {
  const cx = Math.max(r.x, Math.min(b.x, r.x + r.w));
  const cy = Math.max(r.y, Math.min(b.y, r.y + r.h));
  const dx = b.x - cx;
  const dy = b.y - cy;
  return dx * dx + dy * dy < b.r * b.r;
}

// Huhn verliert ein Leben, kehrt zur Startposition zurueck, Rohre werden geleert, kurzer Schutz.
function crash(s, g) {
  g.sound("hurt");
  g.loseLife();
  s.bird = { y: START_Y, vy: 0 };
  s.pipes = [];
  s.spawn = 0;
  s.safe = 90;
}

// Tennis-Duell (nur Spiel-API, keine Importe). Ein Schlaeger gehoert dir (links), der Computer spielt rechts.
// Ball abprallen lassen, Level steigt mit jedem fuenften Treffer. Zwei Spieler am Geraet: fehlt.
const PADDLE_H = 90;
const LEFT_X = 20;
const RIGHT_X = 330;
const PADDLE_W = 10;
const NET_X = 180;

export default {
  title: "Tennis-Duell",
  controls: ["up", "down"],
  lives: 3,

  init(g) {
    return {
      me: { y: 275 },
      cpu: { y: 275 },
      ball: { x: NET_X, y: 350, r: 10, vx: 0, vy: 0 },
      serve: 60,
      speed: 3,
      hits: 0
    };
  },

  update(s, input, g) {
    const top = g.TOP + 4;
    const bottom = g.H - 4;

    // Eigener Schlaeger
    if (input.up) s.me.y -= 5;
    if (input.down) s.me.y += 5;
    s.me.y = g.clamp(s.me.y, top, bottom - PADDLE_H);

    // Computer-Schlaeger folgt der Ballmitte, begrenzt auf 3 + 0.3 * Level pro Frame
    const cpuSpeed = 3 + 0.3 * g.level;
    const diff = s.ball.y - (s.cpu.y + PADDLE_H / 2);
    s.cpu.y += g.clamp(diff, -cpuSpeed, cpuSpeed);
    s.cpu.y = g.clamp(s.cpu.y, top, bottom - PADDLE_H);

    // Aufschlag-Pause
    if (s.serve > 0) {
      s.serve -= 1;
      s.ball.x = NET_X;
      s.ball.y = 350;
      if (s.serve === 0) {
        s.ball.vx = g.random() < 0.5 ? -s.speed : s.speed;
        s.ball.vy = -2 + g.random() * 4;
      }
      return;
    }

    const b = s.ball;
    b.x += b.vx;
    b.y += b.vy;

    // Obere und untere Wand
    if (b.y - b.r < top) { b.y = top + b.r; b.vy = Math.abs(b.vy); }
    if (b.y + b.r > bottom) { b.y = bottom - b.r; b.vy = -Math.abs(b.vy); }

    // Treffer am eigenen (linken) Schlaeger
    if (b.vx < 0 && b.x - b.r < LEFT_X + PADDLE_W && b.x + b.r > LEFT_X &&
        b.y + b.r > s.me.y && b.y - b.r < s.me.y + PADDLE_H) {
      b.vx = s.speed;
      b.vy = (b.y - (s.me.y + PADDLE_H / 2)) * 0.08;
      b.x = LEFT_X + PADDLE_W + b.r + 0.5;
      g.addScore(10);
      g.sound("hit");
      s.hits += 1;
      if (s.hits % 5 === 0) {
        g.nextLevel();
        g.sound("level");
        s.speed += 0.3;
      }
    }

    // Treffer am Computer-Schlaeger (rechts)
    if (b.vx > 0 && b.x + b.r > RIGHT_X && b.x - b.r < RIGHT_X + PADDLE_W &&
        b.y + b.r > s.cpu.y && b.y - b.r < s.cpu.y + PADDLE_H) {
      b.vx = -s.speed;
      b.vy = (b.y - (s.cpu.y + PADDLE_H / 2)) * 0.08;
      b.x = RIGHT_X - b.r - 0.5;
      g.sound("pop");
    }

    // Ball verlaesst das Feld links: Leben weg
    if (b.x < 0) {
      g.sound("hurt");
      g.loseLife();
      resetBall(s);
      return;
    }

    // Ball verlaesst das Feld rechts: Punkte fuer dich
    if (b.x > g.W) {
      g.addScore(25);
      g.sound("coin");
      resetBall(s);
    }
  },

  draw(s, d, g) {
    d.clear("cream");

    // Gestrichelte Mittellinie
    for (let y = g.TOP; y < g.H; y += 24) d.line(NET_X, y, NET_X, y + 12, "ink", 2);

    // Schlaeger
    d.rect(LEFT_X, s.me.y, PADDLE_W, PADDLE_H, "red", { round: 4 });
    d.rect(RIGHT_X, s.cpu.y, PADDLE_W, PADDLE_H, "ink", { round: 4 });

    // Ball
    d.emoji("🎾", s.ball.x, s.ball.y, 24);

    // Hinweis: Zwei-Spieler-Modus gibt es nicht
    d.text("Zwei Spieler: fehlt (nur Computer)", g.W / 2, g.H - 14, { size: 12, color: "ink", align: "center" });
  }
};

function resetBall(s) {
  s.ball = { x: NET_X, y: 350, r: 10, vx: 0, vy: 0 };
  s.serve = 60;
}

