// Wuerfel-100 (nur Spiel-API, keine Importe): vier Spieler wuerfeln abwechselnd am selben Geraet.
// Feuer = wuerfeln (eine 1 beendet den Zug ohne Punkte), Links = Zugpunkte halten. Wer zuerst 100 hat, gewinnt.
export default {
  title: "Wuerfel-100",
  controls: ["left", "fire"],
  lives: 1,

  init(g) {
    return { cur: 0, turn: 0, die: 0, scores: [0, 0, 0, 0], lockL: false, winner: -1 };
  },

  update(s, input, g) {
    if (input.left && !s.lockL) {
      s.scores[s.cur] += s.turn;
      if (s.turn > 0) g.addScore(s.turn);
      s.turn = 0;
      if (s.scores[s.cur] >= 100) {
        s.winner = s.cur;
        s.lockL = input.left;
        g.sound("win");
        g.win();
        return;
      }
      s.cur = (s.cur + 1) % 4;
      g.sound("coin");
    }
    s.lockL = input.left;

    if (input.firePressed) {
      s.die = g.randInt(1, 6);
      if (s.die === 1) {
        s.turn = 0;
        s.cur = (s.cur + 1) % 4;
        g.sound("hurt");
      } else {
        s.turn += s.die;
        g.sound("shoot");
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let i = 0; i < 4; i++) {
      const y = g.TOP + i * 100;
      const on = s.cur === i && s.winner < 0;
      if (on) d.rect(4, y + 2, 352, 96, "red", { round: 12 });
      d.rect(8, y + 6, 344, 88, on ? "yellow" : "cream", { round: 10, line: true });
      d.text("Spieler " + (i + 1), 24, y + 22, { size: 24, color: "ink", align: "left" });
      d.text("Zug: " + (on ? s.turn : 0), 24, y + 60, { size: 20, color: "ink", align: "left" });
      d.text(String(s.scores[i]), 336, y + 26, { size: 44, color: "ink", align: "right" });
    }
    d.text("Letzte Zahl", 180, 452, { size: 16, color: "ink", align: "center" });
    d.rect(100, 470, 160, 110, "cream", { round: 12, line: true });
    d.text(s.die > 0 ? String(s.die) : "?", 180, 490, { size: 64, color: "ink", align: "center" });
    if (s.winner >= 0) {
      d.text("Spieler " + (s.winner + 1) + " gewinnt!", 180, 596, { size: 26, color: "ink", align: "center" });
    } else {
      d.text("Feuer = wuerfeln, Links = halten", 180, 604, { size: 18, color: "ink", align: "center" });
    }
  }
};

