// Flutschen-Suche vom Donut-Start: Streusel, die nicht erreichbar sind, werden zu Leerzeichen.
function reachableMaze(raw) {
  const seen = [];
  for (let y = 0; y < ROWS; y++) {
    const row = [];
    for (let x = 0; x < COLS; x++) row.push(false);
    seen.push(row);
  }
  const queue = [{ x: DSTART.x, y: DSTART.y }];
  seen[DSTART.y][DSTART.x] = true;
  let head = 0;
  while (head < queue.length) {
    const c = queue[head];
    head += 1;
    for (const dd of DIRS) {
      const nx = wrapX(c.x + dd.x);
      const ny = c.y + dd.y;
      if (ny < 0 || ny >= ROWS) continue;
      if (raw[ny].charAt(nx) === "#" || seen[ny][nx]) continue;
      seen[ny][nx] = true;
      queue.push({ x: nx, y: ny });
    }
  }
  const out = [];
  for (let y = 0; y < ROWS; y++) {
    let line = "";
    for (let x = 0; x < COLS; x++) {
      const ch = raw[y].charAt(x);
      if (ch === "#") line += "#";
      else if (seen[y][x] && ch === ".") line += ".";
      else line += " ";
    }
    out.push(line);
  }
  return out;
}

function dotList() {
  const out = [];
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      if (MAZE[y].charAt(x) !== ".") continue;
      let isPow = false;
      for (const p of POWER) if (p.x === x && p.y === y) isPow = true;
      if (!isPow) out.push({ x: x, y: y });
    }
  }
  return out;
}

function wrapX(v) {
  if (v < 0) return COLS - 1;
  if (v >= COLS) return 0;
  return v;
}

function free(x, y) {
  if (y < 0 || y >= ROWS) return false;
  return MAZE[y].charAt(wrapX(x)) !== "#";
}

function dist2(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return dx * dx + dy * dy;
}

function collect(s, g) {
  for (let i = 0; i < s.dots.length; i++) {
    if (s.dots[i].x === s.d.x && s.dots[i].y === s.d.y) {
      s.dots.splice(i, 1);
      g.addScore(10);
      g.sound("coin");
      break;
    }
  }
  for (let i = 0; i < s.pows.length; i++) {
    if (s.pows[i].x === s.d.x && s.pows[i].y === s.d.y) {
      s.pows.splice(i, 1);
      s.power = 300;
      g.addScore(20);
      g.sound("coin");
      break;
    }
  }
}

function moveGhost(s, i, g) {
  const e = s.gh[i];
  const opts = [];
  for (const dd of DIRS) {
    const nx = e.x + dd.x;
    const ny = e.y + dd.y;
    if (free(nx, ny)) opts.push({ x: wrapX(nx), y: ny });
  }
  if (opts.length === 0) return;
  let best = opts[0];
  let bd = dist2(best, s.d);
  for (const o of opts) {
    const dv = dist2(o, s.d);
    if (dv < bd) { bd = dv; best = o; }
  }
  if (opts.length > 1 && g.random() < 0.2) best = opts[g.randInt(0, opts.length - 1)];
  e.x = best.x;
  e.y = best.y;
}

function touch(s, g) {
  for (let i = 0; i < s.gh.length; i++) {
    const e = s.gh[i];
    if (e.x !== s.d.x || e.y !== s.d.y) continue;
    if (s.power > 0) {
      s.gh[i] = { x: GSTART[i].x, y: GSTART[i].y };
      g.addScore(50);
      g.sound("pop");
      continue;
    }
    if (s.safe === 0) {
      g.sound("hurt");
      g.loseLife();
      resetPos(s);
      return;
    }
  }
}

function resetPos(s) {
  s.d = { x: DSTART.x, y: DSTART.y };
  s.want = { x: 1, y: 0 };
  s.dir = { x: 0, y: 0 };
  s.mt = 0;
  s.gh = GSTART.map((p) => ({ x: p.x, y: p.y }));
  s.et = 0;
  s.safe = 60;
}

