  lives: 3,

  init(g) {
    const syms = [];
    for (const sym of SYMS) { syms.push(sym); syms.push(sym); }
    for (let i = syms.length - 1; i > 0; i--) {
      const j = g.randInt(0, i);
      const tmp = syms[i];
      syms[i] = syms[j];
      syms[j] = tmp;
    }
    const cards = [];
    for (let i = 0; i < COLS * ROWS; i++) {
      const c = i % COLS;
      const r = Math.floor(i / COLS);
      cards.push({ x: 24 + c * 84, y: g.TOP + 60 + r * 96, sym: syms[i], open: false, done: false });
    }
    return { cards: cards, cursor: { c: 0, r: 0 }, pick: [], hold: 0, time: 0, moveCool: 0, found: 0 };
  },

