      else if (input.right) s.cursor.c = g.clamp(s.cursor.c + 1, 0, COLS - 1);
      else if (input.up) s.cursor.r = g.clamp(s.cursor.r - 1, 0, ROWS - 1);
      else if (input.down) s.cursor.r = g.clamp(s.cursor.r + 1, 0, ROWS - 1);
      else moved = false;
      if (moved) s.moveCool = MOVE_DELAY;
    }

    // Karte aufdecken
    if (input.firePressed && s.hold === 0 && s.pick.length < 2) {
      const i = s.cursor.r * COLS + s.cursor.c;
      const card = s.cards[i];
      if (!card.open && !card.done) {
        card.open = true;
        s.pick.push(i);
      }
    }

    // Vergleich zweier aufgedeckter Karten
    if (s.pick.length === 2 && s.hold === 0) {
      const a = s.cards[s.pick[0]];
      const b = s.cards[s.pick[1]];
      if (a.sym === b.sym) {
        a.done = true;
        b.done = true;
        s.pick = [];
        s.found += 1;
        g.addScore(10);
        g.sound("coin");
        if (s.found === SYMS.length) {
          g.sound("win");
          g.win();
          return;
        }
      } else {
        s.hold = HOLD_FRAMES;
      }
    }
  },

  draw(s, d) {
    d.clear("cream");
    for (let i = 0; i < s.cards.length; i++) {
      const card = s.cards[i];
      if (card.open || card.done) {
        d.rect(card.x, card.y, CARD, CARD, "cream", { round: 10, line: true });
        d.emoji(card.sym, card.x + CARD / 2, card.y + CARD / 2, 44);
      } else {
        d.rect(card.x, card.y, CARD, CARD, "yellow", { round: 10, shadow: true });
      }
    }
    const cur = s.cards[s.cursor.r * COLS + s.cursor.c];
    d.rect(cur.x - 4, cur.y - 4, CARD + 8, CARD + 8, "red", { round: 12, line: true });
  }
};

