const COLS = 4, ROWS = 3, CARD = 72, MOVE_DELAY = 8, HOLD_FRAMES = 40, TIME_LIMIT = 3000;

export default {
  title: "Enkel-Memory",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    const syms = shuffled(g);
    const cards = [];
    for (let i = 0; i < COLS * ROWS; i++) {
      const c = i % COLS;
      const r = Math.floor(i / COLS);
      cards.push({ x: 24 + c * 84, y: g.TOP + 60 + r * 96, sym: syms[i], open: false, done: false });
    }
    return { cards: cards, cursor: { c: 0, r: 0 }, pick: [], hold: 0, time: 0, moveCool: 0, found: 0, over: "" };
  },

  update(s, input, g) {
    if (s.over !== "") return;

    s.time += 1;
    if (s.time >= TIME_LIMIT) { s.over = "zeit"; g.gameOver(); return; }

    // Zudecken nach Fehlversuch
    if (s.hold > 0) {
      s.hold -= 1;
      if (s.hold === 0) {
        for (const i of s.pick) s.cards[i].open = false;
        s.pick = [];
      }
    }

    // Cursor bewegen, an den Raendern klemmen
    if (s.moveCool > 0) s.moveCool -= 1;
    if (s.moveCool === 0) {
      let moved = true;
      if (input.left) s.cursor.c = g.clamp(s.cursor.c - 1, 0, COLS - 1);
      else if (input.right) s.cursor.c = g.clamp(s.cursor.c + 1, 0, COLS - 1);
      else if (input.up) s.cursor.r = g.clamp(s.cursor.r - 1, 0, ROWS - 1);
      else if (input.down) s.cursor.r = g.clamp(s.cursor.r + 1, 0, ROWS - 1);
      else moved = false;
      if (moved) s.moveCool = MOVE_DELAY;
