      d.text("Runde vorbei. Eine neue Runde mischt die Karten neu.", g.W / 2, 500, { size: 12, color: "ink", align: "center" });
    } else if (s.over === "zeit") {
      d.text("Zeit ist abgelaufen.", g.W / 2, 470, { size: 22, color: "ink", align: "center" });
      d.text("Runde vorbei. Eine neue Runde mischt die Karten neu.", g.W / 2, 500, { size: 12, color: "ink", align: "center" });
    }
  }
};

