// Danach schätzt man die Anzahl, der Computer auch. Wer näher dran ist, gewinnt die Runde.
const SHOW_T = 120, GUESS_T = 300, RESULT_T = 90;
const GRID_COLS = 8, GRID_ROWS = 16, GRID_X = 110, GRID_Y = 160, GRID_STEP = 20;

export default {
  title: "Gummibär-Schätzen",
  controls: ["up", "down", "fire"],
  lives: 3,

  init(g) {
    const s = {
      phase: "show", count: 0, guess: 20, cpu: 0, timer: 0,
      round: 1, cap: 60, spots: [], msg: "", held: 0, dir: 0
    };
    newRound(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.phase === "show") {
      s.timer -= 1;
      if (s.timer <= 0) {
        s.phase = "guess";
        s.timer = GUESS_T;
        s.held = 0;
        s.dir = 0;
        s.msg = "Pfeile: Schätzung wählen, Feuer: bestätigen";
      }
      return;
    }

    if (s.phase === "guess") {
      // Halten: erster Schritt sofort, nach 10 Frames 5er-Schritte alle 6 Frames
